# ==================== FUNÇÕES AUXILIARES ====================

def formatar_moeda(valor) -> str:
    """R$ 5,00 (padrão brasileiro)."""
    try:
        numero = float(valor or 0)
    except Exception:
        numero = 0.0
    texto = f"{numero:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"R$ {texto}"


def arredondar(valor) -> float:
    """Arredonda pra 2 casas (dinheiro nunca fica com 3,99999)."""
    try:
        return round(float(valor or 0) + 1e-9, 2)
    except Exception:
        return 0.0


def obter_cor(nome: str) -> int:
    return CORES_DICCIONARIO.get(nome, 0xFF4500)


def criar_embed(titulo: str = "", descricao: str = "", cor_nome: str = "Fire Force", **kwargs) -> discord.Embed:
    embed = discord.Embed(
        title=titulo,
        description=descricao,
        color=obter_cor(cor_nome),
        timestamp=agora_brt()
    )
    
    footer_text = kwargs.get("footer", "Fire Force • Liga Profissional")
    footer_icon = kwargs.get("footer_icon", None)
    embed.set_footer(text=footer_text, icon_url=footer_icon)

    if kwargs.get("thumb"):
        embed.set_thumbnail(url=kwargs["thumb"])
    if kwargs.get("image"):
        embed.set_image(url=kwargs["image"])
    if kwargs.get("author"):
        embed.set_author(name=kwargs["author"], icon_url=kwargs.get("author_icon"))

    return embed


async def obter_config(guild_id: int) -> dict:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        cursor = await db.execute("SELECT * FROM config WHERE guild_id = ?", (guild_id,))
        row = await cursor.fetchone()
        return dict(row) if row else {}


async def salvar_config(guild_id: int, **kwargs):
    async with aiosqlite.connect(DATABASE_FILE) as db:
        existente = await obter_config(guild_id)
        if existente:
            campos = ", ".join(f"{chave} = ?" for chave in kwargs)
            valores = tuple(kwargs.values()) + (guild_id,)
            await db.execute(f"UPDATE config SET {campos} WHERE guild_id = ?", valores)
        else:
            kwargs["guild_id"] = guild_id
            colunas = ", ".join(kwargs.keys())
            placeholders = ", ".join("?" for _ in kwargs)
            valores = tuple(kwargs.values())
            await db.execute(f"INSERT INTO config ({colunas}) VALUES ({placeholders})", valores)
        await db.commit()


async def e_staff(member: discord.Member) -> bool:
    if member.guild_permissions.administrator:
        return True
    cfg = await obter_config(member.guild.id)
    cargos_permitidos = [
        cfg.get("cargo_dono"),
        cfg.get("cargo_gerente"),
        cfg.get("cargo_mediador")
    ]
    return any(role.id in cargos_permitidos for role in member.roles if role.id)


async def e_dono_ou_gerente(member: discord.Member) -> bool:
    if member.guild_permissions.administrator:
        return True
    cfg = await obter_config(member.guild.id)
    cargos_permitidos = [
        cfg.get("cargo_dono"),
        cfg.get("cargo_gerente")
    ]
    return any(role.id in cargos_permitidos for role in member.roles if role.id)


async def e_dono_do_servidor(member: discord.Member) -> bool:
    """Somente o dono real do Discord ou o cargo Dono configurado; gerente/admin não basta."""
    guild = getattr(member, "guild", None)
    if not guild:
        return False
    if int(getattr(guild, "owner_id", 0) or 0) == int(getattr(member, "id", 0) or 0):
        return True
    cfg = await obter_config(guild.id)
    cargo_dono = int(cfg.get("cargo_dono") or 0)
    return bool(cargo_dono and any(int(getattr(r, "id", 0) or 0) == cargo_dono
                                   for r in getattr(member, "roles", [])))


async def tem_cargo_dono_ou_gerente_configurado(member) -> bool:
    """Autoajuste: exige explicitamente um dos cargos Dono/Gerente configurados."""
    guild = getattr(member, "guild", None)
    if not guild:
        return False
    cfg = await obter_config(guild.id)
    cargos_permitidos = {int(cfg[k]) for k in ("cargo_dono", "cargo_gerente") if cfg.get(k)}
    return any(int(role.id) in cargos_permitidos for role in getattr(member, "roles", []) if getattr(role, "id", None))


async def e_suporte(member: discord.Member) -> bool:
    if member.guild_permissions.administrator:
        return True
    cfg = await obter_config(member.guild.id)
    cargos_permitidos = [
        cfg.get("cargo_suporte"),
        cfg.get("cargo_dono"),
        cfg.get("cargo_gerente"),
        cfg.get("cargo_mediador")
    ]
    return any(role.id in cargos_permitidos for role in member.roles if role.id)


async def pode_usar_pix(member: discord.Member) -> bool:
    """Somente ADM (Mediador), Gerente, Dono ou Administrador podem usar `/pix`."""
    if not getattr(member, "guild", None):
        return False
    return await e_staff(member)


async def pode_usar_trabalho(member: discord.Member) -> bool:
    """Somente Suporte (`cargo_suporte`), Gerente, Dono ou Administrador podem usar `/trabalho`."""
    if not getattr(member, "guild", None):
        return False
    if await e_dono_ou_gerente(member):
        return True
    cfg = await obter_config(member.guild.id)
    cargo_sup = cfg.get("cargo_suporte")
    return bool(cargo_sup and any(r.id == int(cargo_sup) for r in getattr(member, "roles", []) if r.id))


def horario_para_datetime(horario_str: str) -> datetime.datetime:
    partes = horario_str.strip().split(":")
    hora = int(partes[0])
    minuto = int(partes[1])
    hoje = agora_brt().date()
    dt_local = datetime.datetime.combine(hoje, datetime.time(hora, minuto))
    return dt_local.replace(tzinfo=TZ_BRASILIA)


async def obter_bloqueio_compra_min(guild_id: int) -> int:
    """Minutos antes do início em que a compra do diário é bloqueada (configurável)."""
    cfg = await obter_config(guild_id)
    val = cfg.get("bloqueio_compra_min")
    try:
        if val is not None and str(val).strip() != "":
            return max(0, min(int(val), 720))
    except (TypeError, ValueError):
        pass
    return BLOQUEIO_COMPRA_PADRAO_MIN


async def obter_ff_nivel_min(guild_id: int) -> int:
    """Level mínimo da conta no Free Fire para inscrição/substituição (padrão 20)."""
    cfg = await obter_config(guild_id)
    val = cfg.get("ff_nivel_min")
    try:
        if val is not None and str(val).strip() != "":
            return max(0, min(int(val), 100))
    except (TypeError, ValueError):
        pass
    return FF_NIVEL_MIN_PADRAO


async def obter_substituicao_min(guild_id: int) -> int:
    """Até quantos minutos antes do diário o capitão pode substituir membro na line (padrão 5)."""
    cfg = await obter_config(guild_id)
    val = cfg.get("substituicao_min")
    try:
        if val is not None and str(val).strip() != "":
            return max(0, min(int(val), 720))
    except (TypeError, ValueError):
        pass
    return SUBSTITUICAO_MIN_PADRAO


