async def obter_manutencao(guild_id: int) -> tuple:
    """Retorna `(ativa: bool, motivo: str)`."""
    cfg = await obter_config(guild_id)
    ativa = int(cfg.get("manutencao_ativa") or 0) == 1
    motivo = str(cfg.get("manutencao_motivo") or "Manutenção temporária / Atualização do Free Fire.").strip()
    return ativa, motivo


async def definir_manutencao(guild_id: int, ativa: bool, motivo: str = "") -> None:
    await salvar_config(
        guild_id,
        manutencao_ativa=(1 if ativa else 0),
        manutencao_motivo=(motivo or "Manutenção temporária / Atualização do Free Fire.").strip()[:200],
    )
    marcar_sujo()


async def pode_reassumir_atendimento(guild: discord.Guild, novo_user: discord.Member, responsavel_atual_id: Optional[int]) -> tuple:
    """Verifica se `novo_user` pode reassumir um atendimento já assumido por `responsavel_atual_id`.
    • Dono e Gerente podem reassumir SEMPRE em 1 clique.
    • Outro membro da equipe em serviço pode reassumir se o responsável anterior saiu de serviço (`online = 0`) ou saiu do servidor."""
    if not responsavel_atual_id or int(responsavel_atual_id) == int(novo_user.id):
        return True, "livre"
    if await e_dono_ou_gerente(novo_user):
        return True, "gerencia"
    membro_ant = await membro_do_guild(guild, int(responsavel_atual_id))
    if not membro_ant:
        return True, "ausente"
    async with aiosqlite.connect(DATABASE_FILE) as db:
        st = await (await db.execute(
            "SELECT online FROM staff_status WHERE user_id = ? AND guild_id = ?",
            (int(responsavel_atual_id), guild.id),
        )).fetchone()
    if not st or not bool(st[0]):
        return True, "fora_de_servico"
    return (
        False,
        f"Este atendimento está ativo com {mencao(responsavel_atual_id)} (que segue **em serviço**). "
        f"Apenas **Dono/Gerente** pode forçar a troca enquanto o responsável estiver online.",
    )


def pode_comprar_vaga(horario_str: str, lotes_usados: int, lotes_total: int,
                      bloqueio_min: int = BLOQUEIO_COMPRA_PADRAO_MIN,
                      repetir: bool = False,
                      encerrado_hoje: bool = False) -> tuple[bool, str]:
    sufixo_rep = " A compra será liberada novamente amanhã." if repetir else ""
    if encerrado_hoje:
        return False, f"Este diário já iniciou/encerrou hoje.{sufixo_rep}"

    tempo_restante = (horario_para_datetime(horario_str) - agora_brt()).total_seconds()
    if tempo_restante < 0:
        return False, f"O horário deste diário já passou hoje.{sufixo_rep}"

    bloqueio_seg = max(0, int(bloqueio_min)) * 60
    if bloqueio_seg > 0 and tempo_restante <= bloqueio_seg:
        minutos = max(0, int(math.ceil(tempo_restante / 60)))
        return (
            False,
            f"Compra bloqueada: faltam {minutos} min (bloqueio configurado em {int(bloqueio_min)} min antes do início).{sufixo_rep}"
        )

    if lotes_usados >= lotes_total:
        return False, f"Todas as vagas/lotes deste diário foram preenchidos.{sufixo_rep}"

    return True, "Liberado"


def formatar_rotulo_diario(tipo: str, categoria: str) -> str:
    tipo_emojis = {"solo": "🎯", "duo": "👥", "trio": "👨‍👩‍👦", "squad": "👨‍👩‍👧‍👦"}
    cat_emojis = "💎" if categoria == "premium" else "🪙"
    emoji_tipo = tipo_emojis.get(tipo.lower(), "🎮")
    return f"{emoji_tipo} {tipo.title()} {cat_emojis} {categoria.title()}"


def texto_slot(tipo: str) -> str:
    return "Vaga" if tipo.lower() == "solo" else "Lote"


def texto_slots_plural(tipo: str) -> str:
    return "Vagas" if tipo.lower() == "solo" else "Lotes"


# ==================== CONSULTA DE ID FREE FIRE (API v2) ====================
# Como funciona (por que agora funciona de verdade):
#   1. Vários provedores com CORRIDA (hedged requests): o 1º que responder vence
#      e os outros são cancelados — nenhum "servidor dormindo" trava a consulta.
#   2. Fallback automático de região (BR, NA, SAC, US, ME, SG...) — ID que não
#      aparece no BR é procurado nos outros servidores.
#   3. CACHE no banco (24h): consulta repetida é instantânea e funciona mesmo
#      com a internet/provedor fora do ar (usa o último dado salvo).
#   4. DISJUNTOR (circuit breaker): provedor que falha 3x entra em descanso por
#      5 minutos e é ignorado — não atrasa quem está funcionando.
#   5. Sessão HTTP reaproveitada, timeout curto e mensagens de erro honestas.

FF_API_TIMEOUT = 13           # segundos por requisição (aguenta os picos de lentidão do provedor)
FF_CACHE_HORAS = 24           # validade do cache (nick/level quase não mudam)
FF_CACHE_NEGATIVO_SEGUNDOS = 300   # "ID não existe" fica memorizado por 5 min
FF_MAX_REGIOES = 5            # quantas regiões testar quando não achar
FF_ESPERA_CONFIRMACAO = 2.0   # segundos esperando outro provedor contestar "não existe"
FF_ATRASO_CORRIDA = 0.35      # atraso entre disparos dos provedores
FF_FALHAS_PARA_ABRIR = 3      # falhas seguidas para colocar um provedor em descanso
FF_DESCANSO_SEGUNDOS = 300    # tempo de descanso do provedor problemático

# Ordem de regiões testadas (BR primeiro — maioria dos usuários do bot)
FF_REGIOES = ["BR", "NA", "SAC", "US", "EU", "ME", "SG", "IND", "ID", "TH", "VN", "PK", "BD", "CIS", "TW"]

# Provedores atualizados para Free Fire OB55 (corrida com fallback automático):
#   1. free-fire-info-ob55 (Vercel) — principal OB55 (BR + multi-região nativo)
#   2. bancheck-seven (Vercel) — espelho OB55 independente
#   3. freefireapis.lat (/GetPlayer) — rota OB55 atualizada (substitui /info-player)
FF_PROVEDORES = [
    {
        "nome": "ff-info-ob55",
        "url": "https://free-fire-info-ob55.vercel.app/player-info?uid={uid}&region={region}",
    },
    {
        "nome": "ff-mirror-ob55",
        "url": "https://bancheck-seven.vercel.app/api/player?uid={uid}&region={region}",
    },
    {
        "nome": "freefireapis.lat",
        "url": "https://freefireapis.lat/GetPlayer?uid={uid}&region={region}&formatar=true",
    },
]

# status de cada provedor (disjuntor)
_FF_SAUDE: Dict[str, dict] = {}
_FF_SESSAO = None
_FF_NAO_ENCONTRADOS: Dict[str, float] = {}   # uid -> quando foi marcado como inexistente


# ---------- sessão HTTP reaproveitada ----------

def _ff_sessao():
    global _FF_SESSAO
    if _FF_SESSAO is None or _FF_SESSAO.closed:
        timeout = aiohttp.ClientTimeout(total=FF_API_TIMEOUT, connect=5)
        conector = aiohttp.TCPConnector(limit=16, ttl_dns_cache=600)
        _FF_SESSAO = aiohttp.ClientSession(
            timeout=timeout,
            connector=conector,
            headers={"User-Agent": "FireForceBot/6.0 (+discord league manager)"},
        )
    return _FF_SESSAO


# ---------- disjuntor ----------

def _ff_provedor_disponivel(nome: str) -> bool:
    info = _FF_SAUDE.get(nome)
    if not info:
        return True
    aberto_ate = info.get("aberto_ate") or 0
    if aberto_ate and time.time() < aberto_ate:
        return False
    return True


def _ff_marcar_falha(nome: str, erro) -> None:
    info = _FF_SAUDE.setdefault(nome, {"falhas": 0, "aberto_ate": 0, "ultimo_erro": ""})
    info["falhas"] += 1
    info["ultimo_erro"] = str(erro)[:140]
    if info["falhas"] >= FF_FALHAS_PARA_ABRIR:
        info["aberto_ate"] = time.time() + FF_DESCANSO_SEGUNDOS
        info["falhas"] = 0
        print(f"🔌 [FF API] provedor '{nome}' em descanso por {FF_DESCANSO_SEGUNDOS}s — {info['ultimo_erro']}")


def _ff_marcar_sucesso(nome: str) -> None:
    _FF_SAUDE[nome] = {"falhas": 0, "aberto_ate": 0, "ultimo_erro": ""}


# ---------- leitura da resposta (aceita vários formatos) ----------

_CHAVES_NOME = ("nickname", "accountname", "name", "username", "nick")
_CHAVES_NIVEL = ("level", "accountlevel", "nivel", "account_level")
_CHAVES_REGIAO = ("region", "accountregion", "server", "regiao")
_CHAVES_RANK = ("rank", "brrank", "rankname")
_CHAVES_PRIME = ("primelevel", "prime_level")
_CHAVES_CLA = ("clanname", "clan_name", "guildname", "guild_name", "nome_guilda", "nome_cla", "guilda", "cla")
_CHAVES_AVATAR_ID = ("headpic", "head_pic", "avatarid", "avatar_id")
_CHAVES_AVATAR_URL = ("avatarurl", "avatar_url", "headpicurl", "head_pic_url", "iconurl", "icon_url", "profilepic", "profile_pic")


_SUBS_IGNORADOS_JOGADOR = {
    "petinfo", "pet_info", "captainbasicinfo", "captain_basic_info",
    "servicestatus", "service_status", "owner", "usage", "creditscoreinfo",
}


def _ff_procurar(objeto, chaves, profundidade=0, permitir_cla: bool = False):
    """Procura uma chave (case-insensitive) apenas nos blocos da conta do jogador
    (nunca confunde nick/level do pet ou do capitão da guilda com o jogador)."""
    if profundidade > 6:
        return None
    if isinstance(objeto, dict):
        # primeiro nas chaves diretas
        for chave_busca in chaves:
            for chave, valor in objeto.items():
                if chave.lower() == chave_busca and valor not in (None, "", 0, []):
                    return valor
        # depois nos sub-objetos prioritários da conta
        subs_prioritarios = (
            ("clanBasicInfo", "clan_basic_info", "guild", "guildInfo", "guild_info", "clan", "basicInfo", "basic_info", "data", "result")
            if permitir_cla
            else ("basicInfo", "basic_info", "profileInfo", "profile_info", "accountInfo", "account_info", "primeInfo", "data", "result", "player", "account")
        )
        for sub in subs_prioritarios:
            if isinstance(objeto.get(sub), dict):
                achado = _ff_procurar(objeto[sub], chaves, profundidade + 1, permitir_cla=permitir_cla)
                if achado not in (None, "", 0, []):
                    return achado
        # por último, em dicionários aninhados seguros (ignorando petInfo / captainBasicInfo / ServiceStatus)
        for nome_sub, valor in objeto.items():
            if str(nome_sub).lower() in _SUBS_IGNORADOS_JOGADOR:
                continue
            if not permitir_cla and str(nome_sub).lower() in ("clanbasicinfo", "clan_basic_info"):
                continue
            if isinstance(valor, (dict, list)):
                achado = _ff_procurar(valor, chaves, profundidade + 1, permitir_cla=permitir_cla)
                if achado not in (None, "", 0, []):
                    return achado
    elif isinstance(objeto, list):
        for item in objeto[:5]:
            achado = _ff_procurar(item, chaves, profundidade + 1, permitir_cla=permitir_cla)
            if achado not in (None, "", 0, []):
                return achado
    return None


def _ff_extrair(dados) -> Optional[dict]:
    """Extrai nick/nível/região/rank/clã de qualquer formato de resposta."""
    if not isinstance(dados, (dict, list)):
        return None
    if isinstance(dados, dict) and dados.get("success") is False:
        return None
    if isinstance(dados, dict) and dados.get("ok") is False:
        return None

    nome = _ff_procurar(dados, _CHAVES_NOME)
    if not nome or not isinstance(nome, (str, int)):
        return None
    nome = str(nome).strip()
    if len(nome) < 1 or nome.lower() in ("null", "none", "undefined"):
        return None

    nivel = _ff_procurar(dados, _CHAVES_NIVEL)
    try:
        nivel = int(float(str(nivel).replace(".", "").replace(",", ""))) if nivel else 0
    except Exception:
        nivel = 0

    regiao = _ff_procurar(dados, _CHAVES_REGIAO)
    regiao = str(regiao).upper() if isinstance(regiao, (str, int)) else ""

    rank = _ff_procurar(dados, _CHAVES_RANK)
    if isinstance(rank, int) or not rank:
        rank = ""
    else:
        rank = str(rank)[:28]

    prime = _ff_procurar(dados, _CHAVES_PRIME)
    try:
        prime = int(prime) if prime else 0
    except Exception:
        prime = 0

    cla = _ff_procurar(dados, _CHAVES_CLA, permitir_cla=True)
    if isinstance(cla, (dict, list)) or cla is None:
        cla = ""
    else:
        cla_s = str(cla).strip()
        # Evita confundir ID numérico de guilda com nome do clã
        cla = "" if (cla_s.isdigit() and len(cla_s) >= 6) else cla_s[:26]

    avatar_id_raw = _ff_procurar(dados, _CHAVES_AVATAR_ID)
    avatar_id = ""
    if avatar_id_raw not in (None, "", 0, []):
        av_s = re.sub(r"\D", "", str(avatar_id_raw))
        if 5 <= len(av_s) <= 15:
            avatar_id = av_s

    avatar_url_raw = _ff_procurar(dados, _CHAVES_AVATAR_URL)
    avatar_url = ""
    if isinstance(avatar_url_raw, str) and avatar_url_raw.strip().lower().startswith(("http://", "https://")):
        avatar_url = avatar_url_raw.strip()[:300]

    return {
        "nome": nome,
        "nivel": nivel,
        "regiao": regiao,
        "rank": rank,
        "prime": prime,
        "cla": cla,
        "avatar_id": avatar_id,
        "avatar_url": avatar_url,
    }


def _ff_uid_invalido(dados) -> bool:
    """O provedor respondeu que o UID é inválido (formato)."""
    if not isinstance(dados, dict):
        return False
    texto = json.dumps(dados, ensure_ascii=False).upper()
    return any(p in texto for p in ("INVALID_UID", "INVALID UID", "MUST BE AN INTEGER", "INVALID PARAMETER"))


def _ff_nao_encontrado(dados) -> bool:
    """A resposta diz claramente que o jogador não existe?"""
    if not isinstance(dados, dict):
        return False
    texto = json.dumps(dados, ensure_ascii=False).upper()
    return any(p in texto for p in (
        "PLAYER_NOT_FOUND", "UID NOT FOUND", "UID_NOT_FOUND",
        "PLAYER NOT FOUND", "ACCOUNT NOT FOUND", "ACCOUNT_NOT_FOUND",
        "USER_NOT_FOUND", "DOES NOT EXIST", "NOT EXIST",
    ))


def _ff_nao_encontrado_global(dados) -> bool:
    """O provedor já procurou em TODAS as regiões e confirmou que o UID não existe?"""
    if not isinstance(dados, dict):
        return False
    texto = json.dumps(dados, ensure_ascii=False).upper()
    return "NOT FOUND IN ANY REGION" in texto or "NOT FOUND ON ANY SERVER" in texto


def _ff_erro_provedor(dados) -> Optional[str]:
    """Detecta quando o provedor respondeu HTTP 200/4xx/5xx mas está sem contas bot,
    desatualizado ou fora do ar (NUNCA deve ser confundido com 'ID não existe')."""
    if not isinstance(dados, dict):
        return None
    texto = json.dumps(dados, ensure_ascii=False).upper()
    gatilhos_falha = (
        ("ACCOUNTS_EMPTY", "sem contas de consulta na região"),
        ("NO ACCOUNTS ARE AVAILABLE", "sem contas de consulta na região"),
        ("SERVICESTATUS", "rota desativada/status página"),
        ("UNRECOGNIZED_LOGIN_RESPONSE", "falha de login do provedor"),
        ("DEPLOYMENT_NOT_FOUND", "provedor removido"),
        ("RATE_LIMIT", "limite de requisições"),
        ("TOO MANY REQUESTS", "limite de requisições"),
        ("UPSTREAM", "falha no servidor upstream"),
        ("INTERNAL SERVER ERROR", "erro interno do provedor"),
    )
    for chave, descricao in gatilhos_falha:
        if chave in texto:
            return descricao
    if (dados.get("success") is False or dados.get("ok") is False) and not (
        _ff_nao_encontrado(dados) or _ff_uid_invalido(dados)
    ):
        msg = str(dados.get("error") or dados.get("message") or "falha no provedor")[:80]
        return msg
    return None


# ---------- cache no banco ----------

async def _ff_cache_ler(uid: str) -> Optional[dict]:
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            linha = await (await db.execute("SELECT * FROM ff_cache WHERE uid = ?", (uid,))).fetchone()
        return dict(linha) if linha else None
    except Exception:
        return None


async def _ff_cache_salvar(uid: str, jogador: dict, provedor: str) -> None:
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute(
                "INSERT OR REPLACE INTO ff_cache (uid, nick, nivel, regiao, rank, prime, cla, avatar_id, avatar_url, provedor, atualizado_em) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (uid, jogador.get("nome", ""), jogador.get("nivel", 0), jogador.get("regiao", ""),
                 jogador.get("rank", ""), jogador.get("prime", 0), jogador.get("cla", ""),
                 jogador.get("avatar_id", ""), jogador.get("avatar_url", ""),
                 provedor, agora_brt().isoformat())
            )
            await db.commit()
    except Exception as erro:
        print("Erro ao salvar cache do FF:", erro)


def _ff_cache_valido(linha: dict) -> bool:
    try:
        salvo = datetime.datetime.fromisoformat(linha["atualizado_em"])
        if salvo.tzinfo is None:
            salvo = salvo.replace(tzinfo=TZ_BRASILIA)
        return (agora_brt() - salvo).total_seconds() < FF_CACHE_HORAS * 3600
    except Exception:
        return False


# ---------- requisição a um provedor ----------

class _FFNaoEncontradoGlobal(Exception):
    """Sinal interno: o provedor já varreu todas as regiões e confirmou que o UID não existe."""


async def _ff_pedir(provedor: dict, uid: str, regiao: str) -> Optional[dict]:
    """Devolve o jogador, None se o ID não existe na região consultada,
    levanta _FFNaoEncontradoGlobal se não existe em região nenhuma,
    ou levanta RuntimeError se o provedor falhou/mudou de rota."""
    url = provedor["url"].format(uid=uid, region=regiao)
    sessao = _ff_sessao()
    async with sessao.get(url) as resposta:
        corpo = await resposta.text()
        status = resposta.status

    dados = None
    try:
        dados = json.loads(corpo)
    except Exception:
        dados = None

    if dados is not None:
        jogador = _ff_extrair(dados)
        if jogador:
            return jogador
        falha_prov = _ff_erro_provedor(dados)
        if falha_prov:
            raise RuntimeError(falha_prov)
        if _ff_nao_encontrado_global(dados):
            raise _FFNaoEncontradoGlobal()
        if _ff_nao_encontrado(dados) or _ff_uid_invalido(dados):
            return None                      # provedor vivo; o ID é que não existe

    if status == 429:
        raise RuntimeError("limite de uso (429)")
    if status >= 500:
        raise RuntimeError(f"servidor fora ({status})")
    if status != 200:
        raise RuntimeError(f"endpoint indisponível (http {status})")
    raise RuntimeError("resposta sem dados do jogador")


async def _ff_tentar_provedor(provedor: dict, uid: str):
    """Procura o ID no provedor. Retorna (status, dados, provedor).

    1º tenta a região principal (BR) — resolve a maioria e é rápido.
    Se não achar, dispara as outras regiões TODAS EM PARALELO: assim o tempo
    total continua sendo ~1 requisição, em vez de somar o tempo de cada região."""
    nome = provedor["nome"]
    if not _ff_provedor_disponivel(nome):
        return ("descartado", "em descanso", nome)

    regioes = FF_REGIOES[:FF_MAX_REGIOES]

    try:
        jogador = await _ff_pedir(provedor, uid, regioes[0])
    except asyncio.CancelledError:
        raise
    except _FFNaoEncontradoGlobal:
        _ff_marcar_sucesso(nome)
        return ("nao_encontrado", None, nome)
    except Exception as erro:
        _ff_marcar_falha(nome, erro)
        return ("erro", str(erro), nome)

    if jogador:
        _ff_marcar_sucesso(nome)
        jogador["regiao"] = jogador.get("regiao") or regioes[0]
        return ("ok", jogador, nome)

    # não achou no BR: procura nas outras regiões ao mesmo tempo
    outras = regioes[1:]
    tarefas = [asyncio.create_task(_ff_pedir(provedor, uid, regiao)) for regiao in outras]
    confirmou_vazio = True  # BR já respondeu validamente que não existe lá
    try:
        pendentes = set(tarefas)
        while pendentes:
            prontas, pendentes = await asyncio.wait(
                pendentes, return_when=asyncio.FIRST_COMPLETED, timeout=FF_API_TIMEOUT + 2
            )
            if not prontas:
                break
            for tarefa in prontas:
                try:
                    resultado = tarefa.result()
                except _FFNaoEncontradoGlobal:
                    _ff_marcar_sucesso(nome)
                    return ("nao_encontrado", None, nome)
                except Exception:
                    continue
                if resultado:
                    _ff_marcar_sucesso(nome)
                    resultado["regiao"] = resultado.get("regiao") or "?"
                    return ("ok", resultado, nome)
    finally:
        for tarefa in tarefas:
            tarefa.cancel()

    if confirmou_vazio:
        _ff_marcar_sucesso(nome)
        return ("nao_encontrado", None, nome)
    return ("erro", "falha nas regiões secundárias", nome)


async def _ff_disparar(provedor: dict, uid: str, atraso: float):
    if atraso:
        await asyncio.sleep(atraso)
    return await _ff_tentar_provedor(provedor, uid)


# ---------- função principal ----------

async def verificar_ff(uid: str, forcar: bool = False) -> dict:
    """Consulta um ID do Free Fire de forma confiável (corrida + regiões + cache).

    Retorno em caso de sucesso:
        {"ok": True, "nome":..., "nivel":..., "regiao":..., "rank":..., "prime":...,
         "cla":..., "provedor":..., "cache": bool, "aviso": str|None, "atualizado": str}
    """
    uid = str(uid or "").strip()
    if not uid.isdigit() or not (5 <= len(uid) <= 15):
        return {"ok": False, "motivo": "formato",
                "mensagem": "O ID precisa ter de 5 a 15 números (só dígitos)."}

    # 0) já foi marcado como inexistente há pouco? evita bater na API de novo
    if not forcar:
        quando = _FF_NAO_ENCONTRADOS.get(uid)
        if quando and (time.time() - quando) < FF_CACHE_NEGATIVO_SEGUNDOS:
            return {"ok": False, "motivo": "nao_encontrado",
                    "mensagem": "Não encontrei esse ID em nenhuma região de Free Fire. Confira os números."}

    # 1) cache fresco
    salvo = await _ff_cache_ler(uid)
    if salvo and not forcar and _ff_cache_valido(salvo):
        return {
            "ok": True, "nome": salvo["nick"], "nivel": salvo["nivel"], "regiao": salvo["regiao"],
            "rank": salvo["rank"] or "", "prime": salvo["prime"] or 0, "cla": salvo["cla"] or "",
            "avatar_id": salvo.get("avatar_id") or "", "avatar_url": salvo.get("avatar_url") or "",
            "provedor": salvo["provedor"] or "cache", "cache": True, "aviso": None,
            "atualizado": salvo["atualizado_em"],
        }

    # 2) corrida entre os provedores disponíveis
    disponiveis = [p for p in FF_PROVEDORES if _ff_provedor_disponivel(p["nome"])]
    if not disponiveis:
        disponiveis = FF_PROVEDORES  # todos em descanso: tenta o primeiro mesmo assim

    tarefas = [
        asyncio.create_task(_ff_disparar(provedor, uid, indice * FF_ATRASO_CORRIDA))
        for indice, provedor in enumerate(disponiveis)
    ]

    achado = None
    erros = []
    nao_encontrado = False
    pendentes = set(tarefas)
    prazo_total = time.time() + FF_API_TIMEOUT + FF_ATRASO_CORRIDA * len(disponiveis) + 2
    confirmacao_ate = None       # se alguém diz "não existe", damos 3s para outro discordar

    try:
        while pendentes and not achado:
            agora_loop = time.time()
            if agora_loop >= prazo_total:
                erros.append("tempo esgotado")
                break
            if confirmacao_ate and agora_loop >= confirmacao_ate:
                break
            espera = prazo_total - agora_loop
            if confirmacao_ate:
                espera = min(espera, confirmacao_ate - agora_loop)

            prontas, pendentes = await asyncio.wait(
                pendentes, return_when=asyncio.FIRST_COMPLETED, timeout=max(0.1, espera)
            )
            if not prontas:
                if confirmacao_ate:
                    break
                erros.append("tempo esgotado")
                break
            for tarefa in prontas:
                try:
                    status, dados, nome = tarefa.result()
                except Exception as erro:
                    erros.append(str(erro))
                    continue
                if status == "ok" and dados:
                    achado = (dados, nome)
                    break
                if status == "nao_encontrado":
                    nao_encontrado = True
                    if confirmacao_ate is None:
                        confirmacao_ate = time.time() + FF_ESPERA_CONFIRMACAO
                elif status == "erro":
                    erros.append(f"{nome}: {dados}")
    finally:
        for tarefa in pendentes:
            tarefa.cancel()

    if achado:
        jogador, provedor = achado
        await _ff_cache_salvar(uid, jogador, provedor)
        return {
            "ok": True, "nome": jogador["nome"], "nivel": jogador["nivel"], "regiao": jogador["regiao"],
            "rank": jogador.get("rank", ""), "prime": jogador.get("prime", 0), "cla": jogador.get("cla", ""),
            "avatar_id": jogador.get("avatar_id", ""), "avatar_url": jogador.get("avatar_url", ""),
            "provedor": provedor, "cache": False, "aviso": None,
            "atualizado": agora_brt().isoformat(),
        }

    # 3) não achou em nenhum provedor: era "não existe" ou "tudo fora"?
    if nao_encontrado:
        _FF_NAO_ENCONTRADOS[uid] = time.time()
        return {"ok": False, "motivo": "nao_encontrado",
                "mensagem": "Não encontrei esse ID em nenhuma região de Free Fire. Confira os números."}

    if salvo:  # 4) provedores fora do ar, mas temos cache antigo: melhor que nada
        return {
            "ok": True, "nome": salvo["nick"], "nivel": salvo["nivel"], "regiao": salvo["regiao"],
            "rank": salvo["rank"] or "", "prime": salvo["prime"] or 0, "cla": salvo["cla"] or "",
            "avatar_id": salvo.get("avatar_id") or "", "avatar_url": salvo.get("avatar_url") or "",
            "provedor": salvo["provedor"] or "cache", "cache": True,
            "aviso": "Os servidores de consulta estão instáveis agora — mostrando o último dado salvo.",
            "atualizado": salvo["atualizado_em"],
        }

    # 5) último recurso quando as APIs externas estão fora: histórico de partidas já jogadas no bot
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            hist = await (await db.execute(
                "SELECT ff_nome, ff_nivel FROM slot_jogadores "
                "WHERE ff_uid = ? AND ff_nome != '' ORDER BY id DESC LIMIT 1",
                (uid,),
            )).fetchone()
        if hist and hist["ff_nome"]:
            return {
                "ok": True, "nome": hist["ff_nome"], "nivel": int(hist["ff_nivel"] or 0), "regiao": "BR",
                "rank": "", "prime": 0, "cla": "", "provedor": "histórico-local", "cache": True,
                "aviso": "APIs externas em manutenção — conta recuperada do histórico do servidor.",
                "atualizado": agora_brt().isoformat(),
            }
    except Exception:
        pass

    return {"ok": False, "motivo": "offline",
            "mensagem": "Os servidores de consulta não responderam agora (instabilidade ou manutenção). "
                        "Tente de novo em alguns segundos."}


async def _ff_fechar_sessao():
    """Fecha a sessão HTTP com elegância."""
    global _FF_SESSAO
    if _FF_SESSAO and not _FF_SESSAO.closed:
        await _FF_SESSAO.close()
    _FF_SESSAO = None


def ff_status_provedores() -> str:
    """Resumo da saúde dos provedores (usado no /info)."""
    linhas = []
    for provedor in FF_PROVEDORES:
        info = _FF_SAUDE.get(provedor["nome"], {})
        aberto_ate = info.get("aberto_ate") or 0
        if aberto_ate and time.time() < aberto_ate:
            linhas.append(f"🔴 `{provedor['nome']}` em descanso ({int(aberto_ate - time.time())}s)")
        else:
            linhas.append(f"🟢 `{provedor['nome']}` ativo")
    return "\n".join(linhas)


# ---------- busca na base local do bot ----------

_INVISIVEIS = ["\u3164", "\u2800", "\u200b", "\u200c", "\u200d", "\u2060", "\ufeff", "\u00a0"]


def _nick_limpo(nick: str) -> str:
    """Tira espaços invisíveis/zerowidth que os jogadores usam no nick."""
    texto = str(nick or "")
    for caractere in _INVISIVEIS:
        texto = texto.replace(caractere, " ")
    return " ".join(texto.split())


async def consultar_jogador_local(busca: str) -> dict:
    """Procura um jogador pelos nicks que ele usou nas inscrições do bot."""
    busca = (busca or "").strip()
    if not busca:
        return {"ok": False}

    consulta = """
        SELECT j.ff_uid, j.ff_nome, j.ff_nivel, s.criado_em, s.numero, h.tipo, h.categoria, h.horario
        FROM slot_jogadores j
        JOIN slots s ON s.id = j.slot_id
        JOIN horarios h ON h.id = s.horario_id
        WHERE s.confirmado = 1
          AND (j.ff_uid = ? OR LOWER(j.ff_nome) = LOWER(?) OR LOWER(j.ff_nome) LIKE LOWER(?))
        ORDER BY s.criado_em DESC
    """
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linhas = await (await db.execute(consulta, (busca, busca, f"%{busca}%"))).fetchall()

        # nick do Free Fire costuma ter caracteres invisíveis: se a busca direta
        # falhar, compara o "nick limpo" de todas as inscrições do bot.
        if not linhas:
            todas = await (await db.execute(
                """
                SELECT j.ff_nome, s.criado_em, s.numero, h.tipo, h.categoria, h.horario
                FROM slot_jogadores j
                JOIN slots s ON s.id = j.slot_id
                JOIN horarios h ON h.id = s.horario_id
                WHERE s.confirmado = 1
                ORDER BY s.criado_em DESC
                """
            )).fetchall()
            alvo = _nick_limpo(busca).lower()
            linhas = [linha for linha in todas if alvo and (
                _nick_limpo(linha["ff_nome"]).lower() == alvo
                or alvo in _nick_limpo(linha["ff_nome"]).lower()
            )]

    if not linhas:
        return {"ok": False}
    principal = linhas[0]
    return {
        "ok": True,
        "nome": principal["ff_nome"] or "—",
        "partidas": len(linhas),
        "ultimo": f"{formatar_rotulo_diario(principal['tipo'], principal['categoria'])} • {principal['horario']}",
    }


# ==================== PIX PAYLOAD GENERATOR (BRCODE OFICIAL BACEN) ====================

def _crc16(payload: str) -> str:
    """CRC16-CCITT (0xFFFF, polinômio 0x1021) — padrão oficial EMVCo / Banco Central (vetor Bacen -> 1D3D)."""
    crc = 0xFFFF
    for byte in payload.encode("utf-8"):
        crc ^= byte << 8
        for _ in range(8):
            if crc & 0x8000:
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF
    return f"{crc:04X}"


def _emv_campo(campo_id: str, valor: str) -> str:
    return f"{campo_id}{len(valor):02d}{valor}"


def _ascii_pix(texto: str, limite: int, padrao: str) -> str:
    import unicodedata
    limpo = unicodedata.normalize("NFKD", str(texto or "")).encode("ascii", "ignore").decode("ascii")
    limpo = re.sub(r"[^A-Za-z0-9 ]+", " ", limpo).upper()
    limpo = " ".join(limpo.split())[:limite].strip()
    return limpo or padrao[:limite]


def _cpf_valido(digitos: str) -> bool:
    if len(digitos) != 11 or len(set(digitos)) == 1:
        return False
    for tam in (9, 10):
        soma = sum(int(digitos[i]) * ((tam + 1) - i) for i in range(tam))
        dv = (soma * 10) % 11
        if dv == 10:
            dv = 0
        if dv != int(digitos[tam]):
            return False
    return True


def _cnpj_valido(digitos: str) -> bool:
    if len(digitos) != 14 or len(set(digitos)) == 1:
        return False
    pesos1 = (5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2)
    pesos2 = (6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2)
    for idx, pesos in ((12, pesos1), (13, pesos2)):
        soma = sum(int(digitos[i]) * pesos[i] for i in range(idx))
        resto = soma % 11
        dv = 0 if resto < 2 else 11 - resto
        if dv != int(digitos[idx]):
            return False
    return True


_RE_EVP_UUID = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", re.I)
_RE_EMAIL_PIX = re.compile(r"^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$")


def validar_e_normalizar_chave_pix(tipo_escolhido: Optional[str], chave_bruta: str) -> tuple[bool, str, str, str]:
    """Valida e formata a chave PIX exatamente no padrão DICT do Banco Central.
    Retorna `(ok, tipo_normalizado, chave_dict, erro_amigavel)`."""
    limpa = re.sub(r"[\u200b\u200c\u200d\ufeff\xa0]", "", str(chave_bruta or "")).strip()
    if not limpa:
        return False, "", "", "Informe uma chave PIX."

    tipo = (tipo_escolhido or "").strip().lower()
    digitos = re.sub(r"\D", "", limpa)

    # Auto-detecção segura caso a pessoa não tenha escolhido tipo ou tenha escolhido "aleatoria" por engano
    if "@" in limpa:
        tipo = "email"
    elif _RE_EVP_UUID.match(limpa):
        tipo = "aleatoria"
    elif limpa.startswith("+"):
        tipo = "telefone"
    elif len(digitos) == 14 and _cnpj_valido(digitos) and tipo in ("", "cpf", "cnpj", "aleatoria"):
        tipo = "cnpj"
    elif not tipo:
        if len(digitos) == 11:
            if _cpf_valido(digitos) and not (11 <= int(digitos[:2]) <= 99 and digitos[2] == "9"):
                tipo = "cpf"
            elif not _cpf_valido(digitos) and 11 <= int(digitos[:2]) <= 99 and digitos[2] in ("8", "9"):
                tipo = "telefone"
            else:
                return (
                    False,
                    "",
                    "",
                    "Esse número de 11 dígitos pode ser **CPF** ou **Celular**. Selecione o `tipo` da chave (`CPF` ou `Celular / Telefone`) para o QR Code sair perfeito!",
                )
        elif len(digitos) in (10, 12, 13):
            tipo = "telefone"
        else:
            tipo = "aleatoria"

    # Se marcou aleatoria mas digitou CPF/celular sem ser UUID, corrige ou avisa
    if tipo == "aleatoria" and not _RE_EVP_UUID.match(limpa):
        if len(digitos) == 11 and _cpf_valido(digitos) and "." in limpa:
            tipo = "cpf"
        elif "(" in limpa or (digitos.startswith("55") and len(digitos) in (12, 13)):
            tipo = "telefone"
        else:
            return (
                False,
                "aleatoria",
                "",
                "Chave aleatória (EVP) precisa estar no formato de 36 caracteres com traços (ex: `123e4567-e89b-12d3-a456-426614174000`).\n"
                "Se sua chave for **CPF**, **Celular** ou **E-mail**, selecione o tipo correspondente!",
            )

    if tipo == "email":
        email_fmt = limpa.replace(" ", "").lower()
        if not _RE_EMAIL_PIX.match(email_fmt) or len(email_fmt) > 77:
            return False, "email", "", "E-mail PIX inválido. Exemplo válido: `seunome@gmail.com`."
        return True, "email", email_fmt, ""

    if tipo == "cpf":
        if len(digitos) == 14 and _cnpj_valido(digitos):
            return True, "cnpj", digitos, ""
        if len(digitos) != 11:
            return False, "cpf", "", "O CPF precisa ter **11 dígitos** (ou 14 dígitos para CNPJ)."
        if not _cpf_valido(digitos):
            dica_cel = (
                "\n💡 *Se esse número for um **Celular**, escolha o tipo **Celular / Telefone** (para o banco incluir o `+55`).*"
                if (11 <= int(digitos[:2]) <= 99 and digitos[2] == "9")
                else ""
            )
            return False, "cpf", "", f"CPF inválido (dígitos verificadores não conferem). Confira os números!{dica_cel}"
        return True, "cpf", digitos, ""

    if tipo == "cnpj":
        if len(digitos) != 14 or not _cnpj_valido(digitos):
            return False, "cnpj", "", "CNPJ inválido. Informe os 14 dígitos corretos."
        return True, "cnpj", digitos, ""

    if tipo in ("telefone", "celular"):
        if limpa.startswith("+"):
            d_tel = re.sub(r"\D", "", limpa[1:])
            if not d_tel.startswith("55"):
                return True, "telefone", f"+{d_tel}", ""
            digitos = d_tel[2:]
        elif digitos.startswith("55") and len(digitos) in (12, 13):
            digitos = digitos[2:]

        if len(digitos) not in (10, 11) or not (11 <= int(digitos[:2]) <= 99):
            return (
                False,
                "telefone",
                "",
                "Celular inválido. Informe **DDD + número** (ex: `92991234567` ou `(92) 99123-4567`).",
            )
        return True, "telefone", f"+55{digitos}", ""

    if tipo == "aleatoria":
        return True, "aleatoria", limpa.lower(), ""

    return False, tipo, "", "Tipo de chave PIX desconhecido."


def normalizar_chave_pix_emv(tipo: str, chave: str) -> str:
    """Garante a formatação DICT mesmo para chaves salvas anteriormente."""
    ok, _, chave_fmt, _ = validar_e_normalizar_chave_pix(tipo, chave)
    if ok:
        return chave_fmt
    t = (tipo or "aleatoria").strip().lower()
    c = str(chave or "").strip()
    digitos = re.sub(r"\D", "", c)
    if t in ("cpf", "cnpj"):
        return digitos
    if t in ("telefone", "celular"):
        if c.startswith("+"):
            return "+" + re.sub(r"\D", "", c[1:])
        if len(digitos) in (10, 11):
            return f"+55{digitos}"
        if digitos.startswith("55") and len(digitos) in (12, 13):
            return f"+{digitos}"
    if t == "email":
        return c.replace(" ", "").lower()
    return c


def gerar_payload_pix(chave: str, tipo_chave: str = "aleatoria", titular: str = "FIRE FORCE",
                      valor: float = 0.0, txid: str = "***") -> str:
    """Gera o código PIX Copia e Cola (BRCode Estático oficial do Banco Central).

    Nota técnica importante (Manual do BR Code Bacen, seção 2.1.1):
    Em QR Codes estáticos gerados fora do PSP do recebedor, o campo 62/05 (txid)
    DEVE ser `***` (`62070503***`), pois bancos como Caixa, Santander, Bradesco,
    BB e Itaú rejeitam TXIDs personalizados não registrados no PSP de destino.
    """
    chave_fmt = normalizar_chave_pix_emv(tipo_chave, chave)
    gui = _emv_campo("00", "br.gov.bcb.pix")
    chave_sub = _emv_campo("01", chave_fmt)
    conta = _emv_campo("26", gui + chave_sub)

    partes = [
        _emv_campo("00", "01"),
        conta,
        _emv_campo("52", "0000"),
        _emv_campo("53", "986"),
    ]
    if valor and float(valor) > 0:
        partes.append(_emv_campo("54", f"{float(valor):.2f}"))
    partes.append(_emv_campo("58", "BR"))
    partes.append(_emv_campo("59", _ascii_pix(titular, 25, "FIRE FORCE")))
    partes.append(_emv_campo("60", "BRASILIA"))
    partes.append(_emv_campo("62", _emv_campo("05", "***")))

    sem_crc = "".join(partes) + "6304"
    return sem_crc + _crc16(sem_crc)


async def obter_pix_adm(user_id: int, guild_id: int) -> Optional[dict]:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linha = await (await db.execute(
            "SELECT * FROM pix WHERE user_id = ? AND guild_id = ?",
            (int(user_id), int(guild_id))
        )).fetchone()
    return dict(linha) if linha and linha["chave"] else None


async def salvar_pix_adm(user_id: int, guild_id: int, tipo: str, chave: str, titular: str) -> None:
    agora = agora_brt().isoformat()
    async with aiosqlite.connect(DATABASE_FILE) as db:
        await db.execute(
            "INSERT INTO pix (user_id, guild_id, tipo, chave, titular, atualizado_em) "
            "VALUES (?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(user_id, guild_id) DO UPDATE SET "
            "tipo = excluded.tipo, chave = excluded.chave, titular = excluded.titular, atualizado_em = excluded.atualizado_em",
            (int(user_id), int(guild_id), tipo.strip().lower(), chave.strip(), titular.strip(), agora)
        )
        await db.commit()
    marcar_sujo()


async def remover_pix_adm(user_id: int, guild_id: int) -> bool:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        cur = await db.execute(
            "DELETE FROM pix WHERE user_id = ? AND guild_id = ?",
            (int(user_id), int(guild_id))
        )
        await db.commit()
    if cur.rowcount:
        marcar_sujo()
        return True
    return False


# ==================== v13.2: TABELA OFICIAL EM IMAGEM HD (SOLO, DUO, TRIO, SQUAD) ====================

_TABELA_ASSINATURA_CACHE: dict = {}
_ROTULOS_CATEGORIA_CARD = {
    "basico": "BÁSICO",
    "premium": "PREMIUM",
    "mobile": "MOBILE",
    "misto": "MISTO",
    "emulador": "EMULADOR",
}


def montar_lista_vagas(tipo: str, slots_data: list) -> str:
    """Lista numerada de fallback em texto: `N. (nomes)`."""
    total = LOTES_POR_MODO.get((tipo or "solo").lower(), len(slots_data or []))
    linhas = []
    for indice in range(total):
        slot = slots_data[indice] if slots_data and indice < len(slots_data) else {}
        nicks = []
        if slot.get("confirmado"):
            for jogador in (slot.get("jogadores") or []):
                nick = (jogador.get("ff_nome") if isinstance(jogador, dict) else jogador) or ""
                nick = str(nick).strip()
                if nick:
                    nicks.append(nick)
        linhas.append(f"{indice + 1:>2}. ({', '.join(nicks)})")
    return "\n".join(linhas)


def montar_embed_tabela(horario: dict, slots_data: list, ocupadas: int = 0,
                        atualizado_em: str = "") -> discord.Embed:
    """Fallback de segurança caso Pillow não esteja disponível no ambiente."""
    tipo = (horario.get("tipo") or "solo").lower()
    categoria = horario.get("categoria") or "premium"
    total = LOTES_POR_MODO.get(tipo, 48)
    lista = montar_lista_vagas(tipo, slots_data)

    descricao = (
        f"**🏆 Premiação:** `{horario.get('premiacao') or 'Por Kill'}`"
        f"  •  **💰 Valor:** `{formatar_moeda(horario.get('valor'))}`\n"
        f"**🎫 {texto_slots_plural(tipo)}:** `{ocupadas}/{total}`\n\n"
        f"```\n{lista}\n```"
    )

    return criar_embed(
        titulo=f"🔥 {formatar_rotulo_diario(tipo, categoria)} — {horario.get('horario', '--:--')}",
        descricao=descricao,
        cor_nome="Vermelho Escuro",
        footer=("Fire Force • Tabela Oficial em Tempo Real" + (f" • {atualizado_em}" if atualizado_em else "")),
    )


