async def montar_diagnostico_config(guild: discord.Guild) -> tuple[discord.Embed, bool]:
    """Checklist operacional do servidor; não revela tokens nem chaves."""
    cfg = await obter_config(guild.id)
    membro_bot = guild.me
    if not membro_bot and bot.user:
        membro_bot = guild.get_member(bot.user.id)

    permissoes = []
    organizacao = []
    integracoes = []
    falha_critica = False

    def registrar(lista, ok: bool, texto: str, critico: bool = False):
        nonlocal falha_critica
        prefixo = "✅" if ok else ("❌" if critico else "⚠️")
        lista.append(f"{prefixo} {texto}")
        if critico and not ok:
            falha_critica = True

    if membro_bot:
        perms = membro_bot.guild_permissions
        admin = bool(perms.administrator)
        for chave, rotulo, critico in (
            ("manage_channels", "Gerenciar canais (tickets, pagamentos e salas)", True),
            ("view_channel", "Ver canais", True),
            ("send_messages", "Enviar mensagens", True),
            ("embed_links", "Enviar embeds (painéis e recibos)", True),
            ("attach_files", "Anexar arquivos (QR Codes/comprovantes)", False),
            ("read_message_history", "Ler histórico (recuperação de painéis)", False),
        ):
            registrar(permissoes, admin or bool(getattr(perms, chave, False)), rotulo, critico)
    else:
        registrar(permissoes, False, "Não consegui localizar o membro do bot neste servidor", True)

    for rotulo, chave in (("Dono", "cargo_dono"), ("Gerente", "cargo_gerente"),
                          ("Mediador", "cargo_mediador"), ("Suporte", "cargo_suporte")):
        cargo_id = cfg.get(chave)
        try:
            cargo = guild.get_role(int(cargo_id)) if cargo_id else None
        except (TypeError, ValueError):
            cargo = None
        registrar(organizacao, cargo is not None,
                  f"Cargo {rotulo}: {cargo.mention if cargo else 'não configurado ou removido'}")

    for rotulo, chave in (("Diários premium", "cat_premium"), ("Diários básicos", "cat_basico"),
                          ("Pagamentos", "cat_pagamentos"), ("Tickets", "cat_tickets")):
        canal_id = cfg.get(chave)
        try:
            categoria = guild.get_channel(int(canal_id)) if canal_id else None
        except (TypeError, ValueError):
            categoria = None
        valida = isinstance(categoria, discord.CategoryChannel)
        texto = f"Categoria {rotulo}: {categoria.mention if valida else 'não configurada (os canais podem ficar fora de categoria)'}"
        if valida and membro_bot:
            pcat = categoria.permissions_for(membro_bot)
            ok_categoria = pcat.administrator or (pcat.view_channel and pcat.send_messages)
            registrar(organizacao, ok_categoria, texto if ok_categoria else texto + " — revisar permissões")
        else:
            registrar(organizacao, valida, texto)

    canal_logs_id = cfg.get("canal_logs")
    canal_logs = None
    try:
        canal_logs = guild.get_channel(int(canal_logs_id)) if canal_logs_id else None
    except (TypeError, ValueError):
        pass
    if not canal_logs_id:
        registrar(organizacao, False, "Canal de logs geral: não definido (opcional, recomendado)")
    elif not isinstance(canal_logs, discord.TextChannel):
        registrar(organizacao, False, "Canal de logs salvo, mas não encontrado nesta guild")
    elif membro_bot:
        plogs = canal_logs.permissions_for(membro_bot)
        registrar(organizacao, plogs.send_messages and plogs.embed_links,
                  f"Canal de logs: {canal_logs.mention}" +
                  ("" if plogs.send_messages and plogs.embed_links else " — falta enviar mensagens/embeds"))

    canal_fin_id = cfg.get("canal_log_pag_adm")
    try:
        canal_fin = guild.get_channel(int(canal_fin_id)) if canal_fin_id else None
    except (TypeError, ValueError):
        canal_fin = None
    if not isinstance(canal_fin, discord.TextChannel):
        registrar(organizacao, False, "Canal financeiro privado (PIX completo): não configurado")
    else:
        publico_pode_ver = canal_fin.permissions_for(guild.default_role).view_channel
        perms_fin = canal_fin.permissions_for(membro_bot) if membro_bot else None
        bot_ok = bool(perms_fin and perms_fin.view_channel and perms_fin.send_messages
                      and perms_fin.embed_links and perms_fin.read_message_history)
        privado_ok = not publico_pode_ver
        registrar(organizacao, privado_ok and bot_ok,
                  f"Canal financeiro privado: {canal_fin.mention}" +
                  ("" if privado_ok and bot_ok else " — negar Ver canal para @everyone e conferir permissões do bot"))

    canal_parc = guild.get_channel(cfg.get("canal_parcerias") or 0) if cfg.get("canal_parcerias") else None
    integracoes.append(("✅" if canal_parc else "ℹ️") + (
        f" Vitrine de Parcerias: {canal_parc.mention}" if canal_parc else " Vitrine de Parcerias ainda não definida (`/parceria`)"
    ))
    integracoes.append(("✅" if supabase_configurado() else "ℹ️") + (
        " Supabase configurado para backup/sincronização" if supabase_configurado()
        else " Supabase opcional não configurado"))
    integracoes.append(("✅" if os.path.exists(DATABASE_FILE) else "⚠️") +
                       f" Banco local: `{DATABASE_FILE}`")
    integracoes.append(f"ℹ️ Versão do bot: `v{VERSAO_BOT}` • PIX direto Dono/ADM (Bacen BRCode)")

    resumo = ("🔴 Corrija as permissões críticas do bot antes de abrir inscrições."
              if falha_critica else "🟢 Permissões essenciais conferidas; revise os avisos para organizar a operação.")
    embed = criar_embed("🩺 Diagnóstico do servidor", resumo,
                        "Vermelho" if falha_critica else "Esmeralda")
    for titulo, linhas in (("🔐 Permissões do bot", permissoes),
                           ("👥 Cargos, categorias e logs", organizacao),
                           ("🔌 Integrações e ambiente", integracoes)):
        corpo = "\n".join(linhas) or "—"
        embed.add_field(name=titulo, value=corpo[:1024], inline=False)
    embed.set_footer(text="Use /setup para cargos/categorias • /parceria para vitrine • /config e /logs para canais.")
    return embed, falha_critica


class SetupMainSelect(discord.ui.Select):
    def __init__(self):
        super().__init__(
            placeholder="⚙️ Selecione o módulo que deseja configurar...",
            options=[
                discord.SelectOption(label="Cargos da Equipe", value="cargos", emoji="👑", description="Definir Dono, Gerente, ADM e Suporte"),
                discord.SelectOption(label="Categorias de Canais", value="categorias", emoji="📂", description="Salas, pagamentos e atendimentos"),
                discord.SelectOption(label="Bloqueio de Diários", value="bloqueio", emoji="⏱️", description="Minutos antes do início para travar compra"),
                discord.SelectOption(label="Ver Configuração Atual", value="ver", emoji="📋", description="Resumo minimalista de tudo que está ativo"),
                discord.SelectOption(label="Diagnóstico Técnico", value="diagnostico", emoji="🩺", description="Auditar permissões e estrutura do servidor"),
            ],
        )

    async def callback(self, interaction: discord.Interaction):
        if not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("❌ Sem Permissão", "Apenas Dono ou Gerente.", "Vermelho"),
                ephemeral=True,
            )
        mod = self.values[0]
        if mod == "cargos":
            return await interaction.response.send_message(
                embed=criar_embed("👑 Cargos da Equipe", "Selecione abaixo o cargo correspondente a cada função:", "Cinza Escuro"),
                view=SetupCargosView(),
                ephemeral=True,
            )
        if mod == "categorias":
            return await interaction.response.send_message(
                embed=criar_embed("📂 Categorias do Servidor", "Selecione onde os canais automáticos serão criados:", "Cinza Escuro"),
                view=SetupCategoriasView(),
                ephemeral=True,
            )
        if mod == "bloqueio":
            atual = await obter_bloqueio_compra_min(interaction.guild.id)
            return await interaction.response.send_modal(ConfigurarBloqueioCompraModal(atual))
        if mod == "diagnostico":
            embed, _ = await montar_diagnostico_config(interaction.guild)
            return await interaction.response.send_message(embed=embed, ephemeral=True)

        cfg = await obter_config(interaction.guild.id)
        cargos_linhas = []
        for nome, chave in [("Dono", "cargo_dono"), ("Gerente", "cargo_gerente"), ("ADM", "cargo_mediador"), ("Suporte", "cargo_suporte")]:
            role = interaction.guild.get_role(cfg.get(chave, 0)) if cfg.get(chave) else None
            cargos_linhas.append(f"• **{nome}:** {role.mention if role else '`não definido`'}")

        cats_linhas = []
        for nome, chave in [("Premium", "cat_premium"), ("Básico", "cat_basico"), ("Pagamentos", "cat_pagamentos"), ("Tickets", "cat_tickets")]:
            canal = interaction.guild.get_channel(cfg.get(chave, 0)) if cfg.get(chave) else None
            cats_linhas.append(f"• **{nome}:** {canal.mention if canal else '`não definida`'}")

        bloq = await obter_bloqueio_compra_min(interaction.guild.id)
        parc_canal = interaction.guild.get_channel(cfg.get("canal_parcerias") or 0) if cfg.get("canal_parcerias") else None
        resumo = (
            "**👑 Cargos**\n" + "\n".join(cargos_linhas) + "\n\n"
            "**📂 Categorias**\n" + "\n".join(cats_linhas) + "\n\n"
            "**⚡ Operação**\n"
            f"• **Bloqueio de diários:** `{bloq} min` antes\n"
            f"• **PIX (Diários, Depósitos & Parcerias):** chave `/pix` individual de quem assumir\n"
            f"• **Vitrine de Parceiros:** {parc_canal.mention if parc_canal else '`usar /parceria`'}"
        )
        await interaction.response.send_message(
            embed=criar_embed("📋 Configuração Atual", resumo, "Cinza Escuro"),
            ephemeral=True,
        )


