# ==================== STAFF ONLINE / OFFLINE ====================

class StaffPainelSelect(discord.ui.Select):
    def __init__(self):
        super().__init__(
            placeholder="👥 Alterar meu status de serviço...",
            custom_id="ff_staff_sel_v12",
            options=[
                discord.SelectOption(
                    label="Entrar em Serviço",
                    value="on",
                    emoji="🟢",
                    description="Assumir atendimentos (bloqueia inscrição em diários)",
                ),
                discord.SelectOption(
                    label="Sair de Serviço",
                    value="off",
                    emoji="🔴",
                    description="Pausar atendimentos (libera inscrição em diários)",
                ),
            ],
        )

    async def callback(self, interaction: discord.Interaction):
        if not await usuario_equipe_com_suporte(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("❌ Sem Permissão", "Apenas membros da equipe.", "Vermelho"),
                ephemeral=True,
            )
        online = 1 if self.values[0] == "on" else 0
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("INSERT OR REPLACE INTO staff_status VALUES (?, ?, ?)", (interaction.user.id, interaction.guild.id, online))
            await db.commit()
        marcar_sujo()

        await StaffPainelView._atualizar_painel_msg(interaction)
        if online:
            await interaction.response.send_message(
                embed=criar_embed("🟢 Em Serviço", "Você está disponível para atendimentos (inscrição em diários pausada).", "Esmeralda"),
                ephemeral=True,
            )
        else:
            await interaction.response.send_message(
                embed=criar_embed("🔴 Fora de Serviço", "Atendimentos pausados — você está liberado para jogar nos diários.", "Cinza Escuro"),
                ephemeral=True,
            )


class StaffPainelView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)
        self.add_item(StaffPainelSelect())

    @staticmethod
    async def _montar_embed_staff(guild_id: int) -> discord.Embed:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            rows = await (await db.execute("SELECT * FROM staff_status WHERE guild_id = ?", (guild_id,))).fetchall()
        on_list = [f"🟢 {mencao(r['user_id'])}" for r in rows if r["online"]]
        off_list = [f"🔴 {mencao(r['user_id'])}" for r in rows if not r["online"]]
        desc = (
            "Selecione seu status no menu abaixo.\n"
            "-# 🟢 Em serviço: assume tickets • 🔴 Fora de serviço: liberado para jogar"
        )
        embed = criar_embed("👥 Plantão da Equipe", desc, "Cinza Escuro")
        embed.add_field(name="🟢 Em serviço", value="\n".join(on_list) or "*Nenhum*", inline=True)
        embed.add_field(name="🔴 Fora de serviço", value="\n".join(off_list) or "*Nenhum*", inline=True)
        return embed

    @staticmethod
    async def _atualizar_painel_msg(interaction: discord.Interaction):
        try:
            embed = await StaffPainelView._montar_embed_staff(interaction.guild.id)
            await interaction.message.edit(embed=embed, view=StaffPainelView())
        except Exception:
            pass


# ==================== EMBED BUILDER ====================

class EmbedCorSelect(discord.ui.Select):
    def __init__(self, page: int = 0):
        nomes = list(CORES_DICCIONARIO.keys())
        start = page * 25
        super().__init__(
            placeholder="🎨 Selecione a cor da embed...",
            options=[discord.SelectOption(label=n, value=n) for n in nomes[start:start+25]],
            row=page
        )

    async def callback(self, interaction: discord.Interaction):
        self.view.cor = self.values[0]
        await interaction.response.send_message(
            embed=criar_embed("🎨 Cor Selecionada", f"Cor definida como: **{self.values[0]}**", self.values[0]),
            ephemeral=True
        )


class EmbedBuilderView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=300)
        self.cor = "Cinza Escuro"
        self.add_item(EmbedCorSelect(0))
        if len(CORES_DICCIONARIO) > 25:
            self.add_item(EmbedCorSelect(1))
        sel = discord.ui.Select(
            placeholder="📝 Preencher e publicar card...",
            options=[
                discord.SelectOption(
                    label="Abrir Construtor de Card",
                    value="montar",
                    emoji="📝",
                    description="Preenche título, texto, imagem e publica neste canal",
                )
            ],
            row=2,
        )
        sel.callback = self._montar
        self.add_item(sel)

    async def _montar(self, interaction: discord.Interaction):
        await interaction.response.send_modal(EmbedBuilderModal(self.cor))


class EmbedBuilderModal(discord.ui.Modal, title="📝 Construtor de Embed"):
    titulo = discord.ui.TextInput(label="Título da Embed", max_length=256)
    descricao = discord.ui.TextInput(label="Descrição", style=discord.TextStyle.paragraph, max_length=4000)
    footer = discord.ui.TextInput(label="Rodapé (Opcional)", required=False)
    imagem = discord.ui.TextInput(label="URL Imagem Grande (Opcional)", required=False)
    thumbnail = discord.ui.TextInput(label="URL Thumbnail (Opcional)", required=False)

    def __init__(self, cor: str):
        super().__init__()
        self.cor = cor

    async def on_submit(self, interaction: discord.Interaction):
        embed = criar_embed(
            titulo=self.titulo.value,
            descricao=self.descricao.value,
            cor_nome=self.cor,
            footer=self.footer.value or "Fire Force",
            author=interaction.user.display_name,
            author_icon=interaction.user.display_avatar.url
        )
        if self.imagem.value:
            embed.set_image(url=self.imagem.value)
        if self.thumbnail.value:
            embed.set_thumbnail(url=self.thumbnail.value)

        await interaction.response.send_message(embed=embed)


# ==================== ENVIO DE SALA (ID E SENHA) ====================

async def enviar_sala(
    guild: discord.Guild,
    tipo: str,
    categoria: str,
    horario: str,
    sala_id: str,
    sala_senha: str,
    horario_id: Optional[int] = None,
):
    """Avisa todo mundo que a sala abriu no canal coletivo E envia ID + Senha na DM dos inscritos."""
    usuarios_dm: dict[int, tuple[Optional[discord.TextChannel], list[int]]] = {}
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        if horario_id:
            horarios = await (await db.execute(
                "SELECT * FROM horarios WHERE id = ? AND guild_id = ?",
                (int(horario_id), guild.id),
            )).fetchall()
        else:
            # Aceita tanto diários com ativo=1 quanto salas cujo canal oficial ainda está aberto
            # (evita falha silenciosa caso o ADM envie ou refaça o ID/Senha segundos após o horário dar :00).
            horarios = await (await db.execute(
                "SELECT * FROM horarios WHERE guild_id = ? AND tipo = ? AND categoria = ? AND horario = ? "
                "AND (ativo = 1 OR COALESCE(canal_tabela, 0) > 0) "
                "ORDER BY ativo DESC, id DESC",
                (guild.id, tipo, categoria, horario),
            )).fetchall()

        if not horarios:
            return 0

        total_jogadores = 0

        for h in horarios:
            mencoes_h = []
            canal = guild.get_channel(h["canal_tabela"]) if h["canal_tabela"] else None

            lotes = await (await db.execute(
                "SELECT * FROM slots WHERE horario_id = ? AND confirmado = 1", (h["id"],)
            )).fetchall()
            for lote in lotes:
                comp_id = int(lote["comprador_id"])
                num_vaga = int(lote["numero"] or 0)
                mencoes_h.append(mencao(comp_id))
                if comp_id not in usuarios_dm:
                    usuarios_dm[comp_id] = (canal, [])
                if num_vaga and num_vaga not in usuarios_dm[comp_id][1]:
                    usuarios_dm[comp_id][1].append(num_vaga)

                jogadores = await (await db.execute(
                    "SELECT * FROM slot_jogadores WHERE slot_id = ?", (lote["id"],)
                )).fetchall()
                total_jogadores += len(jogadores)
                for j in jogadores:
                    j_dict = dict(j)
                    disc_uid = j_dict.get("discord_user_id")
                    if disc_uid:
                        duid = int(disc_uid)
                        if duid not in usuarios_dm:
                            usuarios_dm[duid] = (canal, [])
                        if num_vaga and num_vaga not in usuarios_dm[duid][1]:
                            usuarios_dm[duid][1].append(num_vaga)

            if canal:
                for alvo_ow, perm_ow in (getattr(canal, "overwrites", None) or {}).items():
                    if getattr(alvo_ow, "id", None) and not getattr(alvo_ow, "bot", False) and not hasattr(alvo_ow, "permissions"):
                        if getattr(perm_ow, "view_channel", None) is True and getattr(perm_ow, "send_messages", None) is False:
                            uid_ow = int(alvo_ow.id)
                            if uid_ow not in usuarios_dm:
                                usuarios_dm[uid_ow] = (canal, [])

                ocupadas = (await (await db.execute(
                    "SELECT COUNT(*) FROM slots WHERE horario_id = ? AND confirmado = 1", (h["id"],)
                )).fetchone())[0]

                slots_data = await obter_slots_data(h["id"])

                embed_sala = criar_embed(
                    titulo="🚨 SALA LIBERADA!",
                    descricao=f"**{formatar_rotulo_diario(tipo, categoria)}** — `{horario}`\n"
                              f"**⏰ O diário começa em menos de 5 minutos!**\n\n"
                              f"**🆔 ID da sala** (toque para copiar)\n```\n{sala_id}\n```\n"
                              f"**🔑 Senha**\n```\n{sala_senha}\n```",
                    cor_nome="Esmeralda",
                    footer="Fire Force • Boa sorte e bom jogo!"
                )
                embed_tabela, png_tabela = await montar_tabela_visual(
                    dict(h), slots_data, ocupadas,
                    atualizado_em=agora_brt().strftime("%H:%M"),
                )

                mencoes_str = " ".join(dict.fromkeys(mencoes_h))
                aviso = f"🚨🚨🚨 {mencoes_str} 🚨🚨🚨" if mencoes_str else "🚨🚨🚨 **SALA LIBERADA!** 🚨🚨🚨"
                kwargs_lib: dict = {"embeds": [embed_sala, embed_tabela]}
                if png_tabela:
                    kwargs_lib["file"] = discord.File(io.BytesIO(png_tabela), filename="tabela_fireforce.png")

                try:
                    if len(aviso) > 1900:
                        await canal.send("🚨🚨🚨 **SALA LIBERADA!** 🚨🚨🚨", **kwargs_lib)
                        chunk = ""
                        for mencao_txt in dict.fromkeys(mencao_txt for mencao_txt in mencoes_h):
                            if len(chunk) + len(mencao_txt) > 1800:
                                await canal.send(chunk)
                                chunk = mencao_txt + " "
                            else:
                                chunk += mencao_txt + " "
                        if chunk:
                            await canal.send(chunk)
                    else:
                        await canal.send(aviso, **kwargs_lib)
                except Exception as erro_canal_sala:
                    _log_arquivo(f"[ENVIAR SALA] falha ao publicar no canal #{getattr(canal, 'id', 0)}: {erro_canal_sala}")

            await db.execute(
                "UPDATE horarios SET sala_id = ?, sala_senha = ?, alerta_ish_enviado = 1 WHERE id = ?",
                (sala_id, sala_senha, h["id"]),
            )

        await db.commit()

    # Ping direto na DM mostrando ID e Senha da sala (não bloqueia se o jogador tiver DM fechada)
    rotulo_dm = formatar_rotulo_diario(tipo, categoria)

    async def _enviar_dm_inscrito(uid_alvo: int, canal_ref, vagas_nums: list[int]):
        try:
            alvo = guild.get_member(uid_alvo) or bot.get_user(uid_alvo)
            if alvo is None:
                alvo = await bot.fetch_user(uid_alvo)
            if not alvo or getattr(alvo, "bot", False):
                return
            vagas_str = ", ".join(f"`#{n}`" for n in sorted(vagas_nums)) if vagas_nums else "`Confirmada`"
            canal_str = f"\n• **Canal da Sala:** {canal_ref.mention}" if canal_ref else ""
            emb_dm = criar_embed(
                "🚨 SUA SALA ABRIU! • ID e Senha",
                f"**{rotulo_dm}** — `{horario}` ({guild.name})\n"
                f"• **Sua Vaga:** {vagas_str}{canal_str}\n"
                f"• **⏰ Atenção:** Entre imediatamente na sala personalizada!\n\n"
                f"**🆔 ID da Sala** *(toque para copiar)*\n```\n{sala_id}\n```\n"
                f"**🔑 Senha**\n```\n{sala_senha}\n```",
                "Esmeralda",
                footer="Fire Force • Bom jogo!",
            )
            await alvo.send(embed=emb_dm)
        except Exception:
            pass

    if usuarios_dm:
        await asyncio.gather(
            *(_enviar_dm_inscrito(uid, info[0], info[1]) for uid, info in usuarios_dm.items()),
            return_exceptions=True,
        )

    return total_jogadores


# ==================== LOOPS DE TAREFAS ====================

RESERVA_MINUTOS = 30          # reserva sem pagamento confirmado expira nesse tempo
LOOP_VERIFICACAO = 30         # de quanto em quanto tempo roda a checagem


async def processar_repeticao_diaria() -> list[tuple[int, int]]:
    """Vira o ciclo diário (após 00:00 BRT) nos painéis com Repetição Diária ativa.

    Preserva o histórico de horários que tiveram jogadores confirmados (arquivando a
    edição anterior como `ativo = 0`, sem apagar o canal privado da partida — que é
    removido manualmente pelo Dono/Gerente) e libera uma nova edição limpa para hoje.
    """
    paineis_atualizar = set()
    avisos_fechar = []
    estornos = []
    hoje = agora_brt().strftime("%Y-%m-%d")

    async with _lock_repeticao_diaria:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            linhas = await (await db.execute(
                "SELECT h.*, COALESCE(p.repetir_diario, 0) AS repetir_diario "
                "FROM horarios h JOIN paineis p ON h.painel_id = p.id "
                "WHERE h.ativo = 1 AND COALESCE(p.repetir_diario, 0) = 1"
            )).fetchall()

            alterou = False
            for row in linhas:
                h = dict(row)
                ciclo = (h.get("data_ciclo") or "").strip()
                if not ciclo:
                    await db.execute("UPDATE horarios SET data_ciclo = ? WHERE id = ?", (hoje, h["id"]))
                    alterou = True
                    continue
                if ciclo >= hoje:
                    continue

                # Virada de dia! Cancela reservas não aprovadas que sobraram de ontem
                pendentes = await (await db.execute(
                    "SELECT * FROM slots WHERE horario_id = ? AND confirmado = 0", (h["id"],)
                )).fetchall()
                for p in pendentes:
                    p_dict = dict(p)
                    if int(p_dict.get("pago_moedas") or 0) == 1:
                        estornos.append(p_dict)
                    await db.execute("DELETE FROM slot_jogadores WHERE slot_id = ?", (p["id"],))
                    await db.execute("DELETE FROM slots WHERE id = ?", (p["id"],))
                    guild_p = bot.get_guild(int(p["guild_id"]))
                    canal_p = guild_p.get_channel(int(p["canal_pag"])) if guild_p and p["canal_pag"] else None
                    if canal_p:
                        avisos_fechar.append((canal_p, "⌛ Reserva Encerrada", "O ciclo anterior deste diário encerrou."))

                confirmadas = (await (await db.execute(
                    "SELECT COUNT(*) FROM slots WHERE horario_id = ? AND confirmado = 1", (h["id"],)
                )).fetchone())[0]

                if confirmadas > 0 or h.get("canal_tabela"):
                    await db.execute(
                        "UPDATE horarios SET ativo = 0, lotes_usados = ? WHERE id = ?",
                        (confirmadas, h["id"]),
                    )
                    ja_existe_hoje = await (await db.execute(
                        "SELECT 1 FROM horarios WHERE painel_id = ? AND horario = ? AND ativo = 1 AND data_ciclo = ?",
                        (h["painel_id"], h["horario"], hoje),
                    )).fetchone()
                    await db.execute("DELETE FROM fila_espera WHERE horario_id = ?", (h["id"],))
                    if not ja_existe_hoje:
                        await db.execute(
                            "INSERT INTO horarios (guild_id, painel_id, tipo, categoria, horario, valor, premiacao, "
                            "vagas_total, lotes_usados, ativo, data_ciclo, encerrado_hoje, alerta_ish_enviado) "
                            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, 1, ?, 0, 0)",
                            (
                                h["guild_id"], h["painel_id"], h["tipo"], h["categoria"],
                                h["horario"], h["valor"], h["premiacao"], h.get("vagas_total") or 48, hoje,
                            ),
                        )
                else:
                    await db.execute("DELETE FROM fila_espera WHERE horario_id = ?", (h["id"],))
                    await db.execute(
                        "UPDATE horarios SET data_ciclo = ?, lotes_usados = 0, encerrado_hoje = 0, alerta_ish_enviado = 0, "
                        "sala_id = NULL, sala_senha = NULL, canal_tabela = NULL, msg_tabela = NULL "
                        "WHERE id = ?",
                        (hoje, h["id"]),
                    )

                paineis_atualizar.add((int(h["guild_id"]), int(h["painel_id"])))
                alterou = True

            # Descarta agendamentos de /ish não enviados de dias anteriores
            cur_salas = await db.execute(
                "UPDATE salas SET enviado = 1 WHERE enviado = 0 AND substr(COALESCE(criado_em, ''), 1, 10) < ?",
                (hoje,),
            )
            if cur_salas.rowcount:
                alterou = True

            if alterou:
                await db.commit()
                marcar_sujo()

    for p_dict in estornos:
        guild_e = bot.get_guild(int(p_dict["guild_id"]))
        await estornar_moedas_reserva_se_necessario(guild_e, p_dict, "virada do ciclo diário sem aprovação")

    for canal, titulo, msg in avisos_fechar:
        _disparar_tarefa_rastreada(_fechar_canal_reserva(canal, msg, titulo))

    return list(paineis_atualizar)


async def loop_expirar():
    """Encerra diários que já passaram, processa repetição diária, cancela reservas
    sem pagamento e fecha os canais de pagamento pendentes."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            paineis_virada = await processar_repeticao_diaria()
            agora = agora_brt()
            hoje = agora.strftime("%Y-%m-%d")
            avisos = []          # (canal, titulo, mensagem)
            estornos_moedas = []
            paineis_para_atualizar = list(paineis_virada)

            async with _lock_aprovacao:
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    db.row_factory = aiosqlite.Row

                    # ---------- 1) reservas pendentes antigas (sem pagamento e sem moedas debitadas) ----------
                    # Se um ADM já assumiu e enviou o QR Code PIX, dá fôlego dobrado (mín. 25 min) p/ não derrubar pagamento em análise!
                    limite_sem_adm = (agora - datetime.timedelta(minutes=RESERVA_MINUTOS)).isoformat()
                    limite_com_adm = (agora - datetime.timedelta(minutes=max(RESERVA_MINUTOS * 2, 25))).isoformat()
                    pendentes_antigas = await (await db.execute(
                        "SELECT * FROM slots WHERE confirmado = 0 AND COALESCE(pago_moedas, 0) = 0 "
                        "AND ((COALESCE(assumido_por, 0) = 0 AND criado_em < ?) "
                        "     OR (COALESCE(assumido_por, 0) > 0 AND criado_em < ?))",
                        (limite_sem_adm, limite_com_adm),
                    )).fetchall()

                    horarios_vaga_aberta = set()
                    for p in pendentes_antigas:
                        if p["cupom_id"]:
                            await db.execute("UPDATE cupons SET usos_atuais = MAX(0, usos_atuais - 1) WHERE id = ?", (p["cupom_id"],))
                            await db.execute(
                                "UPDATE cupons_usados SET usos = MAX(0, usos - 1) WHERE cupom_id = ? AND user_id = ?",
                                (p["cupom_id"], p["comprador_id"]),
                            )
                        h_exp = await (await db.execute(
                            "SELECT painel_id FROM horarios WHERE id = ?", (p["horario_id"],)
                        )).fetchone()
                        if h_exp:
                            paineis_para_atualizar.append((int(p["guild_id"]), int(h_exp["painel_id"])))
                        horarios_vaga_aberta.add((int(p["guild_id"]), int(p["horario_id"])))
                        await db.execute("DELETE FROM slot_jogadores WHERE slot_id = ?", (p["id"],))
                        await db.execute("DELETE FROM slots WHERE id = ?", (p["id"],))
                        guild = bot.get_guild(p["guild_id"])
                        canal = guild.get_channel(p["canal_pag"]) if guild and p["canal_pag"] else None
                        if canal:
                            avisos.append((
                                canal,
                                "⌛ Reserva Expirada",
                                "A reserva ficou sem confirmação de pagamento dentro do prazo e foi cancelada.\n"
                                "Sem problema: é só fazer a inscrição novamente quando quiser."
                            ))
                    if pendentes_antigas:
                        await db.commit()

                    # ---------- 2) diários que já começaram ----------
                    horarios = await (await db.execute(
                        "SELECT h.*, COALESCE(p.repetir_diario, 0) AS repetir_diario "
                        "FROM horarios h LEFT JOIN paineis p ON h.painel_id = p.id WHERE h.ativo = 1"
                    )).fetchall()
                    for h in horarios:
                        h_dict = dict(h)
                        if (horario_para_datetime(h["horario"]) - agora).total_seconds() >= 0:
                            continue

                        repetir = bool(h_dict.get("repetir_diario", 0))
                        if repetir and bool(h_dict.get("encerrado_hoje", 0)) and (h_dict.get("data_ciclo") == hoje):
                            continue

                        pendentes = await (await db.execute(
                            "SELECT * FROM slots WHERE horario_id = ? AND confirmado = 0", (h["id"],)
                        )).fetchall()
                        for p in pendentes:
                            p_dict = dict(p)
                            if int(p_dict.get("pago_moedas") or 0) == 1 or int(p_dict.get("usou_vaga_vip") or 0) == 1:
                                estornos_moedas.append(p_dict)
                            if p["cupom_id"]:
                                await db.execute("UPDATE cupons SET usos_atuais = MAX(0, usos_atuais - 1) WHERE id = ?", (p["cupom_id"],))
                                await db.execute(
                                    "UPDATE cupons_usados SET usos = MAX(0, usos - 1) WHERE cupom_id = ? AND user_id = ?",
                                    (p["cupom_id"], p["comprador_id"]),
                                )
                            await db.execute("DELETE FROM slot_jogadores WHERE slot_id = ?", (p["id"],))
                            await db.execute("DELETE FROM slots WHERE id = ?", (p["id"],))
                            guild = bot.get_guild(p["guild_id"])
                            canal = guild.get_channel(p["canal_pag"]) if guild and p["canal_pag"] else None
                            if canal:
                                if int(p_dict.get("usou_vaga_vip") or 0) == 1:
                                    msg_canc = "O diário já começou sem a liberação do ADM. Sua reserva foi encerrada e sua **🎟️ Vaga VIP** foi devolvida intacta."
                                elif int(p_dict.get("pago_moedas") or 0) == 1:
                                    msg_canc = "O diário já começou sem a liberação do ADM. Sua reserva foi encerrada e as moedas foram estornadas para sua carteira."
                                else:
                                    msg_canc = "O diário já começou e esta reserva foi cancelada."
                                avisos.append((canal, "⌛ Reserva Encerrada", msg_canc))

                        confirmadas = (await (await db.execute(
                            "SELECT COUNT(*) FROM slots WHERE horario_id = ? AND confirmado = 1", (h["id"],)
                        )).fetchone())[0]

                        if repetir:
                            # Mantém ativo=1 para permanecer visível no painel até liberar amanhã!
                            await db.execute(
                                "UPDATE horarios SET encerrado_hoje = 1, data_ciclo = ?, lotes_usados = ? WHERE id = ?",
                                (hoje, confirmadas, h["id"]),
                            )
                        else:
                            await db.execute(
                                "UPDATE horarios SET ativo = 0, lotes_usados = ? WHERE id = ?",
                                (confirmadas, h["id"]),
                            )
                        paineis_para_atualizar.append((h["guild_id"], h["painel_id"]))

                    await db.commit()

            for p_dict in estornos_moedas:
                guild_e = bot.get_guild(int(p_dict["guild_id"]))
                await estornar_moedas_reserva_se_necessario(guild_e, p_dict, "diário iniciou antes da liberação")

            # ---------- ações fora do banco ----------
            vistos_paineis = set()
            for guild_id, painel_id in paineis_para_atualizar:
                if (guild_id, painel_id) in vistos_paineis:
                    continue
                vistos_paineis.add((guild_id, painel_id))
                guild = bot.get_guild(guild_id)
                if guild:
                    try:
                        await rebuild_painel(guild, painel_id)
                    except Exception:
                        pass

            for guild_id_f, horario_id_f in horarios_vaga_aberta:
                guild_f = bot.get_guild(guild_id_f)
                if guild_f:
                    try:
                        await notificar_fila_espera(guild_f, horario_id_f)
                    except Exception:
                        pass

            for canal, titulo, mensagem in avisos:
                _disparar_tarefa_rastreada(_fechar_canal_reserva(canal, mensagem, titulo))

        except Exception as e:
            print("Erro no loop de expiração:", e)
        await asyncio.sleep(LOOP_VERIFICACAO)


async def loop_salas():
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            agora = agora_brt()
            hoje_str = agora.strftime("%Y-%m-%d")
            async with aiosqlite.connect(DATABASE_FILE) as db:
                db.row_factory = aiosqlite.Row
                salas = await (await db.execute("SELECT * FROM salas WHERE enviado = 0")).fetchall()
                candidatos_alerta = await (await db.execute(
                    "SELECT * FROM horarios WHERE ativo = 1 AND COALESCE(encerrado_hoje, 0) = 0 AND COALESCE(alerta_ish_enviado, 0) = 0"
                )).fetchall()

            # 1) Alerta automático 10 minutos antes se houver jogadores confirmados e nenhum ID/Senha cadastrado
            for h in candidatos_alerta:
                h_d = dict(h)
                dif_h = (horario_para_datetime(h_d["horario"]) - agora).total_seconds()
                if not (0 < dif_h <= 600):
                    continue
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    confirmados_h = (await (await db.execute(
                        "SELECT COUNT(*) FROM slots WHERE horario_id = ? AND confirmado = 1", (h_d["id"],)
                    )).fetchone())[0]
                    ja_tem_sala = await (await db.execute(
                        "SELECT 1 FROM salas WHERE guild_id = ? AND tipo = ? AND categoria = ? AND horario = ? "
                        "AND (enviado = 0 OR substr(COALESCE(criado_em, ''), 1, 10) = ?) LIMIT 1",
                        (h_d["guild_id"], h_d["tipo"], h_d["categoria"], h_d["horario"], hoje_str),
                    )).fetchone()
                    if confirmados_h <= 0 or ja_tem_sala or h_d.get("sala_id"):
                        if ja_tem_sala or h_d.get("sala_id"):
                            await db.execute("UPDATE horarios SET alerta_ish_enviado = 1 WHERE id = ?", (h_d["id"],))
                            await db.commit()
                        continue
                    await db.execute("UPDATE horarios SET alerta_ish_enviado = 1 WHERE id = ?", (h_d["id"],))
                    await db.commit()

                guild_h = bot.get_guild(int(h_d["guild_id"]))
                if guild_h:
                    cfg_h = await obter_config(guild_h.id)
                    mencoes = []
                    for ck in ("cargo_dono", "cargo_gerente"):
                        if cfg_h.get(ck):
                            rl = guild_h.get_role(int(cfg_h[ck]))
                            if rl:
                                mencoes.append(rl.mention)
                    canal_tab_ref = f"<#{h_d['canal_tabela']}>" if h_d.get("canal_tabela") else "`canal da sala`"
                    canal_alerta_id = cfg_h.get("canal_logs_suporte") or cfg_h.get("canal_logs")
                    canal_alerta = guild_h.get_channel(int(canal_alerta_id)) if canal_alerta_id else None
                    emb_alerta = criar_embed(
                        "⏰ Alerta 10 Minutos — Sala Sem ID e Senha!",
                        f"O diário **{formatar_rotulo_diario(h_d['tipo'], h_d['categoria'])}** das **`{h_d['horario']}`** "
                        f"tem **`{confirmados_h}`** vaga(s) confirmada(s) e começa em **`~{max(1, int(dif_h // 60))} min`**, "
                        f"mas ainda **não possui ID e Senha** registrados!\n\n"
                        f"• Abra {canal_tab_ref} e selecione **🔑 Definir ID e Senha desta Sala** *(ou use `/ish`)*.",
                        "Amarelo",
                    )
                    if canal_alerta:
                        try:
                            await canal_alerta.send(content=" ".join(mencoes).strip() or None, embed=emb_alerta)
                        except Exception:
                            pass
                    else:
                        await registrar_log(
                            guild_h,
                            "⏰ ALERTA SALA",
                            "⏰ Sala sem ID/Senha a 10 min do início",
                            f"{formatar_rotulo_diario(h_d['tipo'], h_d['categoria'])} às `{h_d['horario']}` ({confirmados_h} confirmados).",
                            "Amarelo",
                        )

            # 2) Envio automático do ID e Senha 5 minutos antes (tolerância até -15 min p/ nunca perder virada de minuto)
            for s in salas:
                diferenca = (horario_para_datetime(s["horario"]) - agora).total_seconds()
                if -900 <= diferenca <= 300:
                    async with aiosqlite.connect(DATABASE_FILE) as db:
                        await db.execute("DELETE FROM salas WHERE id = ?", (s["id"],))
                        await db.commit()
                    marcar_sujo()
                    guild = bot.get_guild(s["guild_id"])
                    if guild:
                        try:
                            await enviar_sala(guild, s["tipo"], s["categoria"], s["horario"], s["sala_id"], s["sala_senha"])
                        except Exception as erro_sala:
                            _log_arquivo(f"[LOOP SALAS] erro ao entregar sala #{s['id']}: {erro_sala}")
        except Exception as e:
            print("Erro no loop de salas:", e)
        await asyncio.sleep(15)


async def loop_tabelas():
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            await processar_repeticao_diaria()
            async with aiosqlite.connect(DATABASE_FILE) as db:
                db.row_factory = aiosqlite.Row
                horarios = await (await db.execute("SELECT * FROM horarios WHERE ativo = 1 AND canal_tabela IS NOT NULL AND canal_tabela > 0")).fetchall()
                paineis = await (await db.execute(
                    "SELECT DISTINCT painel_id, guild_id FROM horarios WHERE ativo = 1"
                )).fetchall()

            for h in horarios:
                guild = bot.get_guild(int(h["guild_id"]))
                if guild:
                    try:
                        await atualizar_tabela(guild, h["id"])
                    except Exception as e:
                        print(f"Erro ao atualizar tabela #{h['id']}:", e)

            # Atualiza vagas e contagem regressiva dos seletores publicados, mantendo a página aberta.
            for p in paineis:
                guild = bot.get_guild(int(p["guild_id"]))
                if guild:
                    try:
                        await rebuild_painel(guild, int(p["painel_id"]))
                    except Exception as e:
                        print(f"Erro ao atualizar painel #{p['painel_id']}:", e)
        except Exception as e:
            print("Erro no loop de tabelas:", e)
        await asyncio.sleep(15)


