class ResetarDiariosView(discord.ui.View):
    """Confirmação minimalista protegida por autor para arquivar painéis de diários."""

    def __init__(self, autor_id: int):
        super().__init__(timeout=90)
        self.autor_id = int(autor_id)
        sel = discord.ui.Select(
            placeholder="🧹 Confirme ou cancele o arquivamento...",
            options=[
                discord.SelectOption(
                    label="Arquivar e Remover Painéis",
                    value="confirmar",
                    emoji="🧹",
                    description="Arquiva os horários atuais e limpa os painéis publicados",
                ),
                discord.SelectOption(
                    label="Cancelar Operação",
                    value="cancelar",
                    emoji="↩️",
                    description="Mantém todos os painéis e horários como estão",
                ),
            ],
        )
        sel.callback = self._decidir
        self.add_item(sel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.autor_id:
            await interaction.response.send_message(
                embed=criar_embed("🔒 Confirmação privada", "Só quem iniciou o reset pode confirmar ou cancelar.", "Vermelho"),
                ephemeral=True,
            )
            return False
        return True

    async def _decidir(self, interaction: discord.Interaction):
        if interaction.data["values"][0] == "cancelar":
            return await interaction.response.edit_message(
                embed=criar_embed("↩️ Reset Cancelado", "Nenhum painel ou diário foi alterado.", "Cinza Escuro"),
                view=None,
            )
        if not interaction.guild or not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Ação não autorizada", "É necessário acesso de Dono/Gerente.", "Vermelho"),
                ephemeral=True,
            )
        await interaction.response.defer()
        ok, mensagem, _ = await executar_reset_diarios(interaction.guild)
        if ok:
            await registrar_log(
                interaction.guild, "🧹 RESET", "🧹 Painéis arquivados",
                f"Por {interaction.user.mention}. {mensagem}", "Amarelo"
            )
        await interaction.edit_original_response(
            embed=criar_embed("✅ Reset Concluído" if ok else "⏸️ Reset Bloqueado", mensagem, "Esmeralda" if ok else "Amarelo"),
            view=None if ok else ResetarDiariosView(self.autor_id),
        )


async def executar_reset_diarios(guild: discord.Guild) -> tuple[bool, str, int]:
    """Arquiva horários, preserva inscrições e remove os painéis publicados.

    A operação é serializada no SQLite. Não inicia se houver pagamentos/reservas
    pendentes, evitando que uma compra em andamento fique sem horário associado.
    """
    async with _lock_reset_diarios:
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")
            pendentes = (await (await db.execute(
                "SELECT COUNT(*) FROM slots WHERE guild_id = ? AND confirmado = 0", (guild.id,)
            )).fetchone())[0]
            if pendentes:
                await db.rollback()
                return (False,
                        f"Há **{pendentes} reserva(s) sem pagamento confirmado**. Resolva ou aguarde a expiração "
                        "antes do reset; não alterei nada.", 0)

            paineis = await (await db.execute(
                "SELECT * FROM paineis WHERE guild_id = ?", (guild.id,)
            )).fetchall()
            horarios = (await (await db.execute(
                "SELECT COUNT(*) FROM horarios WHERE guild_id = ?", (guild.id,)
            )).fetchone())[0]
            inscricoes = (await (await db.execute(
                "SELECT COUNT(*) FROM slots WHERE guild_id = ? AND confirmado = 1", (guild.id,)
            )).fetchone())[0]

            # Mantém o histórico de horários/inscrições para relatórios e auditoria.
            await db.execute(
                "UPDATE horarios SET ativo = 0, painel_id = NULL WHERE guild_id = ?", (guild.id,)
            )
            await db.execute("DELETE FROM paineis WHERE guild_id = ?", (guild.id,))
            await db.commit()

        # Mensagens antigas são removidas depois do commit; se o Discord falhar,
        # os selects já não conseguem abrir horários arquivados.
        for painel in paineis:
            if not painel["channel_id"] or not painel["message_id"]:
                continue
            canal = guild.get_channel(int(painel["channel_id"]))
            if not canal:
                continue
            try:
                msg = await canal.fetch_message(int(painel["message_id"]))
                await msg.delete()
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                continue
            except Exception:
                continue

        mensagem = (f"Arquivei **{horarios} horário(s)** e removi **{len(paineis)} painel(is)**. "
                    f"As **{inscricoes} inscrição(ões) confirmada(s)**, pagamentos e carteira foram preservados.")
        return True, mensagem, len(paineis)


