@bot.tree.command(name="info", description="ℹ️ Exibir informações técnicas do bot")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
async def cmd_info(interaction: discord.Interaction):
    if not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas Dono ou Gerente.", "Vermelho"), ephemeral=True)
    embed = criar_embed("🔥 Fire Force Bot", f"Sistema Executivo • **Versão {VERSAO_BOT}**", "Cinza Escuro")
    embed.add_field(name="🧩 Versão", value=f"`v{VERSAO_BOT}`", inline=True)
    embed.add_field(name="📊 Servidores", value=f"`{len(bot.guilds)}`", inline=True)
    try:
        latencia_txt = f"{round(bot.latency * 1000)}ms"
    except (ValueError, TypeError, OverflowError):
        latencia_txt = "medindo..."
    embed.add_field(name="🏓 Latência", value=f"`{latencia_txt}`", inline=True)

    async with aiosqlite.connect(DATABASE_FILE) as db:
        horarios_cnt = await (await db.execute("SELECT COUNT(*) FROM horarios WHERE guild_id = ? AND ativo = 1", (interaction.guild.id,))).fetchone()
        slots_cnt = await (await db.execute("SELECT COUNT(*) FROM slots WHERE guild_id = ? AND confirmado = 1", (interaction.guild.id,))).fetchone()
        cache_cnt = await (await db.execute("SELECT COUNT(*) FROM ff_cache")).fetchone()

    embed.add_field(name="🔥 Horários Ativos", value=f"`{horarios_cnt[0]}`", inline=True)
    embed.add_field(name="🎫 Inscrições Ativas", value=f"`{slots_cnt[0]}`", inline=True)
    embed.add_field(name="🗂️ IDs em cache", value=f"`{cache_cnt[0]}`", inline=True)
    embed.add_field(name="📡 Consulta FF (provedores)", value=ff_status_provedores(), inline=False)

    await interaction.response.send_message(embed=embed, ephemeral=True)



# ==================== v13.1: CARD VISUAL HD (/perfil • VERMELHO ESCURO & PRETO) ====================

_CARD_FONT_DIRS = (
    r"C:\Windows\Fonts",
    "/usr/share/fonts/truetype/dejavu",
    "/usr/share/fonts/truetype/liberation",
)
_CARD_FONT_CANDIDATES = {
    "black": ("seguibl.ttf", "arialbd.ttf", "DejaVuSans-Bold.ttf", "LiberationSans-Bold.ttf"),
    "bold": ("segoeuib.ttf", "bahnschrift.ttf", "arialbd.ttf", "DejaVuSans-Bold.ttf", "LiberationSans-Bold.ttf"),
    "regular": ("seguisb.ttf", "segoeui.ttf", "arial.ttf", "DejaVuSans.ttf", "LiberationSans-Regular.ttf"),
    "mono": ("consolab.ttf", "DejaVuSansMono-Bold.ttf", "DejaVuSans-Bold.ttf"),
}
_CARD_FONT_CACHE: dict = {}
_CARD_NOTDEF_CACHE: dict = {}


def _card_carregar_fonte(estilo: str, tamanho: int):
    chave = (estilo, int(tamanho))
    if chave in _CARD_FONT_CACHE:
        return _CARD_FONT_CACHE[chave]
    for pasta in _CARD_FONT_DIRS:
        for arq in _CARD_FONT_CANDIDATES.get(estilo, _CARD_FONT_CANDIDATES["bold"]):
            caminho = os.path.join(pasta, arq)
            if os.path.exists(caminho):
                try:
                    fonte = ImageFont.truetype(caminho, int(tamanho))
                    _CARD_FONT_CACHE[chave] = fonte
                    return fonte
                except Exception:
                    continue
    fonte = ImageFont.load_default(size=int(tamanho))
    _CARD_FONT_CACHE[chave] = fonte
    return fonte


def _card_limpar_texto(texto: str, fonte, fallback: str = "", remover_simbolos: bool = False) -> str:
    txt = unicodedata.normalize("NFKC", str(texto or ""))
    fid = id(fonte)
    if fid not in _CARD_NOTDEF_CACHE:
        try:
            _CARD_NOTDEF_CACHE[fid] = bytes(fonte.getmask("\uffff"))
        except Exception:
            _CARD_NOTDEF_CACHE[fid] = b""
    notdef = _CARD_NOTDEF_CACHE[fid]
    saida = []
    for ch in txt:
        if ch in (" ", "\t"):
            saida.append(" ")
            continue
        codigo = ord(ch)
        if codigo < 32 or (0xFE00 <= codigo <= 0xFE0F) or (0x1F000 <= codigo <= 0x1FAFF):
            continue
        if remover_simbolos and ((0x2600 <= codigo <= 0x27BF) or (0x2300 <= codigo <= 0x23FF)):
            continue
        if notdef:
            try:
                if bytes(fonte.getmask(ch)) == notdef:
                    continue
            except Exception:
                continue
        saida.append(ch)
    limpo = " ".join("".join(saida).split())
    return limpo if limpo else fallback


def _card_truncar_px(draw, texto: str, fonte, larg_max: int, remover_simbolos: bool = False) -> str:
    texto = _card_limpar_texto(texto, fonte, "—", remover_simbolos=remover_simbolos)
    if draw.textlength(texto, font=fonte) <= larg_max:
        return texto
    elipse = "..."
    for tam in range(len(texto), 0, -1):
        cand = texto[:tam].rstrip() + elipse
        if draw.textlength(cand, font=fonte) <= larg_max:
            return cand
    return elipse


def _card_ajustar_titulo(draw, texto: str, estilo: str, tam_max: int, tam_min: int, larg_max: int, remover_simbolos: bool = False):
    for tam in range(tam_max, tam_min - 1, -2):
        f = _card_carregar_fonte(estilo, tam)
        limpo = _card_limpar_texto(texto, f, "", remover_simbolos=remover_simbolos)
        if not limpo:
            continue
        if draw.textlength(limpo, font=f) <= larg_max:
            return f, limpo
    f = _card_carregar_fonte(estilo, tam_min)
    return f, _card_truncar_px(draw, texto, f, larg_max, remover_simbolos=remover_simbolos)


def _card_pts_chanfro(x1: float, y1: float, x2: float, y2: float,
                      c_tl: float = 18, c_tr: float = 0, c_br: float = 18, c_bl: float = 0):
    pts = []
    if c_tl > 0:
        pts.extend([(x1, y1 + c_tl), (x1 + c_tl, y1)])
    else:
        pts.append((x1, y1))
    if c_tr > 0:
        pts.extend([(x2 - c_tr, y1), (x2, y1 + c_tr)])
    else:
        pts.append((x2, y1))
    if c_br > 0:
        pts.extend([(x2, y2 - c_br), (x2 - c_br, y2)])
    else:
        pts.append((x2, y2))
    if c_bl > 0:
        pts.extend([(x1 + c_bl, y2), (x1, y2 - c_bl)])
    else:
        pts.append((x1, y2))
    return pts


def _card_gradiente_vertical(w: int, h: int, cor_topo: tuple, cor_base: tuple):
    col = Image.new("RGBA", (1, 64))
    px = col.load()
    for y in range(64):
        t = y / 63.0
        px[0, y] = tuple(int(cor_topo[i] + (cor_base[i] - cor_topo[i]) * t) for i in range(4))
    return col.resize((w, h), Image.Resampling.BILINEAR)


def _card_glow_radial_local(canvas, cx: int, cy: int, rx: int, ry: int, cor_rgb: tuple, alpha_max: int):
    pad_x, pad_y = int(rx * 1.35), int(ry * 1.35)
    x1, y1 = max(0, cx - pad_x), max(0, cy - pad_y)
    x2, y2 = min(canvas.width, cx + pad_x), min(canvas.height, cy + pad_y)
    bw, bh = x2 - x1, y2 - y1
    if bw <= 8 or bh <= 8:
        return
    gw, gh = max(32, bw // 4), max(32, bh // 4)
    sx, sy = gw / bw, gh / bh
    sub = Image.new("RGBA", (gw, gh), (0, 0, 0, 0))
    d = ImageDraw.Draw(sub)
    lcx, lcy = (cx - x1) * sx, (cy - y1) * sy
    for passo in range(10, 0, -1):
        frac = passo / 10.0
        a = min(255, int(alpha_max * (1.0 - (passo - 1) / 10.0) ** 1.85))
        prx, pry = rx * sx * frac, ry * sy * frac
        d.ellipse((lcx - prx, lcy - pry, lcx + prx, lcy + pry), fill=(*cor_rgb, a))
    sub = sub.filter(ImageFilter.GaussianBlur(radius=max(8, int(min(gw, gh) * 0.14))))
    sub = sub.resize((bw, bh), Image.Resampling.BILINEAR)
    canvas.alpha_composite(sub, dest=(x1, y1))


def _card_painel_tatico(
    canvas,
    box: tuple,
    c_tl: int = 28,
    c_tr: int = 8,
    c_br: int = 28,
    c_bl: int = 8,
    topo_rgba=(18, 6, 8, 248),
    base_rgba=(6, 5, 7, 252),
    borda_rgba=(118, 12, 24, 235),
    borda_interna_rgba=(44, 10, 16, 195),
    acento_topo: bool = True,
    acento_esq: bool = False,
):
    x1, y1, x2, y2 = box
    pad = 18
    bx1, by1 = max(0, x1 - pad), max(0, y1 - pad)
    bx2, by2 = min(canvas.width, x2 + pad), min(canvas.height, y2 + pad)
    bw, bh = bx2 - bx1, by2 - by1
    lx1, ly1, lx2, ly2 = x1 - bx1, y1 - by1, x2 - bx1, y2 - by1
    pw, ph = lx2 - lx1, ly2 - ly1

    sub = Image.new("RGBA", (bw, bh), (0, 0, 0, 0))
    ds = ImageDraw.Draw(sub)
    sombra_pts = _card_pts_chanfro(lx1 + 6, ly1 + 10, lx2 + 6, ly2 + 10, c_tl, c_tr, c_br, c_bl)
    ds.polygon(sombra_pts, fill=(0, 0, 0, 175))
    sub = sub.filter(ImageFilter.GaussianBlur(radius=6))

    grad = _card_gradiente_vertical(pw, ph, topo_rgba, base_rgba)
    tex = Image.new("RGBA", (pw, ph), (0, 0, 0, 0))
    dt = ImageDraw.Draw(tex)
    for k in range(int(pw * 0.45), pw + ph, 32):
        dt.line([(k, 0), (k - int(ph * 0.55), int(ph * 0.55))], fill=(155, 14, 24, 14), width=6)
    grad = Image.alpha_composite(grad, tex)
    _card_glow_radial_local(grad, int(pw * 0.12), int(ph * 0.08), int(pw * 0.48), int(ph * 0.48), (128, 6, 12), 34)

    masc = Image.new("L", (pw, ph), 0)
    ImageDraw.Draw(masc).polygon(_card_pts_chanfro(0, 0, pw, ph, c_tl, c_tr, c_br, c_bl), fill=255)
    painel_img = Image.new("RGBA", (bw, bh), (0, 0, 0, 0))
    painel_img.paste(grad, (lx1, ly1), masc)
    sub = Image.alpha_composite(sub, painel_img)

    d = ImageDraw.Draw(sub)
    pts = _card_pts_chanfro(lx1, ly1, lx2, ly2, c_tl, c_tr, c_br, c_bl)
    pts_in = _card_pts_chanfro(
        lx1 + 6, ly1 + 6, lx2 - 6, ly2 - 6,
        max(0, c_tl - 5), max(0, c_tr - 4), max(0, c_br - 5), max(0, c_bl - 4),
    )
    d.line(pts_in + [pts_in[0]], fill=borda_interna_rgba, width=2)
    d.line(pts + [pts[0]], fill=borda_rgba, width=3)

    if acento_topo:
        ax1 = lx1 + c_tl + 8
        ax2 = min(lx2 - c_tr - 8, lx1 + int(pw * 0.44))
        d.line([(ax1, ly1 + 1), (ax2, ly1 + 1)], fill=(192, 14, 24, 255), width=6)
        d.line([(ax1, ly1 + 6), (ax2 - 22, ly1 + 6)], fill=(255, 90, 98, 95), width=2)
    if acento_esq:
        ay1 = ly1 + c_tl + 10
        ay2 = ly2 - c_bl - 10
        d.line([(lx1 + 2, ay1), (lx1 + 2, ay2)], fill=(184, 12, 22, 255), width=7)
        d.line([(lx1 + 8, ay1 + 10), (lx1 + 8, ay2 - 10)], fill=(255, 80, 90, 80), width=2)

    d.line([(lx2 - c_br - 36, ly2 - 1), (lx2 - c_br - 4, ly2 - 1)], fill=(192, 14, 24, 210), width=4)
    canvas.alpha_composite(sub, dest=(bx1, by1))


def _card_chama_ff(
    d,
    cx: float,
    cy: float,
    r: float,
    cor_sombra=(118, 6, 14, 255),
    cor_principal=(192, 14, 24, 255),
    cor_nucleo=(248, 218, 218, 255),
):
    ext = [
        (cx, cy - r * 1.14),
        (cx + r * 0.46, cy - r * 0.48),
        (cx + r * 0.34, cy - r * 0.78),
        (cx + r * 0.84, cy - r * 0.08),
        (cx + r * 0.72, cy + r * 0.54),
        (cx + r * 0.28, cy + r * 0.98),
        (cx, cy + r * 1.06),
        (cx - r * 0.38, cy + r * 0.94),
        (cx - r * 0.78, cy + r * 0.44),
        (cx - r * 0.72, cy - r * 0.16),
        (cx - r * 0.34, cy - r * 0.56),
        (cx - r * 0.24, cy - r * 0.22),
    ]
    d.polygon([(px + 2, py + 4) for px, py in ext], fill=(0, 0, 0, 140))
    d.polygon(ext, fill=cor_sombra, outline=cor_principal, width=3)
    med = [
        (cx + r * 0.02, cy - r * 0.80),
        (cx + r * 0.54, cy + r * 0.02),
        (cx + r * 0.44, cy + r * 0.58),
        (cx, cy + r * 0.96),
        (cx - r * 0.46, cy + r * 0.54),
        (cx - r * 0.48, cy - r * 0.04),
    ]
    d.polygon(med, fill=cor_principal)
    nuc = [
        (cx + r * 0.03, cy - r * 0.30),
        (cx + r * 0.28, cy + r * 0.18),
        (cx + r * 0.18, cy + r * 0.66),
        (cx, cy + r * 0.82),
        (cx - r * 0.20, cy + r * 0.62),
        (cx - r * 0.24, cy + r * 0.16),
    ]
    d.polygon(nuc, fill=cor_nucleo)


def _card_icone_modulo(d, tipo: str, cx: float, cy: float, r: float):
    cor = (196, 14, 24, 255)
    cor_escura = (112, 6, 14, 240)
    cor_clara = (248, 214, 218, 245)
    if tipo == "partidas":
        d.ellipse((cx - r * 0.80, cy - r * 0.80, cx + r * 0.80, cy + r * 0.80), fill=(24, 5, 9, 210), outline=cor, width=5)
        d.ellipse((cx - r * 0.36, cy - r * 0.36, cx + r * 0.36, cy + r * 0.36), outline=cor_clara, width=3)
        d.ellipse((cx - 5, cy - 5, cx + 5, cy + 5), fill=cor_clara)
        for dx1, dy1, dx2, dy2 in (
            (0, -r * 1.08, 0, -r * 0.54),
            (0, r * 0.54, 0, r * 1.08),
            (-r * 1.08, 0, -r * 0.54, 0),
            (r * 0.54, 0, r * 1.08, 0),
        ):
            d.line([(cx + dx1, cy + dy1), (cx + dx2, cy + dy2)], fill=cor, width=5)
    elif tipo == "vitorias":
        d.polygon([
            (cx - r * 0.62, cy - r * 0.78),
            (cx + r * 0.62, cy - r * 0.78),
            (cx + r * 0.44, cy + r * 0.04),
            (cx + r * 0.16, cy + r * 0.28),
            (cx - r * 0.16, cy + r * 0.28),
            (cx - r * 0.44, cy + r * 0.04),
        ], fill=cor, outline=cor_clara, width=2)
        d.arc((cx - r * 0.96, cy - r * 0.68, cx - r * 0.34, cy - r * 0.04), start=95, end=275, fill=cor_clara, width=5)
        d.arc((cx + r * 0.34, cy - r * 0.68, cx + r * 0.96, cy - r * 0.04), start=265, end=85, fill=cor_clara, width=5)
        d.rectangle((cx - r * 0.11, cy + r * 0.26, cx + r * 0.11, cy + r * 0.62), fill=cor_clara)
        d.rounded_rectangle((cx - r * 0.52, cy + r * 0.60, cx + r * 0.52, cy + r * 0.82), radius=5, fill=cor_escura, outline=cor, width=3)
        pts_s = []
        for i in range(10):
            ang = -math.pi / 2 + i * math.pi / 5
            rr = r * (0.24 if i % 2 == 0 else 0.10)
            pts_s.append((cx + math.cos(ang) * rr, cy - r * 0.34 + math.sin(ang) * rr))
        d.polygon(pts_s, fill=(16, 5, 8, 250))
    elif tipo == "streak":
        _card_chama_ff(d, cx, cy, r * 0.86, cor_sombra=cor_escura, cor_principal=cor, cor_nucleo=cor_clara)
    elif tipo == "squad":
        esc = [
            (cx, cy - r * 0.90),
            (cx + r * 0.76, cy - r * 0.56),
            (cx + r * 0.64, cy + r * 0.24),
            (cx, cy + r * 0.90),
            (cx - r * 0.64, cy + r * 0.24),
            (cx - r * 0.76, cy - r * 0.56),
        ]
        d.polygon(esc, outline=cor, fill=(36, 5, 10, 240), width=5)
        d.line([(cx - r * 0.34, cy - r * 0.04), (cx, cy - r * 0.34), (cx + r * 0.34, cy - r * 0.04)], fill=cor_clara, width=5)
        d.line([(cx - r * 0.34, cy + r * 0.26), (cx, cy - r * 0.02), (cx + r * 0.34, cy + r * 0.26)], fill=cor, width=5)
    elif tipo == "relogio":
        d.ellipse((cx - r * 0.82, cy - r * 0.82, cx + r * 0.82, cy + r * 0.82), fill=(30, 5, 10, 235), outline=cor, width=5)
        d.line([(cx, cy - r * 0.46), (cx, cy), (cx + r * 0.36, cy + r * 0.22)], fill=cor_clara, width=5)
        d.ellipse((cx - 5, cy - 5, cx + 5, cy + 5), fill=cor)


def _card_insignia_patente(canvas, cx: int, cy: int, raio: int, indice: int):
    idx = max(0, min(11, int(indice)))
    metais = (
        (146, 78, 66),    # 0 Bronze Escuro
        (176, 174, 178),  # 1 Aço Prateado
        (196, 128, 112),  # 2 Cobre Rubro
        (204, 196, 198),  # 3 Platina Fumê
        (196, 26, 36),    # 4 Diamante Sangue
        (184, 20, 30),    # 5 Mestre Carmesim
        (222, 188, 188),  # 6 Mestre de Honra
        (204, 20, 30),    # 7 Elite Rubro
        (234, 202, 202),  # 8 Elite de Honra
        (216, 22, 32),    # 9 Desafiante
        (242, 214, 214),  # 10 Desafiante de Honra
        (228, 24, 34),    # 11 Hacker
    )
    metal = metais[idx]
    rubi_vivo = (192, 14, 24)
    sangue_med = (122, 7, 14)
    sangue_esc = (64, 4, 9)
    preto_armadura = (8, 6, 8)

    intensidade = 65 + int((idx / 11.0) * 105)
    _card_glow_radial_local(
        canvas, cx, cy,
        int(raio * (1.35 + idx * 0.05)),
        int(raio * (1.15 + idx * 0.04)),
        (156, 8, 14), intensidade,
    )

    box_r = int(raio * 2.25)
    bx1, by1 = max(0, cx - box_r), max(0, cy - int(raio * 1.45))
    bx2, by2 = min(canvas.width, cx + box_r), min(canvas.height, cy + int(raio * 1.45))
    sub = Image.new("RGBA", (bx2 - bx1, by2 - by1), (0, 0, 0, 0))
    d = ImageDraw.Draw(sub)
    lcx, lcy = cx - bx1, cy - by1

    if idx >= 7:
        d.ellipse((lcx - raio * 1.08, lcy - raio * 1.08, lcx + raio * 1.08, lcy + raio * 1.08), outline=(168, 12, 22, 125), width=3)
    if idx >= 9:
        for a0 in (-25, 155):
            d.arc((lcx - raio * 1.16, lcy - raio * 1.16, lcx + raio * 1.16, lcy + raio * 1.16), start=a0, end=a0 + 50, fill=(208, 18, 30, 215), width=5)

    qtd_asas = 1 if idx <= 2 else (2 if idx <= 5 else (3 if idx <= 8 else 4))
    tons_asa = (rubi_vivo, sangue_med, sangue_esc, (40, 4, 8))
    for i in range(qtd_asas - 1, -1, -1):
        off_y = (i - (qtd_asas - 1) / 2.0) * (raio * 0.27)
        envergadura = raio * (1.36 + (qtd_asas - 1 - i) * 0.17 + (0.12 if idx >= 9 else 0.0))
        inclina = raio * (0.25 - i * 0.08)
        cor_a = tons_asa[min(i, len(tons_asa) - 1)]
        for sinal in (-1, 1):
            asa_sombra = [
                (lcx + sinal * raio * 0.54, lcy + off_y - raio * 0.10 + 6),
                (lcx + sinal * envergadura, lcy + off_y - inclina - raio * 0.16 + 6),
                (lcx + sinal * (envergadura * 0.83), lcy + off_y + raio * 0.12 + 6),
                (lcx + sinal * raio * 0.48, lcy + off_y + raio * 0.18 + 6),
            ]
            d.polygon(asa_sombra, fill=(0, 0, 0, 145))
            asa = [
                (lcx + sinal * raio * 0.54, lcy + off_y - raio * 0.12),
                (lcx + sinal * envergadura, lcy + off_y - inclina - raio * 0.18),
                (lcx + sinal * (envergadura * 0.83), lcy + off_y + raio * 0.10),
                (lcx + sinal * raio * 0.48, lcy + off_y + raio * 0.16),
            ]
            d.polygon(asa, fill=(*cor_a, 248), outline=(*metal, 195 if i == 0 else 120), width=3)
            d.line([asa[0], asa[1]], fill=(255, 118, 124, 120 if i == 0 else 55), width=2)

    if idx >= 6:
        coroa = [
            (lcx - raio * 0.46, lcy - raio * 0.72),
            (lcx - raio * 0.56, lcy - raio * 1.05),
            (lcx - raio * 0.22, lcy - raio * 0.86),
            (lcx, lcy - raio * 1.20),
            (lcx + raio * 0.22, lcy - raio * 0.86),
            (lcx + raio * 0.56, lcy - raio * 1.05),
            (lcx + raio * 0.46, lcy - raio * 0.72),
        ]
        d.polygon(coroa, fill=(*sangue_med, 255), outline=(*metal, 240), width=3)
        d.ellipse((lcx - 6, lcy - raio * 1.20 - 6, lcx + 6, lcy - raio * 1.20 + 6), fill=(*metal, 255))

    def _escudo_pts(escala: float):
        r = raio * escala
        return [
            (lcx, lcy - r * 0.96),
            (lcx + r * 0.78, lcy - r * 0.56),
            (lcx + r * 0.68, lcy + r * 0.34),
            (lcx, lcy + r * 0.98),
            (lcx - r * 0.68, lcy + r * 0.34),
            (lcx - r * 0.78, lcy - r * 0.56),
        ]

    d.polygon([(px + 4, py + 9) for px, py in _escudo_pts(1.03)], fill=(0, 0, 0, 185))
    d.polygon(_escudo_pts(1.00), fill=(*sangue_esc, 255), outline=(*metal, 240), width=5)
    d.polygon(_escudo_pts(0.86), fill=(*preto_armadura, 255), outline=(*rubi_vivo, 235), width=4)
    esc_in = _escudo_pts(0.70)
    d.polygon(esc_in, fill=(28, 4, 8, 255), outline=(108, 10, 18, 185), width=2)
    d.polygon([esc_in[0], esc_in[3], esc_in[4], esc_in[5]], fill=(48, 5, 10, 150))

    if idx <= 2:
        qtd_c = idx + 1
        for c in range(qtd_c):
            oy = lcy + (c - (qtd_c - 1) / 2.0) * (raio * 0.24) + raio * 0.05
            d.line(
                [(lcx - raio * 0.33, oy + raio * 0.13), (lcx, oy - raio * 0.14), (lcx + raio * 0.33, oy + raio * 0.13)],
                fill=(*metal, 255), width=9,
            )
    elif idx <= 4:
        gem = [
            (lcx, lcy - raio * 0.46),
            (lcx + raio * 0.38, lcy - raio * 0.06),
            (lcx, lcy + raio * 0.48),
            (lcx - raio * 0.38, lcy - raio * 0.06),
        ]
        d.polygon(gem, fill=(*sangue_med, 255), outline=(*metal, 255), width=4)
        d.polygon([gem[0], gem[1], (lcx, lcy - raio * 0.06)], fill=(*rubi_vivo, 255))
        d.polygon([gem[0], gem[3], (lcx, lcy - raio * 0.06)], fill=(245, 165, 172, 195))
    elif idx <= 6:
        est = []
        for i in range(8):
            ang = -math.pi / 2 + i * math.pi / 4
            rr = raio * (0.48 if i % 2 == 0 else 0.17)
            est.append((lcx + math.cos(ang) * rr, lcy + math.sin(ang) * rr))
        d.polygon(est, fill=(*rubi_vivo, 255), outline=(*metal, 255), width=4)
        d.ellipse((lcx - raio * 0.10, lcy - raio * 0.10, lcx + raio * 0.10, lcy + raio * 0.10), fill=(252, 232, 234, 255))
    elif idx <= 8:
        falcao = [
            (lcx, lcy - raio * 0.48),
            (lcx + raio * 0.44, lcy - raio * 0.18),
            (lcx + raio * 0.22, lcy + raio * 0.08),
            (lcx, lcy + raio * 0.48),
            (lcx - raio * 0.22, lcy + raio * 0.08),
            (lcx - raio * 0.44, lcy - raio * 0.18),
        ]
        d.polygon(falcao, fill=(*rubi_vivo, 255), outline=(*metal, 255), width=4)
        d.polygon(
            [(lcx, lcy - raio * 0.24), (lcx + raio * 0.15, lcy + raio * 0.04),
             (lcx, lcy + raio * 0.26), (lcx - raio * 0.15, lcy + raio * 0.04)],
            fill=(250, 224, 224, 245),
        )
    elif idx <= 10:
        _card_chama_ff(d, lcx, lcy, raio * 0.46, cor_sombra=sangue_esc, cor_principal=rubi_vivo, cor_nucleo=(252, 224, 218, 255))
    else:
        r_sk = raio * 0.39
        d.ellipse((lcx - r_sk, lcy - r_sk * 1.04, lcx + r_sk, lcy + r_sk * 0.56), fill=(236, 228, 230, 252), outline=(*rubi_vivo, 255), width=4)
        d.rounded_rectangle((lcx - r_sk * 0.56, lcy + r_sk * 0.14, lcx + r_sk * 0.56, lcy + r_sk * 0.88), radius=8, fill=(236, 228, 230, 252))
        d.polygon(
            [(lcx - r_sk * 0.62, lcy - r_sk * 0.22), (lcx - r_sk * 0.14, lcy - r_sk * 0.05),
             (lcx - r_sk * 0.22, lcy + r_sk * 0.22), (lcx - r_sk * 0.58, lcy + r_sk * 0.10)],
            fill=(185, 8, 20, 255),
        )
        d.polygon(
            [(lcx + r_sk * 0.62, lcy - r_sk * 0.22), (lcx + r_sk * 0.14, lcy - r_sk * 0.05),
             (lcx + r_sk * 0.22, lcy + r_sk * 0.22), (lcx + r_sk * 0.58, lcy + r_sk * 0.10)],
            fill=(185, 8, 20, 255),
        )
        d.ellipse((lcx - r_sk * 0.42, lcy - r_sk * 0.08, lcx - r_sk * 0.30, lcy + r_sk * 0.04), fill=(255, 198, 200, 255))
        d.ellipse((lcx + r_sk * 0.30, lcy - r_sk * 0.08, lcx + r_sk * 0.42, lcy + r_sk * 0.04), fill=(255, 198, 200, 255))
        d.polygon([(lcx, lcy + r_sk * 0.08), (lcx + r_sk * 0.13, lcy + r_sk * 0.35), (lcx - r_sk * 0.13, lcy + r_sk * 0.35)], fill=(16, 6, 8, 255))
        for tx in (-0.30, 0.0, 0.30):
            d.line([(lcx + r_sk * tx, lcy + r_sk * 0.52), (lcx + r_sk * tx, lcy + r_sk * 0.84)], fill=(16, 6, 8, 255), width=4)

    canvas.alpha_composite(sub, dest=(bx1, by1))


def _card_formatar_data_curta(iso_str: str) -> str:
    bruto = str(iso_str or "").strip()
    if not bruto:
        return ""
    try:
        dt = datetime.datetime.fromisoformat(bruto.replace("Z", "+00:00"))
        return dt.strftime("%d/%m/%Y às %H:%M")
    except Exception:
        limpo = bruto[:16].replace("T", " ")
        if len(limpo) >= 16 and limpo[4] == "-" and limpo[7] == "-":
            return f"{limpo[8:10]}/{limpo[5:7]}/{limpo[0:4]} às {limpo[11:16]}"
        return limpo


async def _obter_avatar_bytes_membro(membro) -> Optional[bytes]:
    """Busca o avatar PNG 256px do jogador com timeout curto e fallback imediato."""
    av = getattr(membro, "display_avatar", None)
    if not av:
        return None
    try:
        av_256 = av.replace(size=256, format="png") if hasattr(av, "replace") else av
        if hasattr(av_256, "read"):
            coro = av_256.read()
            if asyncio.iscoroutine(coro):
                bruto = await asyncio.wait_for(coro, timeout=2.5)
                if isinstance(bruto, (bytes, bytearray)) and len(bruto) > 64:
                    return bytes(bruto)
    except Exception:
        pass

    url = str(getattr(av, "url", "") or "")
    if url.startswith("http://") or url.startswith("https://"):
        try:
            sessao = await _ff_sessao()
            async with sessao.get(url, timeout=aiohttp.ClientTimeout(total=2.2)) as resp:
                if resp.status == 200:
                    bruto = await resp.read()
                    if isinstance(bruto, (bytes, bytearray)) and len(bruto) > 64:
                        return bytes(bruto)
        except Exception:
            pass
    return None


def renderizar_card_perfil_png(
    *,
    user_id: int,
    display_name: str,
    username: str,
    guild_name: str,
    cargo_nome: str,
    dados: dict,
    avatar_bytes: Optional[bytes] = None,
) -> bytes:
    """Renderiza o Card Competitivo HD (1240x700 via 2x SSAA) em Vermelho Escuro Sangue + Preto Obsidiana."""
    W, H = 2480, 1400
    card = _card_gradiente_vertical(W, H, (9, 4, 6, 255), (4, 4, 6, 255))

    _card_glow_radial_local(card, 450, 420, 660, 580, (116, 5, 10), 145)
    _card_glow_radial_local(card, 2080, 220, 780, 480, (92, 4, 8), 120)
    _card_glow_radial_local(card, 1420, 1280, 880, 380, (80, 4, 8), 105)

    bg_fx = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    db = ImageDraw.Draw(bg_fx)

    faixas = (
        (-180, 320, 42, (112, 6, 14, 26)),
        (190, 500, 72, (74, 4, 10, 30)),
        (1500, 460, 82, (104, 6, 14, 26)),
        (2040, 240, 55, (148, 10, 18, 30)),
    )
    for x_top, larg_f, alpha_lin, cor_f in faixas:
        incl = 540
        pol = [(x_top, 0), (x_top + larg_f, 0), (x_top + larg_f - incl, H), (x_top - incl, H)]
        db.polygon(pol, fill=cor_f)
        db.line([(x_top + larg_f, 0), (x_top + larg_f - incl, H)], fill=(172, 12, 22, alpha_lin), width=3)

    for gx in range(1640, 2410, 38):
        for gy in range(88, 470, 38):
            db.rectangle((gx, gy, gx + 4, gy + 4), fill=(188, 16, 26, 28))
    for gx in range(64, 680, 38):
        for gy in range(1040, 1340, 38):
            db.rectangle((gx, gy, gx + 4, gy + 4), fill=(188, 16, 26, 24))

    rng = random.Random(int(user_id) ^ 0xFF13)
    for _ in range(26):
        ex = rng.randint(70, W - 70)
        ey = rng.randint(90, H - 70)
        er = rng.randint(3, 7)
        ea = rng.randint(24, 72)
        db.ellipse((ex - er, ey - er, ex + er, ey + er), fill=(195, 14, 24, ea))

    moldura_ext = _card_pts_chanfro(24, 24, W - 24, H - 24, 34, 34, 34, 34)
    db.line(moldura_ext + [moldura_ext[0]], fill=(92, 8, 16, 230), width=4)
    moldura_int = _card_pts_chanfro(36, 36, W - 36, H - 36, 28, 28, 28, 28)
    db.line(moldura_int + [moldura_int[0]], fill=(38, 7, 12, 195), width=2)

    tam_c = 88
    cor_canto = (192, 14, 24, 255)
    db.line([(24, 24 + tam_c), (24, 58), (58, 24), (24 + tam_c, 24)], fill=cor_canto, width=7)
    db.line([(W - 24 - tam_c, 24), (W - 58, 24), (W - 24, 58), (W - 24, 24 + tam_c)], fill=cor_canto, width=7)
    db.line([(24, H - 24 - tam_c), (24, H - 58), (58, H - 24), (24 + tam_c, H - 24)], fill=cor_canto, width=7)
    db.line([(W - 24 - tam_c, H - 24), (W - 58, H - 24), (W - 24, H - 58), (W - 24, H - 24 - tam_c)], fill=cor_canto, width=7)

    card = Image.alpha_composite(card, bg_fx)
    d_main = ImageDraw.Draw(card, "RGBA")

    # Cabeçalho superior
    _card_chama_ff(d_main, 98, 104, 28)
    f_brand = _card_carregar_fonte("black", 42)
    f_sub_hdr = _card_carregar_fonte("bold", 24)
    f_pill = _card_carregar_fonte("bold", 24)

    d_main.text((142, 80), "FIRE FORCE", font=f_brand, fill=(248, 242, 244, 255))
    w_brand = d_main.textlength("FIRE FORCE", font=f_brand)
    d_main.text((142 + w_brand + 24, 92), "//  FICHA COMPETITIVA OFICIAL", font=f_sub_hdr, fill=(178, 58, 66, 240))

    pat = dados["patente"]
    prox = dados["proxima_patente"]
    idx_pat = int(pat.get("indice", 0))

    srv_limpo = _card_truncar_px(d_main, (guild_name or "FIRE FORCE").upper(), f_pill, 480, remover_simbolos=True)
    txt_hdr_dir = f"{srv_limpo}  •  TIER {idx_pat + 1:02d}/12"
    w_pill = int(d_main.textlength(txt_hdr_dir, font=f_pill)) + 68
    px1, py1, px2, py2 = W - 76 - w_pill, 72, W - 76, 134
    d_main.polygon(_card_pts_chanfro(px1, py1, px2, py2, 16, 6, 16, 6), fill=(26, 4, 8, 255), outline=(148, 10, 18, 255), width=3)
    d_main.text(((px1 + px2) / 2, (py1 + py2) / 2), txt_hdr_dir, font=f_pill, fill=(242, 222, 224, 255), anchor="mm")

    d_main.line([(76, 154), (W - 76, 154)], fill=(84, 8, 16, 255), width=2)
    d_main.line([(76, 154), (430, 154)], fill=(192, 14, 24, 255), width=5)

    # Painel esquerdo: Identidade & Insígnia
    LX1, LY1, LX2, LY2 = 76, 182, 836, 1324
    LCX = (LX1 + LX2) // 2
    _card_painel_tatico(
        card, (LX1, LY1, LX2, LY2),
        c_tl=38, c_tr=12, c_br=38, c_bl=12,
        topo_rgba=(18, 6, 8, 248),
        base_rgba=(5, 4, 6, 252),
        borda_rgba=(124, 12, 22, 240),
        acento_topo=True,
    )

    f_wm = _card_carregar_fonte("black", 240)
    d_main = ImageDraw.Draw(card, "RGBA")
    d_main.text((LCX, 944), f"{idx_pat + 1:02d}", font=f_wm, fill=(24, 6, 10, 255), anchor="mm")

    AV_CY = 394
    AV_R = 148
    _card_glow_radial_local(card, LCX, AV_CY, 245, 225, (152, 8, 14), 135)
    d_main = ImageDraw.Draw(card, "RGBA")

    r_hud = AV_R + 30
    for deg in range(0, 360, 10):
        rad = math.radians(deg)
        r_in_t = r_hud + 8
        r_out_t = r_hud + (17 if deg % 30 == 0 else 13)
        cor_t = (188, 14, 24, 255) if deg % 30 == 0 else (84, 9, 15, 255)
        d_main.line(
            [(LCX + math.cos(rad) * r_in_t, AV_CY + math.sin(rad) * r_in_t),
             (LCX + math.cos(rad) * r_out_t, AV_CY + math.sin(rad) * r_out_t)],
            fill=cor_t,
            width=3 if deg % 30 == 0 else 2,
        )
    d_main.ellipse((LCX - r_hud, AV_CY - r_hud, LCX + r_hud, AV_CY + r_hud), outline=(84, 8, 14, 255), width=4)
    for ang_ini in (-38, 52, 142, 232):
        d_main.arc((LCX - r_hud - 2, AV_CY - r_hud - 2, LCX + r_hud + 2, AV_CY + r_hud + 2), start=ang_ini, end=ang_ini + 36, fill=(196, 14, 24, 255), width=8)

    r_aro = AV_R + 12
    d_main.ellipse((LCX - r_aro, AV_CY - r_aro, LCX + r_aro, AV_CY + r_aro), fill=(16, 5, 8, 255), outline=(164, 12, 20, 255), width=6)

    av_img = None
    if avatar_bytes:
        try:
            av_img = Image.open(io.BytesIO(avatar_bytes)).convert("RGBA")
            av_img = av_img.resize((AV_R * 2, AV_R * 2), Image.Resampling.LANCZOS)
        except Exception:
            av_img = None

    if av_img is None:
        av_img = _card_gradiente_vertical(AV_R * 2, AV_R * 2, (72, 6, 12, 255), (10, 4, 7, 255))
        dm = ImageDraw.Draw(av_img)
        f_ini = _card_carregar_fonte("black", 108)
        ini_limpo = _card_limpar_texto(display_name or username or "FF", f_ini, "FF", remover_simbolos=True)
        iniciais = "".join(ch for ch in ini_limpo if ch.isalnum())[:2].upper() or "FF"
        dm.text((AV_R + 3, AV_R + 1), iniciais, font=f_ini, fill=(0, 0, 0, 180), anchor="mm")
        dm.text((AV_R, AV_R - 2), iniciais, font=f_ini, fill=(248, 236, 238, 255), anchor="mm")

    masc_av = Image.new("L", (AV_R * 2, AV_R * 2), 0)
    ImageDraw.Draw(masc_av).ellipse((0, 0, AV_R * 2, AV_R * 2), fill=255)
    card.paste(av_img, (LCX - AV_R, AV_CY - AV_R), masc_av)
    d_main = ImageDraw.Draw(card, "RGBA")
    d_main.ellipse((LCX - AV_R, AV_CY - AV_R, LCX + AV_R, AV_CY + AV_R), outline=(212, 42, 50, 255), width=3)

    f_tag_av = _card_carregar_fonte("bold", 23)
    lbl_tier = f"RANK #{idx_pat + 1:02d}  •  {int(dados['pontos'])} PTS"
    tw = int(d_main.textlength(lbl_tier, font=f_tag_av)) + 58
    tx1, ty1, tx2, ty2 = LCX - tw // 2, AV_CY + AV_R - 22, LCX + tw // 2, AV_CY + AV_R + 28
    d_main.polygon(_card_pts_chanfro(tx1, ty1, tx2, ty2, 12, 12, 12, 12), fill=(116, 6, 12, 255), outline=(214, 46, 54, 255), width=3)
    d_main.text((LCX, (ty1 + ty2) / 2), lbl_tier, font=f_tag_av, fill=(255, 246, 247, 255), anchor="mm")

    f_nick, nick_txt = _card_ajustar_titulo(d_main, display_name or username or f"Jogador {str(user_id)[-4:]}", "black", 56, 32, 660)
    if not nick_txt:
        f_nick, nick_txt = _card_ajustar_titulo(d_main, username or f"JOGADOR #{str(user_id)[-4:]}", "black", 50, 32, 660)
    d_main.text((LCX + 3, 632), nick_txt, font=f_nick, fill=(0, 0, 0, 255), anchor="mm")
    d_main.text((LCX, 628), nick_txt, font=f_nick, fill=(250, 244, 245, 255), anchor="mm")

    f_handle = _card_carregar_fonte("regular", 27)
    handle_limpo = _card_limpar_texto(username or "", f_handle, f"ID {str(user_id)[-6:]}", remover_simbolos=True)
    if not handle_limpo.startswith("@") and not handle_limpo.startswith("ID "):
        handle_limpo = f"@{handle_limpo}"
    handle_limpo = _card_truncar_px(d_main, handle_limpo, f_handle, 580)
    d_main.text((LCX, 682), handle_limpo, font=f_handle, fill=(176, 118, 124, 255), anchor="mm")

    dy_div = 736
    d_main.line([(LX1 + 68, dy_div), (LCX - 24, dy_div)], fill=(108, 10, 18, 255), width=3)
    d_main.line([(LCX + 24, dy_div), (LX2 - 68, dy_div)], fill=(108, 10, 18, 255), width=3)
    d_main.polygon([(LCX, dy_div - 11), (LCX + 11, dy_div), (LCX, dy_div + 11), (LCX - 11, dy_div)], fill=(192, 14, 24, 255))

    _card_insignia_patente(card, LCX, 962, 128, idx_pat)
    d_main = ImageDraw.Draw(card, "RGBA")

    f_pat_lbl = _card_carregar_fonte("bold", 22)
    d_main.text((LCX, 1142), "PATENTE COMPETITIVA", font=f_pat_lbl, fill=(192, 40, 50, 255), anchor="mm")

    f_pat_nome, pat_nome_txt = _card_ajustar_titulo(d_main, pat["nome"].upper(), "black", 48, 30, 660, remover_simbolos=True)
    d_main.text((LCX + 2, 1198), pat_nome_txt, font=f_pat_nome, fill=(0, 0, 0, 255), anchor="mm")
    d_main.text((LCX, 1194), pat_nome_txt, font=f_pat_nome, fill=(252, 240, 242, 255), anchor="mm")

    f_role = _card_carregar_fonte("bold", 22)
    cargo_limpo = _card_limpar_texto(cargo_nome or "", f_role, "", remover_simbolos=True).strip(" -•|")
    if cargo_limpo:
        role_str = f"CARGO ATIVO: {_card_truncar_px(d_main, cargo_limpo.upper(), f_role, 450, remover_simbolos=True)}"
    else:
        role_str = f"PATAMAR DA PATENTE: {pat['min_pts']} PTS"
    rw = int(d_main.textlength(role_str, font=f_role)) + 52
    rx1, ry1, rx2, ry2 = LCX - rw // 2, 1240, LCX + rw // 2, 1288
    d_main.polygon(_card_pts_chanfro(rx1, ry1, rx2, ry2, 10, 10, 10, 10), fill=(24, 5, 9, 255), outline=(122, 12, 22, 255), width=2)
    d_main.text((LCX, (ry1 + ry2) / 2), role_str, font=f_role, fill=(224, 174, 180, 255), anchor="mm")

    # Painel direito 1: Progressão de Carreira & Pontos
    RX1, RX2 = 876, W - 76
    PY1, PY2 = 182, 502
    _card_painel_tatico(
        card, (RX1, PY1, RX2, PY2),
        c_tl=32, c_tr=12, c_br=32, c_bl=12,
        topo_rgba=(18, 6, 8, 248),
        base_rgba=(6, 5, 7, 252),
        borda_rgba=(120, 12, 22, 235),
        acento_topo=True,
    )
    d_main = ImageDraw.Draw(card, "RGBA")

    f_sec = _card_carregar_fonte("bold", 23)
    f_pts_num = _card_carregar_fonte("black", 76)
    f_pts_lbl = _card_carregar_fonte("bold", 22)
    f_meta = _card_carregar_fonte("bold", 23)

    d_main.text((RX1 + 48, PY1 + 36), "PROGRESSÃO DE CARREIRA", font=f_sec, fill=(198, 28, 38, 255))

    if prox:
        faixa_total = max(1, int(prox["min_pts"]) - int(pat["min_pts"]))
        avanco = max(0, int(dados["pontos"]) - int(pat["min_pts"]))
        pct = min(1.0, avanco / faixa_total)
        rota_txt = f"{pat['nome'].upper()}   »   {prox['nome'].upper()}"
        rodape_esq = f"BASE DA FAIXA: {pat['min_pts']} PTS"
        rodape_dir = f"FALTAM {dados['faltam_pts']} PTS P/ {prox['nome'].upper()}  •  {int(round(pct * 100))}%"
    else:
        pct = 1.0
        rota_txt = f"{pat['nome'].upper()}   •   PATENTE MÁXIMA"
        rodape_esq = f"TOPO DA HIERARQUIA ({pat['min_pts']}+ PTS)"
        rodape_dir = "100% CONCLUÍDO  •  DOMÍNIO ABSOLUTO"

    f_rota, rota_fit = _card_ajustar_titulo(d_main, rota_txt, "black", 38, 26, 940, remover_simbolos=True)
    d_main.text((RX1 + 48, PY1 + 80), rota_fit, font=f_rota, fill=(248, 242, 244, 255))

    pts_str = f"{int(dados['pontos'])}"
    d_main.text((RX2 - 122, PY1 + 32), pts_str, font=f_pts_num, fill=(252, 244, 245, 255), anchor="ra")
    d_main.text((RX2 - 48, PY1 + 58), "PTS", font=f_sec, fill=(196, 14, 24, 255), anchor="ra")
    d_main.text((RX2 - 48, PY1 + 114), "PONTUAÇÃO VITALÍCIA", font=f_pts_lbl, fill=(172, 114, 120, 255), anchor="ra")

    BX1, BY1, BX2, BY2 = RX1 + 48, PY1 + 172, RX2 - 48, PY1 + 228
    d_main.polygon(_card_pts_chanfro(BX1 - 10, BY1 - 10, BX2 + 10, BY2 + 10, 12, 12, 12, 12), fill=(5, 4, 6, 255), outline=(74, 10, 18, 255), width=3)

    n_segs = 22
    incl_seg = 14
    gap_seg = 8
    larg_util = (BX2 - BX1) - incl_seg
    seg_w = (larg_util - gap_seg * (n_segs - 1)) / n_segs
    segs_ativos = int(round(pct * n_segs))
    if pct > 0 and segs_ativos == 0:
        segs_ativos = 1

    if segs_ativos > 0:
        bar_pad = 24
        gb_w, gb_h = (BX2 - BX1) + bar_pad * 2, (BY2 - BY1) + bar_pad * 2
        glow_bar = Image.new("RGBA", (gb_w, gb_h), (0, 0, 0, 0))
        dgb = ImageDraw.Draw(glow_bar)
        for s in range(segs_ativos):
            sx1 = bar_pad + s * (seg_w + gap_seg)
            sx2 = sx1 + seg_w
            pol_g = [(sx1 + incl_seg, bar_pad), (sx2 + incl_seg, bar_pad), (sx2, bar_pad + (BY2 - BY1)), (sx1, bar_pad + (BY2 - BY1))]
            dgb.polygon(pol_g, fill=(185, 10, 18, 95))
        glow_bar = glow_bar.filter(ImageFilter.GaussianBlur(radius=12))
        card.alpha_composite(glow_bar, dest=(BX1 - bar_pad, BY1 - bar_pad))
        d_main = ImageDraw.Draw(card, "RGBA")

    for s in range(n_segs):
        sx1 = BX1 + s * (seg_w + gap_seg)
        sx2 = sx1 + seg_w
        pol_s = [(sx1 + incl_seg, BY1), (sx2 + incl_seg, BY1), (sx2, BY2), (sx1, BY2)]
        if s < segs_ativos:
            t = s / max(1, n_segs - 1)
            r_c = int(92 + t * 112)
            g_c = int(4 + t * 12)
            b_c = int(8 + t * 14)
            r_hi = min(255, r_c + 34)
            g_hi = min(255, g_c + 18)
            b_hi = min(255, b_c + 20)
            d_main.polygon(pol_s, fill=(r_c, g_c, b_c, 255), outline=(min(255, r_c + 42), 26, 32, 255), width=2)
            pol_top = [
                (sx1 + incl_seg + 2, BY1 + 2),
                (sx2 + incl_seg - 2, BY1 + 2),
                (sx2 + incl_seg * 0.64 - 2, BY1 + (BY2 - BY1) * 0.35),
                (sx1 + incl_seg * 0.64 + 2, BY1 + (BY2 - BY1) * 0.35),
            ]
            d_main.polygon(pol_top, fill=(r_hi, g_hi, b_hi, 255))
        else:
            d_main.polygon(pol_s, fill=(18, 10, 13, 255), outline=(46, 14, 20, 255), width=2)

    d_main.text((BX1, PY2 - 54), rodape_esq, font=f_meta, fill=(172, 118, 124, 255))
    d_main.text((BX2, PY2 - 54), rodape_dir, font=f_meta, fill=(244, 204, 208, 255), anchor="ra")

    # Grid 2x2 de Estatísticas
    GAP = 28
    CW = (RX2 - RX1 - GAP) // 2
    CH = 258
    GY1 = 532
    GY2 = GY1 + CH + GAP

    f_card_lbl = _card_carregar_fonte("bold", 22)
    f_card_sub = _card_carregar_fonte("regular", 23)

    winrate = float(dados.get("winrate") or 0.0)
    if dados["partidas"] <= 0 and dados["vitorias"] <= 0:
        tag_wr = "SEM REGISTROS"
    elif winrate >= 45.0:
        tag_wr = "TAXA DOMINANTE"
    elif winrate >= 25.0:
        tag_wr = "ALTO DESEMPENHO"
    elif winrate >= 12.0:
        tag_wr = "RITMO COMPETITIVO"
    else:
        tag_wr = "EM EVOLUÇÃO"

    streak_atual = int(dados.get("streak_atual") or 0)
    maior_streak = int(dados.get("maior_streak") or 0)
    streak_val_txt = f"{streak_atual}x" if streak_atual > 0 else "0"
    streak_sub_txt = f"Recorde: {maior_streak} vitória(s)  •  Lines: {dados['qtd_lines']}"

    cards_cfg = (
        (RX1, GY1, "DIÁRIOS JOGADOS", f"{dados['partidas']}", "Salas confirmadas (+1 pt cada)", "partidas"),
        (RX1 + CW + GAP, GY1, "VITÓRIAS (TOP 1)", f"{dados['vitorias']}", "Booyahs oficiais (+3 pts cada)", "vitorias"),
        (RX1, GY2, "APROVEITAMENTO", f"{winrate:.1f}%", f"Status: {tag_wr}", "winrate"),
        (RX1 + CW + GAP, GY2, "SEQUÊNCIA ATUAL", streak_val_txt, streak_sub_txt, "streak"),
    )

    for cx1, cy1, titulo_m, valor_m, sub_m, icone_m in cards_cfg:
        cx2, cy2 = cx1 + CW, cy1 + CH
        _card_painel_tatico(
            card, (cx1, cy1, cx2, cy2),
            c_tl=22, c_tr=10, c_br=22, c_bl=10,
            topo_rgba=(16, 5, 7, 247),
            base_rgba=(6, 5, 7, 252),
            borda_rgba=(106, 10, 20, 230),
            acento_topo=False,
            acento_esq=True,
        )
        d_main = ImageDraw.Draw(card, "RGBA")
        d_main.text((cx1 + 42, cy1 + 32), titulo_m, font=f_card_lbl, fill=(196, 38, 48, 255))
        f_val_fit, val_fit = _card_ajustar_titulo(d_main, valor_m, "black", 68, 44, CW - 230)
        d_main.text((cx1 + 44, cy1 + 85), val_fit, font=f_val_fit, fill=(0, 0, 0, 255))
        d_main.text((cx1 + 42, cy1 + 82), val_fit, font=f_val_fit, fill=(252, 245, 246, 255))
        d_main.text((cx1 + 42, cy2 - 58), _card_truncar_px(d_main, sub_m, f_card_sub, CW - 80), font=f_card_sub, fill=(176, 128, 134, 255))

        if icone_m == "winrate":
            gx, gy, gr = cx2 - 96, cy1 + 114, 58
            if winrate > 0:
                _card_glow_radial_local(card, gx, gy, 76, 76, (168, 10, 18), 85)
                d_main = ImageDraw.Draw(card, "RGBA")
            d_main.ellipse((gx - gr, gy - gr, gx + gr, gy + gr), outline=(40, 10, 15, 255), width=14)
            ang_fim = -90 + int(round(min(100.0, max(0.0, winrate)) * 3.6))
            if ang_fim > -90:
                d_main.arc((gx - gr, gy - gr, gx + gr, gy + gr), start=-90, end=ang_fim, fill=(196, 14, 24, 255), width=14)
            d_main.ellipse((gx - gr + 22, gy - gr + 22, gx + gr - 22, gy + gr - 22), fill=(20, 5, 8, 255), outline=(118, 12, 22, 255), width=3)
            f_wr_mini = _card_carregar_fonte("bold", 21)
            d_main.text((gx, gy), f"{int(round(winrate))}%", font=f_wr_mini, fill=(246, 214, 218, 255), anchor="mm")
        else:
            ix1, iy1, ix2, iy2 = cx2 - 146, cy1 + 44, cx2 - 40, cy1 + 150
            d_main.polygon(_card_pts_chanfro(ix1, iy1, ix2, iy2, 18, 6, 18, 6), fill=(24, 4, 8, 255), outline=(136, 12, 22, 255), width=3)
            _card_icone_modulo(d_main, icone_m, (ix1 + ix2) / 2, (iy1 + iy2) / 2, 34)

    # Faixa tática inferior (Squad & Última Participação)
    FY1, FY2 = GY2 + CH + GAP, 1324
    _card_painel_tatico(
        card, (RX1, FY1, RX2, FY2),
        c_tl=22, c_tr=10, c_br=26, c_bl=10,
        topo_rgba=(16, 5, 7, 248),
        base_rgba=(6, 5, 7, 252),
        borda_rgba=(112, 12, 22, 230),
        acento_topo=False,
        acento_esq=True,
    )
    d_main = ImageDraw.Draw(card, "RGBA")
    mid_fx = (RX1 + RX2) // 2
    d_main.line([(mid_fx, FY1 + 28), (mid_fx, FY2 - 28)], fill=(92, 10, 18, 255), width=3)

    f_ft_lbl = _card_carregar_fonte("bold", 21)
    f_ft_val = _card_carregar_fonte("bold", 30)
    f_ft_sub = _card_carregar_fonte("regular", 22)

    _card_icone_modulo(d_main, "squad", RX1 + 66, (FY1 + FY2) / 2, 30)
    d_main.text((RX1 + 118, FY1 + 30), "LINE FAVORITA & SQUADS", font=f_ft_lbl, fill=(196, 38, 48, 255))
    line_fav = dados.get("line_favorita") or "Nenhuma line salva (/lines)"
    d_main.text((RX1 + 118, FY1 + 68), _card_truncar_px(d_main, line_fav, f_ft_val, mid_fx - RX1 - 148), font=f_ft_val, fill=(248, 240, 242, 255))
    d_main.text((RX1 + 118, FY1 + 114), f"{dados.get('qtd_lines', 0)} line(s) registrada(s) no servidor", font=f_ft_sub, fill=(172, 124, 130, 255))

    _card_icone_modulo(d_main, "relogio", mid_fx + 62, (FY1 + FY2) / 2, 30)
    d_main.text((mid_fx + 114, FY1 + 30), "ÚLTIMA SALA CONFIRMADA", font=f_ft_lbl, fill=(196, 38, 48, 255))
    ult = dados.get("ultima")
    if ult:
        tipo_u = str(ult.get("tipo") or "4x4").upper()
        cat_u = str(ult.get("categoria") or "Mobile").title()
        hor_u = str(ult.get("horario") or "—")
        dt_fmt = _card_formatar_data_curta(ult.get("criado_em"))
        ult_principal = f"{tipo_u} {cat_u}  •  {hor_u}"
        ult_sec = f"Confirmado em {dt_fmt}" if dt_fmt else "Inscrição confirmada recentemente"
    else:
        ult_principal = "Sem diário recente"
        ult_sec = "Participe de uma sala para pontuar (+1 pt)"
    d_main.text((mid_fx + 114, FY1 + 68), _card_truncar_px(d_main, ult_principal, f_ft_val, RX2 - mid_fx - 144), font=f_ft_val, fill=(248, 240, 242, 255))
    d_main.text((mid_fx + 114, FY1 + 114), _card_truncar_px(d_main, ult_sec, f_ft_sub, RX2 - mid_fx - 144), font=f_ft_sub, fill=(172, 124, 130, 255))

    f_micro = _card_carregar_fonte("bold", 19)
    d_main.text((W // 2, H - 50), "FIRE FORCE COMPETITIVE SYSTEM   •   DIÁRIO +1 PT   •   VITÓRIA +3 PTS", font=f_micro, fill=(142, 72, 80, 255), anchor="mm")

    final_rgb = card.convert("RGB").resize((W // 2, H // 2), Image.Resampling.LANCZOS)
    buf = io.BytesIO()
    final_rgb.save(buf, format="PNG", compress_level=6)
    return buf.getvalue()


class PerfilCardPublicarView(discord.ui.View):
    """Menu discreto para publicar o Card Competitivo no chat (sem dados privados da carteira)."""

    def __init__(
        self,
        autor_id: int,
        alvo_nome: str,
        pat_emoji: str,
        pat_nome: str,
        cargo_txt: str,
        pontos: int,
        png_bytes: bytes,
    ):
        super().__init__(timeout=180)
        self.autor_id = int(autor_id)
        self.alvo_nome = alvo_nome
        self.pat_emoji = pat_emoji
        self.pat_nome = pat_nome
        self.cargo_txt = cargo_txt
        self.pontos = int(pontos)
        self.png_bytes = png_bytes
        self.publicado = False

        sel = discord.ui.Select(
            placeholder="🩸 Opções do Card Competitivo...",
            options=[
                discord.SelectOption(
                    label="Exibir Card no Chat",
                    value="publicar_chat",
                    emoji="📤",
                    description="Publica o card neste canal (sem saldo privado da carteira)",
                ),
            ],
        )
        sel.callback = self._acao
        self.add_item(sel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.autor_id:
            await interaction.response.send_message(
                embed=criar_embed("🔒 Painel privado", "Use `/perfil` para gerar o seu próprio card.", "Vermelho Escuro"),
                ephemeral=True,
            )
            return False
        return True

    async def _acao(self, interaction: discord.Interaction):
        if self.publicado:
            return await interaction.response.send_message(
                embed=criar_embed("✅ Já publicado", "Este card já foi exibido neste canal.", "Vermelho Escuro"),
                ephemeral=True,
            )
        canal = interaction.channel
        if not interaction.guild or not canal or not hasattr(canal, "send"):
            return await interaction.response.send_message(
                embed=criar_embed("❌ Canal inválido", "Não foi possível publicar o card neste canal.", "Vermelho"),
                ephemeral=True,
            )
        me = interaction.guild.me
        perms = canal.permissions_for(me) if (me and hasattr(canal, "permissions_for")) else None
        if perms and not (perms.send_messages and perms.attach_files and perms.embed_links):
            return await interaction.response.send_message(
                embed=criar_embed(
                    "🛠️ Permissão ausente",
                    "O bot precisa de **Enviar mensagens**, **Inserir links** e **Anexar arquivos** neste canal.",
                    "Vermelho",
                ),
                ephemeral=True,
            )

        self.publicado = True
        await interaction.response.defer(ephemeral=True)
        nome_arq = "perfil_fireforce.png"
        arq_pub = discord.File(io.BytesIO(self.png_bytes), filename=nome_arq)
        emb_pub = criar_embed(
            f"{self.pat_emoji} Ficha Competitiva • {self.alvo_nome}",
            f"**Patente:** {self.pat_emoji} **{self.pat_nome}**{self.cargo_txt} • **`{self.pontos} pts`**",
            "Vermelho Escuro",
            image=f"attachment://{nome_arq}",
            footer="Fire Force • Use /perfil para ver sua ficha competitiva",
        )
        try:
            await canal.send(
                embed=emb_pub,
                file=arq_pub,
                allowed_mentions=discord.AllowedMentions.none(),
            )
        except (discord.Forbidden, discord.HTTPException):
            self.publicado = False
            return await interaction.followup.send(
                embed=criar_embed("⚠️ Falha ao enviar", "Verifique as permissões de envio de imagem neste canal.", "Amarelo"),
                ephemeral=True,
            )

        try:
            await interaction.edit_original_response(view=None)
        except Exception:
            pass
        await interaction.followup.send(
            embed=criar_embed("📤 Card Exibido!", "O card competitivo foi publicado no canal.", "Vermelho Escuro"),
            ephemeral=True,
        )


@bot.tree.command(name="perfil", description="🎖️ Ficha competitiva HD: card visual, patente, vitórias, winrate e sequência")
@app_commands.guild_only()
@app_commands.describe(
    usuario="Jogador (opcional; por padrão, seu próprio perfil)",
    publico="Mostrar o card diretamente no chat para todos verem (padrão: privado)",
)
async def cmd_perfil(interaction: discord.Interaction,
                     usuario: Optional[discord.Member] = None,
                     publico: Optional[bool] = False):
    if not interaction.guild:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Só no servidor", "Use este comando dentro do servidor.", "Vermelho"),
            ephemeral=True)

    efemero = not bool(publico)
    await interaction.response.defer(ephemeral=efemero)
    alvo = usuario or interaction.user

    # Garante cargo de patente sincronizado automaticamente
    await sincronizar_cargo_patente(interaction.guild, alvo.id)
    dados = await obter_estatisticas_completas_jogador(interaction.guild.id, alvo.id)
    pat = dados["patente"]
    prox = dados["proxima_patente"]

    cargos_pat = await obter_cargos_patentes(interaction.guild.id)
    rid_pat = cargos_pat.get(pat["slug"])
    role_pat = interaction.guild.get_role(rid_pat) if rid_pat else None
    cargo_txt = f" ({role_pat.mention})" if role_pat else ""
    cargo_nome_card = role_pat.name if role_pat else ""

    png_bytes: Optional[bytes] = None
    if _PIL_DISPONIVEL:
        try:
            avatar_bytes = await _obter_avatar_bytes_membro(alvo)
            png_bytes = await asyncio.to_thread(
                renderizar_card_perfil_png,
                user_id=int(alvo.id),
                display_name=str(getattr(alvo, "display_name", "") or getattr(alvo, "name", "")),
                username=str(getattr(alvo, "name", "") or ""),
                guild_name=str(getattr(interaction.guild, "name", "") or "FIRE FORCE"),
                cargo_nome=cargo_nome_card,
                dados=dados,
                avatar_bytes=avatar_bytes,
            )
        except Exception as erro_card:
            _log_arquivo(f"[PERFIL] falha ao renderizar card PNG user={alvo.id}: {erro_card}")
            png_bytes = None

    if png_bytes:
        nome_arq = "perfil_fireforce.png"
        arquivo_card = discord.File(io.BytesIO(png_bytes), filename=nome_arq)
        embed = criar_embed(
            f"{pat['emoji']} Ficha Competitiva • {alvo.display_name}",
            f"**Patente Atual:** {pat['emoji']} **{pat['nome']}**{cargo_txt} • **`{dados['pontos']} pts`**",
            "Vermelho Escuro",
            image=f"attachment://{nome_arq}",
            footer="Fire Force • Pontuação: cada Diário = +1 pt | cada Vitória = +3 pts",
        )
        if efemero and alvo.id == interaction.user.id:
            saldo = await saldo_carteira(alvo.id, interaction.guild.id)
            vip_qtd = await obter_vagas_vip_usuario(interaction.guild.id, alvo.id)
            vip_str = f" • 🎟️ **Vagas VIP:** {formatar_qtd_vaga_vip(vip_qtd)}" if vip_qtd != 0 else ""
            embed.add_field(
                name="🔒 Seus Recursos Privados (só você vê)",
                value=f"🪙 **Carteira:** `{formatar_moeda(saldo)}`{vip_str}",
                inline=False,
            )
        view_pub = (
            PerfilCardPublicarView(
                autor_id=interaction.user.id,
                alvo_nome=alvo.display_name,
                pat_emoji=pat["emoji"],
                pat_nome=pat["nome"],
                cargo_txt=cargo_txt,
                pontos=dados["pontos"],
                png_bytes=png_bytes,
            )
            if efemero
            else None
        )
        kwargs_envio = {"embed": embed, "file": arquivo_card, "ephemeral": efemero}
        if view_pub is not None:
            kwargs_envio["view"] = view_pub
        return await interaction.followup.send(**kwargs_envio)

    # Fallback em texto caso Pillow não esteja instalado no ambiente
    if prox:
        faixa_total = max(1, int(prox["min_pts"]) - int(pat["min_pts"]))
        avanco = max(0, int(dados["pontos"]) - int(pat["min_pts"]))
        pct_bar = min(1.0, avanco / faixa_total)
        blocos = int(round(pct_bar * 10))
        barra = "🟥" * blocos + "⬛" * (10 - blocos)
        progresso_txt = (
            f"`{barra}` **{int(pct_bar * 100)}%**\n"
            f"• Pontos: **`{dados['pontos']} pts`** • Faltam **`{dados['faltam_pts']} pts`** para {prox['emoji']} **{prox['nome']}**"
        )
    else:
        progresso_txt = (
            f"`🟥🟥🟥🟥🟥🟥🟥🟥🟥🟥` **100% (TOPO MÁXIMO)**\n"
            f"• Pontos acumulados: **`{dados['pontos']} pts`** • Patente máxima alcançada!"
        )

    embed = criar_embed(
        f"{pat['emoji']} Perfil Competitivo • {alvo.display_name}",
        f"**Patente Atual:** {pat['emoji']} **{pat['nome']}**{cargo_txt}\n"
        f"{progresso_txt}",
        "Vermelho Escuro",
        thumb=alvo.display_avatar.url,
        footer="Fire Force • Pontuação: cada Diário = +1 pt | cada Vitória = +3 pts",
    )
    streak_str = (
        f"🔥 **{dados['streak_atual']} seguida(s)** *(recorde: `{dados['maior_streak']}`)*"
        if dados["streak_atual"] > 0
        else f"`0` *(recorde: `{dados['maior_streak']}`)*"
    )
    embed.add_field(
        name="📊 Desempenho Vitalício",
        value=(
            f"• 🎮 **Diários Jogados:** `{dados['partidas']}`\n"
            f"• 🏆 **Vitórias:** `{dados['vitorias']}`\n"
            f"• 🎯 **Aproveitamento:** `{dados['winrate']:.1f}%`"
        ),
        inline=True,
    )
    embed.add_field(
        name="🔥 Sequência & Squad",
        value=(
            f"• **Win Streak:** {streak_str}\n"
            f"• ⚡ **Lines Salvas:** `{dados['qtd_lines']}`\n"
            + (f"• ⭐ **Favorita:** `{dados['line_favorita'][:24]}`" if dados["line_favorita"] else "• ⭐ **Favorita:** `—`")
        ),
        inline=True,
    )
    ultima = dados.get("ultima")
    if ultima:
        data_txt = str(ultima.get("criado_em") or "")[:16].replace("T", " ") or "—"
        ultima_txt = (
            f"{formatar_rotulo_diario(ultima.get('tipo') or '4x4', ultima.get('categoria') or 'mobile')} "
            f"• `{ultima.get('horario') or '—'}` (`{data_txt}`)"
        )
    else:
        ultima_txt = "Nenhum diário recente nos últimos 35 dias."
    embed.add_field(name="🕒 Última Participação", value=ultima_txt, inline=False)

    if efemero and alvo.id == interaction.user.id:
        saldo = await saldo_carteira(alvo.id, interaction.guild.id)
        vip_qtd = await obter_vagas_vip_usuario(interaction.guild.id, alvo.id)
        vip_str = f" • 🎟️ **Vagas VIP:** {formatar_qtd_vaga_vip(vip_qtd)}" if vip_qtd != 0 else ""
        embed.add_field(
            name="🔒 Seus Recursos Privados (só você vê)",
            value=f"🪙 **Carteira:** `{formatar_moeda(saldo)}`{vip_str}",
            inline=False,
        )

    await interaction.followup.send(embed=embed, ephemeral=efemero)


class ConfirmarAnuncioView(discord.ui.View):
    """Prévia e confirmação minimalista antes de publicar anúncio oficial."""

    def __init__(self, autor_id: int, guild: discord.Guild,
                 canal: discord.TextChannel, anuncio: discord.Embed,
                 cargo: Optional[discord.Role]):
        super().__init__(timeout=180)
        self.autor_id = int(autor_id)
        self.guild_id = int(guild.id)
        self.guild = guild
        self.canal = canal
        self.anuncio = anuncio
        self.cargo = cargo
        sel = discord.ui.Select(
            placeholder="📢 Confirme ou cancele a publicação...",
            options=[
                discord.SelectOption(
                    label="Publicar Anúncio Agora",
                    value="publicar",
                    emoji="📢",
                    description=f"Envia o anúncio em #{canal.name}"[:100],
                ),
                discord.SelectOption(
                    label="Cancelar Publicação",
                    value="cancelar",
                    emoji="↩️",
                    description="Descarta esta prévia sem enviar nada",
                ),
            ],
        )
        sel.callback = self._decidir
        self.add_item(sel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.autor_id:
            await interaction.response.send_message(
                embed=criar_embed("🔒 Prévia privada", "Só quem preparou o anúncio pode publicar ou cancelar.", "Vermelho"),
                ephemeral=True,
            )
            return False
        return True

    async def _decidir(self, interaction: discord.Interaction):
        if interaction.data["values"][0] == "cancelar":
            return await interaction.response.edit_message(
                content=None,
                embeds=[criar_embed("↩️ Publicação Cancelada", "O anúncio não foi publicado.", "Cinza Escuro")],
                view=None,
            )

        if not interaction.guild or interaction.guild.id != self.guild_id:
            return await interaction.response.send_message(
                embed=criar_embed("❌ Servidor inválido", "Esta prévia pertence a outro servidor.", "Vermelho"),
                ephemeral=True,
            )
        if not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Ação não autorizada", "Seu acesso de Dono/Gerente foi removido; não publiquei o anúncio.", "Vermelho"),
                ephemeral=True,
            )
        await interaction.response.defer()
        bot_member = interaction.guild.me
        perms = self.canal.permissions_for(bot_member) if bot_member else None
        if not perms or not (perms.send_messages and perms.embed_links):
            return await interaction.edit_original_response(
                embed=criar_embed(
                    "🛠️ Permissão ausente",
                    f"Preciso de **Enviar mensagens** e **Inserir links/embeds** em {self.canal.mention}.",
                    "Vermelho",
                ),
                view=ConfirmarAnuncioView(self.autor_id, self.guild, self.canal, self.anuncio, self.cargo),
            )
        if self.cargo and not self.cargo.mentionable and not perms.mention_everyone:
            return await interaction.edit_original_response(
                embed=criar_embed(
                    "📣 Menção bloqueada",
                    "O cargo não é mencionável e o bot não tem permissão para mencionar cargos.",
                    "Amarelo",
                ),
                view=ConfirmarAnuncioView(self.autor_id, self.guild, self.canal, self.anuncio, self.cargo),
            )
        try:
            await self.canal.send(
                content=self.cargo.mention if self.cargo else None,
                embed=self.anuncio,
                allowed_mentions=discord.AllowedMentions(
                    roles=[self.cargo] if self.cargo else [],
                    users=False, everyone=False, replied_user=False,
                ),
            )
        except (discord.Forbidden, discord.HTTPException) as erro:
            _log_arquivo(f"[ANÚNCIO] publicação guild={self.guild_id} canal={self.canal.id}: {erro}")
            return await interaction.edit_original_response(
                embed=criar_embed("⚠️ Não consegui publicar", "Confira as permissões do canal e tente novamente.", "Amarelo"),
                view=ConfirmarAnuncioView(self.autor_id, self.guild, self.canal, self.anuncio, self.cargo),
            )
        await registrar_log(
            interaction.guild, "📢 ANÚNCIO", "📢 Anúncio publicado",
            f"Por {interaction.user.mention} em {self.canal.mention}."
            + (f" Notificação: {self.cargo.mention}." if self.cargo else " Sem menção de cargo."),
            "Azul",
        )
        await interaction.edit_original_response(
            embed=criar_embed("✅ Anúncio Publicado", f"Publicado com sucesso em {self.canal.mention}.", "Esmeralda"),
            view=None,
        )


@bot.tree.command(name="anunciar", description="📢 Preparar e revisar um anúncio oficial antes de publicar")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
@app_commands.describe(titulo="Título do anúncio (até 256 caracteres)",
                       descricao="Texto do anúncio (até 4.000 caracteres)",
                       canal="Destino (por padrão, o canal atual)",
                       cargo="Cargo opcional a notificar; ninguém é mencionado sem sua escolha",
                       cor="Cor visual da embed")
@app_commands.choices(cor=[
    app_commands.Choice(name="Fire Force", value="Fire Force"),
    app_commands.Choice(name="Azul", value="Azul"),
    app_commands.Choice(name="Esmeralda", value="Esmeralda"),
    app_commands.Choice(name="Dourado", value="Dourado"),
    app_commands.Choice(name="Roxo", value="Roxo"),
    app_commands.Choice(name="Vermelho", value="Vermelho"),
])
@app_commands.checks.cooldown(1, 10.0, key=lambda i: (i.guild_id, i.user.id))
async def cmd_anunciar(interaction: discord.Interaction, titulo: str, descricao: str,
                       canal: Optional[discord.TextChannel] = None,
                       cargo: Optional[discord.Role] = None,
                       cor: Optional[app_commands.Choice[str]] = None):
    if not interaction.guild:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Só no servidor", "Use este comando dentro do servidor.", "Vermelho"),
            ephemeral=True)
    if not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("🔒 Sem permissão", "Apenas Dono, Gerente ou Administrador pode publicar anúncios.", "Vermelho"),
            ephemeral=True)
    titulo = (titulo or "").strip()
    descricao = (descricao or "").strip()
    if not titulo or len(titulo) > 256:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Título inválido", "O título precisa ter de 1 a 256 caracteres.", "Vermelho"),
            ephemeral=True)
    if not descricao or len(descricao) > 4000:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Texto inválido", "A descrição precisa ter de 1 a 4.000 caracteres.", "Vermelho"),
            ephemeral=True)
    destino = canal or interaction.channel
    if not isinstance(destino, discord.TextChannel) or destino.guild.id != interaction.guild.id:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Canal inválido", "Escolha um canal de texto deste servidor.", "Vermelho"),
            ephemeral=True)
    if cargo and (cargo.guild.id != interaction.guild.id or cargo.id == interaction.guild.id):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Cargo inválido", "Escolha um cargo comum deste servidor.", "Vermelho"),
            ephemeral=True)
    bot_member = interaction.guild.me
    perms = destino.permissions_for(bot_member) if bot_member else None
    if not perms or not (perms.send_messages and perms.embed_links):
        return await interaction.response.send_message(
            embed=criar_embed("🛠️ Permissão ausente",
                              f"O bot precisa de **Enviar mensagens** e **Inserir links/embeds** em {destino.mention}.",
                              "Vermelho"), ephemeral=True)
    if cargo and not cargo.mentionable and not perms.mention_everyone:
        return await interaction.response.send_message(
            embed=criar_embed("📣 Menção indisponível",
                              "O cargo não é mencionável e o bot não tem permissão para mencionar cargos.", "Amarelo"),
            ephemeral=True)

    nome_cor = cor.value if cor else "Fire Force"
    anuncio = criar_embed(titulo, descricao, nome_cor,
                          footer=f"{interaction.guild.name} • Fire Force",
                          author=interaction.guild.name,
                          author_icon=interaction.guild.icon.url if interaction.guild.icon else None)
    resumo = criar_embed(
        "👀 Prévia — revise antes de publicar",
        f"**Destino:** {destino.mention}\n"
        f"**Notificação:** {cargo.mention if cargo else 'Nenhuma'}\n\n"
        "A publicação só acontece ao clicar em **Publicar anúncio**. Menções a usuários/@everyone no texto não são disparadas.",
        "Azul")
    view = ConfirmarAnuncioView(interaction.user.id, interaction.guild, destino, anuncio, cargo)
    await interaction.response.send_message(embeds=[resumo, anuncio], view=view, ephemeral=True)


# ==================== INICIALIZAÇÃO ====================

# ══════════════════════════════════════════════════════════════
#  💰 SISTEMA FINANCEIRO — CARTEIRA VIRTUAL • PIX DIRETO • LOGS
#  • Depósito (PIX direto aos Donos) → confirmado manualmente → vira SALDO na carteira
#  • Saldo paga diário (+R$ 1,00 PIX ao ADM)
#  • Saque → PIX pago manualmente por Dono/Gerente
#  • Reserva interna de segurança protegida pelo sistema
#  • Logs completos no canal escolhido + fireforce.log
# ══════════════════════════════════════════════════════════════

# ---------- LOG (canal + arquivo) ----------

def _log_arquivo(texto: str):
    """Grava no fireforce.log e rotaciona quando passa de LOG_TAMANHO_MAX."""
    try:
        with open(ARQUIVO_LOG, "a", encoding="utf-8") as arquivo:
            arquivo.write(f"[{agora_brt().strftime('%d/%m/%Y %H:%M:%S')}] {texto}\n")
        if os.path.getsize(ARQUIVO_LOG) > LOG_TAMANHO_MAX:
            os.replace(ARQUIVO_LOG, ARQUIVO_LOG + ".1")
    except Exception:
        pass


async def canal_de_logs(guild_id: int):
    """ID do canal de logs configurado (com cache curto pra economizar consulta)."""
    cache = _CACHE_LOGS.get(guild_id)
    if cache and (time.time() - cache[1]) < 60:
        return cache[0]
    cfg = await obter_config(guild_id)
    canal_id = cfg.get("canal_logs")
    _CACHE_LOGS[guild_id] = (canal_id, time.time())
    return canal_id


CANAIS_PUBLICOS = (
    ("deposito", "canal_log_deposito", "💰 DEPÓSITO"),
    ("saque", "canal_log_saque", "💸 SAQUE"),
    ("pagamento", "canal_log_pagamento", "🎮 VENDA"),
    ("vaga", "canal_log_vaga", "📢 VAGA"),
)


def mascarar_chave(chave) -> str:
    """Esconde a chave PIX pro canal público: jo***@x.com • ***8900 • 1199...8888"""
    texto = str(chave or "").strip()
    if not texto:
        return "-"
    if "@" in texto:
        nome, _, dominio = texto.partition("@")
        return (nome[:2] + "***@" + dominio) if len(nome) > 2 else ("***@" + dominio)
    digitos = re.sub(r"\D", "", texto)
    if len(digitos) >= 10 and re.fullmatch(r"[\d.\-/()\s+]+", texto):
        return f"***{digitos[-4:]}"
    if len(texto) > 8:
        return f"{texto[:4]}...{texto[-4:]}"
    return "***"


def mascarar_chaves(texto) -> str:
    """Mascara qualquer chave PIX que apareça entre crases (ex.: `joao@pix.com`)."""
    def _troca(match):
        return match.group(1) + mascarar_chave(match.group(2)) + "`"
    return re.sub(r"(🏦[^`\n]{0,40}[Cc]have[^`\n]{0,40}`)([^`]+)`", _troca, str(texto or ""))


async def canal_anuncio(guild, tipo: str):
    """Canal do anúncio: o PÚBLICO configurado pro tipo ou, sem config, o de logs.

    Devolve (canal, publico)."""
    if not guild:
        return None, False
    chave_cfg = {chave: coluna for chave, coluna, _ in CANAIS_PUBLICOS}.get(tipo, "")
    if chave_cfg:
        cfg = await obter_config(guild.id)
        canal_id = cfg.get(chave_cfg)
        if canal_id:
            canal = guild.get_channel(int(canal_id))
            if canal:
                return canal, True
    canal_id = await canal_de_logs(guild.id)
    canal = guild.get_channel(int(canal_id)) if canal_id else None
    return canal, False


async def anunciar(guild, tipo: str, titulo: str, descricao: str, cor: str = "Esmeralda",
                   marcar: Optional[int] = None) -> bool:
    """Anúncio no canal PÚBLICO do tipo (depósito/saque/pagamento).

    Só manda se a equipe tiver configurado um canal separado — assim ninguém
    recebe mensagem repetida sem querer. A chave PIX sai mascarada."""
    canal, publico = await canal_anuncio(guild, tipo)
    if not canal or not publico:
        return False
    texto = mascarar_chaves(descricao) if publico else descricao
    try:
        await canal.send(content=(mencao(marcar) if marcar else None),
                         embed=criar_embed(titulo, texto, cor))
    except Exception as erro:
        _log_arquivo(f"[ANÚNCIO] {tipo}: {erro}")
        return False
    return True


async def registrar_log(guild, tipo: str, titulo: str, descricao: str,
                        cor: str = "Fire Force", campos: Optional[list] = None):
    """Registra o evento no arquivo e no canal de logs (se configurado)."""
    limpo = descricao.replace("**", "").replace("> ", "")
    _log_arquivo(f"[{tipo}] {titulo} — {limpo}")
    marcar_sujo()

    if not guild:
        return
    try:
        canal_id = await canal_de_logs(guild.id)
    except Exception:
        canal_id = None
    if not canal_id:
        return
    canal = guild.get_channel(int(canal_id))
    if not canal:
        return
    try:
        embed = criar_embed(titulo, descricao, cor, footer=f"🔥 Fire Force • {tipo}")
        for campo in (campos or []):
            embed.add_field(name=campo[0], value=campo[1], inline=(len(campo) < 3 or campo[2]))
        await canal.send(embed=embed)
    except Exception:
        pass


# ---------- PIX OFICIAL DOS DONOS (DEPÓSITOS NA CARTEIRA) ----------

async def montar_cobranca_pix_responsavel(
    guild_id: int,
    responsavel_id: int,
    valor: float = 0.0,
    titulo: str = "🏦 Chave PIX Liberada",
    mencao_destino: str = "",
    rodape: str = "Fire Force • QR Code PIX Oficial (BRCode)",
    nome_arquivo: str = "pix_qrcode.png",
):
    """Monta (embed, discord.File|None, CopiarPixAdmView) a partir da chave `/pix`
    cadastrada pelo Dono ou Gerente (`responsavel_id`) que assumiu o atendimento.
    Se `valor <= 0`, gera QR Code e Copia e Cola com valor livre."""
    pix_resp = await obter_pix_adm(int(responsavel_id), int(guild_id))
    if not pix_resp:
        return None, None, None

    tipo_ch = str(pix_resp.get("tipo") or "aleatoria")
    titular = str(pix_resp.get("titular") or "FIRE FORCE")
    chave_norm = normalizar_chave_pix_emv(tipo_ch, str(pix_resp["chave"]))
    val_num = arredondar(valor) if valor and float(valor) > 0 else 0.0
    payload = gerar_payload_pix(chave_norm, tipo_ch, titular, valor=val_num)

    valor_linha = (
        f"• **Valor específico:** **`{formatar_moeda(val_num)}`**\n"
        if val_num > 0
        else "• **Valor:** `Livre (digite o valor combinado no seu banco)`\n"
    )
    saudacao = f"{mencao_destino}, escaneie o QR Code ou copie a chave abaixo:\n\n" if mencao_destino else ""
    embed = criar_embed(
        titulo,
        f"{saudacao}"
        f"{valor_linha}"
        f"• **Responsável:** {mencao(responsavel_id)} (`{titular}`)\n"
        f"• **Chave PIX ({tipo_ch.upper()}):** `{chave_norm}`\n\n"
        f"**📋 PIX Copia e Cola:**\n```\n{payload}\n```\n"
        f"-# 📄 Após pagar, envie o print do comprovante neste canal.",
        "Esmeralda",
        footer=rodape,
    )
    arquivo = None
    try:
        arquivo = discord.File(gerar_qr_url(payload), nome_arquivo)
        embed.set_image(url=f"attachment://{nome_arquivo}")
    except Exception:
        arquivo = None
    return embed, arquivo, CopiarPixAdmView(payload)


def gerar_qr_url(url: str):
    """Gera QR Code (PNG) com margem ISO de 4 módulos e correção de erro M (leitura instantânea em bancos)."""
    qr = qrcode.QRCode(
        version=None,
        error_correction=qrcode.constants.ERROR_CORRECT_M,
        box_size=10,
        border=4,
    )
    qr.add_data(url)
    qr.make(fit=True)
    imagem = qr.make_image(fill_color="black", back_color="white")
    buffer = io.BytesIO()
    imagem.save(buffer, format="PNG")
    buffer.seek(0)
    return buffer


# ---------- NOMES E VALORES (casamento automático) ----------

def normalizar_nome(texto: str) -> str:
    """minúsculas, sem acento e sem símbolos — pra comparar nomes."""
    texto = str(texto or "").strip().lower()
    trocas = str.maketrans("áàâãäéèêëíìîïóòôõöúùûüçñ", "aaaaaeeeeiiiiooooouuuucn")
    texto = texto.translate(trocas)
    texto = re.sub(r"[^a-z0-9 ]+", " ", texto)
    return re.sub(r"\s+", " ", texto).strip()


RE_CODIGO_FF = re.compile(r"\bFF[\s\-_.]*([DPSX])[\s\-_.]*(\d{1,6})[\s\-_.]*([A-Z0-9]{3,8})\b",
                          re.IGNORECASE)


def codigos_no_texto(texto) -> list:
    """Acha o código do checkout (FF-D1-U8CD) ESCRITO na mensagem do pagamento.

    Muita gente paga pelo link fixo e digita o código na mensagem — assim o
    bot reconhece do mesmo jeito que se o código viesse no campo certo."""
    achados = []
    for letra, alvo, sufixo in RE_CODIGO_FF.findall(str(texto or "").upper()):
        codigo = f"FF-{letra}{int(alvo)}-{sufixo}"
        if codigo not in achados:
            achados.append(codigo)
    return achados


def apelidos_do_usuario(usuario) -> str:
    """Apelidos do jogador no Discord (nome de usuário e nome de exibição).

    Ficam guardados no depósito/reserva pra casar com o que a pessoa escrever
    no LivePix — tem gente que escreve só o @ do Discord."""
    partes = []
    for campo in ("name", "global_name", "display_name"):
        valor = str(getattr(usuario, campo, "") or "").strip()
        if valor and valor not in partes:
            partes.append(valor)
    return "|".join(partes)[:200]


def nomes_candidatos(registro, principal) -> list:
    """Todos os nomes que podem aparecer no pagamento deste registro."""
    candidatos = [str(principal or "")]
    try:
        extra = str(registro["apelidos"] or "")
    except Exception:
        extra = ""
    for parte in extra.split("|"):
        parte = parte.strip()
        if parte and parte not in candidatos:
            candidatos.append(parte)
    return [c for c in candidatos if c]


def nome_do_pagamento_bate(evento: dict, esperado) -> bool:
    """Aceita o NOME digitado no LivePix **ou** o que a pessoa escreveu na MENSAGEM.

    Ex.: Nome = "@73u3738" e Mensagem = "Daniel Souza" → casou com o depósito
    de "Daniel Souza". Sem nome e sem mensagem (só o pagamento), também aceita:
    aí o valor e a janela de tempo é que decidem."""
    nome = str((evento or {}).get("nome") or "").strip()
    texto = str((evento or {}).get("texto") or "").strip()
    if not nome and not texto:
        return True
    return nomes_parecidos(nome, esperado) or nomes_parecidos(texto, esperado)


def nomes_parecidos(a: str, b: str) -> bool:
    """Compara o nome do pagamento com o nome do jogador (tolerante, mas seguro)."""
    na, nb = normalizar_nome(a), normalizar_nome(b)
    if not na or not nb:
        return False
    if na == nb or na in nb or nb in na:
        return True
    tokens_a = {t for t in na.split() if len(t) >= 3}
    tokens_b = {t for t in nb.split() if len(t) >= 3}
    if not tokens_a or not tokens_b:
        return False
    comum = tokens_a & tokens_b
    return len(comum) >= min(2, len(tokens_a), len(tokens_b))


def valor_bate(centavos, valor: float) -> bool:
    """Valor pago x valor cobrado (aceita a diferença de taxa da LivePix)."""
    try:
        pago = float(centavos) / 100.0
    except Exception:
        return False
    if abs(pago - valor) <= 0.02:
        return True
    return valor * 0.90 <= pago <= valor * 1.02


async def _ja_visto(pix_id: str, tipo: str = "pagamento") -> bool:
    """Dedupe: cada pagamento/mensagem da LivePix só conta uma vez."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        linha = await (await db.execute("SELECT 1 FROM livepix_vistos WHERE id = ?", (str(pix_id),))).fetchone()
        if linha:
            return True
        await db.execute("INSERT OR IGNORE INTO livepix_vistos (id, tipo, criado_em) VALUES (?, ?, ?)",
                         (str(pix_id), tipo, agora_brt().isoformat()))
        await db.commit()
    return False


# ---------- CARTEIRA (saldo virtual) ----------

async def _garantir_carteira(db, user_id: int, guild_id: int):
    await db.execute(
        "INSERT OR IGNORE INTO carteira (user_id, guild_id, saldo, atualizado_em) VALUES (?, ?, 0, ?)",
        (user_id, guild_id, agora_brt().isoformat())
    )


async def saldo_carteira(user_id: int, guild_id: int) -> float:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linha = await (await db.execute(
            "SELECT saldo FROM carteira WHERE user_id = ? AND guild_id = ?", (user_id, guild_id)
        )).fetchone()
    return arredondar(linha["saldo"] if linha else 0)


async def movimentar_saldo(user_id: int, guild_id: int, valor: float, tipo: str,
                           descricao: str, ref: str = "", permitir_negativo: bool = False):
    """Credita (valor > 0) ou debita (valor < 0). Nunca deixa saldo negativo.
    Devolve o novo saldo, ou None se faltou saldo."""
    try:
        valor = float(valor)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(valor):
        return None
    valor = arredondar(valor)
    async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("BEGIN IMMEDIATE")
        await _garantir_carteira(db, user_id, guild_id)
        linha = await (await db.execute(
            "SELECT saldo FROM carteira WHERE user_id = ? AND guild_id = ?", (user_id, guild_id)
        )).fetchone()
        atual = arredondar(linha["saldo"] if linha else 0)
        novo = arredondar(atual + valor)
        if novo < 0 and not permitir_negativo:
            await db.rollback()
            return None
        await db.execute(
            "UPDATE carteira SET saldo = ?, atualizado_em = ? WHERE user_id = ? AND guild_id = ?",
            (novo, agora_brt().isoformat(), user_id, guild_id)
        )
        await db.execute(
            "INSERT INTO transacoes (guild_id, user_id, tipo, valor, saldo_apos, descricao, ref, criado_em) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (guild_id, user_id, tipo, valor, novo, descricao, ref, agora_brt().isoformat())
        )
        await db.commit()
    marcar_sujo()
    return novo


async def creditar_saldo(user_id: int, guild_id: int, valor: float, tipo: str,
                         descricao: str, ref: str = "") -> float:
    return await movimentar_saldo(user_id, guild_id, abs(valor), tipo, descricao, ref)


async def debitar_saldo(user_id: int, guild_id: int, valor: float, tipo: str,
                        descricao: str, ref: str = ""):
    return await movimentar_saldo(user_id, guild_id, -abs(valor), tipo, descricao, ref)


async def transferir_saldo_atomic(origem_id: int, destino_id: int, guild_id: int,
                                  valor: float, ref: str = "") -> Optional[tuple[float, float]]:
    """Transfere e registra os dois lados em uma única transação SQLite."""
    try:
        valor = float(valor)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(valor) or valor <= 0 or origem_id == destino_id:
        return None
    valor = arredondar(valor)
    agora = agora_brt().isoformat()
    async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("BEGIN IMMEDIATE")
        await _garantir_carteira(db, origem_id, guild_id)
        await _garantir_carteira(db, destino_id, guild_id)
        linhas = await (await db.execute(
            "SELECT user_id, saldo FROM carteira WHERE guild_id = ? AND user_id IN (?, ?)",
            (guild_id, origem_id, destino_id)
        )).fetchall()
        saldos = {int(l["user_id"]): arredondar(l["saldo"]) for l in linhas}
        saldo_origem = saldos.get(int(origem_id), 0.0)
        saldo_destino = saldos.get(int(destino_id), 0.0)
        if saldo_origem < valor:
            await db.rollback()
            return None
        novo_origem = arredondar(saldo_origem - valor)
        novo_destino = arredondar(saldo_destino + valor)
        await db.execute(
            "UPDATE carteira SET saldo = ?, atualizado_em = ? WHERE user_id = ? AND guild_id = ?",
            (novo_origem, agora, origem_id, guild_id))
        await db.execute(
            "UPDATE carteira SET saldo = ?, atualizado_em = ? WHERE user_id = ? AND guild_id = ?",
            (novo_destino, agora, destino_id, guild_id))
        await db.executemany(
            "INSERT INTO transacoes (guild_id, user_id, tipo, valor, saldo_apos, descricao, ref, criado_em) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            ((guild_id, origem_id, "transferencia_enviada", -valor, novo_origem,
              f"Transferência para usuário {destino_id}", f"{ref}:envio" if ref else "", agora),
             (guild_id, destino_id, "transferencia_recebida", valor, novo_destino,
              f"Transferência de usuário {origem_id}", f"{ref}:recebimento" if ref else "", agora)))
        await db.commit()
    marcar_sujo()
    return novo_origem, novo_destino


# ---------- CAIXA DA ORG (livro interno + saldo real) ----------

async def registrar_caixa(guild_id: int, tipo: str, valor: float, descricao: str, ref: str = ""):
    """tipo: 'receita' (entrou) ou 'despesa' (saiu)."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        await db.execute(
            "INSERT INTO livro_caixa (guild_id, tipo, valor, descricao, ref, criado_em) VALUES (?, ?, ?, ?, ?, ?)",
            (guild_id, tipo, arredondar(valor), descricao, ref, agora_brt().isoformat())
        )
        await db.commit()
    marcar_sujo()


async def resumo_caixa(guild_id: int, dia: Optional[str] = None) -> dict:
    """Totais do livro-caixa (geral e do dia, se informado)."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        async def _soma(tipo, filtro="", params=()):
            sql = f"SELECT COALESCE(SUM(valor), 0) FROM livro_caixa WHERE guild_id = ? AND tipo = ? {filtro}"
            return arredondar((await (await db.execute(sql, (guild_id, tipo) + params)).fetchone())[0])
        receitas = await _soma("receita")
        despesas = await _soma("despesa")
        dia_receitas = dia_receitas_qtd = 0.0
        if dia:
            dia_receitas = await _soma("receita", "AND criado_em LIKE ?", (f"{dia}%",))
            dia_despesas = await _soma("despesa", "AND criado_em LIKE ?", (f"{dia}%",))
            dia_receitas_qtd = (await (await db.execute(
                "SELECT COUNT(*) FROM livro_caixa WHERE guild_id = ? AND tipo = 'receita' AND criado_em LIKE ?",
                (guild_id, f"{dia}%")
            )).fetchone())[0]
        else:
            dia_despesas = 0.0
    return {
        "receitas": receitas, "despesas": despesas, "saldo": arredondar(receitas - despesas),
        "dia_receitas": dia_receitas, "dia_despesas": dia_despesas, "dia_movimentos": dia_receitas_qtd,
    }


async def saldo_org(guild_id: int):
    """Saldo contábil interno da organização (depósitos − saques)."""
    resumo = await resumo_caixa(guild_id)
    return resumo["saldo"], "livro interno"


async def fila_saques(guild_id: int) -> dict:
    """Saques em aberto (na fila + liberados aguardando o PIX sair)."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linhas = await (await db.execute(
            "SELECT * FROM saques WHERE guild_id = ? AND status IN ('na_fila', 'liberado') ORDER BY id",
            (guild_id,)
        )).fetchall()
    total = arredondar(sum(arredondar(l["valor"]) for l in linhas))
    return {"saques": [dict(l) for l in linhas], "total": total, "quantidade": len(linhas)}


async def disponibilidade_saque(guild_id: int) -> dict:
    """Quanto a org pode pagar AGORA sem furar a reserva mínima."""
    cfg = await obter_config(guild_id)
    reserva = arredondar(cfg.get("reserva") if cfg.get("reserva") is not None else CARTEIRA_RESERVA)
    valor_org, fonte = await saldo_org(guild_id)
    fila = await fila_saques(guild_id)
    livre = arredondar(valor_org - reserva - fila["total"])
    return {"saldo": valor_org, "fonte": fonte, "reserva": reserva,
            "fila": fila["total"], "fila_qtd": fila["quantidade"], "livre": livre}


# ---------- APROVAÇÃO (usada pelo staff, pela carteira e pela LivePix) ----------

async def pos_aprovacao(guild, slot, horario, staff_id: Optional[int] = None, origem: str = "staff"):
    """Registra o log de ganhos/recebimentos do ADM (com cupom/desconto se usado + quanto pagou + total do dia)."""
    slot_dict = slot if isinstance(slot, dict) else dict(slot)
    hor_dict = horario if isinstance(horario, dict) else dict(horario)

    valor = arredondar(slot_dict.get("valor_cobrado") or 0)
    valor_original = arredondar(hor_dict.get("valor") if hor_dict.get("valor") is not None else valor)
    comprador = slot_dict["comprador_id"]
    numero = slot_dict["numero"]
    slot_id = slot_dict["id"]
    tipo = hor_dict["tipo"]
    categoria = hor_dict["categoria"]
    hora = hor_dict["horario"]
    horario_id = hor_dict["id"]
    cupom_id = slot_dict.get("cupom_id")

    usou_vaga_vip = int(slot_dict.get("usou_vaga_vip") or 0) == 1
    pago_em_moedas = (origem == "moedas_adm") or (int(slot_dict.get("pago_moedas") or 0) == 1)
    valor_moedas = 0.0 if usou_vaga_vip else (arredondar(slot_dict.get("valor_moedas") or valor) if pago_em_moedas else 0.0)
    valor_base_inscr = valor_original if usou_vaga_vip else (valor_moedas if pago_em_moedas else valor)
    valor_pix_adm = (
        arredondar(slot_dict.get("taxa_adm_pix") or (TAXA_VAGA_VIP_ADM_PIX if usou_vaga_vip else TAXA_MOEDAS_ADM_PIX))
        if pago_em_moedas
        else valor
    )

    # Verifica se houve cupom / desconto aplicado na inscrição
    cupom_info = None
    if cupom_id:
        try:
            async with aiosqlite.connect(DATABASE_FILE) as db:
                db.row_factory = aiosqlite.Row
                cupom_row = await (await db.execute(
                    "SELECT codigo, tipo_desconto, valor FROM cupons WHERE id = ?",
                    (cupom_id,),
                )).fetchone()
                if cupom_row:
                    cupom_info = dict(cupom_row)
        except Exception:
            cupom_info = None

    desconto_reais = arredondar(max(0.0, valor_original - valor_base_inscr))
    usou_desconto = bool(cupom_info) or (desconto_reais > 0.009)
    detalhe_desconto = ""
    if usou_desconto:
        if cupom_info:
            cod_cupom = str(cupom_info.get("codigo") or "CUPOM").upper()
            if (cupom_info.get("tipo_desconto") or "pct") == "pct":
                detalhe_desconto = f"`{cod_cupom}` ({cupom_info['valor']:g}% OFF • `-{formatar_moeda(desconto_reais)}`)"
            else:
                detalhe_desconto = f"`{cod_cupom}` (`-{formatar_moeda(desconto_reais)}`)"
        else:
            detalhe_desconto = f"`-{formatar_moeda(desconto_reais)}`"

    canal_adm_enviado_id = None

    # Auditoria / Log de ganhos do ADM (aparece sempre que o ADM confirma uma vaga)
    if staff_id and origem in ("staff", "moedas_adm"):
        hoje_str = agora_brt().strftime("%Y-%m-%d")
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute(
                "INSERT INTO comissoes (guild_id, staff_id, slot_id, horario_id, valor_base, comissao, dia, criado_em) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    guild.id,
                    staff_id,
                    slot_id,
                    horario_id,
                    valor_original,
                    valor_pix_adm,
                    hoje_str,
                    agora_brt().isoformat(),
                ),
            )
            await db.commit()
        marcar_sujo()

        if pago_em_moedas:
            linhas_valores_adm = (
                f"> 🏷️ Valor original do diário: `{formatar_moeda(valor_original)}`\n"
                f"> 🎟️ **Desconto aplicado:** {detalhe_desconto}\n"
                f"> 🪙 Pago em moedas do bot: `{formatar_moeda(valor_moedas)}` *(fora do ADM)*\n"
                f"> 💰 **Quanto pagou no PIX ao ADM:** **`{formatar_moeda(valor_pix_adm)}`**"
                if usou_desconto
                else f"> 🪙 Pago em moedas do bot: `{formatar_moeda(valor_moedas)}` *(fora do ADM)*\n"
                     f"> 💰 **Quanto pagou no PIX ao ADM:** **`{formatar_moeda(valor_pix_adm)}`**"
            )
            canal_adm_enviado_id = await anunciar_pagamento_equipe(
                guild,
                staff_id,
                "🛡️ Log de Ganho do ADM — Vaga Confirmada (Moedas + PIX)",
                f"{mencao(staff_id)} confirmou a vaga de {mencao(comprador)}.\n"
                f"> 🎮 Diário: `{formatar_rotulo_diario(tipo, categoria)}` • `{hora}` ({texto_slot(tipo)} `#{numero}`)\n"
                f"{linhas_valores_adm}",
                "Dourado",
                forcar_adm=True,
            )
        else:
            linhas_valores_adm = (
                f"> 🏷️ Valor original do diário: `{formatar_moeda(valor_original)}`\n"
                f"> 🎟️ **Desconto aplicado:** {detalhe_desconto}\n"
                f"> 💰 **Quanto pagou ao ADM:** **`{formatar_moeda(valor_pix_adm)}`**"
                if usou_desconto
                else f"> 💰 **Quanto pagou ao ADM:** **`{formatar_moeda(valor_pix_adm)}`**"
            )
            canal_adm_enviado_id = await anunciar_pagamento_equipe(
                guild,
                staff_id,
                "🛡️ Log de Ganho do ADM — Vaga Confirmada",
                f"{mencao(staff_id)} confirmou o pagamento de {mencao(comprador)}.\n"
                f"> 🎮 Diário: `{formatar_rotulo_diario(tipo, categoria)}` • `{hora}` ({texto_slot(tipo)} `#{numero}`)\n"
                f"{linhas_valores_adm}",
                "Esmeralda",
                forcar_adm=True,
            )

    titulo_origem = {
        "staff": "PIX direto ao ADM",
        "moedas_adm": f"Moedas + {formatar_moeda(valor_pix_adm)} PIX ao ADM",
        "carteira": "Pagamento com moedas",
    }.get(origem, origem)

    bloco_desc_geral = (
        f"> 🏷️ Valor original: `{formatar_moeda(valor_original)}` • 🎟️ Desconto: {detalhe_desconto}\n"
        if usou_desconto
        else ""
    )
    resumo_valores_log = (
        f"{bloco_desc_geral}"
        f"> 🪙 Moedas do bot: `{formatar_moeda(valor_moedas)}` *(fora do ADM)*\n"
        f"> 💰 **Quanto pagou no PIX ao ADM ({mencao(staff_id) if staff_id else 'ADM'}):** `{formatar_moeda(valor_pix_adm)}`"
        if pago_em_moedas
        else f"{bloco_desc_geral}"
             f"> 💰 **Quanto pagou ao ADM ({mencao(staff_id) if staff_id else 'ADM'}):** `{formatar_moeda(valor_pix_adm)}`"
    )

    await anunciar(
        guild, "pagamento", "🎮 Vaga liberada — pagamento confirmado",
        f"{mencao(comprador)} garantiu a vaga **#{numero}** no diário `{hora}`.\n"
        f"> 🎮 Modo: `{texto_slot(tipo)}` • Categoria: `{categoria.title()}`\n"
        f"> 💰 Valor pago: `{formatar_moeda(valor)}` • ✅ confirmado ({titulo_origem})\n"
        f"> 🧑‍⚖️ Liberado por: {mencao(staff_id) if staff_id else 'Equipe'}",
        "Esmeralda", marcar=comprador)

    # Se o log do ADM já caiu no próprio canal_logs geral (fallback), evita duplicar a mesma mensagem lá
    canal_logs_geral = await canal_de_logs(guild.id) if guild else None
    if canal_adm_enviado_id and canal_logs_geral and int(canal_adm_enviado_id) == int(canal_logs_geral):
        _log_arquivo(f"[✅ PAGAMENTO] {titulo_origem} — slot #{slot_id} ({formatar_moeda(valor_pix_adm)})")
    else:
        await registrar_log(
            guild, "✅ PAGAMENTO", "✅ Recebimento confirmado e vaga liberada",
            f"**{titulo_origem}** — {mencao(comprador)}\n"
            f"> 🎮 Modo: `{texto_slot(tipo)}` • Categoria: `{categoria.title()}`\n"
            f"> ⏰ Diário: `{hora}` • Vaga: `#{numero}`\n"
            f"{resumo_valores_log}",
            "Esmeralda"
        )

    if guild and comprador:
        try:
            await sincronizar_cargo_patente(guild, int(comprador))
        except Exception as erro:
            _log_arquivo(f"[PATENTE] pós-aprovação user={comprador}: {erro}")

    # 🎬 Influenciador em LIVE confirmou a reserva? Publica o card de Caça aos Influenciadores
    try:
        if (
            INFLUENCIADORES_ATIVO
            and guild
            and comprador
            and int(slot_dict.get("influencer_em_live") or 0) == 1
            and int(slot_dict.get("influencer_anunciado") or 0) == 0
        ):
            await anunciar_caca_influencer_do_slot(guild, int(slot_id))
    except Exception as erro:
        _log_arquivo(f"[INFLUENCER] anúncio pós-aprovação slot={slot_id}: {type(erro).__name__}: {erro}")


async def aprovar_pagamento(guild, slot_id: int, staff_id: Optional[int] = None,
                            origem: str = "carteira"):
    """Cria a vaga de verdade (número, canal do diário, acesso, tabela).
    Usado pelo pagamento com saldo e pela confirmação automática da LivePix."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        slot = await (await db.execute("SELECT * FROM slots WHERE id = ?", (slot_id,))).fetchone()
        if not slot or slot["confirmado"]:
            return None
        horario = await (await db.execute("SELECT * FROM horarios WHERE id = ?", (slot["horario_id"],))).fetchone()
        if not horario:
            return None

        total_vagas = LOTES_POR_MODO[horario["tipo"]]
        ocupadas = (await (await db.execute(
            "SELECT COUNT(*) FROM slots WHERE horario_id = ? AND confirmado = 1", (slot["horario_id"],)
        )).fetchone())[0]
        if ocupadas >= total_vagas:
            return None

        numero_final = ocupadas + 1
        await db.execute("UPDATE slots SET confirmado = 1, numero = ? WHERE id = ?", (numero_final, slot["id"]))
        await db.execute("UPDATE horarios SET lotes_usados = ? WHERE id = ?", (numero_final, slot["horario_id"]))
        await db.commit()
        slot = dict(slot)
        slot["numero"] = numero_final
        horario = dict(horario)

    try:
        canal_tabela_id = await criar_canal_tabela(guild, slot["horario_id"])
    except Exception as erro:
        canal_tabela_id = None
        print("Erro ao criar canal do diário:", erro)

    comprador = await membro_do_guild(guild, slot["comprador_id"])
    if comprador:
        try:
            await add_jogador_canal_tabela(guild, slot["horario_id"], comprador)
        except Exception:
            pass
    try:
        await atualizar_tabela(guild, slot["horario_id"])
    except Exception:
        pass
    await rebuild_painel(guild, horario["painel_id"])

    await pos_aprovacao(guild, slot, horario, staff_id=staff_id, origem=origem)

    # avisa o comprador no canal de pagamento + envia recibo na DM + apaga canal em 15s
    canal_pag = guild.get_channel(slot["canal_pag"]) if slot.get("canal_pag") else None
    canal_tab_obj = guild.get_channel(canal_tabela_id) if canal_tabela_id else None
    ref_tab = canal_tab_obj.mention if canal_tab_obj else "o canal oficial do diário"
    try:
        if canal_pag:
            embed = criar_embed(
                "✅ Pagamento Aprovado!",
                f"{mencao(slot['comprador_id'])} — **{texto_slot(horario['tipo']).lower()} #{numero_final}** liberada!\n"
                f"> 🎮 `{formatar_rotulo_diario(horario['tipo'], horario['categoria'])}` • `{horario['horario']}`\n"
                f"> 📊 **Acompanhe tudo em:** {ref_tab}\n"
                f"> 📩 Comprovante enviado na sua **DM** (ID e senha chegam **5 min antes**).\n\n"
                f"⏳ *Este canal de pagamento será salvo nos logs e apagado em **{PAGAMENTO_APROVADO_FECHAR_SEGUNDOS}s**.*",
                "Esmeralda",
            )
            await canal_pag.send(content=mencao(slot["comprador_id"]), embed=embed)
    except Exception:
        pass

    await _notificar_dm_e_agendar_fechamento_pag(
        guild=guild,
        slot_dict=slot,
        horario_dict=horario,
        numero_final=numero_final,
        canal_pag=canal_pag,
        canal_tabela_id=canal_tabela_id,
    )

    return numero_final, horario


async def pagar_com_saldo(guild, slot_id: int, user_id: int):
    """Debita as moedas do bot (fora do repasse ao ADM) e solicita +R$ 1,00 via PIX ao ADM para aprovar a vaga."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        slot = await (await db.execute("SELECT * FROM slots WHERE id = ?", (slot_id,))).fetchone()
        if not slot or slot["confirmado"]:
            return False, "Esta reserva não está mais aberta.", None
        slot_dict = dict(slot)
        if int(slot_dict["comprador_id"]) != int(user_id):
            return False, "Só o dono desta reserva pode pagar com moedas.", None
        if int(slot_dict.get("pago_moedas") or 0) == 1:
            return False, AVISO_MOEDAS_ADM_PIX, None

        horario = await (await db.execute("SELECT * FROM horarios WHERE id = ?", (slot_dict["horario_id"],))).fetchone()
        if not horario or not horario["ativo"]:
            return False, "Este diário já foi encerrado.", None
        if (horario_para_datetime(horario["horario"]) - agora_brt()).total_seconds() <= 0:
            return False, "Este diário já começou.", None

        confirmados = (await (await db.execute(
            "SELECT COUNT(*) FROM slots WHERE horario_id = ? AND confirmado = 1", (slot_dict["horario_id"],)
        )).fetchone())[0]
        if confirmados >= LOTES_POR_MODO.get(horario["tipo"], 48):
            return False, "A sala já está com todas as vagas confirmadas.", None

    valor = arredondar(slot_dict["valor_cobrado"])
    novo = await debitar_saldo(
        user_id, guild.id, valor, "compra",
        f"Diário pago em moedas — reserva #{slot_id}", ref=f"slot:{slot_id}"
    )
    if novo is None:
        saldo_atual = await saldo_carteira(user_id, guild.id)
        return (
            False,
            f"Saldo de moedas insuficiente. Você tem {formatar_moeda(saldo_atual)} e a vaga custa {formatar_moeda(valor)}.",
            None,
        )

    async with aiosqlite.connect(DATABASE_FILE) as db:
        cur = await db.execute(
            "UPDATE slots SET pago_moedas = 1, valor_moedas = ?, taxa_adm_pix = ? "
            "WHERE id = ? AND confirmado = 0 AND COALESCE(pago_moedas, 0) = 0",
            (valor, TAXA_MOEDAS_ADM_PIX, slot_id),
        )
        await db.commit()
        if cur.rowcount != 1:
            await creditar_saldo(user_id, guild.id, valor, "estorno", "Estorno — reserva já processada", ref=f"slot:{slot_id}")
            return False, "Esta reserva já foi processada; suas moedas não foram cobradas.", None
    marcar_sujo()

    canal_pag = guild.get_channel(int(slot_dict["canal_pag"])) if slot_dict.get("canal_pag") else None
    if canal_pag:
        try:
            adm_id = slot_dict.get("assumido_por")
            pix_adm = await obter_pix_adm(adm_id, guild.id) if adm_id else None
            if adm_id and pix_adm:
                emb_pix, arq_qr, payload_pix = await montar_cobranca_pix_adm_embed(
                    adm_id=adm_id,
                    comprador_id=user_id,
                    pix_adm=pix_adm,
                    valor_pix=TAXA_MOEDAS_ADM_PIX,
                    slot_id=slot_id,
                    pago_moedas=True,
                    valor_moedas=valor,
                )
                kwargs_env = {
                    "content": f"{mencao(user_id)} {mencao(adm_id)}",
                    "embed": emb_pix,
                    "view": CopiarPixAdmView(payload_pix),
                }
                if arq_qr:
                    kwargs_env["file"] = arq_qr
                await canal_pag.send(**kwargs_env)
            else:
                emb_aviso = criar_embed(
                    "🪙 Pagamento com Moedas Registrado!",
                    f"{mencao(user_id)}, {AVISO_MOEDAS_ADM_PIX}\n\n"
                    f"> 🪙 **Moedas debitadas:** `{formatar_moeda(valor)}` *(saldo restante: `{formatar_moeda(novo)}`)*\n"
                    f"> 💸 **Falta enviar ao ADM:** **`{formatar_moeda(TAXA_MOEDAS_ADM_PIX)}` via Pix**\n"
                    f"> ⏳ Assim que um ADM clicar em **🙋 Assumir**, a chave PIX e o QR Code dele de "
                    f"**`{formatar_moeda(TAXA_MOEDAS_ADM_PIX)}`** aparecerão aqui para ele liberar sua vaga!",
                    "Dourado",
                    footer="Fire Force • A vaga só é liberada após o ADM aprovar o PIX de R$ 1,00",
                )
                await canal_pag.send(content=mencao(user_id), embed=emb_aviso)
        except Exception as erro:
            _log_arquivo(f"[MOEDAS] aviso canal_pag: {erro}")

    await registrar_log(
        guild,
        "🪙 MOEDAS",
        "🪙 Vaga paga em moedas (aguardando +R$ 1,00 PIX ao ADM)",
        f"{mencao(user_id)} debitou **{formatar_moeda(valor)}** em moedas do bot *(valor fica fora do repasse ao ADM)*.\n"
        f"> 🎮 Modo: `{texto_slot(horario['tipo'])}` • Categoria: `{horario['categoria'].title()}` • `{horario['horario']}`\n"
        f"> 💸 Aguardando envio de **`{formatar_moeda(TAXA_MOEDAS_ADM_PIX)}`** via PIX ao ADM e liberação da vaga.",
        "Dourado",
    )
    return True, AVISO_MOEDAS_ADM_PIX, None


# ---------- DEPÓSITO (PIX DIRETO AOS DONOS) ----------

class DepositoModal(discord.ui.Modal, title="💰 Depositar na Carteira (PIX)"):
    campo_valor = discord.ui.TextInput(
        label="Valor do depósito (R$)", placeholder="Ex: 10,00", required=True, max_length=12)
    campo_nome = discord.ui.TextInput(
        label="Nome do pagador (no comprovante)",
        placeholder="Seu nome completo ou apelido no banco",
        required=True, max_length=60)

    def __init__(self, deposito_id: int = 0, canal_id: int = 0):
        super().__init__()
        self.deposito_id = deposito_id
        self.canal_id = canal_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True, thinking=True)
        valor = parse_valor(self.campo_valor.value)
        minimo = float(await cfgv(interaction.guild.id, "deposito_min", CARTEIRA_DEPOSITO_MIN))
        if valor is None or valor < minimo:
            return await interaction.followup.send(
                embed=criar_embed("❌ Valor inválido", f"O depósito mínimo é **{formatar_moeda(minimo)}**.", "Vermelho"),
                ephemeral=True)

        nome = self.campo_nome.value.strip()
        expira = (agora_brt() + datetime.timedelta(hours=12)).isoformat()

        assumido_por = 0
        if self.deposito_id:
            async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
                db.row_factory = aiosqlite.Row
                cur = await db.execute("UPDATE depositos SET valor = ?, nome_pagador = ?, status = 'na_janela', "
                                       "criado_em = ?, expira_em = ? WHERE id = ? AND guild_id = ? "
                                       "AND user_id = ? AND status IN ('aguardando','na_janela')",
                                       (valor, nome, agora_brt().isoformat(), expira, self.deposito_id,
                                        interaction.guild.id, interaction.user.id))
                await db.commit()
                if cur.rowcount != 1:
                    return await interaction.followup.send(
                        embed=criar_embed("ℹ️ Depósito já resolvido",
                                          "Esse pedido não está mais aberto. Abra um novo pelo painel da carteira.", "Amarelo"),
                        ephemeral=True)
                row_dep = await (await db.execute(
                    "SELECT assumido_por FROM depositos WHERE id = ?", (self.deposito_id,)
                )).fetchone()
                assumido_por = int((row_dep["assumido_por"] if row_dep else 0) or 0)
            deposito_id = self.deposito_id
        else:
            async with aiosqlite.connect(DATABASE_FILE) as db:
                cursor = await db.execute(
                    "INSERT INTO depositos (guild_id, user_id, valor, nome_pagador, apelidos, status, "
                    "criado_em, expira_em) VALUES (?, ?, ?, ?, ?, 'na_janela', ?, ?)",
                    (interaction.guild.id, interaction.user.id, valor, nome,
                     apelidos_do_usuario(interaction.user), agora_brt().isoformat(), expira))
                deposito_id = cursor.lastrowid
                await db.commit()
        marcar_sujo()

        arquivo = None
        view_copiar = None
        mencoes_vip = ""
        if assumido_por:
            embed, arquivo, view_copiar = await montar_cobranca_pix_responsavel(
                interaction.guild.id,
                assumido_por,
                valor=valor,
                titulo="💰 PIX para Depósito na Carteira",
                mencao_destino=interaction.user.mention,
                rodape=f"Fire Force • Depósito #{deposito_id}",
                nome_arquivo="deposito_pix.png",
            )
            if not embed:
                embed = criar_embed(
                    "💰 Pedido de Depósito Registrado",
                    f"{interaction.user.mention} informou o depósito de **`{formatar_moeda(valor)}`** (`{nome}`).\n"
                    f"• {mencao(assumido_por)}, cadastre sua chave em `/pix` e clique novamente em **Assumir** para enviar o QR Code.",
                    "Amarelo",
                    footer=f"Fire Force • Depósito #{deposito_id}",
                )
        else:
            cfg = await obter_config(interaction.guild.id)
            mencoes_vip = " ".join(
                f"<@&{cfg[k]}>" for k in ("cargo_dono", "cargo_gerente") if cfg.get(k)
            )
            embed = criar_embed(
                "💰 Pedido de Depósito Registrado",
                f"• **Jogador:** {interaction.user.mention}\n"
                f"• **Valor desejado:** **`{formatar_moeda(valor)}`**\n"
                f"• **Pagador informado:** `{nome}`\n\n"
                f"-# 🙋 Aguardando o **Dono** ou **Gerente** clicar em **Assumir** — o QR Code e a chave PIX dele serão enviados aqui automaticamente.",
                "Cinza Escuro",
                footer=f"Fire Force • Depósito #{deposito_id}",
            )

        destino = interaction.channel
        try:
            if self.canal_id:
                destino = interaction.guild.get_channel(self.canal_id) or interaction.channel
        except Exception:
            destino = interaction.channel
        enviar = {"embed": embed}
        if mencoes_vip:
            enviar["content"] = mencoes_vip
        if arquivo:
            enviar["file"] = arquivo
        if view_copiar:
            enviar["view"] = view_copiar
        try:
            await destino.send(**enviar)
            await interaction.followup.send(
                embed=criar_embed(
                    "✅ Valor Registrado",
                    "QR Code enviado no canal!" if assumido_por else "Pedido registrado! Assim que um Dono ou Gerente assumir, o PIX aparecerá automaticamente no canal.",
                    "Esmeralda",
                ),
                ephemeral=True,
            )
        except Exception:
            enviar.pop("content", None)
            enviar["ephemeral"] = True
            await interaction.followup.send(**enviar)

        await registrar_log(
            interaction.guild, "💰 DEPÓSITO", "💰 Depósito aberto",
            f"{mencao(interaction.user.id)} abriu depósito de **{formatar_moeda(valor)}** (`{nome}`).",
            "Azul",
        )


class SaqueModal(discord.ui.Modal, title="💸 Sacar — PIX"):
    campo_valor = discord.ui.TextInput(label="Valor do saque (R$)", placeholder="Ex: 25,00", required=True,
                                       max_length=12)
    campo_chave = discord.ui.TextInput(label="Sua chave PIX", placeholder="CPF, celular, e-mail ou aleatória",
                                       required=True, max_length=120)
    campo_titular = discord.ui.TextInput(
        label="Nome do titular da chave", required=False, max_length=80,
        placeholder="Use o mesmo nome do depósito — agiliza o pagamento")

    def __init__(self, tipo_chave: str = "aleatoria", tipo_carteira: str = "jogador",
                 chave_salva: str = "", titular_salvo: str = ""):
        super().__init__()
        self.tipo_chave = tipo_chave or "aleatoria"
        self.tipo_carteira = tipo_carteira or "jogador"
        if chave_salva:
            self.campo_chave.default = chave_salva
        if titular_salvo:
            self.campo_titular.default = titular_salvo

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True, thinking=True)
        valor = parse_valor(self.campo_valor.value)
        minimo = float(await cfgv(interaction.guild.id, "saque_min", CARTEIRA_SAQUE_MIN))
        chave = self.campo_chave.value.strip()
        titular = self.campo_titular.value.strip()
        de_trabalho = (self.tipo_carteira == "trabalho")
        if de_trabalho and not await tem_carteira_trabalho(interaction.user):
            return await interaction.followup.send(
                embed=criar_embed("🔒 Carteira de trabalho", "A carteira de trabalho é exclusiva do cargo Suporte (ADM recebe direto no PIX).", "Vermelho"),
                ephemeral=True)

        saldo = (await saldo_trabalho(interaction.user.id, interaction.guild.id) if de_trabalho
                 else await saldo_carteira(interaction.user.id, interaction.guild.id))
        if de_trabalho:
            agora_saque=agora_brt()
            janela_aberta=(agora_saque.weekday()==6 and agora_saque.hour>=23) or (agora_saque.weekday()==0 and agora_saque.hour<1)
            if not janela_aberta:
                return await interaction.followup.send(embed=criar_embed("💼 Saque semanal ainda não liberado","A nota geral fecha domingo às 23h. O saque da carteira de trabalho fica disponível depois desse fechamento e até segunda 01:00 (BRT).","Amarelo"),ephemeral=True)
            if agora_saque.weekday()==6:
                await fechar_notas_semanais(interaction.guild, agora_saque.strftime('%Y-%m-%d'))
                saldo=await saldo_trabalho(interaction.user.id,interaction.guild.id)
        if valor is None or valor < minimo:
            return await interaction.followup.send(
                embed=criar_embed("❌ Valor inválido", f"O saque mínimo é **{formatar_moeda(minimo)}**.", "Vermelho"),
                ephemeral=True)
        if valor > saldo:
            onde = "na sua **carteira de trabalho** (o salário da equipe)" if de_trabalho else "na sua carteira"
            return await interaction.followup.send(
                embed=criar_embed("❌ Saldo insuficiente",
                                  f"Você tem **{formatar_moeda(saldo)}** {onde} e pediu "
                                  f"**{formatar_moeda(valor)}**.\n\n"
                                  + ("> 💼 O saque do Suporte sai sempre da **carteira de trabalho** "
                                     "(pagamento das avaliações de atendimento)." if de_trabalho else
                                     "> 💰 Use **Depositar PIX** na carteira ou `/transferir` pra completar o valor."),
                                  "Vermelho"), ephemeral=True)

        # salva a chave: o próximo saque vira 1 clique
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute(
                "INSERT OR REPLACE INTO chaves_salvas (user_id, guild_id, tipo, chave, titular, atualizado_em) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (interaction.user.id, interaction.guild.id, self.tipo_chave, chave, titular,
                 agora_brt().isoformat()))
            await db.commit()
        marcar_sujo()

        if de_trabalho:
            novo = await movimentar_trabalho(interaction.user.id, interaction.guild.id, -valor, "saque",
                                             f"Saque da carteira de trabalho ({self.tipo_chave})")
        else:
            novo = await debitar_saldo(interaction.user.id, interaction.guild.id, valor, "saque",
                                       f"Saque solicitado — chave {self.tipo_chave}")
        if novo is None:
            return await interaction.followup.send(
                embed=criar_embed("❌ Saldo insuficiente", "Tente novamente.", "Vermelho"), ephemeral=True)

        disp = await disponibilidade_saque(interaction.guild.id)
        liberado = disp["livre"] >= valor
        status = "liberado" if liberado else "na_fila"

        async with aiosqlite.connect(DATABASE_FILE) as db:
            cursor = await db.execute(
                "INSERT INTO saques (guild_id, user_id, valor, chave_pix, titular, tipo_chave, status, tipo, criado_em, "
                "saldo_antes, saldo_apos) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (interaction.guild.id, interaction.user.id, valor, chave, titular, self.tipo_chave, status,
                 "trabalho" if de_trabalho else "jogador", agora_brt().isoformat(),
                 arredondar(saldo), arredondar(novo)))
            saque_id = cursor.lastrowid
            await db.commit()
        marcar_sujo()

        try:
            canal_ticket = await abrir_ticket_saque(interaction.guild, interaction.user, saque_id)
        except Exception as erro:
            # Não deixa o saque debitado sem um canal privado para acompanhar.
            if de_trabalho:
                await creditar_trabalho(interaction.user.id, interaction.guild.id, valor, "estorno",
                                        f"Estorno automático: não foi possível abrir ticket do saque #{saque_id}",
                                        ref=f"saque-ticket-erro:{saque_id}")
            else:
                await creditar_saldo(interaction.user.id, interaction.guild.id, valor, "estorno",
                                     f"Estorno automático: não foi possível abrir ticket do saque #{saque_id}",
                                     ref=f"saque-ticket-erro:{saque_id}")
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute("UPDATE saques SET status='estornado',ticket_status='estornado' WHERE id=?",(saque_id,))
                await db.commit()
            _log_arquivo(f"[SAQUE] ticket #{saque_id} não abriu; valor devolvido: {erro}")
            return await interaction.followup.send(embed=criar_embed(
                "❌ Não foi possível abrir seu ticket",
                "O valor foi devolvido à sua carteira. Avise o dono/gerente para conferir a permissão **Gerenciar Canais** do bot.","Vermelho"),ephemeral=True)
        aviso_saque=criar_embed(
            "💸 Pedido de saque registrado",
            f"Seu ticket privado está em {canal_ticket.mention}.\n"
            f"> 🔖 Protocolo: `#{saque_id}` • Valor: `{formatar_moeda(valor)}`\n"
            f"> 🔐 A chave PIX e o titular ficam no canal, visível para você e dono/gerente.\n"
            f"> ⏳ Prazo: de 1 minuto a 24 horas ou mais.","Esmeralda")
        aviso_saque.add_field(name="⏱️ Quanto tempo demora?",value="O pagamento é manual e pode levar de **1 minuto a 24 horas ou mais**, conforme disponibilidade.",inline=False)
        aviso_saque.add_field(name="👑 Quem paga agora",value="Somente **Dono ou Gerente** realiza o PIX diretamente e marca o pagamento como concluído.",inline=False)
        await interaction.followup.send(embed=aviso_saque,ephemeral=True)

        await anunciar(
            interaction.guild, "saque", "💸 Novo pedido de saque",
            f"{mencao(interaction.user.id)} pediu **{formatar_moeda(valor)}** e já reservou o valor da "
            f"carteira.\n> 🔖 Protocolo: `#{saque_id}`\n"
            f"> 📋 Status: **{'liberado para pagar ✅' if liberado else 'na fila de pagamento 🤝'}**\n"
            f"> 🏦 Chave: `{mascarar_chave(chave)}`"
            + ("\n> ⏱️ O pagamento sai pelo **dono/gerente** — de minutos até 24h ou mais."
               if liberado else "\n> ⏳ Entra na fila de pagamento assim que o caixa liberar."),
            "Amarelo", marcar=None)
        await notificar_saque(interaction.guild, saque_id)
        await registrar_log(
            interaction.guild, "💸 SAQUE", "💸 Novo pedido de saque",
            f"{mencao(interaction.user.id)} pediu saque de **{formatar_moeda(valor)}**"
            f"{' — descontado da **carteira de trabalho** (salário)' if de_trabalho else ''}.\n"
            f"> 🔖 Protocolo: `#{saque_id}` • Status: `{'liberado para pagar' if liberado else 'na fila'}`\n"
            f"> 🏦 Chave ({self.tipo_chave}): `{mascarar_chave(chave)}` • Titular: `{titular or '-'}`\n"
            + (f"> 💼 Carteira de trabalho: `{formatar_moeda(saldo)}` − `{formatar_moeda(valor)}` = "
               f"**total atualizado `{formatar_moeda(novo)}`**"
               if de_trabalho else
               f"> 💰 Carteira: `{formatar_moeda(saldo)}` − `{formatar_moeda(valor)}` = "
               f"**total atualizado `{formatar_moeda(novo)}`**"),
            "Amarelo")


def embed_ticket_saque(saque) -> discord.Embed:
    """Resumo minimalista do saque privado (visível apenas no ticket restrito)."""
    tipo = saque["tipo"] or "jogador"
    fonte = "💼 Carteira de Trabalho (Suporte)" if tipo == "trabalho" else "🪙 Carteira Pessoal"
    estado = saque["status"]
    fila = {
        "na_fila": "⏳ Na fila do caixa",
        "liberado": "💳 Caixa liberado • Aguardando envio do PIX",
        "pago": "✅ PIX enviado",
        "estornado": "↩️ Estornado para a carteira",
    }.get(estado, "⏳ Aguardando pagamento")
    cor = "Esmeralda" if estado == "pago" else ("Amarelo" if estado == "estornado" else "Cinza Escuro")
    resp = mencao(saque["ticket_assumido_por"]) if saque["ticket_assumido_por"] else "`Aguardando responsável`"

    descricao = (
        f"• **Solicitante:** {mencao(saque['user_id'])}\n"
        f"• **Valor:** **`{formatar_moeda(saque['valor'])}`**\n"
        f"• **Origem:** {fonte}\n"
        f"• **Chave PIX ({(saque['tipo_chave'] or 'chave').upper()}):** `{saque['chave_pix']}`\n"
        f"• **Titular:** `{saque['titular'] or 'não informado'}`\n"
        f"• **Status:** {fila}\n"
        f"• **Responsável:** {resp}\n"
        f"-# Protocolo #{saque['id']} • Canal privado entre solicitante e Dono/Gerente"
    )
    return criar_embed(f"💸 Solicitação de Saque #{saque['id']}", descricao, cor)


async def atualizar_ticket_saque(guild, saque_id: int):
    """Atualiza o cartão privado do saque em qualquer mudança (fila, espera ou pagamento)."""
    if not guild:
        return False
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        row = await (await db.execute("SELECT * FROM saques WHERE id=?", (saque_id,))).fetchone()
    if not row or not row["canal_ticket_id"] or not row["msg_ticket_id"]:
        return False
    canal = guild.get_channel(int(row["canal_ticket_id"]))
    if not canal:
        return False
    try:
        msg = await canal.fetch_message(int(row["msg_ticket_id"]))
        await msg.edit(embed=embed_ticket_saque(row), view=SaqueTicketView(saque_id))
        return True
    except Exception as erro:
        _log_arquivo(f"[SAQUE] ticket #{saque_id} não atualizou: {erro}")
        return False


async def abrir_ticket_saque(guild, solicitante, saque_id: int):
    """Cria o atendimento privado do saque; sem acesso de suporte/mediador."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        row = await (await db.execute("SELECT * FROM saques WHERE id=?", (saque_id,))).fetchone()
    if not row:
        raise RuntimeError("protocolo de saque não encontrado")
    cfg = await obter_config(guild.id)
    categoria = guild.get_channel(cfg.get("cat_pagamentos")) if cfg.get("cat_pagamentos") else None
    if not categoria and cfg.get("cat_tickets"):
        categoria = guild.get_channel(cfg.get("cat_tickets"))
    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        solicitante: discord.PermissionOverwrite(view_channel=True, send_messages=True, attach_files=True, read_message_history=True),
    }
    bot_member = getattr(guild, "me", None)
    if bot_member:
        overwrites[bot_member] = discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True, read_message_history=True)
    cargos_permitidos = set()
    for key in ("cargo_dono", "cargo_gerente"):
        role_id = cfg.get(key)
        role = guild.get_role(int(role_id)) if role_id else None
        if role:
            cargos_permitidos.add(role.id)
            overwrites[role] = discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True)
    for key in ("cargo_suporte", "cargo_mediador"):
        role_id = cfg.get(key)
        role = guild.get_role(int(role_id)) if role_id and int(role_id) not in cargos_permitidos else None
        if role:
            overwrites[role] = discord.PermissionOverwrite(view_channel=False, send_messages=False)
    nome = getattr(solicitante, "display_name", None) or getattr(solicitante, "name", "jogador")
    slug = re.sub(r"[^a-z0-9-]", "-", str(nome).lower()).strip("-")[:35] or "jogador"
    canal = await guild.create_text_channel(f"💸│saque-{int(saque_id)}-{slug}"[:100], category=categoria, overwrites=overwrites)
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("UPDATE saques SET canal_ticket_id=?,ticket_status='aguardando_pagamento' WHERE id=?", (canal.id, saque_id))
            await db.commit()
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            row = await (await db.execute("SELECT * FROM saques WHERE id=?", (saque_id,))).fetchone()
        msg = await canal.send(content=mencao(row["user_id"]), embed=embed_ticket_saque(row), view=SaqueTicketView(saque_id))
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("UPDATE saques SET msg_ticket_id=? WHERE id=?", (msg.id, saque_id))
            await db.commit()
        marcar_sujo()
        return canal
    except Exception:
        try:
            await canal.delete()
        except Exception:
            pass
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("UPDATE saques SET canal_ticket_id=NULL,msg_ticket_id=NULL WHERE id=?", (saque_id,))
            await db.commit()
        raise


class SaqueTicketView(discord.ui.View):
    """Painel minimalista de atendimento privado do saque (Select único moderno)."""

    def __init__(self, saque_id: int = 0):
        super().__init__(timeout=None)
        self.saque_id = int(saque_id) if isinstance(saque_id, int) else 0
        sel = discord.ui.Select(
            custom_id=f"ff_sqt_sel:{self.saque_id}",
            placeholder="💸 Gerenciar solicitação de saque...",
            options=[
                discord.SelectOption(
                    label="Assumir Atendimento",
                    value="assumir",
                    emoji="🙋",
                    description="Dono/Gerente assume o acompanhamento deste saque",
                ),
                discord.SelectOption(
                    label="Reassumir / Trocar Responsável",
                    value="reassumir",
                    emoji="🔄",
                    description="Transfere este saque para você (Dono/Gerente)",
                ),
                discord.SelectOption(
                    label="Confirmar Pagamento Feito",
                    value="pago",
                    emoji="✅",
                    description="Registra o PIX como enviado e avisa o solicitante",
                ),
                discord.SelectOption(
                    label="Marcar Aguardando Pagamento",
                    value="aguardar",
                    emoji="⏳",
                    description="Mantém o status como aguardando envio do PIX",
                ),
                discord.SelectOption(
                    label="Adicionar Pessoa ao Canal",
                    value="adicionar",
                    emoji="➕",
                    description="Concede acesso a outro membro neste canal",
                ),
                discord.SelectOption(
                    label="Encerrar Canal de Saque",
                    value="fechar",
                    emoji="🔒",
                    description="Fecha e remove este canal privado",
                ),
            ],
        )
        sel.callback = self._rotear
        self.add_item(sel)

    async def _buscar(self):
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            return await (await db.execute("SELECT * FROM saques WHERE id=?", (self.saque_id,))).fetchone()

    async def _equipe(self, interaction):
        if await e_dono_ou_gerente(interaction.user):
            return True
        await interaction.response.send_message(
            embed=criar_embed("🔒 Exclusivo Dono/Gerente", "Esta ação é exclusiva do **Dono** ou **Gerente**.", "Vermelho"),
            ephemeral=True,
        )
        return False

    async def _rotear(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        try:
            await interaction.message.edit(view=SaqueTicketView(self.saque_id))
        except Exception:
            pass

        if acao in ("assumir", "reassumir"):
            if not await self._equipe(interaction):
                return
            if not await aviso_fora_de_servico(interaction):
                return
            row = await self._buscar()
            if not row or row["status"] in ("pago", "estornado"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Saque resolvido", "Este pedido já foi pago ou estornado.", "Cinza Escuro"), ephemeral=True
                )
            antigo_resp = row["ticket_assumido_por"]
            if antigo_resp and antigo_resp != interaction.user.id and acao != "reassumir":
                return await interaction.response.send_message(
                    embed=criar_embed(
                        "🙋 Já assumido",
                        f"{mencao(antigo_resp)} está responsável. Use **🔄 Reassumir / Trocar Responsável** se precisar transferir.",
                        "Amarelo",
                    ),
                    ephemeral=True,
                )
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute("UPDATE saques SET ticket_assumido_por=? WHERE id=?", (interaction.user.id, self.saque_id))
                await db.commit()
            marcar_sujo()
            await atualizar_ticket_saque(interaction.guild, self.saque_id)
            return await interaction.response.send_message(
                embed=criar_embed(
                    "🔄 Saque Reassumido" if (antigo_resp and antigo_resp != interaction.user.id) else "🙋 Saque Assumido",
                    "Você ficou responsável por acompanhar este saque.",
                    "Esmeralda",
                ),
                ephemeral=True,
            )

        if acao == "aguardar":
            if not await self._equipe(interaction):
                return
            row = await self._buscar()
            if not row or row["status"] in ("pago", "estornado"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Saque resolvido", "Este pedido já foi pago ou estornado.", "Cinza Escuro"), ephemeral=True
                )
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute("UPDATE saques SET ticket_status='aguardando_pagamento' WHERE id=?", (self.saque_id,))
                await db.commit()
            marcar_sujo()
            await atualizar_ticket_saque(interaction.guild, self.saque_id)
            return await interaction.response.send_message(
                embed=criar_embed("⏳ Status Atualizado", "O saque permanece marcado como **Aguardando pagamento**.", "Cinza Escuro"),
                ephemeral=True,
            )

        if acao == "pago":
            if not await self._equipe(interaction):
                return
            row = await self._buscar()
            if not row or row["status"] in ("pago", "estornado"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Saque resolvido", "Este pedido já foi pago ou estornado.", "Cinza Escuro"), ephemeral=True
                )
            await interaction.response.defer(ephemeral=True, thinking=True)
            ok = await concluir_saque(self.saque_id, interaction.user.id, "pagamento marcado como feito no ticket privado")
            return await interaction.followup.send(
                embed=criar_embed(
                    "✅ Pagamento Registrado" if ok else "ℹ️ Já Resolvido",
                    "O saque foi marcado como pago e o solicitante recebeu a confirmação." if ok else "Outro responsável já resolveu este saque.",
                    "Esmeralda" if ok else "Cinza Escuro",
                ),
                ephemeral=True,
            )

        if acao == "adicionar":
            if not await self._equipe(interaction):
                return
            row = await self._buscar()
            if not row or row["status"] in ("pago", "estornado"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Saque resolvido", "Não é necessário adicionar membros a um saque já finalizado.", "Cinza Escuro"),
                    ephemeral=True,
                )
            return await interaction.response.send_message(
                embed=criar_embed("➕ Adicionar Pessoa", "Selecione abaixo quem deve receber acesso a este canal:", "Cinza Escuro"),
                view=TicketAddView(),
                ephemeral=True,
            )

        if acao == "fechar":
            row = await self._buscar()
            eh_vip = await e_dono_ou_gerente(interaction.user)
            if not row:
                if eh_vip:
                    await interaction.response.send_message("🔒 Encerrando canal...", ephemeral=True)
                    await _apagar_canal_seguro(interaction.channel, "Canal órfão de saque encerrado")
                    return
                return await interaction.response.send_message(
                    embed=criar_embed("❌ Saque não encontrado", "", "Vermelho"), ephemeral=True
                )
            if interaction.user.id != row["user_id"] and not eh_vip:
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Sem Permissão", "Apenas o solicitante ou Dono/Gerente podem encerrar este canal.", "Amarelo"),
                    ephemeral=True,
                )
            if row["status"] not in ("pago", "estornado") and not eh_vip:
                return await interaction.response.send_message(
                    embed=criar_embed("⏳ Saque em andamento", "Aguarde o PIX ser enviado ou estornado antes de fechar o canal.", "Amarelo"),
                    ephemeral=True,
                )
            await interaction.response.send_message(
                embed=criar_embed("🔒 Canal Encerrado", "Este canal será removido em 3 segundos...", "Cinza Escuro")
            )
            await asyncio.sleep(3)
            apagado = await _apagar_canal_seguro(interaction.channel, f"Ticket de saque #{self.saque_id} encerrado")
            if apagado:
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    await db.execute("UPDATE saques SET canal_ticket_id=NULL,msg_ticket_id=NULL WHERE id=?", (self.saque_id,))
                    await db.commit()
                marcar_sujo()


class SaqueAcaoView(discord.ui.View):
    """Seletor minimalista no aviso privado de saque (persistente após restart)."""

    def __init__(self, saque_id: int):
        super().__init__(timeout=None)
        self.saque_id = int(saque_id)
        sel = discord.ui.Select(
            custom_id=f"ff_sqa_sel:{self.saque_id}",
            placeholder="💸 Ação financeira do saque...",
            options=[
                discord.SelectOption(
                    label="Confirmar PIX Enviado",
                    value="pago",
                    emoji="✅",
                    description="Marca o saque como pago e atualiza o caixa",
                ),
                discord.SelectOption(
                    label="Estornar (Devolver Saldo)",
                    value="estorno",
                    emoji="↩️",
                    description="Devolve o valor integral para a carteira",
                ),
                discord.SelectOption(
                    label="Reenviar Dados",
                    value="reenviar",
                    emoji="🔁",
                    description="Reenvia os dados deste saque no canal financeiro",
                ),
            ],
        )
        sel.callback = self._rotear
        self.add_item(sel)

    async def _buscar(self):
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            return await (await db.execute("SELECT * FROM saques WHERE id = ?", (self.saque_id,))).fetchone()

    async def _rotear(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        try:
            await interaction.message.edit(view=SaqueAcaoView(self.saque_id))
        except Exception:
            pass
        if not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Sem Permissão", "Apenas Dono ou Gerente.", "Vermelho"), ephemeral=True
            )

        if acao == "pago":
            saque = await self._buscar()
            if not saque or saque["status"] in ("pago", "estornado"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Já resolvido", "Este saque já foi pago ou estornado.", "Cinza Escuro"), ephemeral=True
                )
            await concluir_saque(saque["id"], interaction.user.id, "pagamento marcado pela equipe")
            try:
                await interaction.message.edit(view=None)
            except Exception:
                pass
            return await interaction.response.send_message(
                embed=criar_embed("✅ Saque Pago", f"Protocolo `#{saque['id']}` marcado como pago.", "Esmeralda"), ephemeral=True
            )

        if acao == "estorno":
            saque = await self._buscar()
            if not saque or saque["status"] in ("pago", "estornado"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Já resolvido", "Este saque já foi pago ou estornado.", "Cinza Escuro"), ephemeral=True
                )
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute("UPDATE saques SET status='estornado',ticket_status='estornado' WHERE id=?", (saque["id"],))
                await db.commit()
            if saque["tipo"] == "trabalho":
                await creditar_trabalho(saque["user_id"], saque["guild_id"], saque["valor"], "estorno", f"Estorno do saque #{saque['id']}", ref=f"saque:{saque['id']}")
            else:
                await creditar_saldo(saque["user_id"], saque["guild_id"], saque["valor"], "estorno", f"Estorno do saque #{saque['id']}", ref=f"saque:{saque['id']}")
            marcar_sujo()
            await atualizar_ticket_saque(interaction.guild, saque["id"])
            await registrar_log(
                interaction.guild, "💸 SAQUE", "↩️ Saque estornado",
                f"Protocolo `#{saque['id']}` foi estornado por {interaction.user.mention}.\n"
                f"• {mencao(saque['user_id'])} recebeu **{formatar_moeda(saque['valor'])}** de volta na carteira.",
                "Amarelo",
            )
            try:
                await interaction.message.edit(view=None)
            except Exception:
                pass
            return await interaction.response.send_message(
                embed=criar_embed("↩️ Saque Estornado", "O saldo retornou integralmente para a carteira do solicitante.", "Amarelo"),
                ephemeral=True,
            )

        if acao == "reenviar":
            await notificar_saque(interaction.guild, self.saque_id, forcar=True)
            return await interaction.response.send_message(
                embed=criar_embed("🔁 Reenviado", "Dados do saque reenviados.", "Cinza Escuro"), ephemeral=True
            )


async def notificar_saque(guild, saque_id: int, forcar: bool = False):
    """Manda pro canal financeiro privado os dados prontos para Dono/Gerente enviar o PIX."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        saque = await (await db.execute("SELECT * FROM saques WHERE id = ?", (saque_id,))).fetchone()
    if not saque or saque["status"] in ("pago", "estornado"):
        return
    if saque["status"] == "na_fila" and not forcar:
        return

    disp = await disponibilidade_saque(guild.id)
    de_trabalho = (saque["tipo"] or "jogador") == "trabalho"
    atual = (
        await saldo_trabalho(saque["user_id"], saque["guild_id"])
        if de_trabalho
        else await saldo_carteira(saque["user_id"], saque["guild_id"])
    )
    fonte_txt = "Carteira de Trabalho (Suporte)" if de_trabalho else "Carteira Pessoal"
    embed = criar_embed(
        f"💸 Saque Solicitado • Protocolo #{saque['id']}",
        f"• **Solicitante:** {mencao(saque['user_id'])}\n"
        f"• **Valor:** **`{formatar_moeda(saque['valor'])}`**\n"
        f"• **Chave PIX:** `{saque['chave_pix']}`\n"
        f"• **Titular:** `{saque['titular'] or 'não informado'}`\n"
        f"• **Origem:** {fonte_txt} *(saldo atual: `{formatar_moeda(atual)}`)*\n"
        f"• **Caixa Interno:** `{formatar_moeda(disp['saldo'])}` *(reserva: `{formatar_moeda(disp['reserva'])}` • fila: `{formatar_moeda(disp['fila'])}`)*\n"
        f"-# Envie o PIX manualmente e registre no seletor abaixo",
        "Cinza Escuro",
    )
    canal, motivo_privacidade = await canal_financeiro_privado(guild)
    if canal:
        try:
            await canal.send(embed=embed, view=SaqueAcaoView(saque_id))
        except Exception as erro:
            _log_arquivo(f"[SAQUE] aviso privado #{saque_id} não enviado: {erro}")
    else:
        _log_arquivo(f"[SAQUE] aviso #{saque_id} sem canal privado: {motivo_privacidade}")


async def concluir_saque(saque_id: int, staff_id: Optional[int] = None, motivo: str = ""):
    """Fecha o saque como PAGO: caixa, log e aviso pro jogador."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        saque = await (await db.execute("SELECT * FROM saques WHERE id = ?", (saque_id,))).fetchone()
        if not saque or saque["status"] in ("pago", "estornado"):
            return False
        cursor=await db.execute(
            "UPDATE saques SET status='pago',ticket_status='pago',processado_em=?,processado_por=? "
            "WHERE id=? AND status NOT IN ('pago','estornado')",
            (agora_brt().isoformat(),staff_id,saque_id))
        if cursor.rowcount==0:return False
        await db.commit()

    await registrar_caixa(saque["guild_id"], "despesa", saque["valor"],
                          f"Saque pago #{saque_id} (PIX direto)", ref=f"saque:{saque_id}")

    guild = bot.get_guild(saque["guild_id"])
    if guild:
        await atualizar_ticket_saque(guild,saque_id)
        try:
            canal, publico = await canal_anuncio(guild, "saque")
            if canal:
                chave_mostrada = mascarar_chave(saque["chave_pix"]) if publico else saque["chave_pix"]
                embed = criar_embed(
                    "✅ Saque pago",
                    f"{mencao(saque['user_id'])} — seu saque foi **enviado**!\n\n"
                    f"> 🔖 Protocolo: `#{saque_id}`\n"
                    f"> 💰 Valor: `{formatar_moeda(saque['valor'])}`\n"
                    f"> 🏦 Chave: `{chave_mostrada}`\n\n"
                    f"Obrigado por jogar na 🔥 Fire Force!",
                    "Esmeralda"
                )
                await canal.send(content=mencao(saque["user_id"]), embed=embed)
        except Exception:
            pass
        quem = f" por {mencao(staff_id)}" if staff_id else ""
        de_trabalho = (saque["tipo"] or "jogador") == "trabalho"
        atual = (await saldo_trabalho(saque["user_id"], guild.id) if de_trabalho
                 else await saldo_carteira(saque["user_id"], guild.id))
        await registrar_log(
            guild, "💸 SAQUE", "✅ Saque pago",
            f"Protocolo `#{saque_id}` — {formatar_moeda(saque['valor'])} para {mencao(saque['user_id'])}{quem}.\n"
            f"> {motivo or 'pagamento enviado'}\n> 🏦 Chave: `{mascarar_chave(saque['chave_pix'])}`\n"
            + (f"> 💼 Carteira de trabalho: `{formatar_moeda(saque['saldo_antes'])}` − "
               f"`{formatar_moeda(saque['valor'])}` = **total atualizado `{formatar_moeda(atual)}`**"
               if (de_trabalho and saque["saldo_antes"] is not None)
               else f"> 💰 Carteira agora: **`{formatar_moeda(atual)}`**"),
            "Esmeralda"
        )
        if de_trabalho:
            await anunciar_pagamento_equipe(
                guild, saque["user_id"], "💼 Salário pago — PIX",
                f"{mencao(saque['user_id'])} recebeu **{formatar_moeda(saque['valor'])}** "
                f"(carteira de trabalho).\n"
                f"> 🔖 Protocolo: `#{saque_id}` • ✅ PIX enviado"
                + (f" por {mencao(staff_id)}" if staff_id else "")
                + f"\n> 💼 Carteira de trabalho agora: `{formatar_moeda(atual)}`",
                "Esmeralda")
        await processar_fila_saques(guild.id)
    return True


# ---------- FILA: paga sozinho quando o caixa permite ----------

async def processar_fila_saques(guild_id: int) -> list:
    """Sempre que entra dinheiro, olha a fila e libera o que couber na reserva."""
    liberados = []
    disp = await disponibilidade_saque(guild_id)
    if disp["livre"] <= 0:
        return liberados

    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        fila = await (await db.execute(
            "SELECT * FROM saques WHERE guild_id = ? AND status = 'na_fila' ORDER BY id", (guild_id,)
        )).fetchall()

    livre = disp["livre"]
    for saque in fila:
        if arredondar(saque["valor"]) > livre:
            continue
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("UPDATE saques SET status = 'liberado' WHERE id = ?", (saque["id"],))
            await db.commit()
        livre = arredondar(livre - saque["valor"])
        liberados.append(dict(saque))

    guild = bot.get_guild(guild_id)
    for saque in liberados:
        if guild:
            await atualizar_ticket_saque(guild,saque["id"])
            await notificar_saque(guild, saque["id"])
            await registrar_log(
                guild, "💸 SAQUE", "⚡ Saque liberado para pagamento",
                f"Protocolo `#{saque['id']}` de {mencao(saque['user_id'])} "
                f"(**{formatar_moeda(saque['valor'])}**) entrou na fila de pagamento de agora.",
                "Verde"
            )
    return liberados


