# ---------- UTILITÁRIOS DO SISTEMA FINANCEIRO ----------

def parse_valor(texto) -> Optional[float]:
    """Aceita '10', '10,00', '10.00', 'R$ 10,00'."""
    try:
        limpo = str(texto or "").strip().lower().replace("r$", "").replace(" ", "")
        if "," in limpo and "." in limpo:
            limpo = limpo.replace(".", "").replace(",", ".")
        else:
            limpo = limpo.replace(",", ".")
        valor = float(limpo)
        if not math.isfinite(valor) or valor <= 0:
            return None
        valor = round(valor, 2)
        return valor if valor > 0 else None
    except Exception:
        return None


async def cfgv(guild_id: int, chave: str, padrao=None):
    """Valor de configuração do servidor com fallback pro padrão."""
    cfg = await obter_config(guild_id)
    valor = cfg.get(chave)
    return padrao if valor in (None, "", 0) else valor


async def extrato_texto(user_id: int, guild_id: int, quantidade: int = 10) -> str:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linhas = await (await db.execute(
            "SELECT * FROM transacoes WHERE guild_id = ? AND user_id = ? ORDER BY id DESC LIMIT ?",
            (guild_id, user_id, quantidade)
        )).fetchall()
    if not linhas:
        return "> *Nenhuma movimentação ainda.*"

    icones = {
        "deposito": "⬆️", "saque": "⬇️", "compra": "🎮", "comissao": "💸",
        "transferencia_enviada": "📤", "transferencia_recebida": "📥",
        "ajuste": "🛠️", "estorno": "↩️", "premio": "🏆",
    }
    texto = []
    for linha in linhas:
        valor = arredondar(linha["valor"])
        sinal = "+" if valor >= 0 else "−"
        icone = icones.get(linha["tipo"], "•")
        quando = (linha["criado_em"] or "")[8:16].replace("-", "/")
        descricao = (linha["descricao"] or "")[:48]
        texto.append(f"> {icone} `{sinal}{formatar_moeda(abs(valor))}` — {descricao} `{quando}`")
    return "\n".join(texto)


async def resumo_comissoes_dia(guild_id: int, dia: str) -> dict:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linhas = await (await db.execute(
            "SELECT staff_id, COUNT(*) AS qtd, COALESCE(SUM(valor_base), 0) AS base, "
            "COALESCE(SUM(comissao), 0) AS total FROM comissoes "
            "WHERE guild_id = ? AND dia = ? GROUP BY staff_id ORDER BY total DESC",
            (guild_id, dia)
        )).fetchall()
    return {
        "por_adm": [dict(l) for l in linhas],
        "total": arredondar(sum(arredondar(l["total"]) for l in linhas)),
        "base": arredondar(sum(arredondar(l["base"]) for l in linhas)),
        "vendas": sum(int(l["qtd"]) for l in linhas),
    }


# ==================== COMANDOS DA CARTEIRA ====================

async def responder_ephemeral(interaction: discord.Interaction, **kwargs):
    """Responde em privado e completa o placeholder quando a interação foi deferida."""
    if interaction.response.is_done():
        tipo_resposta = getattr(interaction.response, "type", None)
        if tipo_resposta == discord.InteractionResponseType.deferred_channel_message:
            return await interaction.edit_original_response(**kwargs)
        return await interaction.followup.send(ephemeral=True, **kwargs)
    return await interaction.response.send_message(ephemeral=True, **kwargs)


async def montar_embed_carteira(alvo, guild_id: int, tipo_carteira: str = "pessoal"):
    avatar = alvo.display_avatar.url if getattr(alvo, "display_avatar", None) else None
    if tipo_carteira == "trabalho":
        saldo = await saldo_trabalho(alvo.id, guild_id)
        extrato = await extrato_trabalho(alvo.id, guild_id, 8)
        embed = criar_embed(
            f"💼 Carteira de trabalho — {alvo.display_name}",
            "Ganhos da equipe e histórico de movimentações. Esta carteira não recebe depósitos PIX.",
            "Dourado",
            thumb=avatar
        )
        embed.add_field(name="💼 Saldo a receber", value=f"**{formatar_moeda(saldo)}**", inline=True)
        embed.add_field(name="🕒 Janela de saque", value="Domingo 23:00 → segunda 01:00 BRT", inline=True)
        embed.add_field(name="📜 Movimentações recentes", value=extrato[:1024], inline=False)
        embed.set_footer(text="Fire Force • Carteira de trabalho privada")
        return embed

    saldo = await saldo_carteira(alvo.id, guild_id)
    extrato = await extrato_texto(alvo.id, guild_id, 8)
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        saques = await (await db.execute(
            "SELECT COUNT(*) AS qtd, COALESCE(SUM(valor), 0) AS total FROM saques "
            "WHERE guild_id = ? AND user_id = ? AND status IN ('na_fila', 'liberado')",
            (guild_id, alvo.id)
        )).fetchone()
    embed = criar_embed(
        f"💰 Carteira pessoal — {alvo.display_name}",
        "Resumo privado da sua carteira. Use os botões abaixo para depositar, sacar ou atualizar.",
        "Esmeralda",
        thumb=avatar
    )
    embed.add_field(name="💰 Saldo disponível", value=f"**{formatar_moeda(saldo)}**", inline=True)
    embed.add_field(
        name="⏳ Saques em andamento",
        value=f"**{formatar_moeda(saques['total'])}** • {saques['qtd']} pedido(s)",
        inline=True
    )
    embed.add_field(name="📜 Movimentações recentes", value=extrato[:1024], inline=False)
    embed.set_footer(text="Fire Force • Carteira pessoal privada")
    return embed

async def mostrar_menu_carteira(interaction: discord.Interaction, editar: bool = False):
    pode_trabalho = await tem_carteira_trabalho(interaction.user)
    embed = criar_embed(
        "💳 Sua carteira",
        "Escolha qual conta quer abrir. **Saldo e movimentações aparecem só para você.**\n\n"
        "> 💰 **Pessoal:** depósitos PIX, saques e movimentações do jogo.\n"
        + ("> 💼 **Trabalho (Suporte):** avaliações e saldo semanal do suporte.\n" if pode_trabalho else "")
        + "\nUse o botão **Atualizar** dentro da carteira para consultar os dados mais recentes.",
        "Fire Force"
    )
    view = CarteiraInicioView(interaction.user.id, pode_trabalho)
    if editar:
        await interaction.response.edit_message(embed=embed, view=view)
    else:
        await responder_ephemeral(interaction, embed=embed, view=view)


async def mostrar_carteira(interaction: discord.Interaction, tipo_carteira: str, editar: bool = True):
    if tipo_carteira == "trabalho" and not await tem_carteira_trabalho(interaction.user):
        return await responder_ephemeral(
            interaction,
            embed=criar_embed("🔒 Carteira exclusiva do Suporte", "A carteira de trabalho está disponível apenas para o cargo Suporte (ADM recebe direto no seu PIX via `/pix`).", "Vermelho")
        )
    embed = await montar_embed_carteira(interaction.user, interaction.guild.id, tipo_carteira)
    view = CarteiraDetalheView(interaction.user.id, tipo_carteira)
    if editar:
        await interaction.response.edit_message(embed=embed, view=view)
    else:
        await interaction.response.send_message(embed=embed, view=view, ephemeral=True)


class CarteiraInicioSelect(discord.ui.Select):
    def __init__(self, owner_id: int, pode_trabalho: bool):
        self.owner_id = int(owner_id)
        opcoes = [
            discord.SelectOption(
                label="Carteira Pessoal",
                value="pessoal",
                emoji="💰",
                description="Saldo em moedas, depósito PIX e pedido de saque",
            )
        ]
        if pode_trabalho:
            opcoes.append(
                discord.SelectOption(
                    label="Carteira de Trabalho (Suporte)",
                    value="trabalho",
                    emoji="💼",
                    description="Saldo semanal de atendimentos e avaliações",
                )
            )
        super().__init__(placeholder="💳 Selecione qual carteira deseja abrir...", options=opcoes)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner_id:
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Carteira privada", "Este painel pertence a quem o abriu.", "Vermelho"),
                ephemeral=True,
            )
