class ConfirmarAjusteSaldoView(discord.ui.View):
    """Confirmação minimalista ligada a quem iniciou o ajuste e à carteira escolhida."""

    def __init__(self, autor_id: int, alvo_id: int, guild_id: int,
                 valor: float, motivo: str, tipo_carteira: str = "pessoal"):
        super().__init__(timeout=90)
        self.autor_id = int(autor_id)
        self.alvo_id = int(alvo_id)
        self.guild_id = int(guild_id)
        self.valor = float(valor)
        self.motivo = str(motivo)[:300]
        self.tipo_carteira = "trabalho" if tipo_carteira == "trabalho" else "pessoal"
        sel = discord.ui.Select(
            placeholder="🛠️ Confirme ou cancele este ajuste...",
            options=[
                discord.SelectOption(
                    label="Confirmar Ajuste de Saldo",
                    value="confirmar",
                    emoji="✅",
                    description="Aplica o ajuste imediatamente e registra em auditoria",
                ),
                discord.SelectOption(
                    label="Cancelar Ajuste",
                    value="cancelar",
                    emoji="↩️",
                    description="Descarta a operação sem alterar nenhum saldo",
                ),
            ],
        )
        sel.callback = self._decidir
        self.add_item(sel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.autor_id:
            await interaction.response.send_message(
                embed=criar_embed("🔒 Confirmação privada", "Só quem preparou este ajuste pode confirmar.", "Vermelho"),
                ephemeral=True,
            )
            return False
        return True

    async def _decidir(self, interaction: discord.Interaction):
        if interaction.data["values"][0] == "cancelar":
            return await interaction.response.edit_message(
                embed=criar_embed("↩️ Ajuste Cancelado", "Nenhum saldo foi alterado.", "Cinza Escuro"), view=None
            )

        if (not interaction.guild or interaction.guild.id != self.guild_id
                or not await e_dono_ou_gerente(interaction.user)):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Ação não autorizada", "Apenas Dono ou Gerente podem confirmar ajustes de carteira.", "Vermelho"),
                ephemeral=True,
            )
        if self.alvo_id == interaction.user.id and not await tem_cargo_dono_ou_gerente_configurado(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed(
                    "🔒 Autoajuste bloqueado",
                    "Apenas os cargos configurados de Dono/Gerente podem fazer autoajuste.",
                    "Vermelho",
                ),
                ephemeral=True,
            )

        await interaction.response.defer()
        alvo = await membro_do_guild(interaction.guild, self.alvo_id)
        if not alvo or getattr(alvo, "bot", False):
            return await interaction.edit_original_response(
                embed=criar_embed("❌ Ajuste cancelado", "O jogador não está mais no servidor ou é um bot.", "Vermelho"),
                view=None,
            )
        if self.tipo_carteira == "trabalho" and not await tem_carteira_trabalho(alvo):
            return await interaction.edit_original_response(
                embed=criar_embed("❌ Ajuste cancelado", "A carteira de trabalho é exclusiva do cargo Suporte.", "Vermelho"),
                view=None,
            )

        descricao_auditoria = f"{self.motivo} — por {interaction.user.display_name}"
        if self.tipo_carteira == "trabalho":
            novo = await movimentar_trabalho(
                self.alvo_id, self.guild_id, self.valor, "ajuste", descricao_auditoria,
                ref=f"ajuste:trabalho:{interaction.id}",
            )
            saldo_atual = await saldo_trabalho(self.alvo_id, self.guild_id)
            nome_carteira = "carteira de trabalho"
            tipo_log = "💼 AJUSTE DE TRABALHO"
            titulo_log = "💼 Ajuste da carteira de trabalho"
        else:
            novo = await movimentar_saldo(
                self.alvo_id, self.guild_id, self.valor, "ajuste", descricao_auditoria,
                ref=f"ajuste:pessoal:{interaction.id}",
            )
            saldo_atual = await saldo_carteira(self.alvo_id, self.guild_id)
            nome_carteira = "carteira pessoal"
            tipo_log = "💰 AJUSTE"
            titulo_log = "💰 Ajuste da carteira pessoal"
        if novo is None:
            return await interaction.edit_original_response(
                embed=criar_embed(
                    "❌ Saldo insuficiente",
                    f"O saldo mudou durante a confirmação. Atual: `{formatar_moeda(saldo_atual)}`.",
                    "Vermelho",
                ),
                view=None,
            )

        await registrar_log(
            interaction.guild, tipo_log, titulo_log,
            f"{interaction.user.mention} {'adicionou' if self.valor > 0 else 'removeu'} "
            f"**{formatar_moeda(abs(self.valor))}** {'para' if self.valor > 0 else 'de'} {alvo.mention}.\n"
            f"• Carteira: **{nome_carteira}**\n• Motivo: {self.motivo}\n"
            f"• Novo saldo: `{formatar_moeda(novo)}`",
            "Verde" if self.valor > 0 else "Amarelo",
        )
        await interaction.edit_original_response(
            embed=criar_embed(
                "✅ Ajuste Confirmado",
                f"• **Membro:** {alvo.mention} (`{'+' if self.valor > 0 else '−'}{formatar_moeda(abs(self.valor))}`)\n"
                f"• **Carteira:** {nome_carteira} → **`{formatar_moeda(novo)}`**\n"
                f"• **Motivo:** {self.motivo}",
                "Esmeralda",
            ),
            view=None,
        )


@bot.tree.command(name="addsaldo", description="🛠️ Ajustar carteira pessoal ou de trabalho (Dono e Gerente)")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
@app_commands.choices(carteira=[
    app_commands.Choice(name="Pessoal", value="pessoal"),
    app_commands.Choice(name="De trabalho", value="trabalho"),
])
@app_commands.describe(usuario="Quem vai receber ou perder o saldo",
                       valor="Valor positivo para adicionar ou negativo para remover (ex: -25,00)",
                       motivo="Motivo obrigatório para auditoria (mínimo 5 caracteres)",
                       carteira="Qual carteira ajustar (pessoal por padrão)")
async def cmd_addsaldo(interaction: discord.Interaction, usuario: discord.Member, valor: str,
                       motivo: Optional[str] = None,
                       carteira: Optional[app_commands.Choice[str]] = None):
    if not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas **Dono** ou **Gerente** podem ajustar saldo.", "Vermelho"),
            ephemeral=True)
    if usuario.id == interaction.user.id and not await tem_cargo_dono_ou_gerente_configurado(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed(
                "🔒 Autoajuste bloqueado",
                "Mediadores e administradores sem cargo configurado não podem ajustar a própria carteira pessoal ou de trabalho. Só os cargos configurados de Dono/Gerente podem fazer autoajuste.",
                "Vermelho"), ephemeral=True)
    if usuario.bot:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Jogador inválido", "Não é permitido ajustar a carteira de um bot.", "Vermelho"),
            ephemeral=True)

    tipo_carteira = carteira.value if carteira else "pessoal"
    if tipo_carteira == "trabalho" and not await tem_carteira_trabalho(usuario):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Carteira de trabalho", "A carteira de trabalho pertence apenas ao cargo Suporte (ADM recebe direto no PIX).", "Vermelho"),
            ephemeral=True)

    motivo_limpo = " ".join((motivo or "").split())
    if len(motivo_limpo) < 5:
        return await interaction.response.send_message(
            embed=criar_embed("📝 Motivo obrigatório", "Informe um motivo claro com pelo menos 5 caracteres para auditoria.", "Amarelo"),
            ephemeral=True)

    texto_valor = str(valor or "").strip()
    negativo = texto_valor.startswith("-")
    magnitude = parse_valor(texto_valor[1:] if negativo else texto_valor)
    if magnitude is None:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Valor inválido", "Use `50`, `50,00` ou `-25,00`.", "Vermelho"),
            ephemeral=True)
    quantidade = -magnitude if negativo else magnitude
    atual = (await saldo_trabalho(usuario.id, interaction.guild.id)
             if tipo_carteira == "trabalho"
             else await saldo_carteira(usuario.id, interaction.guild.id))
    projetado = arredondar(atual + quantidade)
    rotulo_carteira = "carteira de trabalho" if tipo_carteira == "trabalho" else "carteira pessoal"
    if projetado < 0:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Saldo insuficiente",
                              f"{usuario.mention} possui `{formatar_moeda(atual)}` na {rotulo_carteira}; o ajuste deixaria saldo negativo.",
                              "Vermelho"), ephemeral=True)

    embed = criar_embed(
        "🔎 Revise o ajuste de carteira",
        f"**Jogador:** {usuario.mention}\n"
        f"**Carteira:** {rotulo_carteira}\n"
        f"**Ação:** {'Adicionar' if quantidade > 0 else 'Remover'} `{formatar_moeda(abs(quantidade))}`\n"
        f"**Saldo atual:** `{formatar_moeda(atual)}` → **estimado:** `{formatar_moeda(projetado)}`\n"
        f"**Motivo:** {motivo_limpo[:300]}\n\n"
        "A alteração só acontece depois de confirmar. Ela será registrada no extrato e nos logs.",
        "Amarelo")
    await interaction.response.send_message(
        embed=embed,
        view=ConfirmarAjusteSaldoView(interaction.user.id, usuario.id, interaction.guild.id,
                                      quantidade, motivo_limpo, tipo_carteira),
        ephemeral=True)


@bot.tree.command(name="transferir", description="📤 Transferir saldo pra outro jogador")
@app_commands.guild_only()
@app_commands.describe(usuario="Quem vai receber", valor="Quanto transferir (ex: 10,00)")
async def cmd_transferir(interaction: discord.Interaction, usuario: discord.Member, valor: str):
    await interaction.response.defer(ephemeral=True, thinking=True)

    if usuario.id == interaction.user.id:
        return await interaction.followup.send(
            embed=criar_embed("❌ Ops", "Você não pode transferir pra você mesmo.", "Vermelho"), ephemeral=True)
    if usuario.bot:
        return await interaction.followup.send(
            embed=criar_embed("❌ Ops", "Não dá pra transferir pra um bot.", "Vermelho"), ephemeral=True)

    quantidade = parse_valor(valor)
    if quantidade is None:
        return await interaction.followup.send(
            embed=criar_embed("❌ Valor inválido", "Use algo como `10`, `10,00`.", "Vermelho"), ephemeral=True)

    resultado = await transferir_saldo_atomic(
        interaction.user.id, usuario.id, interaction.guild.id, quantidade,
        ref=f"transfer:{interaction.id}")
    if resultado is None:
        saldo = await saldo_carteira(interaction.user.id, interaction.guild.id)
        return await interaction.followup.send(
            embed=criar_embed("❌ Saldo insuficiente",
                              f"Você tem **{formatar_moeda(saldo)}** e tentou enviar **{formatar_moeda(quantidade)}**.",
                              "Vermelho"), ephemeral=True)

    novo_origem, novo_destino = resultado
    await interaction.followup.send(
        embed=criar_embed(
            "📤 Transferência feita",
            f"Você enviou **{formatar_moeda(quantidade)}** para {usuario.mention}.\n"
            f"> 💼 Seu saldo agora: `{formatar_moeda(novo_origem)}`",
            "Esmeralda"
        ), ephemeral=True
    )
    await registrar_log(
        interaction.guild, "💸 TRANSFERÊNCIA", "📤 Transferência entre jogadores",
        f"{interaction.user.mention} → {usuario.mention}\n> 💰 Valor: `{formatar_moeda(quantidade)}`\n"
        f"> Saldos atualizados: `{formatar_moeda(novo_origem)}` / `{formatar_moeda(novo_destino)}`",
        "Azul"
    )


async def abrir_saque(interaction: discord.Interaction, tipo_carteira: str = "pessoal"):
    """Inicia o fluxo PIX privado a partir da carteira selecionada."""
    if not interaction.guild:
        return await responder_ephemeral(
            interaction,
            embed=criar_embed("❌ Só no servidor", "Use a carteira dentro do servidor.", "Vermelho")
        )

    tipo_interno = "jogador"
    if tipo_carteira == "trabalho":
        if not await tem_carteira_trabalho(interaction.user):
            return await responder_ephemeral(
                interaction,
                embed=criar_embed("🔒 Carteira exclusiva do Suporte", "A carteira de trabalho está disponível apenas para o cargo Suporte (ADM recebe direto no PIX).", "Vermelho")
            )
        saldo_trab = await saldo_trabalho(interaction.user.id, interaction.guild.id)
        if saldo_trab <= 0:
            return await responder_ephemeral(
                interaction,
                embed=criar_embed("💼 Carteira de trabalho vazia", "Não há saldo de trabalho disponível para saque.", "Amarelo")
            )
        agora_saque = agora_brt()
        janela_aberta = ((agora_saque.weekday() == 6 and agora_saque.hour >= 23)
                         or (agora_saque.weekday() == 0 and agora_saque.hour < 1))
        if not janela_aberta:
            return await responder_ephemeral(
                interaction,
                embed=criar_embed(
                    "💼 Saque da carteira de trabalho",
                    "O saque fica disponível após o fechamento de domingo, das **23:00 de domingo até 01:00 de segunda (BRT)**.\n\n"
                    f"> 💰 Saldo a receber: `{formatar_moeda(saldo_trab)}`",
                    "Amarelo"
                )
            )
        data_nota = ((agora_saque - datetime.timedelta(days=1)).strftime("%Y-%m-%d")
                     if agora_saque.weekday() == 0 else agora_saque.strftime("%Y-%m-%d"))
        await fechar_notas_semanais(interaction.guild, data_nota)
        tipo_interno = "trabalho"

    saldo = (await saldo_trabalho(interaction.user.id, interaction.guild.id)
             if tipo_interno == "trabalho"
             else await saldo_carteira(interaction.user.id, interaction.guild.id))
    minimo = float(await cfgv(interaction.guild.id, "saque_min", CARTEIRA_SAQUE_MIN))
    if saldo < minimo:
        explicacao = (
            "A carteira de trabalho precisa atingir o mínimo de saque; os próximos ganhos aparecerão aqui."
            if tipo_interno == "trabalho"
            else "Deposite pelo botão **Depositar PIX**, jogue os diários ou receba uma transferência."
        )
        return await responder_ephemeral(
            interaction,
            embed=criar_embed(
                "💸 Saldo abaixo do mínimo",
                f"Saldo: **{formatar_moeda(saldo)}** • mínimo de saque: **{formatar_moeda(minimo)}**.\n\n"
                f"> {explicacao}",
                "Amarelo"
            )
        )

    embed = criar_embed(
        "💸 Solicitar saque PIX",
        f"**Disponível:** `{formatar_moeda(saldo)}`"
        + (" *(carteira de trabalho)*" if tipo_interno == "trabalho" else " *(carteira pessoal)*")
        + "\n\n> 🏦 Escolha o **tipo da sua chave PIX** abaixo.\n"
        "> ⭐ Se já sacou antes, use sua chave salva para preencher mais rápido.",
        "Esmeralda"
    )
    await responder_ephemeral(interaction, embed=embed, view=SaqueTipoView(saldo, tipo_interno))


@bot.tree.command(name="extrato", description="📜 Ver o extrato completo da carteira")
@app_commands.guild_only()
@app_commands.describe(usuario="Ver o extrato de outra pessoa (equipe)", quantidade="Quantas linhas (padrão 15)")
async def cmd_extrato(interaction: discord.Interaction, usuario: Optional[discord.Member] = None,
                      quantidade: Optional[int] = 15):
    alvo = usuario or interaction.user
    if usuario and usuario.id != interaction.user.id and not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Só Dono/Gerente/Administrador pode consultar o extrato de outra pessoa.", "Vermelho"), ephemeral=True)

    quantidade = max(1, min(int(quantidade or 15), 40))
    extrato = await extrato_texto(alvo.id, interaction.guild.id, quantidade)
    saldo = await saldo_carteira(alvo.id, interaction.guild.id)
    embed = criar_embed(f"📜 Extrato — {alvo.display_name}",
                        f"**Saldo atual:** `{formatar_moeda(saldo)}`\n\n{extrato}", "Azul")
    await interaction.response.send_message(embed=embed, ephemeral=True)


@bot.tree.command(name="logs", description="🧾 Configurar e ver os logs do bot (Dono e Gerente)")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
@app_commands.describe(acao="O que fazer", canal="Canal de logs (pra configurar)")
@app_commands.choices(acao=[
    app_commands.Choice(name="Configurar canal", value="canal"),
    app_commands.Choice(name="Canal de DEPÓSITOS (público)", value="canal_deposito"),
    app_commands.Choice(name="Canal de SAQUES (público)", value="canal_saque"),
    app_commands.Choice(name="Canal de VENDAS do diário (público)", value="canal_pagamento"),
    app_commands.Choice(name="Canal de VAGAS da equipe (público)", value="canal_vaga"),
    app_commands.Choice(name="Canal de PAGAMENTOS — Suporte (privado)", value="canal_pag_suporte"),
    app_commands.Choice(name="Canal de PAGAMENTOS — ADM (privado)", value="canal_pag_adm"),
    app_commands.Choice(name="Ver canais configurados", value="ver_canais"),
    app_commands.Choice(name="Ver últimos eventos", value="ver"),
    app_commands.Choice(name="Testar", value="testar"),
    app_commands.Choice(name="Desligar logs", value="desligar"),
])
async def cmd_logs(interaction: discord.Interaction, acao: app_commands.Choice[str],
                   canal: Optional[discord.TextChannel] = None):
    if not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas Dono, Gerente ou Administrador pode configurar/consultar logs.", "Vermelho"), ephemeral=True)

    if acao.value == "canal":
        if not canal:
            return await interaction.response.send_message(
                embed=criar_embed("❌ Falta o canal", "Use `/logs acao:Configurar canal canal:#logs`.", "Vermelho"),
                ephemeral=True)
        await salvar_config(interaction.guild.id, canal_logs=canal.id)
        _CACHE_LOGS.pop(interaction.guild.id, None)
        await interaction.response.send_message(
            embed=criar_embed("✅ Logs ativados", f"Todos os eventos vão aparecer em {canal.mention}.", "Esmeralda"),
            ephemeral=True)
        await registrar_log(interaction.guild, "⚙️ CONFIG", "🧾 Canal de logs configurado",
                            f"Os registros passam a sair em {canal.mention}.\n"
                            f"> Eventos: aprovações, recebimentos PIX de ADM, pagamentos do suporte, depósitos, saques, transferências e ajustes.",
                            "Azul")
        return

    canais_cfg = {
        "canal_deposito": ("canal_log_deposito", "DEPÓSITOS (público)"),
        "canal_saque": ("canal_log_saque", "SAQUES (público)"),
        "canal_pagamento": ("canal_log_pagamento", "VENDAS do diário (público)"),
        "canal_vaga": ("canal_log_vaga", "VAGAS da equipe (público)"),
        "canal_pag_suporte": ("canal_log_pag_suporte", "PAGAMENTOS da equipe — SUPORTE (privado)"),
        "canal_pag_adm": ("canal_log_pag_adm", "PAGAMENTOS da equipe — ADM (privado)"),
    }
    if acao.value in canais_cfg:
        if not canal:
            return await interaction.response.send_message(
                embed=criar_embed("❌ Falta o canal",
                                  f"Use `/logs acao:{acao.name} canal:#seu-canal`.", "Vermelho"), ephemeral=True)
        chave, rotulo = canais_cfg[acao.value]
        privado = "privado" in rotulo.lower()
        dica_canal = ("> 🔒 **Canal privado** — quem não tem acesso a ele não vê o pagamento da equipe.\n"
                      if privado else
                      "> 🔒 A chave PIX sai **mascarada** aqui (ex.: `jo***@pix.com`). A chave completa fica "
                      "somente no canal financeiro privado — ADM.\n")
        await salvar_config(interaction.guild.id, **{chave: canal.id})
        await interaction.response.send_message(
            embed=criar_embed("✅ Canal configurado",
                              f"Os anúncios de **{rotulo}** vão sair em {canal.mention}.\n\n"
                              + dica_canal +
                              "> 💛 Use `/logs acao:Testar` pra ver como fica.", "Esmeralda"), ephemeral=True)
        await registrar_log(interaction.guild, "⚙️ CONFIG", "📢 Canal público configurado",
                            f"{acao.name} → {canal.mention}", "Azul")
        return

    if acao.value == "ver_canais":
        cfg = await obter_config(interaction.guild.id)
        def _mostrar(canal_id):
            return f"<#{int(canal_id)}>" if canal_id else "*(não configurado)*"
        return await interaction.response.send_message(
            embed=criar_embed(
                "🧾 Canais de log",
                f"> 🧾 **Geral (equipe):** {_mostrar(cfg.get('canal_logs'))}\n"
                f"> 🎧 **Atendimento:** {_mostrar(cfg.get('canal_logs_suporte'))}\n\n"
                f"**Públicos** (marcam o jogador, chave mascarada)\n"
                f"> 🛒 **Vendas do diário:** {_mostrar(cfg.get('canal_log_pagamento'))}\n"
                f"> 📢 **Vagas da equipe:** {_mostrar(cfg.get('canal_log_vaga'))}\n"
                f"> 💰 **Depósitos:** {_mostrar(cfg.get('canal_log_deposito'))}\n"
                f"> 💸 **Saques:** {_mostrar(cfg.get('canal_log_saque'))}\n\n"
                f"**Privados** (só a equipe vê)\n"
                f"> 💼 **Pagamentos — Suporte:** {_mostrar(cfg.get('canal_log_pag_suporte'))}\n"
                f"> 🛡️ **Pagamentos — ADM:** {_mostrar(cfg.get('canal_log_pag_adm'))}\n"
                f"> 🎟️ **Cupons:** {_mostrar(cfg.get('canal_cupons'))}\n"
                f"> 🎉 **Eventos:** {_mostrar(cfg.get('canal_eventos'))}\n\n"
                f"> 💡 Vaga é **anúncio de vaga na equipe** (ADM/gerente). Pagamento da equipe é **privado**.\n"
                f"> Sem canal configurado, o aviso continua saindo no **geral**.",
                "Azul"), ephemeral=True)

    if acao.value == "desligar":
        await salvar_config(interaction.guild.id, canal_logs=None)
        _CACHE_LOGS.pop(interaction.guild.id, None)
        return await interaction.response.send_message(
            embed=criar_embed("🔕 Logs desligados", "Os eventos continuam sendo gravados em `fireforce.log`.", "Amarelo"),
            ephemeral=True)

    if acao.value == "testar":
        await registrar_log(interaction.guild, "🧪 TESTE", "🧪 Teste de log",
                            f"Se você está vendo isso, os logs estão funcionando! ({interaction.user.mention})", "Azul")
        return await interaction.response.send_message(
            embed=criar_embed("🧪 Enviado", "Mandei um evento de teste no canal de logs.", "Azul"), ephemeral=True)

    # Os arquivos locais podem misturar eventos de várias guilds. A consulta
    # pelo slash command lê somente o canal de logs deste servidor.
    canal_id = await canal_de_logs(interaction.guild.id)
    canal_logs = interaction.guild.get_channel(int(canal_id)) if canal_id else None
    if not isinstance(canal_logs, discord.TextChannel):
        return await interaction.response.send_message(
            embed=criar_embed("🧾 Logs não configurados",
                              "Configure um canal geral em `/logs acao:Configurar canal` para consultar o histórico deste servidor.\n"
                              "Por privacidade, o arquivo local que pode misturar organizações não é exibido no Discord.",
                              "Amarelo"), ephemeral=True)
    perms_logs = canal_logs.permissions_for(interaction.guild.me)
    if not perms_logs.view_channel or not perms_logs.read_message_history:
        return await interaction.response.send_message(
            embed=criar_embed("🔒 Sem acesso ao histórico",
                              f"Preciso de **Ver canal** e **Ler histórico** em {canal_logs.mention}.", "Vermelho"),
            ephemeral=True)

    linhas = []
    try:
        async for msg in canal_logs.history(limit=12, oldest_first=False):
            quando = msg.created_at.astimezone(TZ_BRASILIA).strftime("%d/%m %H:%M")
            if msg.embeds:
                embed_msg = msg.embeds[0]
                titulo = (embed_msg.title or "Evento")[:90]
                detalhe = re.sub(r"\s+", " ", embed_msg.description or "").strip()
            else:
                titulo = "Evento"
                detalhe = re.sub(r"\s+", " ", msg.content or "").strip()
            if len(detalhe) > 120:
                detalhe = detalhe[:117] + "..."
            linhas.append(f"`{quando}` **{titulo}**" + (f" — {detalhe}" if detalhe else ""))
    except (discord.Forbidden, discord.HTTPException) as erro:
        _log_arquivo(f"[LOGS] leitura guild={interaction.guild.id}: {erro}")
        return await interaction.response.send_message(
            embed=criar_embed("⚠️ Não consegui ler os logs", "Confira as permissões do canal e tente novamente.", "Amarelo"),
            ephemeral=True)
    texto = "\n".join(linhas) or "Nenhum evento publicado neste canal ainda."
    await interaction.response.send_message(
        embed=criar_embed("🧾 Últimos eventos deste servidor", texto, "Cinza Escuro"), ephemeral=True)


@bot.tree.command(name="saude", description="🩺 Como está o bot agora: no ar, Supabase e pendências")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
async def cmd_saude(interaction: discord.Interaction):
    if not interaction.guild:
        return await interaction.response.send_message(
            embed=criar_embed("❌ Só no servidor", "Use este comando dentro do servidor.", "Vermelho"),
            ephemeral=True)
    if not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas Dono, Gerente ou Administrador pode ver o diagnóstico operacional.", "Vermelho"), ephemeral=True)

    await interaction.response.defer(ephemeral=True, thinking=True)
    gid = interaction.guild.id
    fora = await tempo_fora()
    pend = await _pendencias(gid)
    disp = await disponibilidade_saque(gid)

    def _ha(quando: float) -> str:
        return f"há {int(time.time() - quando)}s" if quando else "ainda não"

    loops_vivos = sum(1 for t in _TAREFAS_BACKGROUND.values() if t and not t.done())
    loops_totais = max(len(_TAREFAS_BACKGROUND), 10)
    embed = criar_embed("🩺 Status Operacional", "", "Esmeralda" if not fora else "Amarelo")
    embed.add_field(
        name="🟢 No ar",
        value=f"> Ligado {await _ha_iso(INICIADO_EM.isoformat())} "
              f"({_tempo_texto(int((agora_brt() - INICIADO_EM).total_seconds() // 60))} rodando)\n"
              f"> Último pulso: {await _ha_iso(await _meta_ler('ultimo_pulso'))} • Loops ativos: `{loops_vivos}/{loops_totais}`",
        inline=False)
    embed.add_field(
        name="☁️ Supabase",
        value=(f"> {'✅ configurado' if supabase_configurado() else '❌ não configurado'}"
               f"{' • 🛡️ proteção anti-wipe aguardando nuvem' if _SUPABASE_BLOQUEIO_BANCO_VAZIO else ''}\n"
               f"> Backup completo: {_ha(_sync_ultimo)}\n"
               f"> Tempo real (config/rankings): {_ha(_sql_ultimo)}\n"
               f"> Keep-alive (a cada 2 dias): {await _ha_iso(await _meta_ler('ultimo_ping_supabase'))}"
               + (f"\n> ⚠️ Último erro: `{str(_sync_erro or _sql_erro)[:110]}`"
                  if (_sync_erro or _sql_erro) else "")),
        inline=False)
    embed.add_field(
        name="🔄 Auto-Update (GitHub)",
        value=(
            f"> {'✅ ativo' if AUTO_UPDATE_ATIVO else '⏸️ desativado'} "
            f"(verifica `main` a cada `{AUTO_UPDATE_SEGUNDOS}s`)\n"
            f"> Versão em execução: `v{VERSAO_BOT}` • Commit: `{_obter_commit_curto_local()}`\n"
            f"> Última checagem: {_ha(_AUTO_UPDATE_ULTIMA_CHECAGEM)}"
            + (f"\n> ⚠️ Aviso: `{_AUTO_UPDATE_ULTIMO_ERRO[:100]}`" if _AUTO_UPDATE_ULTIMO_ERRO else "")
        ),
        inline=False,
    )
    embed.add_field(
        name="📋 Pendências abertas",
        value=(f"> 💰 Depósitos abertos: `{pend['depositos']}` ({formatar_moeda(pend['depositos_valor'])})\n"
               f"> 🎮 Reservas aguardando pagamento: `{pend['reservas']}`\n"
               f"> 💸 Saques aguardando envio: `{pend['saques']}` ({formatar_moeda(pend['saques_valor'])})\n"
               f"> 🎧 Tickets abertos: `{pend['tickets']}`"),
        inline=False)
    embed.add_field(
        name="💼 Caixa interno",
        value=f"> Saldo contábil: `{formatar_moeda(disp['saldo'])}` • Reserva: `{formatar_moeda(disp['reserva'])}`",
        inline=False)
    embed.set_footer(text=f"🔥 Fire Force v{VERSAO_BOT} • PIX direto aos Donos e ADMs")
    await interaction.followup.send(embed=embed, ephemeral=True)


