    if not novos and not erros:
        cfg = await obter_config(interaction.guild.id)

        def _canal(valor):
            return f"<#{valor}>" if valor else "`não definido`"

        dias = ["segunda", "terça", "quarta", "quinta", "sexta", "sábado", "domingo"]
