async def _meta_ler(chave: str) -> str:
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            linha = await (await db.execute("SELECT valor FROM sync_meta WHERE chave = ?",
                                            (str(chave),))).fetchone()
        return (linha["valor"] if linha else "") or ""
    except Exception:
        return ""


async def _meta_gravar(chave: str, valor: str):
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("INSERT OR REPLACE INTO sync_meta (chave, valor) VALUES (?, ?)",
                             (str(chave), str(valor)))
            await db.commit()
    except Exception:
        pass


async def canal_financeiro_privado(guild):
    """Canal autorizado para chaves PIX integrais; exige @everyone sem acesso."""
    if not guild:
        return None, "Servidor inválido."
    cfg = await obter_config(guild.id)
    canal_id = cfg.get("canal_log_pag_adm")
    try:
        canal = guild.get_channel(int(canal_id)) if canal_id else None
    except (TypeError, ValueError):
        canal = None
    if not isinstance(canal, discord.TextChannel):
        return None, "Configure `/logs` → **Canal de PAGAMENTOS — ADM (privado)**."
    try:
        everyone_pode_ver = canal.permissions_for(guild.default_role).view_channel
        bot_member = guild.me
        permissoes_bot = canal.permissions_for(bot_member) if bot_member else None
        bot_pode_operar = bool(permissoes_bot and permissoes_bot.view_channel
                               and permissoes_bot.send_messages and permissoes_bot.embed_links
                               and permissoes_bot.read_message_history)
    except Exception:
        everyone_pode_ver, bot_pode_operar = True, False
    if everyone_pode_ver:
        return None, (f"O canal {canal.mention} ainda permite que @everyone veja as chaves. "
                      "Negue **Ver canal** para @everyone e mantenha acesso só para Dono/Gerente.")
    if not bot_pode_operar:
        return None, f"O bot precisa de Ver canal, Enviar mensagens, Embeds e Ler histórico em {canal.mention}."
    return canal, ""


async def redigir_avisos_pix_antigos(guild, limite: int = 150) -> int:
    """Redige mensagens antigas com PIX integral em canais que não são privados."""
    if not guild or not bot.user:
        return 0
    cfg = await obter_config(guild.id)
    ids = {int(v) for v in (cfg.get("canal_logs"), cfg.get("canal_log_pag_adm")) if v}
    privado, _ = await canal_financeiro_privado(guild)
    total = 0
    for canal_id in ids:
        canal = guild.get_channel(canal_id)
        if not isinstance(canal, discord.TextChannel) or (privado and canal.id == privado.id):
            continue
        perms = canal.permissions_for(guild.me) if guild.me else None
        if not perms or not (perms.view_channel and perms.read_message_history):
            continue
        try:
            async for mensagem in canal.history(limit=max(1, min(int(limite), 300)), oldest_first=False):
                if mensagem.author.id != bot.user.id or not mensagem.embeds:
                    continue
                titulo = mensagem.embeds[0].title or ""
                if not (titulo.startswith("💸 PIX PARA ENVIAR")
                        or titulo.startswith("💸 FILA DE PAGAMENTO")):
                    continue
                await mensagem.edit(
                    embed=criar_embed("🔒 Aviso financeiro movido",
                                      "Detalhes PIX antigos foram removidos deste canal por segurança.",
                                      "Cinza"),
                    view=None)
                total += 1
        except Exception as erro:
            _log_arquivo(f"[PRIVACIDADE] migração guild={guild.id} canal={canal.id}: {erro}")
    return total


# ==================== LOOPS (Pulso + Relatório) ====================


# ══════════════════════════════════════════════════════════════════════════════
#  🩺 PULSO E RECUPERAÇÃO PÓS-QUEDA
#  O bot grava "estou vivo" a cada minuto. Quando volta (host que resetou a cada
#  6h, internet que caiu, luz que faltou), ele RECONFERE a LivePix com a janela
#  esticada pelo tempo que ficou fora — ANTES de expirar qualquer coisa — e conta
#  pra equipe o que recuperou. Nada do jogador se perde: o pagamento fica no
#  histórico da LivePix e é aplicado na volta.
# ══════════════════════════════════════════════════════════════════════════════

PULSO_SEGUNDOS = 60         # grava o pulso no máximo 1x por minuto
RECUPERAR_MIN = 3           # ficou fora mais que isso? reconferência de verdade
RECUPERAR_MAX_MIN = 1440    # teto da janela estendida (24h)
INICIADO_EM = agora_brt()   # pra mostrar "estou no ar há X"

_ultimo_pulso_gravado = 0.0
_recuperou_em = 0.0         # quando rolou a última reconferência (evita varredura dupla)


async def _pulso_periodico(forcar: bool = False):
    """Grava 'ainda estou vivo' (vai pro Supabase junto com o resto do estado)."""
    global _ultimo_pulso_gravado
    if not forcar and (time.time() - _ultimo_pulso_gravado) < PULSO_SEGUNDOS:
        return
    _ultimo_pulso_gravado = time.time()
    await _meta_gravar("ultimo_pulso", agora_brt().isoformat())


async def tempo_fora() -> int:
    """Quantos minutos o bot ficou fora do ar (0 = sem referência pra comparar)."""
    texto = await _meta_ler("ultimo_pulso")
    try:
        antes = datetime.datetime.fromisoformat(texto)
    except Exception:
        return 0
    if not antes.tzinfo:
        antes = antes.replace(tzinfo=TZ_BRASILIA)
    return max(0, int((agora_brt() - antes).total_seconds() // 60))


def _tempo_texto(minutos) -> str:
    """'12 min', '5h', '6h30' — jeito curto de falar tempo."""
    minutos = int(minutos or 0)
    if minutos < 60:
        return f"{minutos} min"
    horas, resto = divmod(minutos, 60)
    return f"{horas}h{resto:02d}" if resto else f"{horas}h"


async def _ha_iso(texto) -> str:
    """'hora do último X' em linguagem de gente."""
    try:
        quando = datetime.datetime.fromisoformat(str(texto))
        if not quando.tzinfo:
            quando = quando.replace(tzinfo=TZ_BRASILIA)
        segundos = max(0, int((agora_brt() - quando).total_seconds()))
    except Exception:
        return "sem registro ainda"
    if segundos < 90:
        return f"há {segundos}s"
    if segundos < 5400:
        return f"há {segundos // 60} min"
    return f"há {_tempo_texto(segundos // 60)}"


def pagamento_depois_do_pedido(evento: dict, criado, folga_min: int = 0) -> bool:
    """🩺 Só na reconferência: o PIX tem que ter caído DEPOIS do pedido (5 min de
    folga), pra um pagamento velho não casar com um pedido novo.

    Se a LivePix não mandar a data do evento, não bloqueia."""
    if not folga_min or criado is None or not evento.get("quando"):
        return True
    try:
        return evento["quando"] >= criado - datetime.timedelta(minutes=5)
    except Exception:
        return True


async def _pendencias(guild_id: int) -> dict:
    """Retrato do que está esperando alguém (usado na recuperação e no /saude)."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        dep = await (await db.execute(
            "SELECT COUNT(*) n, COALESCE(SUM(valor), 0) v FROM depositos "
            "WHERE guild_id = ? AND status = 'na_janela'", (guild_id,))).fetchone()
        res = (await (await db.execute(
            "SELECT COUNT(*) FROM slots WHERE guild_id = ? AND confirmado = 0", (guild_id,))).fetchone())[0]
        saq = await (await db.execute(
            "SELECT COUNT(*) n, COALESCE(SUM(valor), 0) v FROM saques "
            "WHERE guild_id = ? AND status IN ('na_fila', 'liberado')", (guild_id,))).fetchone()
        tik = (await (await db.execute(
            "SELECT COUNT(*) FROM tickets WHERE guild_id = ? AND status = 'aberto'", (guild_id,))).fetchone())[0]
    return {"depositos": int(dep["n"] or 0), "depositos_valor": arredondar(dep["v"] or 0),
            "reservas": int(res or 0), "saques": int(saq["n"] or 0),
            "saques_valor": arredondar(saq["v"] or 0), "tickets": int(tik or 0)}


async def _relatorio_atrasado(guild):
    """Se o bot ficou fora na hora do relatório (23:55), manda o de ontem agora."""
    ontem = (agora_brt() - datetime.timedelta(days=1)).strftime("%Y-%m-%d")
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            ja = await (await db.execute(
                "SELECT 1 FROM relatorios_dia WHERE guild_id = ? AND dia = ?", (guild.id, ontem))).fetchone()
        if ja:
            return
        resumo = await resumo_caixa(guild.id, ontem)
        if not (resumo["dia_movimentos"] or resumo["dia_receitas"] or resumo["dia_despesas"]):
            return
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("INSERT INTO relatorios_dia (guild_id, dia, enviado_em) VALUES (?, ?, ?)",
                             (guild.id, ontem, agora_brt().isoformat()))
            await db.commit()
        await enviar_relatorio_diario(guild, ontem)
        _log_arquivo(f"[RELATÓRIO] atrasado de {ontem} enviado depois da queda")
    except Exception as erro:
        _log_arquivo(f"[RELATÓRIO] atrasado: {erro}")


async def recuperar_apos_queda(fora_min: int) -> dict:
    """Reconfere pendências e relatórios atrasados ao retornar de reinício/queda."""
    global _recuperou_em
    _recuperou_em = time.time()
    for leve in await guilds_para_sync():
        guild = leve if hasattr(leve, "get_channel") else bot.get_guild(int(getattr(leve, "id", 0)))
        if guild is None:
            continue
        try:
            await processar_fila_saques(guild.id)
            pend = await _pendencias(guild.id)
            corpo = (
                f"O bot ficou **{_tempo_texto(fora_min)}** fora do ar e voltou automaticamente.\n\n"
                f"> 💸 Saques aguardando envio: `{pend['saques']}` ({formatar_moeda(pend['saques_valor'])})\n"
                f"> 💰 Depósitos abertos: `{pend['depositos']}` ({formatar_moeda(pend['depositos_valor'])})\n"
                f"> 🎮 Reservas abertas: `{pend['reservas']}` • 🎧 Tickets: `{pend['tickets']}`"
            )
            await registrar_log(guild, "🔄 RECUPERAÇÃO", "🔄 Bot online novamente", corpo, "Azul")
            await _relatorio_atrasado(guild)
        except Exception as erro:
            _log_arquivo(f"[RECUPERAÇÃO] {type(erro).__name__}: {erro}")

    await _pulso_periodico(forcar=True)
    return {"ok": True}


async def loop_pulso():
    """Mantém o pulso de prova de vida, supervisor de loops e encerramento limpo no fim do ciclo de 6h."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            flag_fim = os.path.join(_DIRETORIO_BOT, "_encerrar_ciclo.flag")
            if os.path.exists(flag_fim):
                _log_arquivo("[CICLO] _encerrar_ciclo.flag detectado — salvando estado e encerrando de forma limpa.")
                print("  🛑 [CICLO] Sinal de encerramento de ciclo recebido — salvando backup no Supabase...")
                await bot.close()
                return

            # Supervisor: revive automaticamente qualquer tarefa de background que tenha parado
            _iniciar_tarefas_background()

            for guild in list(bot.guilds):
                try:
                    await processar_fila_saques(guild.id)
                    await checar_reserva(guild)
                except Exception as erro_g:
                    _log_arquivo(f"[PULSO] guild={guild.id}: {erro_g}")
            await _pulso_periodico()
        except Exception as erro:
            _log_arquivo(f"[PULSO] erro no loop: {erro}")

        # Checa o sinal de fim de ciclo a cada 5s (totalizando PULSO_INTERVALO)
        passos = max(1, int(PULSO_INTERVALO // 5))
        for _ in range(passos):
            if bot.is_closed():
                return
            if os.path.exists(os.path.join(_DIRETORIO_BOT, "_encerrar_ciclo.flag")):
                break
            await asyncio.sleep(5)


async def loop_relatorio():
    """Todo dia 23:59 (BRT) manda o relatório financeiro do dia no canal de logs."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            agora = agora_brt()
            if agora.hour == 23 and agora.minute >= 55:
                hoje = agora.strftime("%Y-%m-%d")
                for guild in list(bot.guilds):
                    try:
                        async with aiosqlite.connect(DATABASE_FILE) as db:
                            ja = await (await db.execute(
                                "SELECT 1 FROM relatorios_dia WHERE guild_id = ? AND dia = ?", (guild.id, hoje)
                            )).fetchone()
                            if ja:
                                continue
                            await db.execute("INSERT INTO relatorios_dia (guild_id, dia, enviado_em) VALUES (?, ?, ?)",
                                             (guild.id, hoje, agora.isoformat()))
                            await db.commit()
                        await enviar_relatorio_diario(guild, hoje)
                    except Exception as erro_rg:
                        _log_arquivo(f"[RELATÓRIO] guild={guild.id}: {erro_rg}")
        except Exception as erro:
            _log_arquivo(f"[RELATÓRIO] erro: {erro}")
        await asyncio.sleep(300)


async def enviar_relatorio_diario(guild, dia: str):
    resumo = await resumo_caixa(guild.id, dia)
    comissoes = await resumo_comissoes_dia(guild.id, dia)

    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        depositos = await (await db.execute(
            "SELECT COUNT(*) AS qtd, COALESCE(SUM(valor), 0) AS total FROM depositos "
            "WHERE guild_id = ? AND status = 'creditado' AND criado_em LIKE ?", (guild.id, f"{dia}%")
        )).fetchone()
        saques = await (await db.execute(
            "SELECT COUNT(*) AS qtd, COALESCE(SUM(valor), 0) AS total FROM saques "
            "WHERE guild_id = ? AND status = 'pago' AND criado_em LIKE ?", (guild.id, f"{dia}%")
        )).fetchone()

    disp = await disponibilidade_saque(guild.id)
    linhas_adm = "\n".join(
        f"> {mencao(l['staff_id'])} — `{formatar_moeda(l['total'])}` ({l['qtd']} vaga(s) liberada(s))"
        for l in comissoes["por_adm"]
    ) or "> *Nenhum recebimento de ADM registrado hoje.*"

    embed = criar_embed(
        f"📊 Relatório do dia — {dia[8:10]}/{dia[5:7]}",
        f"**🏦 Recebido no PIX direto dos ADMs:** `{formatar_moeda(comissoes['total'])}` ({comissoes['vendas']} vaga(s))\n"
        f"**⬆️ Depósitos na carteira:** `{formatar_moeda(depositos['total'])}` ({depositos['qtd']}x)\n"
        f"**⬇️ Saques pagos:** `{formatar_moeda(saques['total'])}` ({saques['qtd']}x)",
        "Dourado"
    )
    embed.add_field(name="🏅 Log de recebimentos PIX por ADM", value=linhas_adm, inline=False)
    embed.add_field(
        name="🏦 Caixa",
        value=f"> Saldo da org: `{formatar_moeda(disp['saldo'])}` (fonte: {disp['fonte']})\n"
              f"> Reserva protegida: `{formatar_moeda(disp['reserva'])}`\n"
              f"> Fila de saques: `{formatar_moeda(disp['fila'])}` ({disp['fila_qtd']}x)",
        inline=False
    )
    embed.add_field(
        name="📈 Histórico interno",
        value=f"> Receitas totais: `{formatar_moeda(resumo['receitas'])}`\n"
              f"> Despesas totais: `{formatar_moeda(resumo['despesas'])}`\n"
              f"> Saldo: `{formatar_moeda(resumo['saldo'])}`",
        inline=False
    )

    canal_id = await canal_de_logs(guild.id)
    canal = guild.get_channel(int(canal_id)) if canal_id else None
    if canal:
        try:
            await canal.send(embed=embed)
        except Exception:
            pass
    _log_arquivo(f"[RELATÓRIO] {dia} enviado para o servidor {guild.id}")


# ---------- aviso de caixa baixo (1x por hora, sem spam) ----------

async def checar_reserva(guild):
    agora = time.time()
    ultimo = _ULTIMO_AVISO_RESERVA.get(guild.id, 0)
    if agora - ultimo < 3600:
        return
    disp = await disponibilidade_saque(guild.id)
    if disp["saldo"] < disp["reserva"]:
        _ULTIMO_AVISO_RESERVA[guild.id] = agora
        await registrar_log(
            guild, "⚠️ CAIXA", "⚠️ Saldo abaixo da reserva de segurança",
            f"O saldo da org (`{formatar_moeda(disp['saldo'])}`, fonte: {disp['fonte']}) está abaixo da reserva "
            f"de `{formatar_moeda(disp['reserva'])}`.\n"
            f"> 💡 Novos saques entram na fila e são pagos automaticamente quando o caixa recuperar.",
            "Vermelho"
        )



# ══════════════════════════════════════════════════════════════
#  ☁️ SINCRONIZAÇÃO SUPABASE (sobrevive a reset/restart de hospedagem)
#
#  Como funciona: o bot trabalha no banco local (rápido e leve, ~0 MB de
#  RAM extra) e envia uma FOTOGRAFIA compacta do estado para o Supabase
#  (gzip + base64 → ~dezenas de KB). Quando o host reinicia, o bot baixa a
#  fotografia e restaura tudo: config, painéis, diários, carteiras, cupons,
#  tickets, ganhos, rankings e eventos.
#
#  Use segredos do host/.env (nunca publique a chave service role):
#     SUPABASE_URL=https://xxxxxxxx.supabase.co
#     SUPABASE_SERVICE_ROLE_KEY=...  (preferida; mantenha o segredo privado)
#  SUPABASE_ANON_KEY continua aceita por compatibilidade, mas exige RLS
#  configurado corretamente. O ID do snapshot NÃO é controle de acesso.
# ══════════════════════════════════════════════════════════════
SUPABASE_URL = (os.getenv("SUPABASE_URL") or "").rstrip("/")
SUPABASE_KEY = (os.getenv("SUPABASE_SERVICE_ROLE_KEY") or os.getenv("SUPABASE_KEY")
                or os.getenv("SUPABASE_ANON_KEY") or "")
SUPABASE_TABELA = os.getenv("SUPABASE_TABELA", "fireforce_estado")
SUPABASE_ID = os.getenv("SUPABASE_ID", "principal")   # vira o "cofre": use algo difícil de adivinhar
SYNC_SEGUNDOS = int(os.getenv("SYNC_SEGUNDOS", "60"))

# tabelas que podem crescer: guardamos só as N linhas mais recentes
SYNC_LIMITE_TABELAS = {
    "transacoes": 4000, "livro_caixa": 4000, "comissoes": 2000,
    "ganhos_trabalho": 2000, "avaliacoes": 1000, "livepix_vistos": 800,
    "ff_cache": 1500, "eventos": 300,
    "influenciadores": 1000, "influenciador_comissoes": 3000,
}
SUPABASE_CHUNK_MAX_CHARS = 1_800_000
_sync_sujo = False
_sync_ultimo = 0.0
_sync_erro = ""
_ultimo_gc_banco = 0.0
_SUPABASE_BLOQUEIO_BANCO_VAZIO = False


async def limpar_lixo_banco(forcar: bool = False) -> dict:
    """Blindagem cirúrgica vitalícia (Plano Grátis Supabase):
    - NUNCA toca em carteiras (pessoal/trabalho), vitórias, patentes/estatisticas_jogador,
      lines_salvas, ff_blacklist, chaves PIX ou horários ativos.
    - Remove na hora salas já enviadas, tickets já fechados/logados, reservas expiradas,
      filas de espera encerradas e cache velho.
    - Compacta atomicamente diários arquivados há mais de 35 dias em `estatisticas_jogador.partidas_base`
      para que o jogador NUNCA perca suas partidas totais nem sua patente, mantendo `/relatorio` (30d) 100% exato."""
    global _ultimo_gc_banco
    agora_ts = time.time()
    if not forcar and (agora_ts - _ultimo_gc_banco) < 900:
        return {"pulado": True, "removidas": 0, "compactadas": 0}
    _ultimo_gc_banco = agora_ts

    agora_dt = agora_brt()
    corte_1d = (agora_dt - datetime.timedelta(days=1)).isoformat()
    corte_2d = (agora_dt - datetime.timedelta(days=2)).isoformat()
    corte_3d = (agora_dt - datetime.timedelta(days=3)).isoformat()
    corte_7d = (agora_dt - datetime.timedelta(days=7)).isoformat()
    corte_14d = (agora_dt - datetime.timedelta(days=14)).isoformat()
    corte_35d = (agora_dt - datetime.timedelta(days=35)).isoformat()
    corte_40d = (agora_dt - datetime.timedelta(days=40)).isoformat()

    removidas = 0
    compactadas = 0
    try:
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            db.row_factory = aiosqlite.Row
            await db.execute("BEGIN IMMEDIATE")

            # 1) Lixo efêmero imediato (salas já enviadas, tickets fechados, vagas VIP zeradas, fila velha)
            for sql_del, params_del in [
                ("DELETE FROM salas WHERE enviado = 1 OR (COALESCE(criado_em, '') != '' AND criado_em < ?)", (corte_2d,)),
                ("DELETE FROM tickets WHERE status = 'fechado' AND (fechado_em IS NULL OR fechado_em < ?)", (corte_1d,)),
                ("DELETE FROM vagas_vip WHERE qtd = 0", ()),
                ("DELETE FROM fila_espera WHERE horario_id NOT IN (SELECT id FROM horarios WHERE ativo = 1) OR (COALESCE(criado_em, '') != '' AND criado_em < ?)", (corte_2d,)),
                ("DELETE FROM depositos WHERE status IN ('cancelado', 'expirado', 'recusado') AND COALESCE(criado_em, '') != '' AND criado_em < ?", (corte_3d,)),
                ("DELETE FROM depositos WHERE status IN ('aprovado', 'creditado') AND COALESCE(creditado_em, criado_em, '') != '' AND COALESCE(creditado_em, criado_em) < ?", (corte_40d,)),
                ("DELETE FROM saques WHERE status IN ('recusado', 'cancelado') AND COALESCE(criado_em, '') != '' AND criado_em < ?", (corte_7d,)),
                ("DELETE FROM saques WHERE status = 'pago' AND COALESCE(processado_em, criado_em, '') != '' AND COALESCE(processado_em, criado_em) < ?", (corte_40d,)),
                ("DELETE FROM parceiros WHERE status = 'recusado'", ()),
                ("DELETE FROM divulgacoes WHERE status IN ('recusado', 'fechado') AND COALESCE(criado_em, '') != '' AND criado_em < ?", (corte_14d,)),
                ("DELETE FROM cupons WHERE ativo = 0 AND COALESCE(usos_max, 0) > 0 AND COALESCE(usos_atuais, 0) >= usos_max", ()),
                ("DELETE FROM cupons_usados WHERE cupom_id NOT IN (SELECT id FROM cupons)", ()),
                ("DELETE FROM ff_cache WHERE COALESCE(atualizado_em, '') != '' AND atualizado_em < ?", (corte_14d,)),
                ("DELETE FROM slots WHERE confirmado = 0 AND COALESCE(criado_em, '') != '' AND criado_em < ?", (corte_3d,)),
            ]:
                cur = await db.execute(sql_del, params_del)
                removidas += max(0, cur.rowcount or 0)

            # 2) Compactação atômica de slots confirmados arquivados há >35 dias -> estatisticas_jogador.partidas_base
            velhos_conf = await (await db.execute(
                "SELECT s.id, s.guild_id, s.comprador_id FROM slots s "
                "LEFT JOIN horarios h ON h.id = s.horario_id "
                "WHERE s.confirmado = 1 "
                "AND (h.id IS NULL OR h.ativo = 0) "
                "AND COALESCE(s.criado_em, '') != '' AND s.criado_em < ? "
                "ORDER BY s.id ASC",
                (corte_35d,),
            )).fetchall()

            ids_slots_compactados = []
            for row_s in velhos_conf:
                sid = int(row_s["id"])
                gid = int(row_s["guild_id"] or 0)
                uid = int(row_s["comprador_id"] or 0)
                if gid and uid:
                    await db.execute(
                        "INSERT INTO estatisticas_jogador (user_id, guild_id, partidas_base, ultimo_slot_migrado, sequencia_atual, melhor_sequencia, atualizado_em) "
                        "VALUES (?, ?, 1, ?, 0, 0, ?) "
                        "ON CONFLICT(user_id, guild_id) DO UPDATE SET "
                        "partidas_base = COALESCE(partidas_base, 0) + 1, "
                        "ultimo_slot_migrado = CASE WHEN COALESCE(ultimo_slot_migrado, 0) < excluded.ultimo_slot_migrado "
                        "THEN excluded.ultimo_slot_migrado ELSE ultimo_slot_migrado END, "
                        "atualizado_em = excluded.atualizado_em",
                        (uid, gid, sid, agora_dt.isoformat()),
                    )
                    compactadas += 1
                ids_slots_compactados.append(sid)

            if ids_slots_compactados:
                for i in range(0, len(ids_slots_compactados), 400):
                    lote_ids = ids_slots_compactados[i:i + 400]
                    ph = ",".join("?" * len(lote_ids))
                    c1 = await db.execute(f"DELETE FROM slot_jogadores WHERE slot_id IN ({ph})", tuple(lote_ids))
                    c2 = await db.execute(f"DELETE FROM slots WHERE id IN ({ph})", tuple(lote_ids))
                    removidas += max(0, c1.rowcount or 0) + max(0, c2.rowcount or 0)

            # Remove órfãos de slot_jogadores e horários arquivados sem canal ativo que já não têm mais slots
            c_orf = await db.execute("DELETE FROM slot_jogadores WHERE slot_id NOT IN (SELECT id FROM slots)")
            c_hor = await db.execute(
                "DELETE FROM horarios WHERE ativo = 0 "
                "AND COALESCE(canal_tabela, 0) = 0 "
                "AND id NOT IN (SELECT DISTINCT horario_id FROM slots WHERE horario_id IS NOT NULL)"
            )
            removidas += max(0, c_orf.rowcount or 0) + max(0, c_hor.rowcount or 0)

            await db.commit()
    except Exception as erro:
        _log_arquivo(f"[GC BANCO] erro ao limpar lixo: {erro}")
        return {"pulado": False, "removidas": removidas, "compactadas": compactadas, "erro": str(erro)}

    if removidas or compactadas:
        _log_arquivo(f"[GC BANCO] {removidas} linha(s) efêmera(s) limpa(s), {compactadas} partida(s) >35d compactada(s)")
    return {"pulado": False, "removidas": removidas, "compactadas": compactadas}


def supabase_configurado() -> bool:
    return bool(SUPABASE_URL and SUPABASE_KEY)


def marcar_sujo():
    """Avisa que algo mudou (o envio acontece no loop ou no /backup)."""
    global _sync_sujo
    _sync_sujo = True


async def _sb_req(metodo: str, rota: str, json_body=None, params=None, prefer=None):
    """Chamada REST no Supabase com pool persistente + até 3 tentativas automáticas contra oscilações de rede/502."""
    if not supabase_configurado():
        return False, "Supabase não configurado"
    cabecalho = {
        "apikey": SUPABASE_KEY,
        "Authorization": f"Bearer {SUPABASE_KEY}",
        "Accept": "application/json",
    }
    if prefer:
        cabecalho["Prefer"] = prefer

    url_completa = f"{SUPABASE_URL}{rota}"
    timeout = aiohttp.ClientTimeout(total=28, connect=8)
    ultimo_erro = "falha desconhecida"

    for tentativa in range(3):
        try:
            sessao = _ff_sessao()
            async with sessao.request(
                metodo,
                url_completa,
                headers=cabecalho,
                json=json_body,
                params=params,
                timeout=timeout,
            ) as resp:
                texto = await resp.text()
                if resp.status >= 400:
                    ultimo_erro = f"HTTP {resp.status}: {texto[:200]}"
                    if resp.status in (408, 429, 500, 502, 503, 504, 520, 521, 522, 523, 524) and tentativa < 2:
                        await asyncio.sleep(0.8 * (2 ** tentativa))
                        continue
                    return False, ultimo_erro
                try:
                    return True, (json.loads(texto) if texto else {})
                except Exception:
                    return True, {}
        except Exception as erro:
            ultimo_erro = f"{type(erro).__name__}: {erro}"
            if tentativa < 2:
                await asyncio.sleep(0.8 * (2 ** tentativa))
                continue
    return False, ultimo_erro


async def _tabelas_locais() -> list:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        linhas = await (await db.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        )).fetchall()
    return [l[0] for l in linhas]


async def snapshot_dump() -> dict:
    """Fotografia de todas as tabelas (limitando as que crescem)."""
    foto = {"versao": VERSAO_BOT, "quando": agora_brt().isoformat(), "tabelas": {}}
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        for tabela in await _tabelas_locais():
            colunas = [c[1] for c in await (await db.execute(f"PRAGMA table_info({tabela})")).fetchall()]
            limite = SYNC_LIMITE_TABELAS.get(tabela)
            sql = f"SELECT * FROM {tabela}"
            if limite:
                sql += f" ORDER BY rowid DESC LIMIT {limite}"
            linhas = await (await db.execute(sql)).fetchall()
            foto["tabelas"][tabela] = {"colunas": colunas, "linhas": [list(l) for l in linhas]}
    return foto


async def snapshot_aplicar(foto: dict) -> int:
    """Restaura a fotografia no banco local intersepcionando colunas válidas (nunca descarta tabela inteira por coluna nova/antiga)."""
    if not isinstance(foto, dict) or "tabelas" not in foto:
        return 0
    total = 0
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        for tabela, dados in (foto.get("tabelas") or {}).items():
            colunas = dados.get("colunas") or []
            linhas = dados.get("linhas") or []
            if not colunas or not linhas:
                continue
            existentes = {
                x[1]
                for x in await (await db.execute(f"PRAGMA table_info({tabela})")).fetchall()
            }
            if not existentes:
                continue
            pares_validos = [(idx_c, col_c) for idx_c, col_c in enumerate(colunas) if col_c in existentes]
            if not pares_validos:
                continue
            indices_ok = [idx_c for idx_c, _ in pares_validos]
            nomes_ok = [col_c for _, col_c in pares_validos]
            placeholders = ", ".join("?" for _ in nomes_ok)
            sql = f"INSERT OR REPLACE INTO {tabela} ({', '.join(nomes_ok)}) VALUES ({placeholders})"
            for linha in linhas:
                try:
                    valores_ok = tuple(linha[i] for i in indices_ok)
                    await db.execute(sql, valores_ok)
                    total += 1
                except Exception:
                    continue
        await db.commit()
    return total


def _pacote(foto: dict) -> str:
    cru = json.dumps(foto, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return base64.b64encode(gzip.compress(cru, 6)).decode("ascii")


def _despacotar(pacote: str) -> dict:
    return json.loads(gzip.decompress(base64.b64decode(pacote)).decode("utf-8"))


async def salvar_estado(forcar: bool = False) -> str:
    """Envia a fotografia para o Supabase (com trava anti-sobrescrita de banco vazio + fatiamento automático)."""
    global _sync_sujo, _sync_ultimo, _sync_erro
    if not supabase_configurado():
        return "Supabase não configurado (defina SUPABASE_URL e SUPABASE_SERVICE_ROLE_KEY)."

    if _SUPABASE_BLOQUEIO_BANCO_VAZIO:
        _sync_erro = "bloqueado p/ proteger backup em nuvem (aguardando restauração inicial)"
        return f"🛡️ Envio retido: {_sync_erro}"

    # Proteção extra: se o banco local estiver zerado (ex.: máquina recém-ligada) e já houver backup populado na nuvem,
    # jamais sobrescreve automaticamente sem comando explícito de restauração concluída!
    if await _banco_vazio():
        ok_chk, dados_chk = await _sb_req(
            "GET",
            f"/rest/v1/{SUPABASE_TABELA}",
            params={"id": f"eq.{SUPABASE_ID}", "select": "dado,atualizado_em"},
        )
        if ok_chk and dados_chk and len(str(dados_chk[0].get("dado") or "")) > 280 and not forcar:
            _sync_erro = "banco local vazio diante de backup populado na nuvem (protegido contra wipe)"
            return f"🛡️ Envio retido: {_sync_erro}"

    await limpar_lixo_banco(forcar=forcar)
    foto = await snapshot_dump()
    pacote = _pacote(foto)
    agora_iso = agora_brt().isoformat()
    total_linhas = sum(len(t["linhas"]) for t in foto["tabelas"].values())
    kb = len(pacote) / 1024.0

    if len(pacote) <= SUPABASE_CHUNK_MAX_CHARS:
        corpo = {
            "id": SUPABASE_ID,
            "dado": pacote,
            "atualizado_em": agora_iso,
            "versao": VERSAO_BOT,
        }
        ok, dados = await _sb_req(
            "POST", f"/rest/v1/{SUPABASE_TABELA}",
            json_body=corpo,
            prefer="resolution=merge-duplicates,return=minimal",
            params={"on_conflict": "id"},
        )
        if not ok:
            _sync_erro = str(dados)
            return f"❌ Não consegui salvar no Supabase: {_sync_erro[:150]}"
        # Limpa pedaços antigos caso antes estivesse fatiado e agora caiba em 1 bloco
        await _sb_req(
            "DELETE", f"/rest/v1/{SUPABASE_TABELA}",
            params={"id": f"like.{SUPABASE_ID}__chunk_*"},
        )
        _sync_sujo = False
        _sync_ultimo = time.time()
        _sync_erro = ""
        return f"✅ Salvo no Supabase ({kb:.0f} KB, {total_linhas} linhas)"

    # Fatiamento automático em blocos seguros de ~1.8 MB (evita limite HTTP POST no plano grátis)
    partes = [
        pacote[i:i + SUPABASE_CHUNK_MAX_CHARS]
        for i in range(0, len(pacote), SUPABASE_CHUNK_MAX_CHARS)
    ]
    for idx, pedaco in enumerate(partes, start=1):
        ok_p, dados_p = await _sb_req(
            "POST", f"/rest/v1/{SUPABASE_TABELA}",
            json_body={
                "id": f"{SUPABASE_ID}__chunk_{idx}",
                "dado": pedaco,
                "atualizado_em": agora_iso,
                "versao": VERSAO_BOT,
            },
            prefer="resolution=merge-duplicates,return=minimal",
            params={"on_conflict": "id"},
        )
        if not ok_p:
            _sync_erro = str(dados_p)
            return f"❌ Falha ao salvar bloco {idx}/{len(partes)} no Supabase: {_sync_erro[:140]}"

    manifesto = json.dumps({"__ff_chunks__": len(partes), "chars": len(pacote)})
    ok_m, dados_m = await _sb_req(
        "POST", f"/rest/v1/{SUPABASE_TABELA}",
        json_body={
            "id": SUPABASE_ID,
            "dado": manifesto,
            "atualizado_em": agora_iso,
            "versao": VERSAO_BOT,
        },
        prefer="resolution=merge-duplicates,return=minimal",
        params={"on_conflict": "id"},
    )
    if not ok_m:
        _sync_erro = str(dados_m)
        return f"❌ Falha ao salvar manifesto no Supabase: {_sync_erro[:140]}"

    # Limpa eventuais blocos excedentes antigos (ex: antes tinha 4 blocos, agora 3)
    for extra_idx in range(len(partes) + 1, len(partes) + 6):
        await _sb_req(
            "DELETE", f"/rest/v1/{SUPABASE_TABELA}",
            params={"id": f"eq.{SUPABASE_ID}__chunk_{extra_idx}"},
        )

    _sync_sujo = False
    _sync_ultimo = time.time()
    _sync_erro = ""
    return f"✅ Salvo no Supabase ({kb:.0f} KB em {len(partes)} blocos, {total_linhas} linhas)"


async def carregar_estado(forcar: bool = False) -> tuple:
    """Baixa a fotografia (suporta pacote único ou múltiplos blocos automáticos)."""
    if not supabase_configurado():
        return False, "Supabase não configurado."

    ok, dados = await _sb_req(
        "GET", f"/rest/v1/{SUPABASE_TABELA}",
        params={"id": f"eq.{SUPABASE_ID}", "select": "dado,atualizado_em,versao"},
    )
    if not ok:
        return False, f"❌ Erro ao baixar do Supabase: {str(dados)[:150]}"
    if not dados:
        return False, "Nada salvo no Supabase ainda (primeira execução)."

    registro = dados[0]
    dado_cru = str(registro.get("dado") or "")
    if dado_cru.startswith("{") and "__ff_chunks__" in dado_cru:
        try:
            meta = json.loads(dado_cru)
            qtd_blocos = int(meta.get("__ff_chunks__") or 0)
        except Exception as erro:
            return False, f"❌ Manifesto inválido no Supabase: {erro}"
        partes_baixadas = []
        for idx in range(1, qtd_blocos + 1):
            ok_c, dados_c = await _sb_req(
                "GET", f"/rest/v1/{SUPABASE_TABELA}",
                params={"id": f"eq.{SUPABASE_ID}__chunk_{idx}", "select": "dado"},
            )
            if not ok_c or not dados_c:
                return False, f"❌ Bloco {idx}/{qtd_blocos} ausente no Supabase."
            partes_baixadas.append(str(dados_c[0].get("dado") or ""))
        dado_cru = "".join(partes_baixadas)

    try:
        foto = _despacotar(dado_cru)
    except Exception as erro:
        return False, f"❌ Pacote inválido: {erro}"

    if not forcar and not await _banco_vazio():
        return False, ("O banco local já tem dados — use `/restaurar forcar:Sim` "
                       "se quiser sobrescrever com o backup do Supabase.")

    linhas = await snapshot_aplicar(foto)
    return True, f"✅ Restaurado do Supabase: {linhas} linhas (backup de {registro.get('atualizado_em', '?')})"


# ══════════════════════════════════════════════════════════════
#  🧱 ESTRUTURAS NO SUPABASE (tempo real)
#
#  Além do backup completo (fireforce_estado), o bot escreve nas tabelas
#  "de verdade" do Supabase pra você consultar/linkar de fora:
#
#    • ff_config        → configurações do bot (as mesmas do /config)
#    • ff_cargos        → cargos (dono, gerente, mediador, suporte)
#    • ff_staff_online  → quem está ON/OFF agora (painel /staff)
#    • ff_rankings      → tops: saldo, transferências, depósitos, ganhos,
#                         vitórias, comissões e carteira de trabalho
#
#  O SQL que cria essas tabelas está no arquivo `supabase_setup.sql`.
# ══════════════════════════════════════════════════════════════

