NOTA_VALORES_PADRAO = {0.0: 0.0, 0.5: 0.05, 1.0: 0.50, 1.5: 0.75, 2.0: 1.00, 2.5: 1.25,
                       3.0: 1.50, 3.5: 1.75, 4.0: 2.00, 4.5: 2.25, 5.0: 2.50}


def _emoji_nota(nota: float) -> str:
    cheias = int(nota)
    resto = nota - cheias
    return "⭐" * cheias + ("½" if resto >= 0.5 else "") or "0️⃣"


async def nota_valores(guild_id: int) -> dict:
    """Tabela nota → valor (configurável no /config)."""
    texto = await cfgv(guild_id, "nota_valores", "")
    if texto:
        try:
            dados = json.loads(texto)
            return {float(k): float(v) for k, v in dados.items()}
        except Exception:
            pass
    return dict(NOTA_VALORES_PADRAO)


def fila_normalizada(tipo: str) -> str:
    """As 2 filas do servidor: 🎧 suporte e 🤝 mediador (ADM)."""
    return "mediador" if (tipo or "").strip().lower() in ("mediador", "adm", "financeiro") else "suporte"


def cargos_da_fila(tipo: str) -> list:
    """Quem atende cada fila: 🎧 suporte (cargo_suporte) e 🤝 mediador/ADM (cargo_mediador)."""
    if fila_normalizada(tipo) == "mediador":
        return ["cargo_mediador", "cargo_gerente", "cargo_dono"]
    return ["cargo_suporte", "cargo_gerente", "cargo_dono"]


async def atendente_autorizado(tipo: str, member) -> bool:
    if member.guild_permissions.administrator:
        return True
    cfg = await obter_config(member.guild.id)
    permitidos = [cfg.get(k) for k in cargos_da_fila(tipo)]
    return any(r.id in permitidos for r in getattr(member, "roles", []) if r.id)


async def e_gerencia(member) -> bool:
    """Dono, gerente ou administrador."""
    if member.guild_permissions.administrator:
        return True
    cfg = await obter_config(member.guild.id)
    return any(r.id in [cfg.get("cargo_dono"), cfg.get("cargo_gerente")]
               for r in getattr(member, "roles", []) if r.id)


# ---------- EM SERVIÇO / FORA DE SERVIÇO (painel /staff) ----------

async def em_servico(user_id: int, guild_id: int) -> bool:
    """True quando o membro marcou Em serviço; sem registro, fica fora de serviço."""
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            linha = await (await db.execute(
                "SELECT online FROM staff_status WHERE user_id = ? AND guild_id = ?",
                (int(user_id), int(guild_id)))).fetchone()
    except Exception:
        # Falha no banco = negar assumir até confirmar que está em serviço.
        return False
    return bool(linha[0]) if linha else False


async def usuario_equipe_com_suporte(member) -> bool:
    """Inclui suporte e os cargos de ADM/mediador/gerência nos fluxos de serviço (/staff)."""
    if not getattr(member, "guild", None):
        return False
    return await e_staff(member) or await e_suporte(member)


async def tem_carteira_trabalho(member) -> bool:
    """Único cargo com carteira de trabalho: Suporte.
    ADM (Mediador, Gerente, Dono ou Administrador) não possui carteira de trabalho e recebe direto no PIX."""
    guild = getattr(member, "guild", None)
    if not guild:
        return False
    cfg = await obter_config(guild.id)
    cargo_sup = cfg.get("cargo_suporte")
    if not cargo_sup:
        return False
    ids = {r.id for r in getattr(member, "roles", []) if r.id}
    chefia = {int(cfg[k]) for k in ("cargo_dono", "cargo_gerente", "cargo_mediador") if cfg.get(k)}
    if (chefia & ids) or (getattr(member, "guild_permissions", None) and member.guild_permissions.administrator):
        return False
    return int(cargo_sup) in ids


async def usuario_staff_em_servico(member) -> bool:
    """True para staff de plantão; falha de leitura também bloqueia a inscrição."""
    guild = getattr(member, "guild", None)
    if not guild or not await usuario_equipe_com_suporte(member):
        return False
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            linha = await (await db.execute(
                "SELECT online FROM staff_status WHERE user_id = ? AND guild_id = ?",
                (int(member.id), int(guild.id))
            )).fetchone()
        # Sem registro significa fora de serviço; registro com online=1 bloqueia o jogo.
        return bool(linha[0]) if linha else False
    except Exception as erro:
        _log_arquivo(f"[SERVIÇO] não foi possível validar status de jogo para {member.id}: {erro}")
        return True


async def aviso_fora_de_servico(interaction) -> bool:
    """True = pode seguir; False = já respondeu que está fora de serviço."""
    if await em_servico(interaction.user.id, interaction.guild.id):
        return True
    await interaction.response.send_message(
        embed=criar_embed(
            "🔴 Você está FORA DE SERVIÇO",
            "Entre em serviço no painel **/staff** (botão 🟢 Em serviço) para poder assumir atendimentos.\n"
            "> 🟢 Quem está em serviço aparece como disponível para todo o time.\n"
            "> 🔴 Fora de serviço, pode jogar nos diários, mas não assume atendimentos.",
            "Amarelo"),
        ephemeral=True)
    return False


async def canal_pagamento_equipe(guild, staff_id: int, forcar_adm: bool = False):
    """Canal PRIVADO do log da equipe:
      • Suporte -> canal_log_pag_suporte (com fallback para canal_logs_suporte / canal_logs)
      • ADM -> canal_log_pag_adm (com fallback automático para canal_logs / canal_logs_suporte,
        para que o log de ganhos do ADM NUNCA suma caso um canal separado não esteja definido)."""
    if not guild:
        return None, "adm"
    cfg = await obter_config(guild.id)
    qual = "adm"
    if not forcar_adm:
        membro = await membro_do_guild(guild, staff_id)
        try:
            if membro is not None and not membro.guild_permissions.administrator:
                ids = {r.id for r in getattr(membro, "roles", []) if r.id}
                chefia = {cfg.get("cargo_dono"), cfg.get("cargo_gerente"), cfg.get("cargo_mediador")}
                if cfg.get("cargo_suporte") in ids and not (chefia & ids):
                    qual = "suporte"
        except Exception:
            qual = "adm"

    if qual == "suporte":
        candidatos = (cfg.get("canal_log_pag_suporte"), cfg.get("canal_logs_suporte"), cfg.get("canal_logs"))
    else:
        candidatos = (cfg.get("canal_log_pag_adm"), cfg.get("canal_logs"), cfg.get("canal_logs_suporte"))

    for cid in candidatos:
        if not cid:
            continue
        try:
            canal = guild.get_channel(int(cid))
        except (TypeError, ValueError):
            canal = None
        if isinstance(canal, discord.TextChannel):
            return canal, qual
    return None, qual


async def anunciar_pagamento_equipe(guild, staff_id: int, titulo: str, descricao: str,
                                    cor: str = "Esmeralda", forcar_adm: bool = False) -> Optional[int]:
    """Log de recebimento/pagamento da equipe:
      • Suporte: mostra tickets avaliados hoje, média semanal e carteira de trabalho.
      • ADM: mostra quanto recebeu nesta confirmação + total acumulado no DIA e na SEMANA.
    Retorna o ID do canal onde enviou (ou None se nenhum canal de log estiver configurado)."""
    try:
        canal, qual = await canal_pagamento_equipe(guild, staff_id, forcar_adm=forcar_adm)
        if not canal:
            return None
        rotulo = "🎧 SUPORTE" if qual == "suporte" else "🛡️ ADM"
        extra = ""
        hoje = agora_brt().strftime('%Y-%m-%d')
        semana = (agora_brt() - datetime.timedelta(days=agora_brt().weekday())).replace(
            hour=0, minute=0, second=0, microsecond=0
        ).isoformat()
        if qual == "suporte":
            try:
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    db.row_factory = aiosqlite.Row
                    dia = await (await db.execute(
                        "SELECT COUNT(*) n FROM avaliacoes WHERE guild_id=? AND atendente_id=? AND substr(criado_em,1,10)=?",
                        (guild.id, staff_id, hoje),
                    )).fetchone()
                    sem = await (await db.execute(
                        "SELECT COUNT(*) n, AVG(nota) media FROM avaliacoes WHERE guild_id=? AND atendente_id=? AND criado_em>=?",
                        (guild.id, staff_id, semana),
                    )).fetchone()
                saldo = await saldo_trabalho(staff_id, guild.id)
                extra = (f"\n\n> 🎫 Tickets avaliados hoje: **{dia['n'] or 0}**"
                         f"\n> ⭐ Média desta semana: **{float(sem['media'] or 0):.2f}/5** ({sem['n'] or 0} avaliações)"
                         f"\n> 💼 Total disponível na carteira: **{formatar_moeda(saldo)}**")
            except Exception:
                pass
        else:
            try:
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    db.row_factory = aiosqlite.Row
                    dia_adm = await (await db.execute(
                        "SELECT COUNT(*) AS n, COALESCE(SUM(comissao), 0) AS total "
                        "FROM comissoes WHERE guild_id = ? AND staff_id = ? AND dia = ?",
                        (guild.id, staff_id, hoje),
                    )).fetchone()
                    sem_adm = await (await db.execute(
                        "SELECT COUNT(*) AS n, COALESCE(SUM(comissao), 0) AS total "
                        "FROM comissoes WHERE guild_id = ? AND staff_id = ? AND criado_em >= ?",
                        (guild.id, staff_id, semana),
                    )).fetchone()
                qtd_hoje = int(dia_adm["n"] or 0)
                tot_hoje = arredondar(dia_adm["total"] or 0)
                qtd_sem = int(sem_adm["n"] or 0)
                tot_sem = arredondar(sem_adm["total"] or 0)
                extra = (
                    f"\n\n> 📅 Vagas confirmadas hoje por este ADM: **{qtd_hoje}**"
                    f"\n> 💵 **Total ganho por este ADM hoje:** **`{formatar_moeda(tot_hoje)}`**"
                    f"\n> 📊 Acumulado nesta semana: `{formatar_moeda(tot_sem)}` ({qtd_sem} vaga{'s' if qtd_sem != 1 else ''})"
                )
            except Exception as erro_adm:
                _log_arquivo(f"[LOG ADM] erro resumo diário: {erro_adm}")
        rodape = "Fire Force • Carteira de trabalho (Suporte)" if qual == "suporte" else f"Fire Force • Controle de ganhos do ADM ({hoje[8:10]}/{hoje[5:7]})"
        embed = criar_embed(titulo, f"> 👤 **Cargo:** {rotulo}\n{descricao}{extra}", cor, footer=rodape)
        await canal.send(embed=embed)
        return canal.id
    except Exception as erro:
        _log_arquivo(f"[PAG-EQUIPE] {erro}")
        return None


# ---------- CARTEIRA DE TRABALHO (salários da equipe) ----------

async def saldo_trabalho(user_id: int, guild_id: int) -> float:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linha = await (await db.execute(
            "SELECT saldo FROM carteira_trabalho WHERE user_id = ? AND guild_id = ?", (user_id, guild_id)
        )).fetchone()
    return arredondar(linha["saldo"] if linha else 0)


async def movimentar_trabalho(user_id: int, guild_id: int, valor: float, tipo: str,
                              descricao: str, ref: str = "", permitir_negativo: bool = False):
    valor = arredondar(valor)
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        await db.execute("INSERT OR IGNORE INTO carteira_trabalho (user_id, guild_id, saldo, atualizado_em) "
                         "VALUES (?, ?, 0, ?)", (user_id, guild_id, agora_brt().isoformat()))
        linha = await (await db.execute(
            "SELECT saldo FROM carteira_trabalho WHERE user_id = ? AND guild_id = ?", (user_id, guild_id)
        )).fetchone()
        atual = arredondar(linha["saldo"] if linha else 0)
        novo = arredondar(atual + valor)
        if novo < 0 and not permitir_negativo:
            await db.rollback()
            return None
        await db.execute("UPDATE carteira_trabalho SET saldo = ?, atualizado_em = ? WHERE user_id = ? AND guild_id = ?",
                         (novo, agora_brt().isoformat(), user_id, guild_id))
        await db.execute(
            "INSERT INTO ganhos_trabalho (guild_id, user_id, tipo, valor, saldo_apos, descricao, ref, criado_em) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (guild_id, user_id, tipo, valor, novo, descricao, ref, agora_brt().isoformat())
        )
        await db.commit()
    marcar_sujo()
    return novo


async def creditar_trabalho(user_id: int, guild_id: int, valor: float, tipo: str,
                            descricao: str, ref: str = ""):
    return await movimentar_trabalho(user_id, guild_id, abs(valor), tipo, descricao, ref)


async def extrato_trabalho(user_id: int, guild_id: int, quantidade: int = 8) -> str:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        linhas = await (await db.execute(
            "SELECT * FROM ganhos_trabalho WHERE guild_id = ? AND user_id = ? ORDER BY id DESC LIMIT ?",
            (guild_id, user_id, quantidade)
        )).fetchall()
    if not linhas:
        return "> *Nenhum ganho registrado.*"
    icones = {"comissao": "💸", "avaliacao": "⭐", "saque": "🏦", "reset": "🔄", "ajuste": "🛠️", "premio": "🏆"}
    return "\n".join(
        f"> {icones.get(l['tipo'], '•')} `{'+' if l['valor'] >= 0 else '−'}{formatar_moeda(abs(l['valor']))}`"
        f" — {(l['descricao'] or '')[:44]} `{(l['criado_em'] or '')[8:16].replace('-', '/')}`"
        for l in linhas
    )


async def avisar_abandono_saldo(guild) -> int:
    """Domingo à noite: última chamada para o Suporte que ainda tem salário na carteira de trabalho."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        contas = await (await db.execute(
            "SELECT * FROM carteira_trabalho WHERE guild_id = ? AND saldo > 0", (guild.id,)
        )).fetchall()
    contas_validas = []
    for c in contas:
        membro = await membro_do_guild(guild, c["user_id"])
        if membro and await tem_carteira_trabalho(membro):
            contas_validas.append(c)
    if not contas_validas:
        return 0

    linhas = [f"> {mencao(c['user_id'])}: `{formatar_moeda(c['saldo'])}`" for c in contas_validas]
    cfg = await obter_config(guild.id)
    marcas = [f"<@&{cfg.get('cargo_suporte')}>"] if cfg.get("cargo_suporte") else []
    canal_id = await canal_de_logs(guild.id)
    canal = guild.get_channel(int(canal_id)) if canal_id else None
    if canal:
        try:
            await canal.send(
                content=" ".join(marcas)[:180],
                embed=criar_embed(
                    "⏰ ÚLTIMA CHAMADA — carteira de trabalho (Suporte)",
                    "O prazo acaba **hoje**. Quem não pedir o saque até **01:00 (horário de Brasília)** "
                    "considera **abandono de saldo**: o valor vira da **Org** e sai da carteira.\n\n"
                    "**Suporte ainda com saldo:**\n" + "\n".join(linhas) +
                    "\n\n> 💸 Pedir saque: painel **Carteira** → **Carteira de trabalho** → **Solicitar saque**.", "Vermelho"))
        except Exception:
            pass
    await registrar_log(
        guild, "⏰ PRAZO", "⏰ Última chamada para sacar o salário (Suporte)",
        "Prazo: até **01:00 (Brasília)**. Depois disso o saldo vira **abandono de saldo** (fica com a Org).\n"
        + "\n".join(linhas), "Vermelho")
    return len(contas_validas)


async def reset_semanal_trabalho(guild) -> dict:
    """Fim do prazo (segunda 01:00 BRT): quem não sacou perde o saldo — abandono de saldo (vira da Org)."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        contas = await (await db.execute(
            "SELECT * FROM carteira_trabalho WHERE guild_id = ? AND saldo > 0", (guild.id,)
        )).fetchall()

    total = 0.0
    linhas = []
    for conta in contas:
        await movimentar_trabalho(conta["user_id"], guild.id, -conta["saldo"], "abandono",
                                  "Abandono de saldo — não sacou até 01:00 (Brasília); o valor virou da Org.",
                                  ref=f"abandono:{agora_brt().strftime('%Y-%m-%d')}")
        total = arredondar(total + conta["saldo"])
        linhas.append(f"> {mencao(conta['user_id'])}: `{formatar_moeda(conta['saldo'])}`")

    if linhas:
        await registrar_log(
            guild, "🚫 ABANDONO DE SALDO", "🚫 Abandono de saldo — virou da Org",
            f"Ninguém tirou o dinheiro até **01:00 (horário de Brasília)**. O valor saiu da carteira e "
            f"ficou com a **Org**.\n**Total: {formatar_moeda(total)}**\n" + "\n".join(linhas) +
            "\n> 💡 O prazo de saque da carteira de trabalho é o **domingo** (até 01:00 de segunda, Brasília).",
            "Vermelho"
        )
    return {"total": total, "contas": len(linhas)}


def multiplicador_nota_semanal(media: float) -> float:
    """Faixas acordadas: <2=0%; 2–2.99=25%; 3–3.99=50%; 4–4.49=90%; 4.5–4.99=95%; 5=100%."""
    if media < 2.0: return 0.0
    if media < 3.0: return 0.25
    if media < 4.0: return 0.50
    if media < 4.5: return 0.90
    if media < 5.0: return 0.95
    return 1.0


async def fechar_notas_semanais(guild, data_ref=None) -> int:
    """Apura avaliações semanais e aplica o redutor só sobre os ganhos da semana."""
    agora=agora_brt()
    fim=(agora-datetime.timedelta(days=1)).replace(hour=23,minute=59,second=59,microsecond=999999) if agora.weekday()==0 and agora.hour<1 else agora
    data_ref=data_ref or fim.strftime('%Y-%m-%d')
    marca=f"nota_semanal:{guild.id}:{data_ref}"
    inicio=(fim-datetime.timedelta(days=6)).replace(hour=0,minute=0,second=0,microsecond=0)
    async with aiosqlite.connect(DATABASE_FILE) as db:
        ja=await (await db.execute("SELECT 1 FROM sync_meta WHERE chave=?",(marca,))).fetchone()
        if ja: return 0
        db.row_factory=aiosqlite.Row
        staffs=await (await db.execute(
            "SELECT DISTINCT atendente_id FROM avaliacoes WHERE guild_id=? AND criado_em>=? AND criado_em<=?",
            (guild.id,inicio.isoformat(),fim.isoformat()))).fetchall()
    processados=0
    for row in staffs:
        uid=int(row['atendente_id'])
        membro_staff = await membro_do_guild(guild, uid)
        if not membro_staff or not await tem_carteira_trabalho(membro_staff):
            continue
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory=aiosqlite.Row
            ev=await (await db.execute(
                "SELECT COUNT(*) n, AVG(nota) media FROM avaliacoes WHERE guild_id=? AND atendente_id=? AND criado_em>=? AND criado_em<=?",
                (guild.id,uid,inicio.isoformat(),fim.isoformat()))).fetchone()
            ganho=await (await db.execute(
                "SELECT COALESCE(SUM(valor),0) total FROM ganhos_trabalho WHERE guild_id=? AND user_id=? AND tipo IN ('comissao','avaliacao') AND criado_em>=? AND criado_em<=?",
                (guild.id,uid,inicio.isoformat(),fim.isoformat()))).fetchone()
        n=int(ev['n'] or 0); media=float(ev['media'] or 0); bruto=arredondar(ganho['total'] or 0)
        mult=multiplicador_nota_semanal(media) if n else 1.0
        reducao=arredondar(bruto*(1-mult)); saldo_antes=await saldo_trabalho(uid,guild.id)
        ajuste=min(reducao,max(0.0,saldo_antes))
        ref_ajuste=f"nota-semanal:{data_ref}:{uid}"
        async with aiosqlite.connect(DATABASE_FILE) as db:
            ajuste_ja_feito=await (await db.execute("SELECT 1 FROM ganhos_trabalho WHERE guild_id=? AND user_id=? AND ref=?",(guild.id,uid,ref_ajuste))).fetchone()
        if ajuste>0 and not ajuste_ja_feito:
            await movimentar_trabalho(uid,guild.id,-ajuste,'ajuste',
                f"Ajuste semanal por média {media:.2f}/5 em {n} avaliações; faixa {mult:.0%}.",ref=ref_ajuste)
        elif ajuste_ja_feito:
            ajuste=0.0
        saldo=await saldo_trabalho(uid,guild.id)
        faixa=f"{mult:.0%} do ganho semanal" if n else "sem avaliações; sem redutor"
        desc=(f"{mencao(uid)}\n> 🎫 Tickets avaliados: **{n}**\n> ⭐ Média semanal: **{media:.2f}/5**\n"
              f"> 📈 Ganho bruto semanal: `{formatar_moeda(bruto)}`\n> ⚖️ Faixa aplicada: **{faixa}**\n"
              f"> ➖ Ajuste efetuado: `{formatar_moeda(ajuste)}`\n> 💼 Total atual na carteira: `{formatar_moeda(saldo)}`\n"
              f"> 🧾 Saque manual no domingo; prazo final segunda 01:00 BRT.")
        await anunciar_pagamento_equipe(guild,uid,"⭐ Fechamento semanal de avaliações e ganhos",desc,"Dourado")
        processados+=1
    async with aiosqlite.connect(DATABASE_FILE) as db:
        await db.execute("INSERT OR REPLACE INTO sync_meta(chave,valor) VALUES(?,?)",(marca,agora.isoformat()))
        await db.commit()
    marcar_sujo(); return processados


async def loop_fechamento_semanal():
    """Domingo (configurável) na virada da meia-noite: fecha a semana da equipe."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            agora = agora_brt()
            dia = int(await cfgv(None, "dia_fechamento", 0))   # 0 = segunda (fim do domingo)
            hoje = agora.weekday()
            # 🚨 véspera (domingo 23h): última chamada para quem ainda tem salário na carteira
            if hoje == (dia - 1) % 7 and agora.hour == 23:
                for guild in bot.guilds:
                    try:
                        await fechar_notas_semanais(guild, agora.strftime('%Y-%m-%d'))
                    except Exception as erro:
                        _log_arquivo(f"[NOTA SEMANAL] erro: {erro}")
                marca_aviso = f"aviso_saldo:{agora.strftime('%Y-%m-%d')}"
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    ja_aviso = await (await db.execute(
                        "SELECT 1 FROM sync_meta WHERE chave = ?", (marca_aviso,))).fetchone()
                    if not ja_aviso:
                        await db.execute("INSERT OR REPLACE INTO sync_meta (chave, valor) VALUES (?, ?)",
                                         (marca_aviso, agora.isoformat()))
                        await db.commit()
                        for guild in bot.guilds:
                            try:
                                await avisar_abandono_saldo(guild)
                            except Exception as erro:
                                _log_arquivo(f"[ABANDONO] aviso: {erro}")
            # ⏰ prazo final: 01:00 (Brasília) do dia do fechamento
            if hoje == dia and agora.hour == 1:
                marca = f"fechamento:{agora.strftime('%Y-%m-%d')}"
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    ja = await (await db.execute("SELECT 1 FROM sync_meta WHERE chave = ?", (marca,))).fetchone()
                    if ja:
                        await asyncio.sleep(600)
                        continue
                    await db.execute("INSERT OR REPLACE INTO sync_meta (chave, valor) VALUES (?, ?)",
                                     (marca, agora.isoformat()))
                    await db.commit()
                for guild in bot.guilds:
                    try:
                        await reset_semanal_trabalho(guild)
                    except Exception as erro:
                        _log_arquivo(f"[FECHAMENTO] erro: {erro}")
                    try:
                        await pagar_fila_trabalho(guild)
                    except Exception:
                        pass
        except Exception as erro:
            _log_arquivo(f"[FECHAMENTO] erro no loop: {erro}")
        await asyncio.sleep(300)


async def pagar_fila_trabalho(guild) -> int:
    """Libera os saques de trabalho que já podem ser pagos (reserva respeitada)."""
    disp = await disponibilidade_saque(guild.id)
    livre = disp["livre"]
    if livre <= 0:
        return 0
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        fila = await (await db.execute(
            "SELECT * FROM saques WHERE guild_id = ? AND status = 'na_fila' AND tipo = 'trabalho' ORDER BY id",
            (guild.id,)
        )).fetchall()
    liberados = 0
    for saque in fila:
        if arredondar(saque["valor"]) > livre:
            continue
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("UPDATE saques SET status = 'liberado' WHERE id = ?", (saque["id"],))
            await db.commit()
        livre = arredondar(livre - saque["valor"])
        liberados += 1
        await notificar_saque(guild, saque["id"])
    return liberados


