# ---------- RECONCILIAÇÃO SEGURA DE TICKETS/DEPÓSITOS ----------

async def _buscar_canal_guild(guild, channel_id):
    """Busca o canal pela cache/API; devolve None só quando não existe mais."""
    if not channel_id:
        return None
    channel = guild.get_channel(int(channel_id))
    if channel:
        return channel
    try:
        channel = await guild.fetch_channel(int(channel_id))
    except discord.NotFound:
        return None
    # Erros transitórios/permissões são propagados: não marcar como órfão sem certeza.
    if getattr(getattr(channel, "guild", None), "id", guild.id) != guild.id:
        return None
    return channel


async def _reconciliar_ticket_estado(guild, usuario_id=None, limpar_fechados=False):
    """Fecha no banco tickets órfãos; nunca toca em depósitos/saques.

    Um erro de rede/permissão não vira falso órfão. Canais de tickets já fechados
    são apagados na inicialização caso o processo tenha caído antes da limpeza.
    Chamadas ao Discord ocorrem fora de transações SQLite para não travar o banco.
    """
    orfaos = 0
    removidos = 0
    async with _lock_ticket_estado:
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            db.row_factory = aiosqlite.Row
            sql = "SELECT id, channel_id FROM tickets WHERE guild_id = ? AND status = 'aberto'"
            args = [guild.id]
            if usuario_id is not None:
                sql += " AND user_id = ?"
                args.append(int(usuario_id))
            abertas = [dict(r) for r in await (await db.execute(sql, tuple(args))).fetchall()]
            fechados = []
            if limpar_fechados and usuario_id is None:
                fechados = [dict(r) for r in await (await db.execute(
                    "SELECT id, channel_id FROM tickets WHERE guild_id=? AND status='fechado' AND channel_id IS NOT NULL",
                    (guild.id,))).fetchall()]

        ids_orfaos = []
        for row in abertas:
            try:
                canal = await _buscar_canal_guild(guild, row["channel_id"])
            except (discord.Forbidden, discord.HTTPException) as erro:
                _log_arquivo(f"[TICKET] reconciliação sem acesso guild={guild.id} id={row['id']}: {erro}")
                continue
            if canal is None:
                ids_orfaos.append(int(row["id"]))

        if ids_orfaos:
            async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
                for ticket_id in ids_orfaos:
                    cur = await db.execute(
                        "DELETE FROM tickets WHERE id=? AND guild_id=? AND status='aberto'",
                        (ticket_id, guild.id))
                    orfaos += max(0, cur.rowcount)
                await db.commit()

        ids_fechados_limpos = []
        for row in fechados:
            try:
                canal = await _buscar_canal_guild(guild, row["channel_id"])
                if canal:
                    await canal.delete(reason=f"Limpeza de ticket já fechado #{row['id']} após reinício")
                    removidos += 1
                ids_fechados_limpos.append(int(row["id"]))
            except discord.NotFound:
                ids_fechados_limpos.append(int(row["id"]))
            except (discord.Forbidden, discord.HTTPException) as erro:
                _log_arquivo(f"[TICKET] limpeza canal fechado #{row['id']}: {erro}")

        if ids_fechados_limpos:
            async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
                for tid_limpo in ids_fechados_limpos:
                    await db.execute("DELETE FROM tickets WHERE id=? AND guild_id=? AND status='fechado'", (tid_limpo, guild.id))
                await db.commit()

    if orfaos or removidos:
        marcar_sujo()
        _log_arquivo(f"[TICKET] reconciliação guild={guild.id}: {orfaos} órfão(s) fechado(s), {removidos} canal(is) finalizado(s) removido(s)")
    return {"tickets_orfaos": orfaos, "canais_fechados_removidos": removidos}

async def _reconciliar_depositos_orfaos(guild):
    """Cancela somente canais de atendimento de depósito vazios que já sumiram.

    Pedidos PIX com valor/status na_janela são preservados para a recuperação de pagamento.
    As consultas ao Discord acontecem fora da transação SQLite.
    """
    async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
        db.row_factory = aiosqlite.Row
        rows = [dict(r) for r in await (await db.execute(
            "SELECT id, canal_id FROM depositos WHERE guild_id=? AND status='aguardando' "
            "AND COALESCE(valor,0)<=0", (guild.id,))).fetchall()]
    ids_cancelar = []
    for row in rows:
        try:
            canal = await _buscar_canal_guild(guild, row["canal_id"])
        except (discord.Forbidden, discord.HTTPException) as erro:
            _log_arquivo(f"[DEPÓSITO] reconciliação sem acesso guild={guild.id} id={row['id']}: {erro}")
            continue
        if canal is None:
            ids_cancelar.append(int(row["id"]))
    cancelados = 0
    if ids_cancelar:
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            for deposito_id in ids_cancelar:
                cur = await db.execute("UPDATE depositos SET status='cancelado' WHERE id=? AND guild_id=? AND status='aguardando'",
                                       (deposito_id, guild.id))
                cancelados += max(0, cur.rowcount)
            await db.commit()
    if cancelados:
        marcar_sujo()
        _log_arquivo(f"[DEPÓSITO] {cancelados} atendimento(s) vazio(s) sem canal marcado(s) como cancelado(s), guild={guild.id}")
    return cancelados

