class EscolherModoCreditarKillsView(discord.ui.View):
    """Permite escolher Solo / Duo / Trio / Squad quando o ticket não veio vinculado a um horário específico (ou ao trocar modo)."""

    def __init__(self, autor_id: int, ticket_dict: dict, nomes_atuais: Optional[list[str]] = None, valor_kill_sug: str = "", rotulo_diario: str = ""):
        super().__init__(timeout=240)
        self.autor_id = int(autor_id)
        self.ticket_dict = dict(ticket_dict)
        self.nomes_atuais = list(nomes_atuais or [])
        self.valor_kill_sug = valor_kill_sug
        self.rotulo_diario = rotulo_diario
        sel = discord.ui.Select(
            placeholder="🎮 Escolha o modo da partida p/ informar as kills...",
            options=[
                discord.SelectOption(label="Solo (1 Jogador)", value="solo", emoji="👤", description="Informa as kills do jogador + valor por kill"),
                discord.SelectOption(label="Duo (2 Jogadores)", value="duo", emoji="👥", description="Informa kills dos Jogadores 1 e 2 + valor por kill"),
                discord.SelectOption(label="Trio (3 Jogadores)", value="trio", emoji="🔥", description="Informa kills dos Jogadores 1, 2 e 3 + valor por kill"),
                discord.SelectOption(label="Squad (4 Jogadores)", value="squad", emoji="🛡️", description="Informa kills dos Jogadores 1, 2, 3 e 4 + valor por kill"),
            ],
        )
        sel.callback = self._escolher_modo
        self.add_item(sel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.autor_id or not await e_dono_ou_gerente(interaction.user):
            await interaction.response.send_message(
                embed=criar_embed("🔒 Restrito", "Apenas quem iniciou este lançamento (Dono/Gerente) pode continuar.", "Vermelho"),
                ephemeral=True,
            )
            return False
        return True

    async def _escolher_modo(self, interaction: discord.Interaction):
        modo = interaction.data["values"][0]
        await interaction.response.send_modal(
            CreditarKillsModal(
                autor_id=self.autor_id,
                ticket_dict=self.ticket_dict,
                modo=modo,
                nomes_jogadores=self.nomes_atuais,
                valor_kill_sugerido=self.valor_kill_sug,
                rotulo_diario=self.rotulo_diario,
            )
        )


class CreditarKillsModal(discord.ui.Modal):
    """Modal adaptável: Solo (1 campo de kill), Duo (2), Trio (3) ou Squad (4) + Premiação por Kill (R$)."""

    def __init__(
        self,
        autor_id: int,
        ticket_dict: dict,
        modo: str,
        nomes_jogadores: Optional[list[str]] = None,
        valor_kill_sugerido: str = "",
        rotulo_diario: str = "",
        kills_preenchidas: Optional[list[int]] = None,
    ):
        modo_norm = modo if modo in ("solo", "duo", "trio", "squad") else "squad"
        qtd_jog = JOGADORES_POR_LOTE.get(modo_norm, 4)
        super().__init__(title=f"🪙 Creditar Kills — {modo_norm.capitalize()}"[:45])
        self.autor_id = int(autor_id)
        self.ticket_dict = dict(ticket_dict)
        self.modo = modo_norm
        self.qtd_jog = qtd_jog
        self.nomes_jogadores = list(nomes_jogadores or [])
        self.rotulo_diario = rotulo_diario

        self.campos_kills: list[discord.ui.TextInput] = []
        for idx in range(1, qtd_jog + 1):
            nick = self.nomes_jogadores[idx - 1].strip() if idx - 1 < len(self.nomes_jogadores) else ""
            if qtd_jog == 1:
                lbl = (f"Kills do Jogador ({nick})" if nick else "Kills do Jogador")[:45]
            else:
                lbl = (f"Kills — Jogador {idx} ({nick})" if nick else f"Kills — Jogador {idx}")[:45]
            val_padrao = (
                str(kills_preenchidas[idx - 1])
                if (kills_preenchidas and idx - 1 < len(kills_preenchidas))
                else ("0" if qtd_jog > 1 else "")
            )
            campo_k = discord.ui.TextInput(
                label=lbl,
                placeholder="Quantidade de kills (ex: 3)" if qtd_jog == 1 else f"Kills feitas pelo Jogador {idx} (ex: 0, 2, 5)",
                default=val_padrao,
                min_length=1,
                max_length=4,
                required=True,
            )
            self.campos_kills.append(campo_k)
            self.add_item(campo_k)

        self.campo_valor_kill = discord.ui.TextInput(
            label="Premiação por Kill em R$",
            placeholder="Ex: 1,50 ou 2,00",
            default=valor_kill_sugerido or "",
            min_length=1,
            max_length=12,
            required=True,
        )
        self.add_item(self.campo_valor_kill)

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.guild or not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Exclusivo Dono & Gerente", "Apenas Dono ou Gerente podem creditar premiação.", "Vermelho"),
                ephemeral=True,
            )

        bruto_val = (self.campo_valor_kill.value or "").upper().replace("R$", "").strip().replace(",", ".")
        try:
            valor_kill = arredondar(float(bruto_val))
        except Exception:
            valor_kill = -1.0
        if not math.isfinite(valor_kill) or valor_kill <= 0 or valor_kill > 5000:
            return await interaction.response.send_message(
                embed=criar_embed("⚠️ Valor por Kill Inválido", "Informe um valor maior que zero para cada kill (ex.: `1,00`, `1,50`, `2,00`).", "Amarelo"),
                ephemeral=True,
            )

        itens = []
        kills_lista = []
        for idx, campo in enumerate(self.campos_kills, start=1):
            txt_k = (campo.value or "").strip()
            if txt_k == "":
                txt_k = "0"
            if not txt_k.isdigit():
                return await interaction.response.send_message(
                    embed=criar_embed("⚠️ Quantidade de Kills Inválida", f"No **Jogador {idx}**, digite apenas números inteiros (`0`, `1`, `2`...).", "Amarelo"),
                    ephemeral=True,
                )
            k_int = int(txt_k)
            if k_int < 0 or k_int > 99:
                return await interaction.response.send_message(
                    embed=criar_embed("⚠️ Quantidade Fora do Limite", f"Revise as kills do **Jogador {idx}** (`0` a `99`).", "Amarelo"),
                    ephemeral=True,
                )
            nick = self.nomes_jogadores[idx - 1].strip() if idx - 1 < len(self.nomes_jogadores) else ""
            kills_lista.append(k_int)
            itens.append({
                "pos": idx,
                "nome": nick,
                "kills": k_int,
                "subtotal": arredondar(k_int * valor_kill),
            })

        soma_kills = sum(kills_lista)
        if soma_kills <= 0:
            return await interaction.response.send_message(
                embed=criar_embed("⚠️ Zero Kills Informadas", "A soma de kills precisa ser pelo menos **`1`** para gerar premiação.", "Amarelo"),
                ephemeral=True,
            )

        total_pagar = arredondar(soma_kills * valor_kill)
        dados_k = {
            "ticket_id": int(self.ticket_dict["id"]),
            "channel_id": int(self.ticket_dict["channel_id"]),
            "alvo_user_id": int(self.ticket_dict["user_id"]),
            "modo": self.modo,
            "nomes_jogadores": self.nomes_jogadores,
            "kills_lista": kills_lista,
            "itens": itens,
            "soma_kills": soma_kills,
            "valor_kill": valor_kill,
            "valor_kill_str": f"{valor_kill:.2f}".replace(".", ","),
            "total_pagar": total_pagar,
            "rotulo_diario": self.rotulo_diario,
            "ticket_dict": self.ticket_dict,
        }

        await interaction.response.send_message(
            embed=_montar_embed_resumo_kills_etapa1(dados_k),
            view=ConfirmarCreditarKillsEtapa1View(self.autor_id, dados_k),
            ephemeral=True,
        )


class ConfirmarCreditarKillsEtapa1View(discord.ui.View):
    """1ª Confirmação: mostra o cálculo completo de cada jogador + total e pergunta 'Foi isso mesmo?'."""

    def __init__(self, autor_id: int, dados_k: dict):
        super().__init__(timeout=300)
        self.autor_id = int(autor_id)
        self.dados_k = dict(dados_k)
        sel = discord.ui.Select(
            placeholder="🧐 1ª Confirmação: foi isso mesmo?",
            options=[
                discord.SelectOption(
                    label=f"Sim, foi isso mesmo! ({formatar_moeda(self.dados_k['total_pagar'])})"[:100],
                    value="confirmar_1",
                    emoji="✅",
                    description="Avança para a 2ª confirmação antes de aplicar as moedas",
                ),
                discord.SelectOption(
                    label="Corrigir Kills ou Valor por Kill",
                    value="corrigir",
                    emoji="✏️",
                    description="Reabre a janela preenchida para ajustar algum número",
                ),
                discord.SelectOption(
                    label="Trocar Modo (Solo / Duo / Trio / Squad)",
                    value="trocar_modo",
                    emoji="🔄",
                    description="Altera a quantidade de jogadores do cálculo",
                ),
                discord.SelectOption(
                    label="Cancelar",
                    value="cancelar",
                    emoji="❌",
                    description="Cancela sem aplicar nenhuma moeda",
                ),
            ],
        )
        sel.callback = self._decidir_etapa1
        self.add_item(sel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.autor_id or not await e_dono_ou_gerente(interaction.user):
            await interaction.response.send_message(
                embed=criar_embed("🔒 Restrito", "Apenas quem iniciou este lançamento pode confirmar.", "Vermelho"),
                ephemeral=True,
            )
            return False
        return True

    async def _decidir_etapa1(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        if acao == "cancelar":
            return await interaction.response.edit_message(
                embed=criar_embed("❌ Operação Cancelada", "Nenhuma moeda foi creditada.", "Cinza Escuro"),
                view=None,
            )
        if acao == "corrigir":
            return await interaction.response.send_modal(
                CreditarKillsModal(
                    autor_id=self.autor_id,
                    ticket_dict=self.dados_k["ticket_dict"],
                    modo=self.dados_k["modo"],
                    nomes_jogadores=self.dados_k["nomes_jogadores"],
                    valor_kill_sugerido=self.dados_k["valor_kill_str"],
                    rotulo_diario=self.dados_k["rotulo_diario"],
                    kills_preenchidas=self.dados_k["kills_lista"],
                )
            )
        if acao == "trocar_modo":
            return await interaction.response.edit_message(
                embed=criar_embed(
                    "🎮 Trocar Modo do Cálculo",
                    "Selecione abaixo se a partida foi **Solo, Duo, Trio ou Squad**:",
                    "Cinza Escuro",
                ),
                view=EscolherModoCreditarKillsView(
                    autor_id=self.autor_id,
                    ticket_dict=self.dados_k["ticket_dict"],
                    nomes_atuais=self.dados_k["nomes_jogadores"],
                    valor_kill_sug=self.dados_k["valor_kill_str"],
                    rotulo_diario=self.dados_k["rotulo_diario"],
                ),
            )
        if acao == "confirmar_1":
            return await interaction.response.edit_message(
                embed=_montar_embed_resumo_kills_etapa2(self.dados_k),
                view=ConfirmarCreditarKillsEtapa2View(self.autor_id, self.dados_k),
            )


class ConfirmarCreditarKillsEtapa2View(discord.ui.View):
    """2ª Confirmação Final: pergunta se quer realmente aplicar essas moedas na conta agora."""

    def __init__(self, autor_id: int, dados_k: dict):
        super().__init__(timeout=300)
        self.autor_id = int(autor_id)
        self.dados_k = dict(dados_k)
        sel = discord.ui.Select(
            placeholder="⚠️ 2ª Confirmação: aplicar estas moedas na conta agora?",
            options=[
                discord.SelectOption(
                    label=f"SIM, APLICAR {formatar_moeda(self.dados_k['total_pagar'])} EM MOEDAS AGORA"[:100],
                    value="aplicar",
                    emoji="🪙",
                    description="Credita o valor na carteira do jogador e envia o comprovante",
                ),
                discord.SelectOption(
                    label="Voltar para Revisar Detalhes (1ª Confirmação)",
                    value="voltar",
                    emoji="↩️",
                    description="Retorna à tela com as kills de cada jogador",
                ),
                discord.SelectOption(
                    label="Cancelar (Não aplicar moedas)",
                    value="cancelar",
                    emoji="❌",
                    description="Aborta sem creditar nada",
                ),
            ],
        )
        sel.callback = self._decidir_etapa2
        self.add_item(sel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.autor_id or not await e_dono_ou_gerente(interaction.user):
            await interaction.response.send_message(
                embed=criar_embed("🔒 Restrito", "Apenas quem iniciou este lançamento pode confirmar.", "Vermelho"),
                ephemeral=True,
            )
            return False
        return True

    async def _decidir_etapa2(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        if acao == "cancelar":
            return await interaction.response.edit_message(
                embed=criar_embed("❌ Operação Cancelada", "Nenhuma moeda foi aplicada na conta.", "Cinza Escuro"),
                view=None,
            )
        if acao == "voltar":
            return await interaction.response.edit_message(
                embed=_montar_embed_resumo_kills_etapa1(self.dados_k),
                view=ConfirmarCreditarKillsEtapa1View(self.autor_id, self.dados_k),
            )
        if acao != "aplicar":
            return

        await interaction.response.defer(ephemeral=True, thinking=True)
        guild = interaction.guild
        if not guild:
            return

        tid = int(self.dados_k["ticket_id"])
        alvo_uid = int(self.dados_k["alvo_user_id"])
        total_pagar = arredondar(self.dados_k["total_pagar"])
        soma_kills = int(self.dados_k["soma_kills"])
        valor_kill = arredondar(self.dados_k["valor_kill"])
        rot_diario = self.dados_k.get("rotulo_diario") or self.dados_k["modo"].capitalize()

        async with _lock_deposito:
            async with aiosqlite.connect(DATABASE_FILE) as db:
                cur = await db.execute(
                    "UPDATE tickets SET premiacao_creditada = 1 WHERE id = ? AND COALESCE(premiacao_creditada, 0) = 0",
                    (tid,),
                )
                await db.commit()
                if cur.rowcount != 1:
                    return await interaction.edit_original_response(
                        embed=criar_embed(
                            "⚠️ Já Aplicado",
                            "A premiação deste ticket já havia sido creditada anteriormente.",
                            "Amarelo",
                        ),
                        view=None,
                    )

            desc_extrato = f"Premiação de Kills ({soma_kills}x {formatar_moeda(valor_kill)}) • {rot_diario}"
            novo_saldo = await creditar_saldo(
                alvo_uid,
                guild.id,
                total_pagar,
                "premiacao_kills",
                desc_extrato,
                ref=f"kills-tk:{tid}",
            )

        marcar_sujo()

        escala = len(self.dados_k["itens"])
        linhas_det = []
        for it in self.dados_k["itens"]:
            nick = f" (`{it['nome']}`)" if it.get("nome") else ""
            rot_j = f"Jogador{nick}" if escala == 1 else f"Jogador {it['pos']}{nick}"
            linhas_det.append(f"• **{rot_j}:** `{it['kills']}` kill(s) ➜ `{formatar_moeda(it['subtotal'])}`")
        resumo_jogs = "\n".join(linhas_det)

        canal_tk = guild.get_channel(int(self.dados_k["channel_id"])) or interaction.channel
        emb_publico = criar_embed(
            "🪙 Premiação de Kills Creditada na Carteira!",
            f"Parabéns, {mencao(alvo_uid)}! Sua premiação foi conferida e aplicada pela gerência ({interaction.user.mention}):\n\n"
            f"{resumo_jogs}\n\n"
            f"• **Total de Kills:** `{soma_kills}` kill(s) × `{formatar_moeda(valor_kill)}`\n"
            f"• 💰 **Creditado em Moedas:** **`{formatar_moeda(total_pagar)}`**\n"
            f"• 💳 **Novo Saldo na Carteira:** `{formatar_moeda(novo_saldo)}`\n\n"
            f"-# Você pode usar seu saldo nos próximos diários ou solicitar saque em `/carteira`!",
            "Esmeralda",
        )
        if canal_tk and hasattr(canal_tk, "send"):
            try:
                await canal_tk.send(content=mencao(alvo_uid), embed=emb_publico)
            except Exception:
                pass

        await avisar_jogador(
            guild,
            alvo_uid,
            embed=criar_embed(
                "🪙 Premiação Recebida na Carteira!",
                f"Você recebeu **`{formatar_moeda(total_pagar)}`** em moedas referente às suas kills em **{guild.name}**!\n\n"
                f"{resumo_jogs}\n\n"
                f"• **Cálculo:** `{soma_kills}` kill(s) × `{formatar_moeda(valor_kill)}`\n"
                f"• **Novo saldo:** `{formatar_moeda(novo_saldo)}`",
                "Esmeralda",
            ),
        )

        await registrar_log(
            guild,
            "🏆 PREMIAÇÃO KILLS",
            "🪙 Premiação de kills creditada no ticket",
            f"• **Recebedor:** {mencao(alvo_uid)} (Ticket `#{tid}`)\n"
            f"• **Aprovado por:** {interaction.user.mention}\n"
            f"• **Referência:** {rot_diario}\n"
            f"• **Cálculo:** `{soma_kills}` kill(s) × `{formatar_moeda(valor_kill)}` = **`{formatar_moeda(total_pagar)}`**\n"
            f"{resumo_jogs}\n"
            f"• **Saldo após crédito:** `{formatar_moeda(novo_saldo)}`",
            "Esmeralda",
        )

        await interaction.edit_original_response(
            embed=criar_embed(
                "✅ Moedas Aplicadas com Sucesso!",
                f"**`{formatar_moeda(total_pagar)}`** creditados na carteira de {mencao(alvo_uid)}!\n"
                f"• **Novo saldo dele:** `{formatar_moeda(novo_saldo)}`\n"
                f"-# Quando terminar o atendimento, basta usar **🔒 Fechar Atendimento** no seletor do canal.",
                "Esmeralda",
            ),
            view=None,
        )


async def _iniciar_fluxo_creditar_kills_ticket(interaction: discord.Interaction, ticket_dict: dict):
    """Abre direto o Modal se o ticket já tem modo do diário vinculado, ou pergunta Solo/Duo/Trio/Squad."""
    modo_vinc, nomes_vinc, sug_kill, rotulo_d = await _obter_contexto_diario_ticket(ticket_dict)
    if modo_vinc in ("solo", "duo", "trio", "squad"):
        return await interaction.response.send_modal(
            CreditarKillsModal(
                autor_id=interaction.user.id,
                ticket_dict=ticket_dict,
                modo=modo_vinc,
                nomes_jogadores=nomes_vinc,
                valor_kill_sugerido=sug_kill,
                rotulo_diario=rotulo_d,
            )
        )
    await interaction.response.send_message(
        embed=criar_embed(
            "🪙 Creditar Premiação de Kills",
            f"Selecione abaixo o **modo da partida** de {mencao(ticket_dict['user_id'])} para informar as kills e o valor por kill:",
            "Dourado",
        ),
        view=EscolherModoCreditarKillsView(
            autor_id=interaction.user.id,
            ticket_dict=ticket_dict,
        ),
        ephemeral=True,
    )


class TicketView(discord.ui.View):
    """Painel minimalista de atendimento (Select único moderno, persistente após restart)."""

    def __init__(self, ticket_id: int = 0):
        super().__init__(timeout=None)
        self.ticket_id = int(ticket_id or 0)
        sel = discord.ui.Select(
            custom_id=f"ff_tk_sel:{self.ticket_id}",
            placeholder="⚙️ Gerenciar este atendimento...",
            options=[
                discord.SelectOption(
                    label="Assumir Atendimento",
                    value="assumir",
                    emoji="🙋",
                    description="Atendente da fila assume este canal",
                ),
                discord.SelectOption(
                    label="Reassumir / Trocar Atendente",
                    value="reassumir",
                    emoji="🔄",
                    description="Assume se o atendente saiu de serviço (ou gerência troca)",
                ),
                discord.SelectOption(
                    label="Creditar Premiação de Kills (Moedas)",
                    value="creditar_kills",
                    emoji="🪙",
                    description="Dono/Gerente: calcula kills (Solo a Squad) c/ dupla confirmação",
                ),
                discord.SelectOption(
                    label="Adicionar Pessoa",
                    value="add",
                    emoji="➕",
                    description="Adiciona outro membro a este canal",
                ),
                discord.SelectOption(
                    label="Remover Pessoa",
                    value="rem",
                    emoji="➖",
                    description="Remove um membro adicionado ao canal",
                ),
                discord.SelectOption(
                    label="Renomear Canal",
                    value="ren",
                    emoji="✏️",
                    description="Altera o nome deste canal privado",
                ),
                discord.SelectOption(
                    label="Fechar Atendimento",
                    value="fechar",
                    emoji="🔒",
                    description="Encerra o atendimento e avalia de 0 a 5 estrelas",
                ),
            ],
        )
        sel.callback = self._rotear
        self.add_item(sel)

    async def _ticket(self, channel_id: int):
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            return await (await db.execute(
                "SELECT * FROM tickets WHERE channel_id = ? ORDER BY id DESC LIMIT 1", (channel_id,)
            )).fetchone()

    async def _rotear(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        try:
            await interaction.message.edit(view=TicketView(self.ticket_id))
        except Exception:
            pass

        if acao in ("assumir", "reassumir"):
            ticket = await self._ticket(interaction.channel.id)
            if not ticket:
                return await interaction.response.send_message(
                    embed=criar_embed("❌ Atendimento não encontrado", "Abra um novo pelo painel.", "Vermelho"), ephemeral=True
                )
            if not await atendente_autorizado(fila_normalizada(ticket["tipo"]), interaction.user):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Sem Permissão", "Apenas a equipe desta fila (ou gerência) pode assumir.", "Vermelho"),
                    ephemeral=True,
                )
            if not await aviso_fora_de_servico(interaction):
                return
            antigo_at = ticket["assumido_por"]
            trocou_at = False
            if antigo_at and antigo_at != interaction.user.id:
                if acao != "reassumir":
                    return await interaction.response.send_message(
                        embed=criar_embed(
                            "🙋 Já assumido",
                            f"Este atendimento já está com {mencao(antigo_at)}.\n"
                            f"-# Se ele saiu de serviço (ou se você for Gerente/Dono), use **🔄 Reassumir / Trocar Atendente**.",
                            "Amarelo",
                        ),
                        ephemeral=True,
                    )
                pode_re, motivo_re = await pode_reassumir_atendimento(interaction.guild, interaction.user, antigo_at)
                if not pode_re:
                    return await interaction.response.send_message(
                        embed=criar_embed("🔒 Atendente ainda em serviço", motivo_re, "Amarelo"),
                        ephemeral=True,
                    )
                trocou_at = True

            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute(
                    "UPDATE tickets SET assumido_por = ?, assumido_em = ? WHERE id = ?",
                    (interaction.user.id, agora_brt().isoformat(), ticket["id"]),
                )
                await db.commit()
            marcar_sujo()

            if trocou_at:
                try:
                    await interaction.channel.set_permissions(interaction.user, view_channel=True, send_messages=True, read_message_history=True)
                except Exception:
                    pass

            cfg = await obter_config(interaction.guild.id)
            for chave in cargos_da_fila(fila_normalizada(ticket["tipo"])):
                if chave in ("cargo_dono", "cargo_gerente"):
                    continue
                cargo = interaction.guild.get_role(cfg.get(chave)) if cfg.get(chave) else None
                if cargo:
                    try:
                        await interaction.channel.set_permissions(cargo, overwrite=None)
                    except Exception:
                        pass

            embed = criar_embed(
                "🔄 Atendimento Reassumido" if trocou_at else "🙋 Atendimento Assumido",
                (f"Atendimento transferido de {mencao(antigo_at)} para {interaction.user.mention}.\n" if trocou_at else f"{interaction.user.mention} assumiu este atendimento.\n")
                + f"• Ao concluir, {mencao(ticket['user_id'])} encerra no seletor acima e avalia o atendimento.",
                "Esmeralda",
            )
            await interaction.response.send_message(content=mencao(ticket["user_id"]), embed=embed)
            return await registrar_log_suporte(
                interaction.guild, "🎫 TICKET",
                "🔄 Atendimento reassumido" if trocou_at else "🙋 Atendimento assumido",
                f"{mencao(interaction.user.id)} {'reassumiu' if trocou_at else 'assumiu'} o protocolo `#{ticket['id']}` "
                f"(fila `{ticket['tipo']}`) de {mencao(ticket['user_id'])}.", "Verde",
            )

        if acao == "creditar_kills":
            if not await e_dono_ou_gerente(interaction.user):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Exclusivo Dono & Gerente", "Somente Dono ou Gerente podem creditar premiação de kills.", "Vermelho"),
                    ephemeral=True,
                )
            ticket = await self._ticket(interaction.channel.id)
            if not ticket:
                return await interaction.response.send_message(
                    embed=criar_embed("❌ Atendimento não encontrado", "Este canal não possui registro de ticket ativo.", "Vermelho"),
                    ephemeral=True,
                )
            tk_d = dict(ticket)
            if int(tk_d.get("premiacao_creditada") or 0) == 1:
                return await interaction.response.send_message(
                    embed=criar_embed(
                        "⚠️ Premiação Já Creditada",
                        "Este ticket já teve uma premiação de kills aplicada na carteira para evitar pagamento duplicado.",
                        "Amarelo",
                    ),
                    ephemeral=True,
                )
            return await _iniciar_fluxo_creditar_kills_ticket(interaction, tk_d)

        if acao == "add":
            if not await self._pode_gerenciar(interaction):
                return
            return await interaction.response.send_message(
                embed=criar_embed("➕ Adicionar Pessoa", "Selecione abaixo quem deve entrar no canal:", "Cinza Escuro"),
                view=TicketAddView(),
                ephemeral=True,
            )

        if acao == "rem":
            if not await self._pode_gerenciar(interaction):
                return
            return await interaction.response.send_message(
                embed=criar_embed("➖ Remover Pessoa", "Selecione abaixo quem deve sair do canal:", "Cinza Escuro"),
                view=TicketRemView(),
                ephemeral=True,
            )

        if acao == "ren":
            if not await self._pode_gerenciar(interaction):
                return
            return await interaction.response.send_modal(TicketRenomearModal())

        if acao == "fechar":
            ticket = await self._ticket(interaction.channel.id)
            eh_vip = await e_gerencia(interaction.user)
            if not ticket:
                if eh_vip:
                    await interaction.response.send_message("🔒 Encerrando canal...", ephemeral=True)
                    await _apagar_canal_seguro(interaction.channel, "Canal órfão encerrado")
                    return
                return await interaction.response.send_message(
                    embed=criar_embed("❌ Atendimento não encontrado", "", "Vermelho"), ephemeral=True
                )
            eh_cliente = interaction.user.id == ticket["user_id"]
            if not eh_cliente and not eh_vip:
                return await interaction.response.send_message(
                    embed=criar_embed(
                        "🔒 Encerramento pelo Cliente",
                        f"Quem fecha o atendimento é {mencao(ticket['user_id'])} (ou Dono/Gerente) para registrar a avaliação.",
                        "Amarelo",
                    ),
                    ephemeral=True,
                )
            if not ticket["assumido_por"] or (eh_vip and not eh_cliente):
                await interaction.response.defer(ephemeral=True)
                motivo_fecho = "encerrado antes de assumir" if not ticket["assumido_por"] else f"encerrado pela gerência ({interaction.user.display_name})"
                fechou = await _fechar_ticket_sem_nota(interaction.guild, ticket, interaction.user.id, motivo_fecho)
                return await interaction.followup.send(
                    embed=criar_embed(
                        "🔒 Atendimento Encerrado" if fechou else "ℹ️ Já finalizado",
                        "Canal encerrado com sucesso." if fechou else "Este atendimento já havia sido encerrado.",
                        "Cinza Escuro",
                    ),
                    ephemeral=True,
                )
            return await interaction.response.send_message(
                embed=criar_embed(
                    "⭐ Avalie o Atendimento",
                    f"Antes de encerrar, escolha uma nota para {mencao(ticket['assumido_por'])} *(descrição opcional)*:",
                    "Dourado",
                ),
                view=TicketNotaView(ticket["id"], ticket["assumido_por"]),
                ephemeral=True,
            )

    async def _pode_gerenciar(self, interaction) -> bool:
        ticket = await self._ticket(interaction.channel.id)
        if not ticket:
            return False
        if interaction.user.id == ticket["assumido_por"] or await e_gerencia(interaction.user):
            return True
        await interaction.response.send_message(
            embed=criar_embed("🔒 Só quem assumiu", "Assuma o atendimento (ou seja gerência) para usar esta opção.", "Vermelho"),
            ephemeral=True,
        )
        return False


class TicketNotaView(discord.ui.View):
    """0 a 5 estrelas, com meia estrela — é isso que paga o atendente."""

    def __init__(self, ticket_id: int, atendente_id: int):
        super().__init__(timeout=300)
        self.ticket_id = ticket_id
        self.atendente_id = atendente_id
        opcoes = [0.0, 0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0]
        self.selecionar.options = [
            discord.SelectOption(
                label=("0 (sem estrela)" if n == 0 else f"{_emoji_nota(n)}  ({n:g} estrela{'s' if n != 1 else ''})"),
                value=str(n), description=("Nota zero — o atendente não recebe nada" if n == 0
                                           else f"Vale {formatar_moeda(NOTA_VALORES_PADRAO[n])} para o atendente"))
            for n in opcoes
        ]

    @discord.ui.select(placeholder="Escolha a nota do atendimento (0 a 5 estrelas)...", min_values=1, max_values=1)
    async def selecionar(self, interaction: discord.Interaction, select: discord.ui.Select):
        nota = float(select.values[0])
        await interaction.response.send_modal(TicketNotaDescModal(self.ticket_id, self.atendente_id, nota))


class TicketNotaDescModal(discord.ui.Modal, title="⭐ Finalizar atendimento"):
    descricao = discord.ui.TextInput(label="Descrição (opcional)", style=discord.TextStyle.paragraph,
                                     required=False, max_length=500,
                                     placeholder="Conte como foi o atendimento (opcional)")

    def __init__(self, ticket_id: int, atendente_id: int, nota: float):
        super().__init__()
        self.ticket_id = ticket_id
        self.atendente_id = atendente_id
        self.nota = nota

    async def on_submit(self, interaction: discord.Interaction):
        await finalizar_ticket(interaction, self.ticket_id, self.atendente_id, self.nota, self.descricao.value)


async def finalizar_ticket(interaction, ticket_id: int, atendente_id: int, nota: float, descricao: str):
    valores = await nota_valores(interaction.guild.id)
    membro_atendente = await membro_do_guild(interaction.guild, atendente_id)
    atendente_tem_carteira = bool(membro_atendente and await tem_carteira_trabalho(membro_atendente))
    valor = arredondar(valores.get(nota, 0.0)) if atendente_tem_carteira else 0.0
    descricao = (descricao or "").strip()

    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        ticket = await (await db.execute("SELECT * FROM tickets WHERE id = ?", (ticket_id,))).fetchone()
        if not ticket or ticket["status"] != "aberto":
            return await interaction.response.send_message(
                embed=criar_embed("ℹ️ Já finalizado", "Este atendimento já foi fechado.", "Amarelo"), ephemeral=True)
        await db.execute(
            "UPDATE tickets SET status = 'fechado', nota = ?, nota_desc = ?, pago_nota = ?, "
            "fechado_em = ?, fechado_por = ? WHERE id = ?",
            (nota, descricao, valor, agora_brt().isoformat(), interaction.user.id, ticket_id))
        await db.commit()
        await db.execute(
            "INSERT INTO avaliacoes (guild_id, ticket_id, avaliador_id, atendente_id, nota, descricao, valor_pago, criado_em) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (interaction.guild.id, ticket_id, interaction.user.id, atendente_id, nota, descricao,
             valor, agora_brt().isoformat()))
        await db.commit()
    marcar_sujo()

    if atendente_tem_carteira and valor > 0:
        await creditar_trabalho(atendente_id, interaction.guild.id, valor, "avaliacao",
                                f"Avaliação {_emoji_nota(nota)} do atendimento #{ticket_id}",
                                ref=f"ticket:{ticket_id}")
        await registrar_caixa(interaction.guild.id, "despesa", valor,
                              f"Pagamento de atendimento #{ticket_id} (nota {nota:g})", ref=f"ticket:{ticket_id}")

    saldo_atendente = await saldo_trabalho(atendente_id, interaction.guild.id) if atendente_tem_carteira else 0.0
    bloco_carteira_msg = (
        f"> 💰 Valor para o suporte: `{formatar_moeda(valor)}`\n"
        f"> 💼 Carteira de trabalho dele agora: `{formatar_moeda(saldo_atendente)}`\n"
        if atendente_tem_carteira
        else ""
    )
    embed = criar_embed(
        "✅ Atendimento finalizado",
        f"**{mencao(interaction.user.id)}** avaliou com {_emoji_nota(nota)} **({nota:g} estrela{'s' if nota != 1 else ''})**.\n"
        f"{bloco_carteira_msg}"
        + (f"> 📝 *{descricao[:200]}*" if descricao else "> 📝 *(sem descrição)*"),
        "Esmeralda")
    await interaction.response.send_message(embed=embed)

    await registrar_log_suporte(
        interaction.guild, "⭐ AVALIAÇÃO", "⭐ Atendimento avaliado",
        f"Protocolo `#{ticket_id}` — fila `{ticket['tipo']}`\n"
        f"> 👤 Cliente: {mencao(interaction.user.id)}\n"
        f"> 🙋 Atendente: {mencao(atendente_id)}\n"
        f"> ⭐ Nota: **{nota:g}** ({_emoji_nota(nota)})\n"
        + (
            f"> 💰 Pago ao suporte: `{formatar_moeda(valor)}`\n"
            f"> 💼 Saldo de trabalho agora: `{formatar_moeda(saldo_atendente)}`\n"
            if atendente_tem_carteira
            else "> ℹ️ Atendente é ADM (sem carteira de trabalho; recebe direto no PIX nos diários).\n"
        )
        + (f"> 📝 Descrição: {descricao[:300]}" if descricao else "> 📝 Sem descrição"),
        "Dourado")

    if atendente_tem_carteira:
        hoje = agora_brt().strftime('%Y-%m-%d')
        async with aiosqlite.connect(DATABASE_FILE) as db:
            qtd_dia = (await (await db.execute(
                "SELECT COUNT(*) FROM avaliacoes WHERE guild_id=? AND atendente_id=? AND substr(criado_em,1,10)=?",
                (interaction.guild.id, atendente_id, hoje))).fetchone())[0]
        await anunciar_pagamento_equipe(
            interaction.guild, atendente_id, "⭐ Nota de atendimento registrada",
            f"{mencao(atendente_id)} recebeu **{nota:g}/5 {_emoji_nota(nota)}** no ticket `#{ticket_id}`.\n"
            f"> 💵 Ganho deste atendimento: `{formatar_moeda(valor)}`\n"
            f"> 🎫 Tickets avaliados hoje: **{qtd_dia}**\n"
            f"> 💼 Carteira de trabalho agora: `{formatar_moeda(saldo_atendente)}`\n"
            f"> 📊 Nota geral é recalculada no fechamento semanal com todas as avaliações.", "Dourado")

    try:
        await interaction.channel.send(embed=criar_embed(
            "🔒 Atendimento encerrado",
            f"Obrigado pelo contato! Este canal será fechado em {TICKET_FECHAR_SEGUNDOS} segundos.", "Cinza Escuro"))
    except Exception:
        pass
    await asyncio.sleep(TICKET_FECHAR_SEGUNDOS)
    ok_del = await _apagar_canal_seguro(
        interaction.channel,
        f"Ticket #{ticket_id} encerrado após avaliação ({nota:g}/5)",
    )
    if ok_del:
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            await db.execute("DELETE FROM tickets WHERE id = ? AND status = 'fechado'", (ticket_id,))
            await db.commit()
        marcar_sujo()


async def _fechar_ticket_sem_nota(guild, ticket, actor_id: int, motivo: str) -> bool:
    """Fecha apenas um ticket regular (tabela tickets); status primeiro, canal/log depois, e remove linha encerrada."""
    ticket_id = int(ticket["id"])
    async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
        cur = await db.execute(
            "UPDATE tickets SET status='fechado', fechado_em=?, fechado_por=? "
            "WHERE id=? AND guild_id=? AND status='aberto'",
            (agora_brt().isoformat(), int(actor_id), ticket_id, guild.id))
        await db.commit()
        if cur.rowcount != 1:
            return False
    marcar_sujo()
    apagou_canal = False
    try:
        canal = await _buscar_canal_guild(guild, ticket["channel_id"])
        if canal:
            try:
                await canal.send(embed=criar_embed(
                    "🔒 Atendimento encerrado",
                    f"Este atendimento foi encerrado. Motivo: {motivo[:120]}.", "Cinza Escuro"))
            except (discord.Forbidden, discord.HTTPException) as erro:
                _log_arquivo(f"[TICKET] aviso de fechamento #{ticket_id} falhou: {erro}")
            ok_del = await _apagar_canal_seguro(canal, f"Atendimento #{ticket_id} fechado: {motivo[:200]}")
            if ok_del:
                apagou_canal = True
            else:
                _log_arquivo(f"[TICKET] canal do ticket fechado #{ticket_id} será reconciliado no próximo boot")
        else:
            apagou_canal = True
    except (discord.Forbidden, discord.HTTPException) as erro:
        _log_arquivo(f"[TICKET] canal #{ticket_id} indisponível após fechar: {erro}")
    if apagou_canal:
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            await db.execute("DELETE FROM tickets WHERE id = ? AND status = 'fechado'", (ticket_id,))
            await db.commit()
        marcar_sujo()
    _log_arquivo(f"[TICKET] fechado sem avaliação id={ticket_id} guild={guild.id} por={actor_id}: {motivo[:150]}")
    return True


@bot.tree.command(name="meu_ticket_fechar", description="🔒 Fechar seu atendimento aberto neste canal")
@app_commands.guild_only()
async def cmd_meu_ticket_fechar(interaction: discord.Interaction):
    """Atalho para o solicitante (ou Dono/Gerente) encerrar o canal de atendimento atual."""
    if not interaction.guild or not interaction.channel:
        return await _responder_erro_interacao(
            interaction, criar_embed("⚠️ Use dentro do servidor", "Este comando funciona no canal do atendimento.", "Amarelo"))
    eh_vip = await e_dono_ou_gerente(interaction.user)
    async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
        db.row_factory = aiosqlite.Row
        ticket = await (await db.execute(
            "SELECT * FROM tickets WHERE guild_id=? AND channel_id=? AND status='aberto' ORDER BY id DESC LIMIT 1",
            (interaction.guild.id, interaction.channel.id))).fetchone()
        parceria = None
        divulgacao = None
        if not ticket:
            parceria = await (await db.execute(
                "SELECT * FROM parceiros WHERE guild_id=? AND canal_ticket_id=? ORDER BY id DESC LIMIT 1",
                (interaction.guild.id, interaction.channel.id))).fetchone()
        if not ticket and not parceria:
            divulgacao = await (await db.execute(
                "SELECT * FROM divulgacoes WHERE guild_id=? AND canal_ticket_id=? ORDER BY id DESC LIMIT 1",
                (interaction.guild.id, interaction.channel.id))).fetchone()

    if parceria:
        if not eh_vip and int(parceria["solicitante_id"] or 0) != int(interaction.user.id):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Sem Permissão", "Apenas o solicitante, Dono ou Gerente podem encerrar este canal.", "Vermelho"),
                ephemeral=True,
            )
        await interaction.response.defer(ephemeral=True)
        if parceria["status"] == "pendente":
            async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
                await db.execute("UPDATE parceiros SET status='cancelada' WHERE id=?", (parceria["id"],))
                await db.commit()
            marcar_sujo()
        await interaction.followup.send(
            embed=criar_embed("🔒 Encerrando Canal", "Canal de parceria encerrado.", "Cinza Escuro"), ephemeral=True
        )
        await asyncio.sleep(1)
        await _apagar_canal_seguro(interaction.channel, "Canal de parceria encerrado via comando")
        return

    if divulgacao:
        if not eh_vip and int(divulgacao["solicitante_id"] or 0) != int(interaction.user.id):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Sem Permissão", "Apenas o contratante, Dono ou Gerente podem encerrar este canal.", "Vermelho"),
                ephemeral=True,
            )
        await interaction.response.defer(ephemeral=True)
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            await db.execute("UPDATE divulgacoes SET status='fechada', fechado_em=? WHERE id=?", (agora_brt().isoformat(), divulgacao["id"]))
            await db.commit()
        marcar_sujo()
        await interaction.followup.send(
            embed=criar_embed("🔒 Encerrando Canal", "Canal de divulgação encerrado.", "Cinza Escuro"), ephemeral=True
        )
        await asyncio.sleep(1)
        await _apagar_canal_seguro(interaction.channel, "Canal de divulgação encerrado via comando")
        return

    if not ticket:
        return await interaction.response.send_message(
            embed=criar_embed("ℹ️ Atendimento não encontrado", "Este canal não possui atendimento aberto.", "Cinza Escuro"),
            ephemeral=True)
    if int(ticket["user_id"] or 0) != int(interaction.user.id) and not eh_vip:
        return await interaction.response.send_message(
            embed=criar_embed("🔒 Só o solicitante fecha", "Você só pode fechar o atendimento que abriu.", "Vermelho"),
            ephemeral=True)
    if ticket["assumido_por"] and int(ticket["user_id"] or 0) == int(interaction.user.id):
        return await interaction.response.send_message(
            embed=criar_embed("⭐ Avalie o Atendimento", "Escolha a nota para finalizar este atendimento.", "Dourado"),
            view=TicketNotaView(ticket["id"], ticket["assumido_por"]), ephemeral=True)
    fechou = await _fechar_ticket_sem_nota(interaction.guild, ticket, interaction.user.id,
                                           "fechado pelo comando /meu_ticket_fechar")
    await interaction.response.send_message(
        embed=criar_embed("✅ Atendimento fechado" if fechou else "ℹ️ Já finalizado",
                          "Seu canal foi encerrado; o histórico financeiro e demais tickets não foram alterados." if fechou
                          else "O ticket já foi fechado por outra ação.", "Esmeralda" if fechou else "Amarelo"),
        ephemeral=True)


@bot.tree.command(name="tickets_fechar", description="🧹 Dono: fechar tickets regulares por filtro")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
@app_commands.describe(
    escopo="Escolha quais atendimentos regulares fechar",
    categoria="Usado quando o escopo for por categoria",
    usuario="Usado quando o escopo for por usuário",
    ticket_id="ID do protocolo, usado no escopo ticket específico",
    confirmar="Marque Sim somente depois de conferir a prévia")
@app_commands.choices(
    escopo=[
        app_commands.Choice(name="Todos os atendimentos regulares", value="todos"),
        app_commands.Choice(name="Uma categoria", value="categoria"),
        app_commands.Choice(name="De um usuário", value="usuario"),
        app_commands.Choice(name="Um protocolo específico", value="ticket"),
    ],
    categoria=[
        app_commands.Choice(name="Suporte geral", value="suporte"),
        app_commands.Choice(name="Dúvida de pagamento", value="duvida_pagamento"),
        app_commands.Choice(name="Receber premiação (kills)", value="receber_premiacao"),
    ])
async def cmd_tickets_fechar(
    interaction: discord.Interaction,
    escopo: app_commands.Choice[str],
    categoria: Optional[app_commands.Choice[str]] = None,
    usuario: Optional[discord.Member] = None,
    ticket_id: Optional[int] = None,
    confirmar: bool = False,
):
    """Prévia + confirmação; afeta só a tabela tickets, nunca depósitos/saques."""
    if not interaction.guild:
        return await interaction.response.send_message("Use este comando no servidor.", ephemeral=True)
    if not await e_dono_do_servidor(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("🔒 Só o dono", "Somente o dono do servidor ou o cargo Dono configurado pode usar isso.", "Vermelho"),
            ephemeral=True)

    modo = escopo.value
    if modo == "categoria" and not categoria:
        return await interaction.response.send_message("Escolha a categoria do ticket.", ephemeral=True)
    if modo == "usuario" and not usuario:
        return await interaction.response.send_message("Escolha o usuário.", ephemeral=True)
    if modo == "ticket" and not ticket_id:
        return await interaction.response.send_message("Informe o ID do protocolo.", ephemeral=True)

    sql = "SELECT * FROM tickets WHERE guild_id=? AND status='aberto'"
    args = [interaction.guild.id]
    if modo == "categoria":
        sql += " AND COALESCE(categoria,'suporte')=?"
        args.append(categoria.value)
    elif modo == "usuario":
        sql += " AND user_id=?"
        args.append(usuario.id)
    elif modo == "ticket":
        sql += " AND id=?"
        args.append(int(ticket_id))
    sql += " ORDER BY id"
    async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
        db.row_factory = aiosqlite.Row
        rows = await (await db.execute(sql, tuple(args))).fetchall()
    if not rows:
        return await interaction.response.send_message(
            embed=criar_embed("✅ Nenhum ticket aberto", "Não encontrei tickets regulares correspondentes. Depósitos e saques não foram consultados nem alterados.", "Esmeralda"),
            ephemeral=True)

    if not confirmar:
        linhas = []
        for row in rows[:12]:
            canal = interaction.guild.get_channel(int(row["channel_id"] or 0))
            linhas.append(f"• `#{row['id']}` — {row['categoria'] or 'suporte'} — "
                          f"{mencao(row['user_id'])} — {canal.mention if canal else 'canal ausente'}")
        if len(rows) > 12:
            linhas.append(f"… e mais {len(rows)-12}.")
        return await interaction.response.send_message(
            embed=criar_embed("⚠️ Prévia — nada foi fechado",
                              f"Correspondências: **{len(rows)}**. Para executar, rode novamente com `confirmar: Sim`.\n\n"
                              + "\n".join(linhas)
                              + "\n\nEste comando só mexe em atendimentos da tabela `tickets`; canais de depósito e saque ficam intactos.",
                              "Amarelo"), ephemeral=True)

    await interaction.response.defer(ephemeral=True, thinking=True)
    fechados = 0
    falhas = 0
    for row in rows:
        try:
            if await _fechar_ticket_sem_nota(interaction.guild, row, interaction.user.id,
                                             f"fechamento em lote pelo dono ({modo})"):
                fechados += 1
        except Exception as erro:
            falhas += 1
            _log_arquivo(f"[TICKET] fechamento em lote #{row['id']}: {type(erro).__name__}: {erro}")
    await interaction.followup.send(
        embed=criar_embed("🧹 Limpeza concluída",
                          f"Tickets regulares fechados: **{fechados}**. Falhas: **{falhas}**.\n"
                          "Nenhum depósito, pedido de saque ou saldo foi alterado.",
                          "Esmeralda" if not falhas else "Amarelo"), ephemeral=True)


@bot.tree.command(name="reparar_pendencias", description="🩺 Dono: corrigir tickets órfãos e pendências travadas")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
@app_commands.describe(
    deposito_id="Opcional: ID de um depósito que você confirmou estar realmente abandonado",
    confirmar="Confirma o cancelamento desse ID específico (após revisar a prévia)")
async def cmd_reparar_pendencias(
    interaction: discord.Interaction,
    deposito_id: Optional[int] = None,
    confirmar: bool = False,
):
    """Reconcilia canais ausentes e permite cancelar um depósito por ID com dupla confirmação."""
    if not interaction.guild:
        return await interaction.response.send_message("Use este comando no servidor.", ephemeral=True)
    if not await e_dono_do_servidor(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("🔒 Só o dono", "Somente o dono do servidor ou o cargo Dono configurado pode usar isso.", "Vermelho"),
            ephemeral=True)

    await interaction.response.defer(ephemeral=True, thinking=True)
    tickets = await _reconciliar_ticket_estado(interaction.guild, limpar_fechados=True)
    depositos_orfaos = await _reconciliar_depositos_orfaos(interaction.guild)
    canais_vagas_aprovadas = await _limpar_canais_pag_ja_confirmados(interaction.guild)
    cancelado = False
    detalhe = ""
    if deposito_id is not None:
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            db.row_factory = aiosqlite.Row
            row = await (await db.execute(
                "SELECT id,user_id,valor,status FROM depositos WHERE id=? AND guild_id=?",
                (int(deposito_id), interaction.guild.id))).fetchone()
            if not row:
                detalhe = f"Não encontrei o depósito `#{deposito_id}` neste servidor."
            elif row["status"] == "creditado":
                detalhe = f"O depósito `#{deposito_id}` já foi creditado; não foi alterado."
            elif row["status"] not in ("aguardando", "na_janela"):
                detalhe = f"O depósito `#{deposito_id}` já está como `{row['status']}`; não foi alterado."
            elif not confirmar:
                detalhe = (f"Prévia: `#{row['id']}` — {mencao(row['user_id'])} — "
                           f"{formatar_moeda(row['valor'] or 0)} — status `{row['status']}`.\n"
                           "Nada foi cancelado. Se você conferiu no extrato bancário que não houve pagamento, rode novamente com `confirmar: Sim`.")
            else:
                cur = await db.execute(
                    "UPDATE depositos SET status='cancelado' WHERE id=? AND guild_id=? AND status IN ('aguardando','na_janela')",
                    (int(deposito_id), interaction.guild.id))
                await db.commit()
                cancelado = cur.rowcount == 1
                if cancelado:
                    marcar_sujo()
                    detalhe = f"Depósito `#{deposito_id}` marcado como cancelado; histórico e saldo foram preservados."
                else:
                    detalhe = "O estado mudou durante a operação; atualize a tela e tente novamente."

    async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
        db.row_factory = aiosqlite.Row
        ativos = await (await db.execute(
            "SELECT id,user_id,valor,status FROM depositos WHERE guild_id=? AND status IN ('aguardando','na_janela') ORDER BY id DESC LIMIT 10",
            (interaction.guild.id,))).fetchall()
    resumo = (f"Tickets órfãos fechados: **{tickets['tickets_orfaos']}**. "
              f"Canais de tickets já fechados removidos: **{tickets['canais_fechados_removidos']}**. "
              f"Canais de vagas já aprovadas limpos: **{canais_vagas_aprovadas}**. "
              f"Atendimentos vazios de depósito sem canal cancelados: **{depositos_orfaos}**.")
    if ativos:
        resumo += "\n\nPendências de depósito preservadas (não cancelei automaticamente):\n" + "\n".join(
            f"• `#{r['id']}` — {mencao(r['user_id'])} — {formatar_moeda(r['valor'] or 0)} — `{r['status']}`"
            for r in ativos)
        resumo += "\nConfira cada ID antes de usar `deposito_id` com `confirmar: Sim`; isso impede que um pagamento real seja descartado."
    if detalhe:
        resumo += "\n\n" + detalhe
    await interaction.followup.send(
        embed=criar_embed("🩺 Reconciliação concluída" if not cancelado else "🩺 Estado corrigido",
                          resumo[:4000], "Esmeralda"), ephemeral=True)


async def registrar_log_suporte(guild, tipo: str, titulo: str, descricao: str, cor: str = "Azul"):
    """Log da equipe de atendimento (canal próprio)."""
    limpo = descricao.replace("**", "").replace("> ", "")
    _log_arquivo(f"[{tipo}] {titulo} — {limpo}")
    if not guild:
        return
    try:
        canal_id = await cfgv(guild.id, "canal_logs_suporte", None)
    except Exception:
        canal_id = None
    if not canal_id:
        return
    canal = guild.get_channel(int(canal_id))
    if not canal:
        return
    try:
        await canal.send(embed=criar_embed(titulo, descricao, cor, footer="🔥 Fire Force • atendimento"))
    except Exception:
        pass


