# ---------- DEPÓSITO COMO ATENDIMENTO PRIVADO ----------

async def abrir_atendimento_deposito(interaction: discord.Interaction):
    """Cria o canal privado do depósito: jogador + suporte/gerente/dono (sem mediador)."""
    await _reconciliar_depositos_orfaos(interaction.guild)
    cfg = await obter_config(interaction.guild.id)
    async with aiosqlite.connect(DATABASE_FILE) as db:
        aberto = await (await db.execute(
            "SELECT 1 FROM depositos WHERE guild_id = ? AND user_id = ? AND status IN ('na_janela','aguardando')",
            (interaction.guild.id, interaction.user.id)
        )).fetchone()
    if aberto:
        return await responder_ephemeral(
            interaction,
            embed=criar_embed("⚠️ Você já tem um depósito aberto",
                              "Finalize o depósito atual (ou fale com a equipe) antes de abrir outro. 💛",
                              "Amarelo")
        )

    categoria = interaction.guild.get_channel(cfg.get("cat_tickets")) or interaction.guild.get_channel(cfg.get("cat_pagamentos"))
    overwrites = {
        interaction.guild.default_role: discord.PermissionOverwrite(view_channel=False),
        interaction.user: discord.PermissionOverwrite(view_channel=True, send_messages=True, attach_files=True,
                                                      read_message_history=True),
        interaction.guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True),
    }
    for chave in ("cargo_suporte", "cargo_gerente", "cargo_dono"):     # mediador NÃO vê o depósito
        if cfg.get(chave):
            cargo = interaction.guild.get_role(cfg[chave])
            if cargo:
                overwrites[cargo] = discord.PermissionOverwrite(view_channel=True, send_messages=True,
                                                               manage_messages=True, read_message_history=True)

    canal = None
    try:
        canal = await interaction.guild.create_text_channel(
            f"💰│deposito-{interaction.user.display_name}"[:100], category=categoria, overwrites=overwrites)
        async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
            cursor = await db.execute(
                "INSERT INTO depositos (guild_id, user_id, valor, nome_pagador, apelidos, status, canal_id, "
                "criado_em) VALUES (?, ?, 0, '', ?, 'aguardando', ?, ?)",
                (interaction.guild.id, interaction.user.id, apelidos_do_usuario(interaction.user), canal.id,
                 agora_brt().isoformat()))
            deposito_id = cursor.lastrowid
            await db.commit()
    except Exception as erro:
        if canal:
            try:
                await canal.delete(reason="Rollback: falha ao registrar atendimento de depósito")
            except Exception as erro_delete:
                _log_arquivo(f"[DEPÓSITO] rollback canal={getattr(canal, 'id', 0)} falhou: {erro_delete}")
        _log_arquivo(f"[DEPÓSITO] abertura falhou guild={interaction.guild.id} user={interaction.user.id}: {type(erro).__name__}: {erro}")
        return await _responder_erro_interacao(
            interaction, criar_embed("⚠️ Não consegui abrir o atendimento de depósito",
                                     "O canal ou o registro não foi criado corretamente. Tente novamente em instantes.", "Vermelho"))
    marcar_sujo()

    embed = criar_embed(
        f"💰 Depósito na Carteira #{deposito_id}",
        f"Olá {interaction.user.mention}, este é o seu canal privado de depósito.\n\n"
        f"• **1.** Escolha **Abrir Depósito** no seletor abaixo e informe o valor.\n"
        f"• **2.** Assim que o **Dono** ou **Gerente** assumir, o QR Code e a chave PIX dele serão enviados automaticamente aqui.\n"
        f"• **3.** Envie o comprovante neste canal para o crédito das suas moedas.\n"
        f"-# Canal privado entre solicitante e gestão financeira",
        "Cinza Escuro",
    )
    try:
        await canal.send(content=mencao(interaction.user.id), embed=embed, view=DepositoCanalView(deposito_id))
    except Exception as erro:
        try:
            async with aiosqlite.connect(DATABASE_FILE, timeout=30) as db:
                await db.execute("UPDATE depositos SET status='cancelado' WHERE id=? AND status='aguardando'", (deposito_id,))
                await db.commit()
            await canal.delete(reason="Rollback: falha ao publicar painel inicial do depósito")
        except Exception as erro_rollback:
            _log_arquivo(f"[DEPÓSITO] rollback do atendimento #{deposito_id}: {type(erro_rollback).__name__}: {erro_rollback}")
        marcar_sujo()
        _log_arquivo(f"[DEPÓSITO] painel inicial falhou #{deposito_id}: {type(erro).__name__}: {erro}")
        return await _responder_erro_interacao(
            interaction, criar_embed("⚠️ O canal foi revertido",
                                     "Não consegui publicar o painel. Nenhum atendimento de depósito ficou aberto; tente novamente.", "Vermelho"))
    await responder_ephemeral(
        interaction,
        embed=criar_embed("✅ Atendimento Criado", f"Continue em {canal.mention}", "Cinza Escuro")
    )

    await registrar_log_suporte(
        interaction.guild, "💰 DEPÓSITO", "💰 Atendimento de depósito aberto",
        f"{mencao(interaction.user.id)} abriu um atendimento de depósito.\n"
        f"> 🔖 Protocolo: `#{deposito_id}` • Canal: {canal.mention}", "Azul")


class DepositoComprovanteView(discord.ui.View):
    """Seletor minimalista no comprovante do depósito (persistente após restart)."""

    def __init__(self, deposito_id: int = 0):
        super().__init__(timeout=None)
        self.deposito_id = int(deposito_id) if isinstance(deposito_id, int) else 0
        sel = discord.ui.Select(
            custom_id=f"ff_dep_comp_sel:{self.deposito_id}",
            placeholder="📄 Analisar comprovante de depósito...",
            options=[
                discord.SelectOption(
                    label="Confirmar Comprovante e Creditar",
                    value="ok",
                    emoji="✅",
                    description="Valida o PIX recebido e credita as moedas na carteira",
                ),
                discord.SelectOption(
                    label="Reprovar Comprovante",
                    value="no",
                    emoji="❌",
                    description="Mantém sem crédito e solicita novo comprovante",
                ),
            ],
        )
        sel.callback = self._decidir
        self.add_item(sel)

    async def _autorizar(self, interaction):
        if not await atendente_autorizado("suporte", interaction.user):
            await interaction.response.send_message(
                embed=criar_embed("🔒 Sem Permissão", "Apenas a equipe autorizada pode decidir comprovantes de depósito.", "Vermelho"),
                ephemeral=True,
            )
            return None
        if not await aviso_fora_de_servico(interaction):
            return None
        deposito = await DepositoCanalView()._deposito(interaction.channel.id)
        if (not deposito or int(deposito["id"]) != self.deposito_id
                or deposito["status"] not in ("aguardando", "na_janela")):
            await interaction.response.send_message(
                embed=criar_embed("ℹ️ Depósito resolvido", "Este depósito não está mais pendente ou foi cancelado.", "Cinza Escuro"),
                ephemeral=True,
            )
            return None
        if (not deposito["assumido_por"] or deposito["assumido_por"] != interaction.user.id) and not await e_gerencia(interaction.user):
            await interaction.response.send_message(
                embed=criar_embed("🔒 Só quem assumiu ou gerência", "Apenas quem assumiu este depósito ou Dono/Gerente pode decidir.", "Vermelho"),
                ephemeral=True,
            )
            return None
        return deposito

    async def _decidir(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        try:
            await interaction.message.edit(view=DepositoComprovanteView(self.deposito_id))
        except Exception:
            pass
        deposito = await self._autorizar(interaction)
        if not deposito:
            return
        if acao == "ok":
            await interaction.response.defer(ephemeral=True, thinking=True)
            saldo = await creditar_deposito(interaction.guild, dict(deposito), "comprovante validado manualmente pela equipe")
            try:
                await interaction.message.edit(view=None)
            except Exception:
                pass
            return await interaction.followup.send(
                embed=criar_embed(
                    "✅ Comprovante Aceito",
                    f"Depósito de `{formatar_moeda(deposito['valor'])}` creditado.\n• **Saldo atualizado:** `{formatar_moeda(saldo)}`",
                    "Esmeralda",
                ),
                ephemeral=True,
            )

        try:
            await interaction.message.edit(view=None)
        except Exception:
            pass
        await interaction.response.send_message(
            embed=criar_embed("❌ Comprovante Reprovado", "O saldo não foi creditado e o jogador foi notificado no canal.", "Vermelho"),
            ephemeral=True,
        )
        await interaction.channel.send(
            content=mencao(deposito["user_id"]),
            embed=criar_embed(
                "❌ Comprovante Não Validado",
                "Não conseguimos validar este comprovante. Envie um novo print legível contendo valor, data e destinatário.",
                "Amarelo",
            ),
        )
        await registrar_log_suporte(
            interaction.guild, "💰 DEPÓSITO", "❌ Comprovante reprovado",
            f"{mencao(interaction.user.id)} reprovou o comprovante enviado por {mencao(deposito['user_id'])}. Nenhum saldo foi creditado.",
            "Vermelho",
        )


class DepositoCanalView(discord.ui.View):
    """Painel minimalista dentro do canal privado de depósito (Select único moderno)."""

    def __init__(self, deposito_id: int = 0):
        super().__init__(timeout=None)
        self.deposito_id = int(deposito_id or 0)
        sel = discord.ui.Select(
            custom_id=f"ff_dep_sel:{self.deposito_id}",
            placeholder="💰 Selecione uma opção para este depósito...",
            options=[
                discord.SelectOption(
                    label="Abrir Depósito (Informar Valor)",
                    value="abrir",
                    emoji="💳",
                    description="Jogador informa o valor em R$ que deseja depositar",
                ),
                discord.SelectOption(
                    label="Assumir e Enviar Meu PIX",
                    value="assumir",
                    emoji="🙋",
                    description="Dono/Gerente assume e envia automaticamente seu QR Code PIX",
                ),
                discord.SelectOption(
                    label="Reassumir / Trocar Responsável",
                    value="reassumir",
                    emoji="🔄",
                    description="Troca o Dono/Gerente responsável e reenvia o novo PIX",
                ),
                discord.SelectOption(
                    label="Confirmar e Creditar Moedas",
                    value="manual",
                    emoji="✅",
                    description="Confirma o pagamento recebido e credita na carteira",
                ),
                discord.SelectOption(
                    label="Pedir Comprovante",
                    value="comprovante",
                    emoji="📄",
                    description="Solicita ao jogador a imagem do comprovante PIX",
                ),
                discord.SelectOption(
                    label="Encerrar Atendimento",
                    value="fechar",
                    emoji="🔒",
                    description="Fecha e apaga este canal de depósito",
                ),
            ],
        )
        sel.callback = self._rotear
        self.add_item(sel)

    async def _deposito(self, channel_id: int):
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            return await (await db.execute(
                "SELECT * FROM depositos WHERE canal_id = ? ORDER BY id DESC LIMIT 1", (channel_id,)
            )).fetchone()

    async def _rotear(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        try:
            await interaction.message.edit(view=DepositoCanalView(self.deposito_id))
        except Exception:
            pass

        if acao == "abrir":
            deposito = await self._deposito(interaction.channel.id)
            if not deposito:
                return await interaction.response.send_message(
                    embed=criar_embed("❌ Não encontrado", "Abra um novo pelo painel **Carteira → Depositar PIX**.", "Vermelho"),
                    ephemeral=True,
                )
            if deposito["status"] not in ("aguardando", "na_janela"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Atendimento encerrado", "Este pedido já foi resolvido ou cancelado.", "Cinza Escuro"),
                    ephemeral=True,
                )
            if interaction.user.id != deposito["user_id"]:
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Apenas o titular", f"Quem preenche o valor do depósito é {mencao(deposito['user_id'])}.", "Amarelo"),
                    ephemeral=True,
                )
            return await interaction.response.send_modal(DepositoModal(deposito["id"], interaction.channel.id))

        if acao in ("assumir", "reassumir"):
            deposito = await self._deposito(interaction.channel.id)
            if not deposito or not await e_dono_ou_gerente(interaction.user):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Exclusivo Dono/Gerente", "Apenas **Dono** ou **Gerente** assume depósitos (o PIX enviado é o de quem assumir).", "Vermelho"),
                    ephemeral=True,
                )
            if deposito["status"] not in ("aguardando", "na_janela"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Depósito encerrado", "Este atendimento já foi resolvido ou cancelado.", "Cinza Escuro"),
                    ephemeral=True,
                )
            antigo_dep = deposito["assumido_por"]
            if antigo_dep and antigo_dep != interaction.user.id and acao != "reassumir":
                return await interaction.response.send_message(
                    embed=criar_embed(
                        "🙋 Já assumido",
                        f"Já foi assumido por {mencao(antigo_dep)}. Use **🔄 Reassumir / Trocar Responsável** se precisar trocar o PIX.",
                        "Amarelo",
                    ),
                    ephemeral=True,
                )

            pix_meu = await obter_pix_adm(interaction.user.id, interaction.guild.id)
            if not pix_meu:
                return await interaction.response.send_message(
                    embed=criar_embed(
                        "⚠️ Cadastre sua chave PIX primeiro",
                        "Use `/pix` para cadastrar sua chave PIX antes de assumir — no depósito, sua chave PIX e QR Code são enviados **automaticamente** ao assumir.",
                        "Amarelo",
                    ),
                    ephemeral=True,
                )

            await interaction.response.defer()
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute("UPDATE depositos SET assumido_por = ? WHERE id = ?", (interaction.user.id, deposito["id"]))
                await db.commit()
            marcar_sujo()

            valor_dep = float(deposito["valor"] or 0)
            trocou_dep = bool(antigo_dep and antigo_dep != interaction.user.id)
            embed_pix, arquivo_pix, view_pix = await montar_cobranca_pix_responsavel(
                interaction.guild.id,
                interaction.user.id,
                valor=valor_dep,
                titulo=(
                    f"🔄 Depósito Reassumido — Novo PIX de {interaction.user.display_name}"
                    if trocou_dep
                    else f"💰 Depósito Assumido — PIX de {interaction.user.display_name}"
                ),
                mencao_destino=mencao(deposito["user_id"]),
                rodape=f"Fire Force • Depósito #{deposito['id']}",
                nome_arquivo="deposito_pix.png",
            )
            kwargs_envio = {"content": mencao(deposito["user_id"]), "embed": embed_pix}
            if arquivo_pix:
                kwargs_envio["file"] = arquivo_pix
            if view_pix:
                kwargs_envio["view"] = view_pix
            await interaction.followup.send(**kwargs_envio)
            return await registrar_log_suporte(
                interaction.guild, "💰 DEPÓSITO",
                "🔄 Depósito reassumido (novo PIX)" if trocou_dep else "🙋 Depósito assumido (PIX enviado)",
                f"{mencao(interaction.user.id)} {'reassumiu' if trocou_dep else 'assumiu'} o depósito `#{deposito['id']}` e enviou seu PIX automaticamente.",
                "Verde",
            )

        if acao == "manual":
            deposito = await self._deposito(interaction.channel.id)
            if not deposito or not await atendente_autorizado("suporte", interaction.user):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Sem Permissão", "Apenas equipe autorizada pode confirmar depósitos.", "Vermelho"),
                    ephemeral=True,
                )
            if not await aviso_fora_de_servico(interaction):
                return
            if deposito["status"] not in ("aguardando", "na_janela"):
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Depósito encerrado", "Este depósito já foi resolvido ou cancelado.", "Cinza Escuro"),
                    ephemeral=True,
                )
            if float(deposito["valor"] or 0) <= 0:
                return await interaction.response.send_message(
                    embed=criar_embed("⚠️ Valor não informado", "O jogador precisa escolher **Abrir Depósito** e informar o valor primeiro.", "Amarelo"),
                    ephemeral=True,
                )
            if (not deposito["assumido_por"] or deposito["assumido_por"] != interaction.user.id) and not await e_gerencia(interaction.user):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Só quem assumiu ou gerência", "Assuma este depósito ou peça ao Dono/Gerente.", "Vermelho"),
                    ephemeral=True,
                )
            await interaction.response.defer(ephemeral=True, thinking=True)
            saldo = await creditar_deposito(interaction.guild, dict(deposito), "confirmação manual pela equipe")
            return await interaction.followup.send(
                embed=criar_embed("✅ Depósito Confirmado", f"Crédito registrado.\n• **Saldo atualizado:** `{formatar_moeda(saldo)}`", "Esmeralda"),
                ephemeral=True,
            )

        if acao == "comprovante":
            deposito = await self._deposito(interaction.channel.id)
            if not deposito or not await atendente_autorizado("suporte", interaction.user):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Sem Permissão", "Apenas equipe autorizada pode solicitar comprovante.", "Vermelho"),
                    ephemeral=True,
                )
            if not await aviso_fora_de_servico(interaction):
                return
            if deposito["status"] == "creditado":
                return await interaction.response.send_message(
                    embed=criar_embed("ℹ️ Já creditado", "Este depósito já foi confirmado.", "Cinza Escuro"),
                    ephemeral=True,
                )
            if float(deposito["valor"] or 0) <= 0:
                return await interaction.response.send_message(
                    embed=criar_embed("⚠️ Valor não informado", "Peça ao jogador para preencher o valor em **Abrir Depósito** primeiro.", "Amarelo"),
                    ephemeral=True,
                )
            if (not deposito["assumido_por"] or deposito["assumido_por"] != interaction.user.id) and not await e_gerencia(interaction.user):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Só quem assumiu ou gerência", "Assuma este depósito ou peça ao Dono/Gerente.", "Vermelho"),
                    ephemeral=True,
                )
            embed = criar_embed(
                "📄 Comprovante de Depósito Solicitado",
                f"{mencao(deposito['user_id'])}, envie **neste canal** a imagem do comprovante PIX.\n\n"
                f"• **Valor esperado:** `{formatar_moeda(deposito['valor'])}`\n"
                f"-# Após conferir na conta PIX, valide no seletor abaixo",
                "Cinza Escuro",
            )
            await interaction.response.send_message(
                content=mencao(deposito["user_id"]), embed=embed, view=DepositoComprovanteView(deposito["id"])
            )
            return await registrar_log_suporte(
                interaction.guild, "💰 DEPÓSITO", "📄 Comprovante solicitado",
                f"{mencao(interaction.user.id)} pediu comprovante de depósito a {mencao(deposito['user_id'])} — `{formatar_moeda(deposito['valor'])}`.",
                "Azul",
            )

        if acao == "fechar":
            deposito = await self._deposito(interaction.channel.id)
            eh_equipe = await atendente_autorizado("suporte", interaction.user)
            eh_dono_dep = bool(deposito and interaction.user.id == deposito["user_id"] and deposito["status"] != "creditado")
            if not eh_equipe and not eh_dono_dep:
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Sem Permissão", "Apenas a equipe (ou o solicitante antes da conclusão) pode encerrar este canal.", "Vermelho"),
                    ephemeral=True,
                )
            if deposito and deposito["status"] != "creditado":
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    await db.execute("UPDATE depositos SET status = 'cancelado' WHERE id = ?", (deposito["id"],))
                    await db.commit()
                marcar_sujo()
            await interaction.response.send_message(
                embed=criar_embed("🔒 Atendimento Encerrado", "Este canal será fechado em 3 segundos...", "Cinza Escuro")
            )
            await asyncio.sleep(3)
            await _apagar_canal_seguro(interaction.channel, "Canal de depósito encerrado")
        try:
            await interaction.channel.delete()
        except Exception:
            pass


async def creditar_deposito(guild, deposito, origem: str, livepix_id: str = ""):
    """Credita uma única vez; manual/prova e LivePix compartilham a mesma trava."""
    async with _lock_deposito:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory=aiosqlite.Row
            atual=await (await db.execute("SELECT * FROM depositos WHERE id=?",(deposito["id"],))).fetchone()
        if not atual:
            return 0.0
        if atual["status"]=="creditado":
            return await saldo_carteira(atual["user_id"],atual["guild_id"])
        if atual["status"] not in ("aguardando", "na_janela"):
            _log_arquivo(f"[DEPÓSITO] crédito recusado: id={atual['id']} status={atual['status']}")
            return await saldo_carteira(atual["user_id"], atual["guild_id"])
        deposito=dict(atual)
        valor=arredondar(deposito["valor"] or 0)
        if valor<=0:return await saldo_carteira(deposito["user_id"],deposito["guild_id"])
        novo=await creditar_saldo(deposito["user_id"],deposito["guild_id"],valor,
            "deposito",f"Depósito PIX — {deposito['nome_pagador'] or origem}",ref=livepix_id or f"deposito:{deposito['id']}")
        await registrar_caixa(deposito["guild_id"],"receita",valor,
            f"Depósito da carteira — #{deposito['id']}",ref=livepix_id or f"deposito:{deposito['id']}")
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("UPDATE depositos SET status='creditado',livepix_id=?,creditado_em=? WHERE id=?",
                             (livepix_id,agora_brt().isoformat(),deposito["id"]))
            await db.commit()
        marcar_sujo()
    if not guild:return novo
    await registrar_log(guild,"💰 DEPÓSITO","✅ Depósito creditado",
        f"{mencao(deposito['user_id'])} depositou **{formatar_moeda(valor)}**.\n> 💰 Saldo agora: `{formatar_moeda(novo)}`\n> ⚡ Origem: {origem}","Esmeralda")
    await anunciar(guild,"deposito","✅ Depósito confirmado (PIX)",
        f"{mencao(deposito['user_id'])} depositou **{formatar_moeda(valor)}** e o saldo já caiu na carteira dele 💰\n"
        f"> ⚡ Confirmação: {origem}\n> 🎮 Já pode usar pra pagar o diário na hora!","Esmeralda",marcar=deposito["user_id"])
    canal=guild.get_channel(int(deposito["canal_id"])) if deposito.get("canal_id") else None
    if canal:
        try:
            await canal.send(content=mencao(deposito["user_id"]),embed=criar_embed("✅ Depósito confirmado!",
                f"Seu saldo de **{formatar_moeda(valor)}** caiu na carteira.\n> 💰 Saldo agora: `{formatar_moeda(novo)}`\n> 🎮 Já pode usar pra pagar o diário! Este canal fecha em {DEPOSITO_FECHAR_SEGUNDOS}s.","Esmeralda"))
            await asyncio.sleep(DEPOSITO_FECHAR_SEGUNDOS)
            await _apagar_canal_seguro(canal, f"Depósito #{deposito['id']} confirmado")
        except Exception:pass
    return novo


# ---------- CUPONS: ANÚNCIO + ESGOTADO ----------

def _dados_cupom(cupom) -> str:
    if (cupom["tipo_desconto"] or "pct") == "pct":
        desconto = f"{cupom['valor']:g}% de desconto"
    else:
        desconto = f"{formatar_moeda(cupom['valor'])} de desconto"
    limites = []
    if cupom["usos_max"]:
        limites.append(f"{cupom['usos_max']} usos no total")
    if cupom["usos_por_user"]:
        limites.append(f"{cupom['usos_por_user']}x por pessoa")
    if cupom["expira_em"]:
        limites.append(f"válido até {str(cupom['expira_em'])[:16].replace('T', ' às ')}")
    return (f"**{desconto}** em qualquer diário\n"
            f"> 🎟️ **Como usar:** `/cupom {cupom['codigo']}` no seu canal de pagamento\n"
            f"> 📊 Limites: {', '.join(limites) if limites else 'sem limite'}")


async def anunciar_cupom(guild, cupom_id: int):
    """Manda o anúncio do cupom no canal configurado (marcando todo mundo)."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        cupom = await (await db.execute("SELECT * FROM cupons WHERE id = ?", (cupom_id,))).fetchone()
    if not cupom or not guild:
        return
    canal_id = await cfgv(guild.id, "canal_cupons", None)
    canal = guild.get_channel(int(canal_id)) if canal_id else None
    if not canal:
        return
    embed = criar_embed(
        f"🎟️ CUPOM NOVO — {cupom['codigo']}",
        f"{_dados_cupom(cupom)}\n\n"
        f"> ⚠️ Quando os usos acabarem, este cupom é **encerrado automaticamente**.\n"
        f"> 🏁 Corra e garanta sua vaga!",
        "Dourado", footer="🔥 Fire Force • Cupons")
    try:
        mensagem = await canal.send(content="@everyone", embed=embed)
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute("UPDATE cupons SET msg_id = ?, canal_id = ? WHERE id = ?",
                             (mensagem.id, canal.id, cupom_id))
            await db.commit()
        marcar_sujo()
    except Exception as erro:
        _log_arquivo(f"[CUPOM] erro ao anunciar: {erro}")


async def encerrar_cupom(guild, cupom, motivo: str):
    """Fecha o cupom: edita o anúncio + avisa todo mundo uma única vez."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        await db.execute("UPDATE cupons SET esgotado_avisado = 1, ativo = 0 WHERE id = ?", (cupom["id"],))
        await db.commit()
    marcar_sujo()

    canal_id = cupom["canal_id"] or await cfgv(guild.id, "canal_cupons", None)
    canal = guild.get_channel(int(canal_id)) if canal_id else None
    if canal:
        texto = ("🎟️ **CUPOM ESGOTADO** — não é mais válido. Fique ligado nos próximos! 🔥"
                 if motivo == "esgotado" else
                 "⌛ **CUPOM EXPIRADO** — não é mais válido. Fique ligado nos próximos! 🔥")
        try:
            if cupom["msg_id"]:
                mensagem = await canal.fetch_message(int(cupom["msg_id"]))
                embed = criar_embed(f"❌ {texto}", f"O cupom `{cupom['codigo']}` foi encerrado.", "Vermelho",
                                    footer="🔥 Fire Force • Cupons")
                await mensagem.edit(content="@everyone", embed=embed)
            else:
                await canal.send(content="@everyone", embed=criar_embed(f"❌ {texto}",
                                                                        f"O cupom `{cupom['codigo']}` foi encerrado.",
                                                                        "Vermelho"))
        except Exception:
            pass
    await registrar_log(guild, "🎟️ CUPOM", f"🎟️ Cupom {motivo}",
                        f"O cupom `{cupom['codigo']}` foi **{motivo}** e não pode mais ser usado.\n"
                        f"> 👥 Usos: `{cupom['usos_atuais']}`"
                        + (f"/{cupom['usos_max']}" if cupom["usos_max"] else ""),
                        "Vermelho")


async def loop_cupons():
    """Verifica cupons esgotados/expirados e encerra sozinho (edita o anúncio)."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            async with aiosqlite.connect(DATABASE_FILE) as db:
                db.row_factory = aiosqlite.Row
                cupons = await (await db.execute(
                    "SELECT * FROM cupons WHERE COALESCE(esgotado_avisado, 0) = 0"
                )).fetchall()
            for cupom in cupons:
                guild = bot.get_guild(cupom["guild_id"])
                if not guild:
                    continue
                esgotado = cupom["usos_max"] and cupom["usos_atuais"] >= cupom["usos_max"]
                expirado = False
                if cupom["expira_em"]:
                    try:
                        # expira_em é digitado como DD/MM/AAAA (validado na criação)
                        expirado = agora_brt().replace(tzinfo=None) > datetime.datetime.strptime(
                            str(cupom["expira_em"]).strip(), "%d/%m/%Y")
                    except Exception:
                        expirado = False
                if esgotado:
                    await encerrar_cupom(guild, cupom, "esgotado")
                elif expirado:
                    await encerrar_cupom(guild, cupom, "expirado")
        except Exception as erro:
            _log_arquivo(f"[CUPOM] erro no loop: {erro}")
        await asyncio.sleep(120)


# ---------- EVENTOS ----------

async def evento_ativo(guild_id: int, valor: float = None, tipo: str = None, categoria: str = None):
    """Evento rolando agora (e compatível com o diário, se informado)."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        eventos = await (await db.execute(
            "SELECT * FROM eventos WHERE guild_id = ? AND ativo = 1", (guild_id,)
        )).fetchall()
    for evento in eventos:
        if evento["fim_em"]:
            try:
                _fim = datetime.datetime.fromisoformat(str(evento["fim_em"]))
                if _fim.tzinfo is None:
                    _fim = _fim.replace(tzinfo=TZ_BRASILIA)
                if agora_brt() > _fim:
                    continue
            except Exception:
                pass
        if valor is not None and arredondar(evento["aposta_min"] or 0) > arredondar(valor):
            continue
        if tipo and evento["modos"] and str(evento["modos"]).lower() not in ("todos", "todas"):
            if tipo.lower() not in [m.strip().lower() for m in str(evento["modos"]).split(",") if m.strip()]:
                continue
        if categoria and evento["categorias"] and str(evento["categorias"]).lower() not in ("todas", "todos"):
            if categoria.lower() not in [c.strip().lower() for c in str(evento["categorias"]).split(",") if c.strip()]:
                continue
        return evento
    return None


async def registrar_participante(evento, slot_id: int, user_id: int, valor: float):
    async with aiosqlite.connect(DATABASE_FILE) as db:
        await db.execute(
            "INSERT OR IGNORE INTO evento_participantes (evento_id, user_id, slot_id, valor, criado_em) "
            "VALUES (?, ?, ?, ?, ?)",
            (evento["id"], user_id, slot_id, arredondar(valor), agora_brt().isoformat()))
        await db.commit()
    marcar_sujo()


