@bot.tree.command(name="vitoria", description="🏆 Registrar uma vitória (top 1) no ranking de um jogador")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
@app_commands.describe(usuario="Quem venceu", quantidade="Quantas vitórias registrar (padrão 1)")
async def cmd_vitoria(interaction: discord.Interaction, usuario: discord.Member, quantidade: Optional[int] = 1):
    if not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas Dono ou Gerente registram vitórias.", "Vermelho"), ephemeral=True)
    quantidade = max(1, int(quantidade or 1))
    dados_antes = await obter_estatisticas_completas_jogador(interaction.guild.id, usuario.id)
    pat_antes = dados_antes["patente"]

    # Se o comando foi executado dentro do canal privado de uma sala ativa, zera o streak dos outros capitães da sala
    try:
        async with aiosqlite.connect(DATABASE_FILE) as db:
            h_sala = await (await db.execute(
                "SELECT id FROM horarios WHERE guild_id = ? AND canal_tabela = ? ORDER BY id DESC LIMIT 1",
                (interaction.guild.id, interaction.channel.id),
            )).fetchone()
        if h_sala:
            await zerar_sequencia_perdedores_sala(interaction.guild.id, int(h_sala[0]), usuario.id)
    except Exception:
        pass

    async with aiosqlite.connect(DATABASE_FILE) as db:
        await db.execute("INSERT INTO vitorias (user_id, guild_id, qtd) VALUES (?, ?, ?) "
                         "ON CONFLICT(user_id, guild_id) DO UPDATE SET qtd = qtd + ?",
                         (usuario.id, interaction.guild.id, quantidade, quantidade))
        await db.commit()
        total = (await (await db.execute("SELECT qtd FROM vitorias WHERE user_id = ? AND guild_id = ?",
                                         (usuario.id, interaction.guild.id))).fetchone())[0]
    streak_atual, maior_streak = await registrar_sequencia_vitoria(interaction.guild.id, usuario.id, quantidade)
    dados_depois = await sincronizar_cargo_patente(interaction.guild, usuario.id)
    pat_depois = dados_depois["patente"] if dados_depois else pat_antes
    subiu_patente = pat_depois["slug"] != pat_antes["slug"]
    marcar_sujo()

    linha_streak = (
        f"\n• 🔥 **Sequência invicta:** **{streak_atual} vitória(s) seguida(s)** *(recorde: `{maior_streak}`)*"
        if streak_atual >= 2
        else f"\n• 🔥 **Sequência atual:** `{streak_atual}` *(recorde: `{maior_streak}`)*"
    )
    linha_patente = (
        f"\n• 🎖️ **SUBIU DE PATENTE!** {pat_antes['emoji']} `{pat_antes['nome']}` ➜ {pat_depois['emoji']} **{pat_depois['nome']}**!"
        if subiu_patente
        else f"\n• 🎖️ **Patente:** {pat_depois['emoji']} **{pat_depois['nome']}** (`{dados_depois['pontos'] if dados_depois else 0} pts`)"
    )

    await interaction.response.send_message(
        embed=criar_embed(
            "🏆 Vitória Registrada!",
            f"{usuario.mention} agora soma **{total}** vitória{'s' if total != 1 else ''} (`+{quantidade}`).{linha_streak}{linha_patente}",
            "Dourado",
        )
    )
    await registrar_log(
        interaction.guild, "🏆 RANKING", "🏆 Vitória registrada",
        f"{usuario.mention} +{quantidade} vitória(s) — total `{total}` • streak `{streak_atual}` • patente `{pat_depois['nome']}` (por {interaction.user.mention}).",
        "Dourado",
    )


async def _executar_remocao_vitoria(
    interaction: discord.Interaction,
    usuario: discord.Member,
    qtd_pedida: int,
    vitorias_seguidas_reais: Optional[int],
    dados_antes: dict,
):
    vit_antes = int(dados_antes["vitorias"])
    pts_antes = int(dados_antes["pontos"])
    pat_antes = dados_antes["patente"]

    removidas = min(vit_antes, max(1, int(qtd_pedida)))
    novo_total = max(0, vit_antes - removidas)

    async with aiosqlite.connect(DATABASE_FILE) as db:
        if novo_total <= 0:
            await db.execute(
                "DELETE FROM vitorias WHERE user_id = ? AND guild_id = ?",
                (usuario.id, interaction.guild.id),
            )
        else:
            await db.execute(
                "UPDATE vitorias SET qtd = ? WHERE user_id = ? AND guild_id = ?",
                (novo_total, usuario.id, interaction.guild.id),
            )
        await db.commit()

    streak_atual, maior_streak = await ajustar_sequencia_apos_remocao_vitoria(
        interaction.guild.id, usuario.id, novo_total, vitorias_seguidas_reais=vitorias_seguidas_reais
    )
    dados_depois = await sincronizar_cargo_patente(interaction.guild, usuario.id)
    pat_depois = dados_depois["patente"] if dados_depois else pat_antes
    pts_depois = int(dados_depois["pontos"]) if dados_depois else max(0, pts_antes - removidas * 3)
    winrate_depois = float(dados_depois["winrate"]) if dados_depois else 0.0
    partidas_jogadas = int(dados_depois["partidas"]) if dados_depois else int(dados_antes["partidas"])
    pts_removidos = max(0, pts_antes - pts_depois)
    desceu_patente = pat_depois["slug"] != pat_antes["slug"]
    marcar_sujo()

    if pts_depois <= 0 and dados_depois.get("cargos_removidos"):
        linha_patente = (
            f"\n• 📉 **Patente zerada:** cargo(s) `{', '.join(dados_depois['cargos_removidos'])}` removido(s) (`0 pts`)"
        )
    elif desceu_patente:
        linha_patente = (
            f"\n• 📉 **DESCEU DE PATENTE:** {pat_antes['emoji']} `{pat_antes['nome']}` ➜ "
            f"{pat_depois['emoji']} **{pat_depois['nome']}** (`{pts_antes} pts` ➜ `{pts_depois} pts`)"
        )
    else:
        linha_patente = (
            f"\n• 🎖️ **Patente atual:** {pat_depois['emoji']} **{pat_depois['nome']}** "
            f"(`{pts_antes} pts` ➜ `{pts_depois} pts`)"
        )

    await interaction.followup.send(
        embed=criar_embed(
            "📉 Vitória(s) Removida(s) e Pontos Ajustados",
            f"Ajuste aplicado em {usuario.mention}:\n\n"
            f"• 🏆 **Vitórias totais:** `{vit_antes}` ➜ **`{novo_total}`** (`-{removidas}`)\n"
            f"• 📊 **Pontos descontados:** `-{pts_removidos} pts` (`{pts_antes}` ➜ `{pts_depois} pts`)\n"
            f"• 🔥 **Vitórias seguidas preservadas:** `{streak_atual}` *(recorde: `{maior_streak}`)*\n"
            f"• 🎮 **Diários jogados / Winrate:** `{partidas_jogadas}` diário(s) • `{winrate_depois:.1f}%`"
            f"{linha_patente}",
            "Amarelo",
        )
    )
    await registrar_log(
        interaction.guild,
        "🏆 RANKING",
        "📉 Vitória(s) removida(s)",
        f"{usuario.mention} teve `-{removidas}` vitória(s) removida(s) por {interaction.user.mention} — "
        f"vitórias `{vit_antes}` ➜ `{novo_total}` • seguidas `{streak_atual}` • pontos `{pts_antes}` ➜ `{pts_depois}` • "
        f"patente `{pat_antes['nome']}` ➜ `{pat_depois['nome']}`.",
        "Amarelo",
    )


class RemoverVitoriaModal(discord.ui.Modal, title="📉 Remover Vitórias de Jogador"):
    campo_remover = discord.ui.TextInput(
        label="Quantas vitórias você quer remover?",
        placeholder="Ex: 1",
        min_length=1,
        max_length=5,
        required=True,
    )
    campo_seguidas = discord.ui.TextInput(
        label="Quantas vitórias seguidas ele tinha?",
        placeholder="Ex: 5 (mantém as seguidas dele sem apagar)",
        min_length=1,
        max_length=5,
        required=True,
    )

    def __init__(self, usuario: discord.Member, dados_atuais: dict):
        super().__init__()
        self.usuario = usuario
        self.dados_atuais = dados_atuais
        vit_at = int(dados_atuais.get("vitorias") or 0)
        seq_at = int(dados_atuais.get("sequencia_atual") or 0)
        self.campo_remover.default = "1"
        self.campo_remover.placeholder = f"Ele tem {vit_at} vitória(s) no total (ex: 1)"
        self.campo_seguidas.default = str(seq_at)
        self.campo_seguidas.placeholder = f"Atual no perfil: {seq_at} seguida(s)"

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.guild or not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("❌ Sem Permissão", "Apenas Dono ou Gerente podem remover vitórias.", "Vermelho"),
                ephemeral=True,
            )
        txt_rem = (self.campo_remover.value or "").strip()
        txt_seq = (self.campo_seguidas.value or "").strip()
        if not txt_rem.isdigit() or int(txt_rem) <= 0:
            return await interaction.response.send_message(
                embed=criar_embed("⚠️ Valor inválido", "Informe um número inteiro maior que zero para remover (ex: `1`).", "Amarelo"),
                ephemeral=True,
            )
        if not txt_seq.isdigit() or int(txt_seq) < 0:
            return await interaction.response.send_message(
                embed=criar_embed("⚠️ Valor inválido", "Informe quantas vitórias seguidas ele tinha usando apenas números (`0` ou mais).", "Amarelo"),
                ephemeral=True,
            )

        await interaction.response.defer(thinking=True)
        dados_frescos = await obter_estatisticas_completas_jogador(interaction.guild.id, self.usuario.id)
        if int(dados_frescos["vitorias"]) <= 0:
            return await interaction.followup.send(
                embed=criar_embed("ℹ️ Nenhuma Vitória", f"{self.usuario.mention} já está com `0` vitórias.", "Amarelo"),
                ephemeral=True,
            )
        await _executar_remocao_vitoria(
            interaction,
            self.usuario,
            int(txt_rem),
            int(txt_seq),
            dados_frescos,
        )


@bot.tree.command(name="removervitoria", description="📉 Remover vitórias lançadas por engano (preserva seguidas/diários e ajusta patente)")
@app_commands.guild_only()
@app_commands.default_permissions(manage_channels=True)
@app_commands.describe(
    usuario="Jogador que terá vitórias removidas",
    quantidade="Quantas vitórias remover (se deixar vazio, abre janela perguntando)",
    vitorias_seguidas="Quantas vitórias seguidas reais ele tinha (mantém as seguidas intactas)",
)
async def cmd_remover_vitoria(
    interaction: discord.Interaction,
    usuario: discord.Member,
    quantidade: Optional[int] = None,
    vitorias_seguidas: Optional[int] = None,
):
    if not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas Dono ou Gerente podem remover vitórias.", "Vermelho"),
            ephemeral=True,
        )

    dados_antes = await obter_estatisticas_completas_jogador(interaction.guild.id, usuario.id)
    vit_antes = int(dados_antes["vitorias"])

    if vit_antes <= 0:
        return await interaction.response.send_message(
            embed=criar_embed(
                "ℹ️ Nenhuma Vitória para Remover",
                f"{usuario.mention} já está com **`0` vitórias** registradas.",
                "Amarelo",
            ),
            ephemeral=True,
        )

    # Se não preencheu os dois campos na barra, abre o Modal perguntando quantas remover e quantas seguidas ele tinha!
    if quantidade is None or vitorias_seguidas is None:
        modal = RemoverVitoriaModal(usuario, dados_antes)
        if quantidade is not None:
            modal.campo_remover.default = str(max(1, int(quantidade)))
        if vitorias_seguidas is not None:
            modal.campo_seguidas.default = str(max(0, int(vitorias_seguidas)))
        return await interaction.response.send_modal(modal)

    await interaction.response.defer(thinking=True)
    await _executar_remocao_vitoria(
        interaction,
        usuario,
        max(1, int(quantidade)),
        max(0, int(vitorias_seguidas)),
        dados_antes,
    )


@bot.tree.command(name="booyah", description="🔥 Definir o canal de Booyah ou publicar um Booyah oficial com foto FF, nick e clã")
@app_commands.guild_only()
@app_commands.describe(
    canal_booyah="Definir/alterar o canal onde os Booyahs serão enviados (Dono/Gerente)",
    modo="Modo da partida vencida (Solo, Duo, Trio ou Squad)",
    categoria="Categoria da partida (ex: Premium, Básico, Evento)",
    horario="Horário da sala (ex: 22:00)",
    ids_ff="IDs do Free Fire dos vencedores separados por espaço ou vírgula (1 no Solo até 4 no Squad)",
)
@app_commands.choices(
    modo=[
        app_commands.Choice(name="Solo (1 jogador)", value="solo"),
        app_commands.Choice(name="Duo (2 jogadores)", value="duo"),
        app_commands.Choice(name="Trio (3 jogadores)", value="trio"),
        app_commands.Choice(name="Squad (4 jogadores)", value="squad"),
    ]
)
async def cmd_booyah(
    interaction: discord.Interaction,
    canal_booyah: Optional[discord.TextChannel] = None,
    modo: Optional[app_commands.Choice[str]] = None,
    categoria: Optional[str] = None,
    horario: Optional[str] = None,
    ids_ff: Optional[str] = None,
):
    if not await e_staff(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas ADM, Gerente ou Dono pode usar `/booyah`.", "Vermelho"),
            ephemeral=True,
        )

    # 1. Configurar canal de Booyah
    if canal_booyah is not None and not ids_ff:
        if not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Exclusivo Dono & Gerente", "Somente Dono ou Gerente pode definir o canal oficial de Booyah.", "Vermelho"),
                ephemeral=True,
            )
        await salvar_config(interaction.guild.id, canal_booyah=canal_booyah.id)
        marcar_sujo()
        await registrar_log(
            interaction.guild,
            "⚙️ CONFIG",
            "🔥 Canal de Booyah definido",
            f"{interaction.user.mention} definiu {canal_booyah.mention} como canal oficial de Booyah.",
            "Esmeralda",
        )
        return await interaction.response.send_message(
            embed=criar_embed(
                "🔥 Canal de Booyah Configurado!",
                f"Todos os Booyahs (tanto pelas salas quanto por `/booyah`) serão publicados em {canal_booyah.mention}.",
                "Esmeralda",
            ),
            ephemeral=True,
        )

    if canal_booyah is not None and await e_dono_ou_gerente(interaction.user):
        await salvar_config(interaction.guild.id, canal_booyah=canal_booyah.id)
        marcar_sujo()

    # 2. Se chamado sem argumentos, mostra status + instruções rápidas
    if not ids_ff:
        cfg_atual = await obter_config(interaction.guild.id)
        cid_b = cfg_atual.get("canal_booyah")
        ref_b = f"<#{cid_b}>" if cid_b else "`não definido`"
        return await interaction.response.send_message(
            embed=criar_embed(
                "🔥 Central de Booyah — Fire Force",
                f"• **Canal oficial atual:** {ref_b}\n\n"
                f"**Como usar:**\n"
                f"> **1.** Direto no canal da sala: abra o menu da sala e escolha **🏆 Enviar Booyah desta Sala** *(puxa modo, categoria, horário e IDs da vaga automaticamente!)*\n"
                f"> **2.** Manualmente aqui: `/booyah modo:Squad categoria:Premium horario:22:00 ids_ff:12345678 87654321 ...`\n"
                f"> **3.** Definir canal: `/booyah canal_booyah:#booyah` ou `/config canal_booyah:#booyah`",
                "Vermelho Escuro",
            ),
            ephemeral=True,
        )

    uids = [u for u in re.findall(r"\d{5,15}", ids_ff or "")][:4]
    if not uids:
        return await interaction.response.send_message(
            embed=criar_embed("❌ IDs Inválidos", "Informe de 1 a 4 IDs numéricos do Free Fire (5 a 15 dígitos).", "Vermelho"),
            ephemeral=True,
        )

    modo_str = modo.value if modo else {1: "solo", 2: "duo", 3: "trio"}.get(len(uids), "squad")
    qtd_max_modo = JOGADORES_POR_LOTE.get(modo_str, 4)
    uids = uids[:qtd_max_modo]
    cat_str = (categoria or "Premium").strip()[:30]
    hora_str = (horario or agora_brt().strftime("%H:%M")).strip()[:12]

    await interaction.response.defer(ephemeral=True, thinking=True)
    jogadores_base = [{"ff_uid": u, "ff_nome": f"ID {u}"} for u in uids]
    ok, msg = await publicar_booyah_canal(
        guild=interaction.guild,
        modo=modo_str,
        categoria=cat_str,
        horario_str=hora_str,
        jogadores_base=jogadores_base,
        autor_staff=interaction.user,
    )
    await interaction.followup.send(
        embed=criar_embed(
            "🔥 Booyah Publicado!" if ok else "⚠️ Não foi possível publicar o Booyah",
            msg,
            "Vermelho Escuro" if ok else "Amarelo",
        ),
        ephemeral=True,
    )


@bot.tree.command(name="trabalho", description="💼 Carteira de trabalho semanal do Suporte")
@app_commands.guild_only()
@app_commands.describe(usuario="Inspecionar outro membro (Dono e Gerente)")
async def cmd_trabalho(interaction: discord.Interaction, usuario: Optional[discord.Member] = None):
    if not await pode_usar_trabalho(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed(
                "❌ Comando Exclusivo do Suporte",
                "Apenas **Suporte**, **Gerente** ou **Dono** podem usar `/trabalho`.\n"
                "• Se você é **ADM**, consulte seus ganhos no PIX em `/pix` (`acao: Ver meus ganhos no PIX`).",
                "Vermelho",
            ),
            ephemeral=True,
        )
    alvo = usuario or interaction.user
    if usuario and usuario.id != interaction.user.id and not await e_dono_ou_gerente(interaction.user):
        return await interaction.response.send_message(
            embed=criar_embed("❌ Sem Permissão", "Apenas Dono ou Gerente podem inspecionar outro membro.", "Vermelho"),
            ephemeral=True,
        )

    # Caso 1: Suporte -> Carteira de trabalho semanal
    if await tem_carteira_trabalho(alvo):
        saldo = await saldo_trabalho(alvo.id, interaction.guild.id)
        extrato = await extrato_trabalho(alvo.id, interaction.guild.id, 10)
        embed = criar_embed(
            f"💼 Carteira de trabalho (Suporte) — {alvo.display_name}",
            f"**A receber:** `{formatar_moeda(saldo)}`\n"
            f"**Fechamento:** domingo à noite; saque até segunda **01:00 BRT** (depois, saldo não sacado vira da Org)\n\n"
            f"**Últimos ganhos:**\n{extrato}",
            "Dourado",
        )
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            semana_inicio = (agora_brt() - datetime.timedelta(days=agora_brt().weekday())).replace(
                hour=0, minute=0, second=0, microsecond=0
            ).isoformat()
            stats = await (await db.execute(
                "SELECT COUNT(*) n, AVG(nota) media FROM avaliacoes WHERE guild_id=? AND atendente_id=? AND criado_em>=?",
                (interaction.guild.id, alvo.id, semana_inicio),
            )).fetchone()
        embed.add_field(
            name="📊 Desempenho nesta semana",
            value=f"> 🎫 Tickets avaliados: **{stats['n'] or 0}**\n> ⭐ Média geral: **{float(stats['media'] or 0):.2f}/5**"
                  if stats["n"] else "> Ainda sem avaliações nesta semana.",
            inline=False,
        )
        embed.add_field(
            name="🧾 Como a nota semanal afeta o valor",
            value="> Média 5★: **100%** • 4,50–4,99★: **95%** • 4,00–4,49★: **90%**\n"
                  "> 3,00–3,99★: **50%** • 2,00–2,99★: **25%** • abaixo de 2★: **0%**\n"
                  "> Notas por atendimento ficam na carteira do Suporte; saque no domingo até segunda 01:00 BRT.",
            inline=False,
        )
        return await interaction.response.send_message(embed=embed, ephemeral=True)

    # Caso 2: ADM / Mediador / Gerente / Dono -> Controle de ganhos recebidos no PIX (sem carteira)
    if await e_staff(alvo):
        hoje = agora_brt().strftime("%Y-%m-%d")
        semana_inicio = (agora_brt() - datetime.timedelta(days=agora_brt().weekday())).replace(
            hour=0, minute=0, second=0, microsecond=0
        ).isoformat()
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            dia_adm = await (await db.execute(
                "SELECT COUNT(*) AS n, COALESCE(SUM(comissao), 0) AS total "
                "FROM comissoes WHERE guild_id = ? AND staff_id = ? AND dia = ?",
                (interaction.guild.id, alvo.id, hoje),
            )).fetchone()
            sem_adm = await (await db.execute(
                "SELECT COUNT(*) AS n, COALESCE(SUM(comissao), 0) AS total "
                "FROM comissoes WHERE guild_id = ? AND staff_id = ? AND criado_em >= ?",
                (interaction.guild.id, alvo.id, semana_inicio),
            )).fetchone()
            ultimos = await (await db.execute(
                "SELECT c.valor_base, c.comissao, c.criado_em, h.horario, h.tipo, s.pago_moedas, s.cupom_id "
                "FROM comissoes c "
                "LEFT JOIN horarios h ON h.id = c.horario_id "
                "LEFT JOIN slots s ON s.id = c.slot_id "
                "WHERE c.guild_id = ? AND c.staff_id = ? ORDER BY c.id DESC LIMIT 10",
                (interaction.guild.id, alvo.id),
            )).fetchall()

        linhas_hist = []
        for r in ultimos:
            r_d = dict(r)
            pago_adm = arredondar(r_d.get("comissao") or 0)
            base_orig = arredondar(r_d.get("valor_base") or pago_adm)
            quando_txt = str(r_d.get("criado_em") or "")[8:16].replace("-", "/").replace("T", " ")
            hor_txt = r_d.get("horario") or "--:--"
            foi_moedas = int(r_d.get("pago_moedas") or 0) == 1
            teve_desc = (not foi_moedas and base_orig - pago_adm > 0.009) or bool(r_d.get("cupom_id"))
            tag_extra = (
                " *(moedas + PIX)*" if foi_moedas
                else (f" *(desconto sob `{formatar_moeda(base_orig)}`)*" if teve_desc else "")
            )
            linhas_hist.append(f"> 🏦 **`{formatar_moeda(pago_adm)}`** — diário `{hor_txt}`{tag_extra} • `{quando_txt}`")

        embed_adm = criar_embed(
            f"🛡️ Controle de Ganhos do ADM — {alvo.display_name}",
            f"**Ganho hoje ({hoje[8:10]}/{hoje[5:7]}):** **`{formatar_moeda(dia_adm['total'] or 0)}`** "
            f"({int(dia_adm['n'] or 0)} vaga{'s' if int(dia_adm['n'] or 0) != 1 else ''} confirmada{'s' if int(dia_adm['n'] or 0) != 1 else ''})\n"
            f"**Ganho nesta semana:** `{formatar_moeda(sem_adm['total'] or 0)}` "
            f"({int(sem_adm['n'] or 0)} vaga{'s' if int(sem_adm['n'] or 0) != 1 else ''})\n"
            f"> ℹ️ *ADMs recebem direto na própria chave `/pix` (não possuem carteira de trabalho retida no bot).*\n\n"
            f"**Últimas confirmações registradas:**\n"
            + ("\n".join(linhas_hist) if linhas_hist else "> *Nenhuma vaga confirmada ainda.*"),
            "Esmeralda",
            footer="Fire Force • Auditoria de ganhos do ADM",
        )
        return await interaction.response.send_message(embed=embed_adm, ephemeral=True)

    return await interaction.response.send_message(
        embed=criar_embed(
            "🔒 Exclusivo da Equipe",
            f"{alvo.mention} não possui cargo de Suporte nem de ADM neste servidor.",
            "Vermelho",
        ),
        ephemeral=True,
    )


# ==================== PARCERIAS (🤝) & DIVULGAÇÃO PAGA (📣) — v12.0 ====================

async def avisar_jogador(guild: Optional[discord.Guild], user_id: int, embed: discord.Embed) -> bool:
    """Envia aviso por DM ao usuário de forma segura (nunca interrompe o fluxo caso DM esteja fechada)."""
    if not user_id:
        return False
    try:
        alvo = (await membro_do_guild(guild, int(user_id))) if guild else None
        if not alvo:
            alvo = bot.get_user(int(user_id)) or await bot.fetch_user(int(user_id))
        if alvo:
            await alvo.send(embed=embed)
            return True
    except Exception:
        pass
    return False


_CANAIS_TRANSCRITOS = set()


async def salvar_transcricao_canal(canal, motivo: str = "Atendimento encerrado") -> bool:
    """Salva uma transcrição limpa e compacta (mensagens + links de anexos) no canal privado de logs antes de apagar."""
    if not canal or not hasattr(canal, "history"):
        return False
    cid = getattr(canal, "id", 0)
    if cid and cid in _CANAIS_TRANSCRITOS:
        return False
    guild = getattr(canal, "guild", None)
    if not guild:
        return False

    try:
        cfg = await obter_config(guild.id)
        log_id = cfg.get("canal_logs_suporte") or cfg.get("canal_logs")
        if not log_id:
            return False
        log_canal = guild.get_channel(int(log_id))
        if not log_canal:
            return False

        mensagens = []
        async for m in canal.history(limit=50):
            mensagens.append(m)
        mensagens.reverse()

        if not mensagens:
            return False

        if cid:
            _CANAIS_TRANSCRITOS.add(cid)
            if len(_CANAIS_TRANSCRITOS) > 2000:
                _CANAIS_TRANSCRITOS.clear()

        participantes = []
        anexos_links = []
        linhas_txt = [
            f"FIRE FORCE v{VERSAO_BOT} — TRANSCRIÇÃO DE CANAL",
            f"Canal: #{getattr(canal, 'name', cid)} (ID {cid})",
            f"Encerrado em: {agora_brt().strftime('%d/%m/%Y %H:%M:%S')} BRT",
            f"Motivo: {motivo}",
            "-" * 60,
        ]

        for m in mensagens:
            autor = getattr(m, "author", None)
            autor_nome = getattr(autor, "display_name", str(autor or "Sistema"))
            eh_bot = bool(getattr(autor, "bot", False))
            if autor and not eh_bot and autor.mention not in participantes:
                participantes.append(autor.mention)
            dt_m = getattr(m, "created_at", None)
            hora_m = dt_m.astimezone(TZ_BRASILIA).strftime("%H:%M") if dt_m else "--:--"
            texto_m = (getattr(m, "content", "") or "").strip()
            if not texto_m and getattr(m, "embeds", None):
                emb0 = m.embeds[0]
                texto_m = f"[Card: {emb0.title or 'painel'}]"
            if texto_m:
                linhas_txt.append(f"[{hora_m}] {autor_nome}: {texto_m}")
            for att in (getattr(m, "attachments", None) or []):
                url_a = getattr(att, "url", "")
                fn_a = getattr(att, "filename", "anexo")
                if url_a:
                    anexos_links.append(f"[{fn_a}]({url_a})")
                    linhas_txt.append(f"[{hora_m}] {autor_nome} [ANEXO]: {fn_a} -> {url_a}")

        everyone_ve = False
        try:
            everyone_ve = bool(log_canal.permissions_for(guild.default_role).view_channel)
        except Exception:
            everyone_ve = False

        resumo_desc = (
            f"• **Canal encerrado:** `#{getattr(canal, 'name', cid)}`\n"
            f"• **Motivo:** {motivo[:180]}\n"
            f"• **Mensagens registradas:** `{len(mensagens)}` • **Anexos:** `{len(anexos_links)}`\n"
            f"• **Participantes:** {', '.join(participantes[:8]) if participantes else '*apenas sistema*'}"
        )
        if anexos_links and not everyone_ve:
            resumo_desc += "\n• **Comprovantes/Anexos:** " + " • ".join(anexos_links[:5])

        emb_log = criar_embed("🗂️ Transcrição de Canal Encerrado", resumo_desc[:3900], "Cinza Escuro")
        if not everyone_ve:
            conteudo_bytes = "\n".join(linhas_txt).encode("utf-8", errors="replace")
            nome_arq = f"transcricao-{_slug_canal(getattr(canal, 'name', 'canal'), 'canal')}.txt"
            arquivo_txt = discord.File(io.BytesIO(conteudo_bytes), filename=nome_arq)
            await log_canal.send(embed=emb_log, file=arquivo_txt)
        else:
            await log_canal.send(embed=emb_log)
        return True
    except Exception as erro:
        _log_arquivo(f"[TRANSCRIÇÃO] canal={cid}: {type(erro).__name__}: {erro}")
        return False


async def _apagar_canal_seguro(canal, motivo: str = "Atendimento encerrado") -> bool:
    """Salva transcrição compacta no log privado e remove o canal com tratamento seguro."""
    if not canal or not hasattr(canal, "delete"):
        return False
    await salvar_transcricao_canal(canal, motivo)
    try:
        await canal.delete(reason=motivo[:250])
        return True
    except Exception as erro:
        _log_arquivo(f"[CANAL] falha ao apagar canal={getattr(canal, 'id', 0)}: {type(erro).__name__}: {erro}")
        return False


def _normalizar_convite_url(link: str) -> str:
    """Normaliza links discord.gg/... para https://discord.gg/... para botões Link."""
    texto = (link or "").strip()
    if not texto:
        return ""
    if texto.startswith(("http://", "https://")):
        return texto
    if texto.startswith(("discord.gg/", "discord.com/invite/")):
        return "https://" + texto
    return texto


def _slug_canal(texto: str, padrao: str = "org") -> str:
    limpo = re.sub(r"[^a-z0-9\-]+", "-", (texto or "").lower().strip()).strip("-")
    return (limpo[:28] or padrao)


async def _overwrites_dono_gerente(guild: discord.Guild, solicitante: discord.abc.Snowflake) -> dict:
    """Canal privado visível EXCLUSIVAMENTE para o solicitante + Dono e Gerente."""
    cfg = await obter_config(guild.id)
    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        solicitante: discord.PermissionOverwrite(
            view_channel=True, send_messages=True, attach_files=True, read_message_history=True
        ),
    }
    if guild.me:
        overwrites[guild.me] = discord.PermissionOverwrite(
            view_channel=True, send_messages=True, embed_links=True,
            attach_files=True, manage_channels=True, read_message_history=True
        )
    # Garante explicitamente que Suporte e ADM (Mediador) NÃO vejam o canal
    for chave_negada in ("cargo_suporte", "cargo_mediador"):
        rid = cfg.get(chave_negada)
        if rid:
            cargo_neg = guild.get_role(int(rid))
            if cargo_neg:
                overwrites[cargo_neg] = discord.PermissionOverwrite(view_channel=False)
    for chave_vip in ("cargo_dono", "cargo_gerente"):
        rid = cfg.get(chave_vip)
        if rid:
            cargo_vip = guild.get_role(int(rid))
            if cargo_vip:
                overwrites[cargo_vip] = discord.PermissionOverwrite(
                    view_channel=True, send_messages=True, embed_links=True,
                    attach_files=True, manage_messages=True, read_message_history=True
                )
    return overwrites


async def _reconciliar_parcerias_divulgacoes(guild: discord.Guild):
    """Fecha registros pendentes cujo canal foi apagado manualmente."""
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        pendentes_p = await (await db.execute(
            "SELECT id, canal_ticket_id FROM parceiros WHERE guild_id = ? AND status = 'pendente'",
            (guild.id,)
        )).fetchall()
        for r in pendentes_p:
            cid = r["canal_ticket_id"]
            if cid and not guild.get_channel(int(cid)):
                await db.execute("UPDATE parceiros SET status = 'cancelada' WHERE id = ?", (r["id"],))
        abertas_d = await (await db.execute(
            "SELECT id, canal_ticket_id FROM divulgacoes WHERE guild_id = ? AND status = 'aberto'",
            (guild.id,)
        )).fetchall()
        for r in abertas_d:
            cid = r["canal_ticket_id"]
            if cid and not guild.get_channel(int(cid)):
                await db.execute(
                    "UPDATE divulgacoes SET status = 'fechada', fechado_em = ? WHERE id = ?",
                    (agora_brt().isoformat(), r["id"]),
                )
        await db.commit()


async def listar_parceiros_aprovados(guild_id: int) -> list[dict]:
    async with aiosqlite.connect(DATABASE_FILE) as db:
        db.row_factory = aiosqlite.Row
        rows = await (await db.execute(
            "SELECT * FROM parceiros WHERE guild_id = ? AND status = 'aprovada' ORDER BY nome_org COLLATE NOCASE ASC",
            (guild_id,)
        )).fetchall()
        return [dict(r) for r in rows]


