class ValorEspecificoPixLiberadoModal(discord.ui.Modal, title="💰 Valor Específico na Chave PIX"):
    def __init__(
        self,
        canal_id: int,
        responsavel_id: int,
        solicitante_id: int,
        titulo_pix: str,
        rodape_pix: str,
        divulgacao_id: int = 0,
    ):
        super().__init__()
        self.canal_id = int(canal_id)
        self.responsavel_id = int(responsavel_id)
        self.solicitante_id = int(solicitante_id or 0)
        self.titulo_pix = titulo_pix
        self.rodape_pix = rodape_pix
        self.divulgacao_id = int(divulgacao_id or 0)
        self.valor_inp = discord.ui.TextInput(
            label="Qual o valor específico em R$?",
            placeholder="Ex: 25,00",
            required=True,
            max_length=16,
        )
        self.add_item(self.valor_inp)

    async def on_submit(self, interaction: discord.Interaction):
        if not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message("❌ Apenas Dono ou Gerente.", ephemeral=True)
        valor = parse_valor(self.valor_inp.value)
        if not valor or valor <= 0:
            return await interaction.response.send_message(
                embed=criar_embed("❌ Valor inválido", "Informe um valor maior que zero (ex: `25,00`).", "Vermelho"),
                ephemeral=True,
            )
        if self.divulgacao_id:
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute("UPDATE divulgacoes SET valor_acordado = ? WHERE id = ?", (valor, self.divulgacao_id))
                await db.commit()
            marcar_sujo()

        embed_pix, arq_pix, view_pix = await montar_cobranca_pix_responsavel(
            interaction.guild.id,
            self.responsavel_id,
            valor=valor,
            titulo=self.titulo_pix,
            mencao_destino=mencao(self.solicitante_id) if self.solicitante_id else "",
            rodape=self.rodape_pix,
            nome_arquivo="chave_pix.png",
        )
        if not embed_pix:
            return await interaction.response.send_message(
                embed=criar_embed("⚠️ Chave PIX não encontrada", "Cadastre sua chave em `/pix` primeiro.", "Amarelo"),
                ephemeral=True,
            )
        canal_dest = interaction.guild.get_channel(self.canal_id) or interaction.channel
        kwargs_msg = {"embed": embed_pix}
        if self.solicitante_id:
            kwargs_msg["content"] = mencao(self.solicitante_id)
        if arq_pix:
            kwargs_msg["file"] = arq_pix
        if view_pix:
            kwargs_msg["view"] = view_pix
        await canal_dest.send(**kwargs_msg)
        await interaction.response.send_message(
            embed=criar_embed("✅ Chave PIX Liberada", f"Chave PIX enviada no canal com o valor de **`{formatar_moeda(valor)}`**.", "Esmeralda"),
            ephemeral=True,
        )


class EscolherValorPixLiberadoView(discord.ui.View):
    """Pergunta ao Dono/Gerente se deseja definir um valor específico na chave PIX ou não."""

    def __init__(
        self,
        canal_id: int,
        responsavel_id: int,
        solicitante_id: int,
        titulo_pix: str,
        rodape_pix: str,
        divulgacao_id: int = 0,
    ):
        super().__init__(timeout=180)
        self.canal_id = int(canal_id)
        self.responsavel_id = int(responsavel_id)
        self.solicitante_id = int(solicitante_id or 0)
        self.titulo_pix = titulo_pix
        self.rodape_pix = rodape_pix
        self.divulgacao_id = int(divulgacao_id or 0)

    @discord.ui.select(
        placeholder="🔓 Tem um valor específico para colocar na chave PIX?",
        options=[
            discord.SelectOption(
                label="Sim — Colocar um valor específico",
                value="com_valor",
                emoji="💰",
                description="Digitar o valor em R$ para já sair cravado no QR Code",
            ),
            discord.SelectOption(
                label="Não — Liberar chave sem valor específico",
                value="sem_valor",
                emoji="🆓",
                description="Enviar sua chave PIX e QR Code com valor livre",
            ),
        ],
    )
    async def escolher_modo(self, interaction: discord.Interaction, select: discord.ui.Select):
        if interaction.user.id != self.responsavel_id:
            return await interaction.response.send_message("❌ Apenas quem assumiu o atendimento pode escolher.", ephemeral=True)
        modo = select.values[0]
        if modo == "com_valor":
            return await interaction.response.send_modal(
                ValorEspecificoPixLiberadoModal(
                    self.canal_id,
                    self.responsavel_id,
                    self.solicitante_id,
                    self.titulo_pix,
                    self.rodape_pix,
                    divulgacao_id=self.divulgacao_id,
                )
            )

        embed_pix, arq_pix, view_pix = await montar_cobranca_pix_responsavel(
            interaction.guild.id,
            self.responsavel_id,
            valor=0.0,
            titulo=self.titulo_pix,
            mencao_destino=mencao(self.solicitante_id) if self.solicitante_id else "",
            rodape=self.rodape_pix,
            nome_arquivo="chave_pix.png",
        )
        if not embed_pix:
            return await interaction.response.edit_message(
                embed=criar_embed("⚠️ Chave PIX não encontrada", "Cadastre sua chave em `/pix` primeiro.", "Amarelo"),
                view=None,
            )
        canal_dest = interaction.guild.get_channel(self.canal_id) or interaction.channel
        kwargs_msg = {"embed": embed_pix}
        if self.solicitante_id:
            kwargs_msg["content"] = mencao(self.solicitante_id)
        if arq_pix:
            kwargs_msg["file"] = arq_pix
        if view_pix:
            kwargs_msg["view"] = view_pix
        await canal_dest.send(**kwargs_msg)
        await interaction.response.edit_message(
            embed=criar_embed("✅ Chave PIX Liberada", "Sua chave PIX foi enviada no canal sem valor fixo (valor livre).", "Esmeralda"),
            view=None,
        )


class ParceriaTicketView(discord.ui.View):
    """Controles minimalistas dentro do ticket de parceria.
    Após clicar em Assumir, libera a nova função 'Liberar Chave PIX' no painel."""

    def __init__(self, parceria_id: int, assumido: bool = False):
        super().__init__(timeout=None)
        self.parceria_id = int(parceria_id)
        self.assumido = bool(assumido)
        opcoes = [
            discord.SelectOption(
                label="Assumir Atendimento",
                value="assumir",
                emoji="🙋",
                description="Dono/Gerente assume (habilita Liberar Chave PIX)",
            ),
            discord.SelectOption(
                label="Reassumir / Trocar Responsável",
                value="reassumir",
                emoji="🔄",
                description="Transfere esta parceria para você (Dono/Gerente)",
            ),
        ]
        if self.assumido:
            opcoes.append(
                discord.SelectOption(
                    label="Liberar Chave PIX",
                    value="liberar_pix",
                    emoji="🔓",
                    description="Envia sua chave /pix (pergunta se tem valor específico)",
                )
            )
        opcoes.extend([
            discord.SelectOption(
                label="Aprovar e Publicar na Vitrine",
                value="aprovar",
                emoji="✅",
                description="Aprova a parceria, publica na Vitrine e fecha o canal",
            ),
            discord.SelectOption(
                label="Editar Ficha Antes de Aprovar",
                value="editar",
                emoji="✏️",
                description="Ajustar nome, link ou descrição da organização",
            ),
            discord.SelectOption(
                label="Recusar Solicitação",
                value="recusar",
                emoji="❌",
                description="Recusa a solicitação e encerra este canal",
            ),
            discord.SelectOption(
                label="Encerrar Canal",
                value="fechar",
                emoji="🔒",
                description="Fecha e apaga este canal de parceria agora",
            ),
        ])
        sel = discord.ui.Select(
            custom_id=f"ff_parc_tk_{self.parceria_id}",
            placeholder="⚙️ Gerenciar Parceria...",
            options=opcoes,
        )
        sel.callback = self._decidir
        self.add_item(sel)

    async def _decidir(self, interaction: discord.Interaction):
        acao = interaction.data["values"][0]
        async with aiosqlite.connect(DATABASE_FILE) as db:
            db.row_factory = aiosqlite.Row
            parceria = await (await db.execute("SELECT * FROM parceiros WHERE id = ?", (self.parceria_id,))).fetchone()
        if not parceria:
            # Mesmo se o registro não existir mais, permite que Dono/Gerente limpe o canal órfão
            if acao == "fechar" and await e_dono_ou_gerente(interaction.user):
                await interaction.response.send_message("🔒 Encerrando canal...", ephemeral=True)
                await _apagar_canal_seguro(interaction.channel, "Canal de parceria órfão encerrado")
                return
            return await interaction.response.send_message("❌ Registro não encontrado.", ephemeral=True)

        p = dict(parceria)
        eh_vip = await e_dono_ou_gerente(interaction.user)
        ja_assumido = int(p.get("assumido_por") or 0)

        if acao == "fechar":
            if not eh_vip and interaction.user.id != int(p.get("solicitante_id") or 0):
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Sem Permissão", "Apenas o solicitante, Dono ou Gerente podem encerrar este canal.", "Vermelho"),
                    ephemeral=True,
                )
            await interaction.response.defer(ephemeral=True)
            if p.get("status") == "pendente":
                async with aiosqlite.connect(DATABASE_FILE) as db:
                    await db.execute("UPDATE parceiros SET status = 'cancelada' WHERE id = ?", (self.parceria_id,))
                    await db.commit()
                marcar_sujo()
            await interaction.followup.send(
                embed=criar_embed("🔒 Encerrando Canal", "Este canal será apagado em 2 segundos...", "Cinza Escuro"),
                ephemeral=True,
            )
            await asyncio.sleep(2)
            apagou = await _apagar_canal_seguro(interaction.channel, "Canal de parceria encerrado")
            if not apagou:
                await interaction.followup.send(
                    embed=criar_embed("⚠️ Permissão necessária", "Verifique se o cargo do bot possui a permissão **Gerenciar Canais** nesta categoria.", "Amarelo"),
                    ephemeral=True,
                )
            return

        if not eh_vip:
            try:
                await interaction.message.edit(view=ParceriaTicketView(self.parceria_id, assumido=bool(ja_assumido)))
            except Exception:
                pass
            return await interaction.response.send_message(
                embed=criar_embed("🔒 Exclusivo Dono/Gerente", "Apenas **Dono** ou **Gerente** gerenciam esta opção.", "Vermelho"),
                ephemeral=True,
            )

        if acao in ("assumir", "reassumir"):
            if ja_assumido and ja_assumido != interaction.user.id and acao != "reassumir":
                try:
                    await interaction.message.edit(view=ParceriaTicketView(self.parceria_id, assumido=True))
                except Exception:
                    pass
                return await interaction.response.send_message(
                    embed=criar_embed(
                        "🙋 Já assumido",
                        f"Esta parceria já foi assumida por {mencao(ja_assumido)}. Use **🔄 Reassumir / Trocar Responsável** se precisar transferir.",
                        "Amarelo",
                    ),
                    ephemeral=True,
                )
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute("UPDATE parceiros SET assumido_por = ? WHERE id = ?", (interaction.user.id, self.parceria_id))
                await db.commit()
            marcar_sujo()
            await interaction.response.edit_message(view=ParceriaTicketView(self.parceria_id, assumido=True))
            return await interaction.followup.send(
                embed=criar_embed(
                    "🙋 Parceria Assumida",
                    f"{interaction.user.mention} assumiu este atendimento.\n"
                    f"-# 🔓 A função **Liberar Chave PIX** já está disponível no painel acima.",
                    "Esmeralda",
                )
            )

        if acao == "liberar_pix":
            try:
                await interaction.message.edit(view=ParceriaTicketView(self.parceria_id, assumido=True))
            except Exception:
                pass
            if not ja_assumido:
                return await interaction.response.send_message(
                    embed=criar_embed("🙋 Assuma primeiro", "Selecione **Assumir Atendimento** antes de liberar a chave PIX.", "Amarelo"),
                    ephemeral=True,
                )
            if ja_assumido != interaction.user.id:
                return await interaction.response.send_message(
                    embed=criar_embed("🔒 Assumido por outro responsável", f"Apenas {mencao(ja_assumido)} (quem assumiu) pode liberar a própria chave PIX.", "Vermelho"),
                    ephemeral=True,
                )
            pix_meu = await obter_pix_adm(interaction.user.id, interaction.guild.id)
            if not pix_meu:
                return await interaction.response.send_message(
                    embed=criar_embed(
                        "⚠️ Cadastre sua chave PIX primeiro",
                        "Use `/pix` para cadastrar sua chave PIX e em seguida selecione **Liberar Chave PIX** novamente.",
                        "Amarelo",
                    ),
                    ephemeral=True,
                )
            return await interaction.response.send_message(
                embed=criar_embed(
                    "🔓 Liberar Chave PIX",
                    "Deseja colocar um **valor específico** na sua chave PIX (QR Code + Copia e Cola) ou enviar **sem valor específico**?",
                    "Cinza Escuro",
                ),
                view=EscolherValorPixLiberadoView(
                    interaction.channel.id,
                    interaction.user.id,
                    int(p.get("solicitante_id") or 0),
                    titulo_pix=f"🏦 Chave PIX — {interaction.user.display_name}",
                    rodape_pix=f"Fire Force • Parceria #{self.parceria_id}",
                ),
                ephemeral=True,
            )

        if acao == "editar":
            try:
                await interaction.message.edit(view=ParceriaTicketView(self.parceria_id, assumido=bool(ja_assumido)))
            except Exception:
                pass
            return await interaction.response.send_modal(EditarParceiroModal(self.parceria_id, p))

        if acao == "aprovar":
            await interaction.response.defer(ephemeral=True)
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute(
                    "UPDATE parceiros SET status = 'aprovada', aprovado_por = ?, aprovado_em = ? WHERE id = ?",
                    (interaction.user.id, agora_brt().isoformat(), self.parceria_id),
                )
                await db.commit()
            marcar_sujo()

            cfg = await obter_config(interaction.guild.id)
            if cfg.get("cargo_parceiro") and p.get("solicitante_id"):
                membro_rep = await membro_do_guild(interaction.guild, int(p["solicitante_id"]))
                cargo_p = interaction.guild.get_role(int(cfg["cargo_parceiro"]))
                if membro_rep and cargo_p:
                    try:
                        await membro_rep.add_roles(cargo_p, reason="Parceria oficial aprovada")
                    except Exception:
                        pass

            _, msg_vit = await atualizar_vitrine_parceiros(interaction.guild)
            if p.get("solicitante_id"):
                await avisar_jogador(
                    interaction.guild,
                    int(p["solicitante_id"]),
                    criar_embed(
                        "🤝 Parceria Aprovada!",
                        f"Sua organização **{p['nome_org']}** foi aprovada por {interaction.user.mention} e já está ativa na nossa Vitrine de Parceiros!",
                        "Esmeralda",
                    ),
                )
            await registrar_log(
                interaction.guild, "🤝 PARCERIA", "🤝 Parceria aprovada",
                f"Org **{p['nome_org']}** aprovada por {interaction.user.mention}.\n• {msg_vit}",
                "Esmeralda",
            )
            await interaction.followup.send(
                embed=criar_embed("✅ Parceria Aprovada", f"{msg_vit}\nEncerrando o canal em 3 segundos...", "Esmeralda"),
                ephemeral=True,
            )
            await asyncio.sleep(3)
            await _apagar_canal_seguro(interaction.channel, "Parceria aprovada")
            return

        if acao == "recusar":
            await interaction.response.defer(ephemeral=True)
            async with aiosqlite.connect(DATABASE_FILE) as db:
                await db.execute(
                    "UPDATE parceiros SET status = 'recusada', aprovado_por = ?, aprovado_em = ? WHERE id = ?",
                    (interaction.user.id, agora_brt().isoformat(), self.parceria_id),
                )
                await db.commit()
            marcar_sujo()
            if p.get("solicitante_id"):
                await avisar_jogador(
                    interaction.guild,
                    int(p["solicitante_id"]),
                    criar_embed(
                        "ℹ️ Solicitação de Parceria Encerrada",
                        f"Sua solicitação para **{p['nome_org']}** foi analisada e não pôde ser aprovada neste momento.",
                        "Amarelo",
                    ),
                )
            await interaction.followup.send(
                embed=criar_embed("❌ Solicitação Recusada", "Canal será encerrado em 2 segundos...", "Cinza Escuro"),
                ephemeral=True,
            )
            await asyncio.sleep(2)
            await _apagar_canal_seguro(interaction.channel, "Parceria recusada")


class ConfigurarNossaOrgModal(discord.ui.Modal, title="📝 Ficha da Nossa Organização"):
    def __init__(self, cfg: dict, guild_name: str):
        super().__init__()
        self.nome = discord.ui.TextInput(
            label="Nome da Nossa Organização",
            default=str(cfg.get("nossa_org_nome") or guild_name)[:80],
            max_length=80,
        )
        self.link = discord.ui.TextInput(
            label="Nosso Link de Convite Permanente",
            default=str(cfg.get("nossa_org_link") or "")[:150],
            placeholder="https://discord.gg/...",
            max_length=150,
        )
        self.motivos = discord.ui.TextInput(
            label="Nossos Diferenciais (enviados ao parceiro)",
            style=discord.TextStyle.paragraph,
            default=str(cfg.get("nossa_org_motivos") or "")[:600],
            placeholder="Diários todos os dias, pagamento imediato via PIX e organização profissional.",
            max_length=600,
        )
        self.add_item(self.nome)
        self.add_item(self.link)
        self.add_item(self.motivos)

    async def on_submit(self, interaction: discord.Interaction):
        await salvar_config(
            interaction.guild.id,
            nossa_org_nome=self.nome.value.strip(),
            nossa_org_link=_normalizar_convite_url(self.link.value.strip()),
            nossa_org_motivos=self.motivos.value.strip(),
        )
        marcar_sujo()
        await interaction.response.send_message(
            embed=criar_embed("✅ Nossa Ficha Salva", "Ela será enviada automaticamente em todos os novos tickets de parceria.", "Esmeralda"),
            ephemeral=True,
        )


class CadastrarParceiroDiretoModal(discord.ui.Modal, title="➕ Adicionar Parceiro na Vitrine"):
    nome_org = discord.ui.TextInput(label="Nome da Organização", placeholder="Ex: Org Phoenix FF", max_length=80)
    convite_link = discord.ui.TextInput(label="Link de Convite", placeholder="https://discord.gg/...", max_length=150)
    motivos = discord.ui.TextInput(
        label="Por que entrar nessa Org?",
        style=discord.TextStyle.paragraph,
        placeholder="Diferenciais e motivos que aparecerão para quem clicar na vitrine...",
        max_length=600,
    )

    async def on_submit(self, interaction: discord.Interaction):
        link_norm = _normalizar_convite_url(self.convite_link.value.strip())
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute(
                "INSERT INTO parceiros (guild_id, nome_org, convite_link, motivos, solicitante_id, "
                "status, aprovado_por, criado_em, aprovado_em) VALUES (?, ?, ?, ?, ?, 'aprovada', ?, ?, ?)",
                (
                    interaction.guild.id,
                    self.nome_org.value.strip(),
                    link_norm,
                    self.motivos.value.strip(),
                    interaction.user.id,
                    interaction.user.id,
                    agora_brt().isoformat(),
                    agora_brt().isoformat(),
                ),
            )
            await db.commit()
        marcar_sujo()
        ok_v, msg_v = await atualizar_vitrine_parceiros(interaction.guild)
        await interaction.response.send_message(
            embed=criar_embed("✅ Parceiro Adicionado", f"**{self.nome_org.value.strip()}** cadastrado!\n• {msg_v}", "Esmeralda" if ok_v else "Amarelo"),
            ephemeral=True,
        )


class DefinirCanalVitrineView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=180)
        sel = discord.ui.ChannelSelect(
            placeholder="🏛️ Selecione o canal público da Vitrine de Parceiros...",
            channel_types=[discord.ChannelType.text],
        )
        sel.callback = self._escolher
        self.add_item(sel)

    async def _escolher(self, interaction: discord.Interaction):
        canal_sel = interaction.guild.get_channel(int(interaction.data["values"][0]))
        if not isinstance(canal_sel, discord.TextChannel):
            return await interaction.response.send_message("❌ Canal inválido.", ephemeral=True)
        await salvar_config(interaction.guild.id, canal_parcerias=canal_sel.id, msg_vitrine_parcerias=None)
        marcar_sujo()
        ok_v, msg_v = await atualizar_vitrine_parceiros(interaction.guild)
        await interaction.response.edit_message(
            embed=criar_embed("🏛️ Vitrine Configurada", msg_v, "Esmeralda" if ok_v else "Vermelho"),
            view=None,
        )


class RemoverParceiroView(discord.ui.View):
    def __init__(self, parceiros: list[dict]):
        super().__init__(timeout=180)
        opcoes = [
            discord.SelectOption(
                label=str(p["nome_org"] or "Parceiro")[:100],
                value=str(p["id"]),
                emoji="🗑️",
                description=f"Cliques: {p.get('cliques') or 0} • {str(p.get('convite_link') or '')[:60]}"[:100],
            )
            for p in parceiros[:25]
        ] or [discord.SelectOption(label="Nenhum parceiro cadastrado", value="0", emoji="ℹ️")]
        sel = discord.ui.Select(placeholder="🗑️ Selecione o parceiro que deseja remover...", options=opcoes)
        sel.callback = self._remover
        self.add_item(sel)

    async def _remover(self, interaction: discord.Interaction):
        pid = int(interaction.data["values"][0])
        if pid <= 0:
            return await interaction.response.send_message(
                embed=criar_embed("ℹ️ Lista vazia", "Não há parceiro para remover.", "Cinza Escuro"),
                ephemeral=True,
            )
        async with aiosqlite.connect(DATABASE_FILE) as db:
            await db.execute(
                "UPDATE parceiros SET status = 'removida' WHERE id = ? AND guild_id = ?",
                (pid, interaction.guild.id),
            )
            await db.commit()
        marcar_sujo()
        _, msg_v = await atualizar_vitrine_parceiros(interaction.guild)
        await interaction.response.edit_message(
            embed=criar_embed("🗑️ Parceiro Removido", f"Parceria encerrada.\n• {msg_v}", "Amarelo"),
            view=None,
        )


class ParceriaAdminHubView(discord.ui.View):
    """Hub minimalista de gestão de parcerias (/parceria) para Dono e Gerente."""

    def __init__(self):
        super().__init__(timeout=300)

    @discord.ui.select(
        placeholder="🤝 Selecione uma operação de Parcerias...",
        options=[
            discord.SelectOption(
                label="Publicar Painel de Solicitação",
                value="publicar_painel",
                emoji="📌",
                description="Envia neste canal o painel para representantes pedirem parceria",
            ),
            discord.SelectOption(
                label="Definir Canal da Vitrine de Parceiros",
                value="definir_vitrine",
                emoji="🏛️",
                description="Escolhe o canal onde o painel automático de Orgs parceiras fica",
            ),
            discord.SelectOption(
                label="Configurar Ficha da Nossa Org",
                value="nossa_ficha",
                emoji="📝",
                description="Define nosso nome, link e motivos enviados nos tickets de parceria",
            ),
            discord.SelectOption(
                label="Adicionar Parceiro Direto na Vitrine",
                value="adicionar_direto",
                emoji="➕",
                description="Cadastra uma organização aprovada direto na Vitrine",
            ),
            discord.SelectOption(
                label="Remover Parceiro da Vitrine",
                value="remover",
                emoji="🗑️",
                description="Retira uma organização da Vitrine e atualiza o painel",
            ),
            discord.SelectOption(
                label="Relatório de Parceiros & Cliques",
                value="listar",
                emoji="📊",
                description="Mostra todas as parcerias ativas e quantos cliques cada uma teve",
            ),
        ],
    )
    async def selecionar(self, interaction: discord.Interaction, select: discord.ui.Select):
        if not await e_dono_ou_gerente(interaction.user):
            return await interaction.response.send_message("❌ Apenas Dono ou Gerente.", ephemeral=True)
